  {
    "function_signature": "apply_default_user_permissions(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.apply_default_user_permissions(target_user_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  target_role text;\r\nbegin\r\n  select role::text\r\n  into target_role\r\n  from public.profiles\r\n  where id = target_user_id;\r\n\r\n  if target_role is null then\r\n    return;\r\n  end if;\r\n\r\n  insert into public.user_permissions (\r\n    user_id,\r\n    permission_key\r\n  )\r\n  select\r\n    target_user_id,\r\n    defaults.permission_key\r\n  from public.role_default_permissions defaults\r\n  where defaults.role_name = target_role\r\n  on conflict do nothing;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "cancel_shift_swap_request(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.cancel_shift_swap_request(requested_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  request_row public.shift_swap_requests%rowtype;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'לא נמצאה התחברות פעילה.';\r\n  end if;\r\n\r\n  select *\r\n  into request_row\r\n  from public.shift_swap_requests\r\n  where id = requested_request_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'בקשת ההחלפה לא נמצאה.';\r\n  end if;\r\n\r\n  if request_row.requester_user_id <> current_user_id then\r\n    raise exception 'רק מגיש הבקשה יכול לבטל אותה.';\r\n  end if;\r\n\r\n  if request_row.status not in ('pending_counterparty', 'pending_manager') then\r\n    raise exception 'לא ניתן לבטל בקשה שכבר נסגרה.';\r\n  end if;\r\n\r\n  update public.shift_swap_requests\r\n  set\r\n    status = 'cancelled',\r\n    cancelled_at = now()\r\n  where id = request_row.id\r\n  returning * into request_row;\r\n\r\n  return jsonb_build_object(\r\n    'id', request_row.id,\r\n    'status', request_row.status,\r\n    'cancelledAt', request_row.cancelled_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "close_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.close_availability_period(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, period_status text, closed_at timestamp with time zone, total_dispatchers integer, submitted_dispatchers integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_actor_email text;\r\n  current_actor_display_name text;\r\n\r\n  target_period_title text;\r\n  target_period_year integer;\r\n  target_period_month integer;\r\n  target_period_status text;\r\n\r\n  calculated_total_dispatchers integer;\r\n  calculated_submitted_dispatchers integer;\r\n\r\n  target_closed_at timestamptz;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_actor_email,\r\n    current_actor_display_name\r\n  from public.profiles profile\r\n  where profile.id =\r\n    current_user_id\r\n    and profile.is_active = true;\r\n\r\n  if current_actor_email is null then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability periods';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.title,\r\n    period.year,\r\n    period.month,\r\n    period.status\r\n  into\r\n    target_period_title,\r\n    target_period_year,\r\n    target_period_month,\r\n    target_period_status\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if target_period_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  if target_period_status <> 'open' then\r\n    raise exception\r\n      'Only open availability periods can be closed';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_total_dispatchers\r\n  from public.profiles profile\r\n  where profile.role::text =\r\n    'dispatcher'\r\n    and profile.is_active = true;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_submitted_dispatchers\r\n  from public.availability_submissions submission\r\n  join public.profiles profile\r\n    on profile.id =\r\n      submission.user_id\r\n  where submission.period_id =\r\n    requested_period_id\r\n    and submission.status =\r\n      'submitted'\r\n    and profile.role::text =\r\n      'dispatcher'\r\n    and profile.is_active = true;\r\n\r\n  if calculated_total_dispatchers = 0 then\r\n    raise exception\r\n      'No active dispatchers were found';\r\n  end if;\r\n\r\n  if calculated_submitted_dispatchers <>\r\n     calculated_total_dispatchers then\r\n    raise exception\r\n      'Not all active dispatchers have submitted availability';\r\n  end if;\r\n\r\n  target_closed_at := now();\r\n\r\n  update public.availability_periods period\r\n  set\r\n    status = 'closed',\r\n    closed_at =\r\n      target_closed_at,\r\n    updated_by =\r\n      current_user_id,\r\n    updated_at =\r\n      target_closed_at\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    'availability_period_closed',\r\n\r\n    current_user_id,\r\n    current_actor_email,\r\n    current_actor_display_name,\r\n\r\n    null,\r\n    null,\r\n    null,\r\n\r\n    'availability_period',\r\n    requested_period_id,\r\n\r\n    format(\r\n      'נסגרה תקופת אילוצים: %s',\r\n      coalesce(\r\n        target_period_title,\r\n        format(\r\n          '%s/%s',\r\n          target_period_month,\r\n          target_period_year\r\n        )\r\n      )\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      'open'\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      'closed',\r\n      'closed_at',\r\n      target_closed_at,\r\n      'total_dispatchers',\r\n      calculated_total_dispatchers,\r\n      'submitted_dispatchers',\r\n      calculated_submitted_dispatchers\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'source',\r\n      'close-availability-period-rpc',\r\n\r\n      'period_id',\r\n      requested_period_id,\r\n\r\n      'year',\r\n      target_period_year,\r\n\r\n      'month',\r\n      target_period_month\r\n    )\r\n  );\r\n\r\n  return query\r\n  select\r\n    requested_period_id,\r\n    'closed'::text,\r\n    target_closed_at,\r\n    calculated_total_dispatchers,\r\n    calculated_submitted_dispatchers;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "close_driver_availability_period(uuid,boolean)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.close_driver_availability_period(requested_period_id uuid, requested_force boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  total_drivers_count integer := 0;\r\n  submitted_drivers_count integer := 0;\r\n  missing_drivers_count integer := 0;\r\n\r\n  closed_at_value timestamptz :=\r\n    now();\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into total_drivers_count\r\n  from public.profiles\r\n  where role =\r\n    'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  select\r\n    count(\r\n      distinct submission.user_id\r\n    )::integer\r\n  into submitted_drivers_count\r\n  from public.driver_availability_submissions\r\n    submission\r\n  join public.profiles\r\n    profile\r\n    on profile.id =\r\n      submission.user_id\r\n  where submission.period_id =\r\n      target_period.id\r\n    and submission.status =\r\n      'submitted'\r\n    and profile.role =\r\n      'on_call'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  missing_drivers_count :=\r\n    greatest(\r\n      total_drivers_count -\r\n      submitted_drivers_count,\r\n      0\r\n    );\r\n\r\n  /*\r\n   * Driver submissions are optional.\r\n   * Missing submissions are informational only\r\n   * and never block the close operation.\r\n   */\r\n  if target_period.status =\r\n      'closed'\r\n  then\r\n    return jsonb_build_object(\r\n      'periodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'status',\r\n        target_period.status,\r\n\r\n      'closedAt',\r\n        target_period.closed_at,\r\n\r\n      'totalDrivers',\r\n        total_drivers_count,\r\n\r\n      'submittedDrivers',\r\n        submitted_drivers_count,\r\n\r\n      'missingDrivers',\r\n        missing_drivers_count,\r\n\r\n      'forced',\r\n        false,\r\n\r\n      'alreadyClosed',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status <>\r\n      'open'\r\n  then\r\n    raise exception\r\n      'only open driver availability periods can be closed';\r\n  end if;\r\n\r\n  update public.driver_availability_periods\r\n  set\r\n    status =\r\n      'closed',\r\n\r\n    closed_at =\r\n      closed_at_value,\r\n\r\n    updated_by =\r\n      current_user_id,\r\n\r\n    updated_at =\r\n      closed_at_value\r\n\r\n  where id =\r\n    target_period.id\r\n\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status,\r\n\r\n    'closedAt',\r\n      target_period.closed_at,\r\n\r\n    'totalDrivers',\r\n      total_drivers_count,\r\n\r\n    'submittedDrivers',\r\n      submitted_drivers_count,\r\n\r\n    'missingDrivers',\r\n      missing_drivers_count,\r\n\r\n    /*\r\n     * Kept for backward-compatible frontend response shape.\r\n     * Missing submissions no longer require force.\r\n     */\r\n    'forced',\r\n      false,\r\n\r\n    'alreadyClosed',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "close_morning_driver_availability_period(uuid,boolean)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.close_morning_driver_availability_period(requested_period_id uuid, requested_force boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  total_drivers integer := 0;\r\n  submitted_drivers integer := 0;\r\n  missing_drivers integer := 0;\r\n  closed_at_value timestamptz := now();\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception 'period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status = 'closed' then\r\n    return jsonb_build_object(\r\n      'periodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'status',\r\n        target_period.status,\r\n\r\n      'closedAt',\r\n        target_period.closed_at,\r\n\r\n      'totalDrivers',\r\n        0,\r\n\r\n      'submittedDrivers',\r\n        0,\r\n\r\n      'missingDrivers',\r\n        0,\r\n\r\n      'forced',\r\n        coalesce(\r\n          requested_force,\r\n          false\r\n        ),\r\n\r\n      'alreadyClosed',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception 'only open periods can be closed';\r\n  end if;\r\n\r\n  select count(*)\r\n  into total_drivers\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  select count(*)\r\n  into submitted_drivers\r\n  from public.morning_driver_availability_submissions submission\r\n  join public.profiles profile\r\n    on profile.id = submission.user_id\r\n  where submission.period_id = target_period.id\r\n    and submission.status = 'submitted'\r\n    and profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  missing_drivers :=\r\n    greatest(\r\n      total_drivers\r\n      - submitted_drivers,\r\n      0\r\n    );\r\n\r\n  if missing_drivers > 0\r\n     and not coalesce(\r\n       requested_force,\r\n       false\r\n     )\r\n  then\r\n    raise exception\r\n      'not all morning drivers submitted availability';\r\n  end if;\r\n\r\n  update public.morning_driver_availability_periods\r\n  set\r\n    status = 'closed',\r\n    closed_at = closed_at_value,\r\n    updated_by = current_user_id,\r\n    updated_at = closed_at_value\r\n  where id = target_period.id\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status,\r\n\r\n    'closedAt',\r\n      target_period.closed_at,\r\n\r\n    'totalDrivers',\r\n      total_drivers,\r\n\r\n    'submittedDrivers',\r\n      submitted_drivers,\r\n\r\n    'missingDrivers',\r\n      missing_drivers,\r\n\r\n    'forced',\r\n      coalesce(\r\n        requested_force,\r\n        false\r\n      ),\r\n\r\n    'alreadyClosed',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "complete_initial_password_change()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.complete_initial_password_change()\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  affected_rows integer;\r\nbegin\r\n  if auth.uid() is null then\r\n    raise exception 'User is not authenticated';\r\n  end if;\r\n\r\n  update public.profiles\r\n  set\r\n    must_change_password = false,\r\n    updated_at = now()\r\n  where id = auth.uid();\r\n\r\n  get diagnostics affected_rows = row_count;\r\n\r\n  if affected_rows = 0 then\r\n    raise exception 'User profile was not found';\r\n  end if;\r\n\r\n  return true;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_availability_period(integer,integer,timestamp with time zone,text,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_availability_period(requested_year integer, requested_month integer, requested_submission_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone, requested_title text DEFAULT NULL::text, requested_instructions text DEFAULT NULL::text)\n RETURNS TABLE(period_id uuid, created_slots integer, period_status text)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  created_period_id uuid;\r\n  rebuild_result record;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability periods';\r\n  end if;\r\n\r\n  if requested_year is null\r\n     or requested_year < 2020\r\n     or requested_year > 2200 then\r\n    raise exception\r\n      'Invalid availability year';\r\n  end if;\r\n\r\n  if requested_month is null\r\n     or requested_month < 1\r\n     or requested_month > 12 then\r\n    raise exception\r\n      'Invalid availability month';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.availability_periods period\r\n    where period.year =\r\n      requested_year\r\n      and period.month =\r\n        requested_month\r\n  ) then\r\n    raise exception\r\n      'Availability period already exists for %/%',\r\n      requested_month,\r\n      requested_year;\r\n  end if;\r\n\r\n  insert into public.availability_periods (\r\n    year,\r\n    month,\r\n    status,\r\n    title,\r\n    instructions,\r\n    submission_deadline,\r\n    created_by,\r\n    updated_by\r\n  )\r\n  values (\r\n    requested_year,\r\n    requested_month,\r\n    'draft',\r\n\r\n    coalesce(\r\n      nullif(\r\n        trim(requested_title),\r\n        ''\r\n      ),\r\n\r\n      format(\r\n        'אילוצים לחודש %s/%s',\r\n        lpad(\r\n          requested_month::text,\r\n          2,\r\n          '0'\r\n        ),\r\n        requested_year\r\n      )\r\n    ),\r\n\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_instructions,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    ),\r\n\r\n    requested_submission_deadline,\r\n    current_user_id,\r\n    current_user_id\r\n  )\r\n  returning id\r\n  into created_period_id;\r\n\r\n  select *\r\n  into rebuild_result\r\n  from public.rebuild_availability_period_slots(\r\n    created_period_id\r\n  );\r\n\r\n  return query\r\n  select\r\n    created_period_id,\r\n    rebuild_result.created_slots,\r\n    'draft'::text;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_driver_availability_period(integer,integer,text,text,timestamp with time zone)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_driver_availability_period(requested_year integer, requested_month integer, requested_title text DEFAULT NULL::text, requested_instructions text DEFAULT NULL::text, requested_submission_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  user_permissions text[];\r\n\r\n  created_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  first_day date;\r\n  last_day date;\r\n\r\n  created_days_count integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  user_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n    any(user_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_year\r\n    not between 2020 and 2100\r\n  then\r\n    raise exception\r\n      'invalid year';\r\n  end if;\r\n\r\n  if requested_month\r\n    not between 1 and 12\r\n  then\r\n    raise exception\r\n      'invalid month';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_availability_periods\r\n    where year = requested_year\r\n      and month = requested_month\r\n  ) then\r\n    raise exception\r\n      'driver availability period already exists';\r\n  end if;\r\n\r\n  first_day :=\r\n    make_date(\r\n      requested_year,\r\n      requested_month,\r\n      1\r\n    );\r\n\r\n  last_day :=\r\n    (\r\n      first_day\r\n      + interval '1 month'\r\n      - interval '1 day'\r\n    )::date;\r\n\r\n  insert into public.driver_availability_periods (\r\n    year,\r\n    month,\r\n    status,\r\n    title,\r\n    instructions,\r\n    submission_deadline,\r\n    created_by,\r\n    updated_by\r\n  )\r\n  values (\r\n    requested_year,\r\n    requested_month,\r\n    'draft',\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_title,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    ),\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_instructions,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    ),\r\n    requested_submission_deadline,\r\n    current_user_id,\r\n    current_user_id\r\n  )\r\n  returning *\r\n  into created_period;\r\n\r\n  insert into public.driver_availability_days (\r\n    period_id,\r\n    availability_date,\r\n    weekday_number,\r\n    weekday_name,\r\n    sort_order\r\n  )\r\n  select\r\n    created_period.id,\r\n\r\n    generated_day::date,\r\n\r\n    extract(\r\n      dow\r\n      from generated_day\r\n    )::integer,\r\n\r\n    case\r\n      extract(\r\n        dow\r\n        from generated_day\r\n      )::integer\r\n\r\n      when 0 then 'ראשון'\r\n      when 1 then 'שני'\r\n      when 2 then 'שלישי'\r\n      when 3 then 'רביעי'\r\n      when 4 then 'חמישי'\r\n      when 5 then 'שישי'\r\n      when 6 then 'שבת'\r\n    end,\r\n\r\n    extract(\r\n      day\r\n      from generated_day\r\n    )::integer\r\n\r\n  from generate_series(\r\n    first_day::timestamp,\r\n    last_day::timestamp,\r\n    interval '1 day'\r\n  ) as generated_day;\r\n\r\n  get diagnostics\r\n    created_days_count =\r\n      row_count;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      created_period.id,\r\n\r\n    'year',\r\n      created_period.year,\r\n\r\n    'month',\r\n      created_period.month,\r\n\r\n    'status',\r\n      created_period.status,\r\n\r\n    'title',\r\n      created_period.title,\r\n\r\n    'submissionDeadline',\r\n      created_period.submission_deadline,\r\n\r\n    'createdDays',\r\n      created_days_count,\r\n\r\n    'createdAt',\r\n      created_period.created_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_driver_schedule_draft(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_driver_schedule_draft(requested_availability_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  availability_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  created_schedule_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  availability_day\r\n    public.driver_availability_days%rowtype;\r\n\r\n  selected_user_id uuid;\r\n  selected_original_user_id uuid;\r\n\r\n  rotation_users uuid[];\r\n  rotation_position integer;\r\n  target_month_start date;\r\n  rotation_history_rows integer := 0;\r\n\r\n  selected_last_assignment_date date;\r\n  selected_gap_days integer;\r\n  selected_spacing_warning boolean;\r\n  selected_warning_text text;\r\n\r\n  created_days_count integer := 0;\r\n  assigned_days_count integer := 0;\r\n  unassigned_days_count integer := 0;\r\n  warning_count integer := 0;\r\n\r\n  active_drivers_count integer := 0;\r\n\r\n  assignments_json jsonb :=\r\n    '[]'::jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_availability_period_id\r\n    is null\r\n  then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into availability_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_availability_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if availability_period.status <>\r\n    'closed'\r\n  then\r\n    raise exception\r\n      'driver availability period must be closed before scheduling';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_periods\r\n    where availability_period_id =\r\n      availability_period.id\r\n  ) then\r\n    raise exception\r\n      'driver schedule period already exists for this availability period';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_periods\r\n    where year =\r\n      availability_period.year\r\n      and month =\r\n        availability_period.month\r\n  ) then\r\n    raise exception\r\n      'driver schedule period already exists for this month';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into active_drivers_count\r\n  from public.profiles\r\n  where role =\r\n    'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  if active_drivers_count = 0 then\r\n    raise exception\r\n      'no active on-call drivers were found';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.driver_availability_days\r\n    where period_id =\r\n      availability_period.id\r\n  ) then\r\n    raise exception\r\n      'driver availability period has no days';\r\n  end if;\r\n\r\n  target_month_start :=\r\n    make_date(\r\n      availability_period.year,\r\n      availability_period.month,\r\n      1\r\n    );\r\n\r\n  /*\r\n   * זיהוי רוטציית 5 הכוננים מתוך ההיסטוריה.\r\n   *\r\n   * מקור האמת לרוטציה הוא original_user_id.\r\n   * רק כאשר הוא חסר משתמשים ב-assigned_user_id.\r\n   * כך החלפה ידנית חד-פעמית לא מזיזה את המחזור.\r\n   *\r\n   * נבדקות כל 120 הפרמוטציות האפשריות של חמשת\r\n   * הכוננים הנפוצים ב-120 הימים שקדמו לחודש היעד.\r\n   * לכל פרמוטציה מחושב כמה ימי עבר היא מסבירה\r\n   * נכון לפי מחזור קבוע של חמישה ימים.\r\n   */\r\n  with history as (\r\n    select\r\n      day_row.duty_date,\r\n      coalesce(\r\n        day_row.original_user_id,\r\n        day_row.assigned_user_id\r\n      ) as rotation_user_id\r\n    from public.driver_schedule_days day_row\r\n    join public.profiles profile_row\r\n      on profile_row.id =\r\n        coalesce(\r\n          day_row.original_user_id,\r\n          day_row.assigned_user_id\r\n        )\r\n      and profile_row.role =\r\n        'on_call'::public.user_role\r\n      and profile_row.is_active = true\r\n    where day_row.duty_date <\r\n      target_month_start\r\n      and day_row.duty_date >=\r\n        target_month_start -\r\n        interval '120 days'\r\n      and coalesce(\r\n        day_row.original_user_id,\r\n        day_row.assigned_user_id\r\n      ) is not null\r\n  ),\r\n  top_users as (\r\n    select\r\n      history.rotation_user_id as user_id,\r\n      count(*)::integer as appearances\r\n    from history\r\n    group by\r\n      history.rotation_user_id\r\n    order by\r\n      count(*) desc,\r\n      max(history.duty_date) desc\r\n    limit 5\r\n  ),\r\n  permutations as (\r\n    select\r\n      array[\r\n        first_user.user_id,\r\n        second_user.user_id,\r\n        third_user.user_id,\r\n        fourth_user.user_id,\r\n        fifth_user.user_id\r\n      ]::uuid[] as rotation\r\n    from top_users first_user\r\n    cross join top_users second_user\r\n    cross join top_users third_user\r\n    cross join top_users fourth_user\r\n    cross join top_users fifth_user\r\n    where first_user.user_id <>\r\n        second_user.user_id\r\n      and first_user.user_id <>\r\n        third_user.user_id\r\n      and first_user.user_id <>\r\n        fourth_user.user_id\r\n      and first_user.user_id <>\r\n        fifth_user.user_id\r\n      and second_user.user_id <>\r\n        third_user.user_id\r\n      and second_user.user_id <>\r\n        fourth_user.user_id\r\n      and second_user.user_id <>\r\n        fifth_user.user_id\r\n      and third_user.user_id <>\r\n        fourth_user.user_id\r\n      and third_user.user_id <>\r\n        fifth_user.user_id\r\n      and fourth_user.user_id <>\r\n        fifth_user.user_id\r\n  ),\r\n  scored as (\r\n    select\r\n      permutation.rotation,\r\n      sum(\r\n        case\r\n          when history.rotation_user_id =\r\n            permutation.rotation[\r\n              (\r\n                (\r\n                  (\r\n                    history.duty_date -\r\n                    target_month_start\r\n                  ) % 5\r\n                  + 5\r\n                ) % 5\r\n              ) + 1\r\n            ]\r\n          then 1\r\n          else 0\r\n        end\r\n      )::integer as match_count,\r\n      count(*)::integer as compared_days\r\n    from permutations permutation\r\n    cross join history\r\n    group by\r\n      permutation.rotation\r\n    order by\r\n      match_count desc,\r\n      compared_days desc\r\n    limit 1\r\n  )\r\n  select\r\n    scored.rotation,\r\n    scored.compared_days\r\n  into\r\n    rotation_users,\r\n    rotation_history_rows\r\n  from scored;\r\n\r\n  /*\r\n   * אם אין מספיק היסטוריה, משלימים רוטציה\r\n   * מחמשת הכוננים הפעילים. ברגע שתצטבר\r\n   * היסטוריה, החודשים הבאים ילמדו את המחזור\r\n   * בפועל אוטומטית.\r\n   */\r\n  if rotation_users is null\r\n     or cardinality(rotation_users) <> 5\r\n  then\r\n    select\r\n      array_agg(\r\n        profile_row.id\r\n        order by\r\n          coalesce(\r\n            profile_row.schedule_name,\r\n            profile_row.display_name\r\n          ),\r\n          profile_row.id\r\n      )\r\n    into rotation_users\r\n    from (\r\n      select profile.id,\r\n             profile.schedule_name,\r\n             profile.display_name\r\n      from public.profiles profile\r\n      where profile.role =\r\n          'on_call'::public.user_role\r\n        and profile.is_active = true\r\n      order by\r\n        coalesce(\r\n          profile.schedule_name,\r\n          profile.display_name\r\n        ),\r\n        profile.id\r\n      limit 5\r\n    ) profile_row;\r\n  end if;\r\n\r\n  if rotation_users is null\r\n     or cardinality(rotation_users) <> 5\r\n  then\r\n    raise exception\r\n      'driver rotation requires five active on-call drivers';\r\n  end if;\r\n\r\n  insert into public.driver_schedule_periods (\r\n    year,\r\n    month,\r\n    status,\r\n    availability_period_id,\r\n    title,\r\n    created_by,\r\n    updated_by\r\n  )\r\n  values (\r\n    availability_period.year,\r\n    availability_period.month,\r\n    'draft',\r\n    availability_period.id,\r\n    coalesce(\r\n      availability_period.title,\r\n      format(\r\n        'לוח כוננים %s/%s',\r\n        lpad(\r\n          availability_period.month::text,\r\n          2,\r\n          '0'\r\n        ),\r\n        availability_period.year\r\n      )\r\n    ),\r\n    current_user_id,\r\n    current_user_id\r\n  )\r\n  returning *\r\n  into created_schedule_period;\r\n\r\n  for availability_day in\r\n    select *\r\n    from public.driver_availability_days\r\n    where period_id =\r\n      availability_period.id\r\n    order by\r\n      availability_date\r\n  loop\r\n    selected_user_id :=\r\n      null;\r\n\r\n    selected_original_user_id :=\r\n      null;\r\n\r\n    selected_last_assignment_date :=\r\n      null;\r\n\r\n    selected_gap_days :=\r\n      null;\r\n\r\n    selected_spacing_warning :=\r\n      false;\r\n\r\n    selected_warning_text :=\r\n      null;\r\n\r\n    /*\r\n     * רוטציה יומית רציפה של חמישה כוננים.\r\n     * היום הראשון בחודש אינו מאפס את המחזור:\r\n     * המיקום מחושב מול target_month_start והפרמוטציה\r\n     * שנלמדה מהחודשים הקודמים.\r\n     */\r\n    rotation_position :=\r\n      (\r\n        (\r\n          availability_day.availability_date -\r\n          target_month_start\r\n        ) % 5\r\n        + 5\r\n      ) % 5\r\n      + 1;\r\n\r\n    selected_original_user_id :=\r\n      rotation_users[\r\n        rotation_position\r\n      ];\r\n\r\n    /*\r\n     * אילוצים הם שכבת חריגים בלבד.\r\n     * אין חובה להגיש אילוצים:\r\n     * - אין רשומה = אין חסימה.\r\n     * - available = מותר.\r\n     * - unavailable = מחפשים מחליף.\r\n     */\r\n    if not exists (\r\n      select 1\r\n      from public.driver_availability_entries entry\r\n      where entry.period_id =\r\n          availability_period.id\r\n        and entry.day_id =\r\n          availability_day.id\r\n        and entry.user_id =\r\n          selected_original_user_id\r\n        and entry.availability_status =\r\n          'unavailable'\r\n    ) then\r\n      selected_user_id :=\r\n        selected_original_user_id;\r\n    else\r\n      /*\r\n       * הכונן המקורי אינו זמין.\r\n       * בוחרים מחליף בלי לשנות את original_user_id,\r\n       * כדי שהיום הבא ימשיך את המחזור המקורי.\r\n       *\r\n       * סדר העדיפויות:\r\n       * 1. לא סימן unavailable.\r\n       * 2. לא עבד בפועל ביום הקודם.\r\n       * 3. מי שסימן available עדיף על מי שלא הגיש.\r\n       * 4. פחות כוננויות בפועל בחודש.\r\n       * 5. מרווח גדול יותר מהכוננות הקודמת.\r\n       */\r\n      select\r\n        candidate.user_id,\r\n        candidate.last_assignment_date,\r\n        candidate.gap_days\r\n      into\r\n        selected_user_id,\r\n        selected_last_assignment_date,\r\n        selected_gap_days\r\n      from (\r\n        select\r\n          profile.id as user_id,\r\n\r\n          availability_entry.availability_status,\r\n\r\n          (\r\n            select max(previous_day.duty_date)\r\n            from public.driver_schedule_days previous_day\r\n            where previous_day.assigned_user_id =\r\n                profile.id\r\n              and previous_day.duty_date <\r\n                availability_day.availability_date\r\n          ) as last_assignment_date,\r\n\r\n          (\r\n            availability_day.availability_date -\r\n            (\r\n              select max(previous_day.duty_date)\r\n              from public.driver_schedule_days previous_day\r\n              where previous_day.assigned_user_id =\r\n                  profile.id\r\n                and previous_day.duty_date <\r\n                  availability_day.availability_date\r\n            )\r\n          ) as gap_days,\r\n\r\n          (\r\n            select count(*)::integer\r\n            from public.driver_schedule_days current_month_day\r\n            where current_month_day.period_id =\r\n                created_schedule_period.id\r\n              and current_month_day.assigned_user_id =\r\n                profile.id\r\n          ) as current_month_assignments\r\n\r\n        from public.profiles profile\r\n\r\n        left join public.driver_availability_entries\r\n          availability_entry\r\n          on availability_entry.user_id =\r\n            profile.id\r\n          and availability_entry.period_id =\r\n            availability_period.id\r\n          and availability_entry.day_id =\r\n            availability_day.id\r\n\r\n        where profile.role =\r\n            'on_call'::public.user_role\r\n          and profile.is_active = true\r\n          and profile.id <>\r\n            selected_original_user_id\r\n          and (\r\n            availability_entry.availability_status\r\n              is null\r\n            or\r\n            availability_entry.availability_status <>\r\n              'unavailable'\r\n          )\r\n          and not exists (\r\n            select 1\r\n            from public.driver_schedule_days previous_actual_day\r\n            where previous_actual_day.period_id =\r\n                created_schedule_period.id\r\n              and previous_actual_day.duty_date =\r\n                availability_day.availability_date -\r\n                1\r\n              and previous_actual_day.assigned_user_id =\r\n                profile.id\r\n          )\r\n      ) candidate\r\n\r\n      order by\r\n        case\r\n          when candidate.availability_status =\r\n            'available'\r\n          then 0\r\n          else 1\r\n        end,\r\n\r\n        candidate.current_month_assignments,\r\n\r\n        case\r\n          when candidate.last_assignment_date\r\n            is null\r\n          then 0\r\n          when candidate.gap_days >= 5\r\n          then 0\r\n          else 1\r\n        end,\r\n\r\n        candidate.last_assignment_date\r\n          nulls first,\r\n\r\n        candidate.user_id\r\n\r\n      limit 1;\r\n\r\n      if selected_user_id is null then\r\n        selected_warning_text :=\r\n          'לא נמצא מחליף זמין לכונן המקורי ברוטציה.';\r\n\r\n        warning_count :=\r\n          warning_count + 1;\r\n      else\r\n        selected_warning_text :=\r\n          'שיבוץ חלופי עקב אילוץ של הכונן המקורי ברוטציה.';\r\n\r\n        warning_count :=\r\n          warning_count + 1;\r\n      end if;\r\n    end if;\r\n\r\n    if (\r\n      selected_user_id is not null\r\n      and selected_user_id is distinct from\r\n        selected_original_user_id\r\n      and selected_gap_days between 2 and 4\r\n      and selected_warning_text is null\r\n    ) then\r\n      selected_spacing_warning :=\r\n        true;\r\n\r\n      selected_warning_text :=\r\n        format(\r\n          'אזהרה: הכונן שובץ לאחר מרווח של %s ימים בלבד מהכוננות הקודמת.',\r\n          selected_gap_days\r\n        );\r\n\r\n      warning_count :=\r\n        warning_count + 1;\r\n    end if;\r\n\r\n    insert into public.driver_schedule_days (\r\n      period_id,\r\n      duty_date,\r\n      weekday_number,\r\n      weekday_name,\r\n      original_user_id,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes\r\n    )\r\n    values (\r\n      created_schedule_period.id,\r\n      availability_day.availability_date,\r\n      availability_day.weekday_number,\r\n      availability_day.weekday_name,\r\n      selected_original_user_id,\r\n      selected_user_id,\r\n\r\n      case\r\n        when selected_user_id is null\r\n        then null\r\n\r\n        else\r\n          'automatic'\r\n            ::public.driver_assignment_source\r\n      end,\r\n\r\n      false,\r\n      selected_warning_text\r\n    );\r\n\r\n    created_days_count :=\r\n      created_days_count + 1;\r\n\r\n    if selected_user_id is null then\r\n      unassigned_days_count :=\r\n        unassigned_days_count + 1;\r\n    else\r\n      assigned_days_count :=\r\n        assigned_days_count + 1;\r\n    end if;\r\n  end loop;\r\n\r\n  /*\r\n   * הטריגר מתעד רק עדכונים.\r\n   * לכן השיבוצים הראשוניים נרשמים כאן.\r\n   */\r\n  insert into\r\n    public.driver_schedule_assignment_history (\r\n      schedule_day_id,\r\n      previous_user_id,\r\n      new_user_id,\r\n      change_type,\r\n      changed_by,\r\n      note\r\n    )\r\n  select\r\n    schedule_day.id,\r\n    null,\r\n    schedule_day.assigned_user_id,\r\n    'automatic_assignment'\r\n      ::public.driver_assignment_change_type,\r\n    current_user_id,\r\n\r\n    case\r\n      when schedule_day.notes is not null\r\n      then\r\n        'יצירת טיוטה אוטומטית. '\r\n        || schedule_day.notes\r\n\r\n      else\r\n        'יצירת טיוטת שיבוץ אוטומטית'\r\n    end\r\n\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n\r\n  where schedule_day.period_id =\r\n    created_schedule_period.id\r\n    and schedule_day.assigned_user_id\r\n      is not null;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'scheduleDayId',\r\n            schedule_day.id,\r\n\r\n          'dutyDate',\r\n            schedule_day.duty_date,\r\n\r\n          'weekdayNumber',\r\n            schedule_day.weekday_number,\r\n\r\n          'weekdayName',\r\n            schedule_day.weekday_name,\r\n\r\n          'originalUserId',\r\n            schedule_day.original_user_id,\r\n\r\n          'assignedUserId',\r\n            schedule_day.assigned_user_id,\r\n\r\n          'assignmentSource',\r\n            schedule_day.assignment_source,\r\n\r\n          'isAssigned',\r\n            schedule_day.assigned_user_id\r\n              is not null,\r\n\r\n          'notes',\r\n            schedule_day.notes,\r\n\r\n          'spacingWarning',\r\n            schedule_day.notes is not null\r\n        )\r\n        order by\r\n          schedule_day.duty_date\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into assignments_json\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n  where schedule_day.period_id =\r\n    created_schedule_period.id;\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      created_schedule_period.id,\r\n\r\n    'availabilityPeriodId',\r\n      availability_period.id,\r\n\r\n    'year',\r\n      created_schedule_period.year,\r\n\r\n    'month',\r\n      created_schedule_period.month,\r\n\r\n    'status',\r\n      created_schedule_period.status,\r\n\r\n    'activeDrivers',\r\n      active_drivers_count,\r\n\r\n    'rotationUsers',\r\n      to_jsonb(\r\n        rotation_users\r\n      ),\r\n\r\n    'rotationHistoryRows',\r\n      rotation_history_rows,\r\n\r\n    'createdDays',\r\n      created_days_count,\r\n\r\n    'assignedDays',\r\n      assigned_days_count,\r\n\r\n    'unassignedDays',\r\n      unassigned_days_count,\r\n\r\n    'warningCount',\r\n      warning_count,\r\n\r\n    'hasWarnings',\r\n      (\r\n        warning_count > 0\r\n        or unassigned_days_count > 0\r\n      ),\r\n\r\n    'createdAt',\r\n      created_schedule_period.created_at,\r\n\r\n    'assignments',\r\n      assignments_json\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_morning_driver_availability_period(integer,integer,text,text,timestamp with time zone)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_morning_driver_availability_period(requested_year integer, requested_month integer, requested_title text DEFAULT NULL::text, requested_instructions text DEFAULT NULL::text, requested_submission_deadline timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  created_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  current_date_value date;\r\n  last_date_value date;\r\n\r\n  weekday_number_value integer;\r\n  weekday_name_value text;\r\n\r\n  created_shifts integer := 0;\r\n  current_sort_order integer := 1;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_year is null\r\n     or requested_year < 2020\r\n     or requested_year > 2100\r\n  then\r\n    raise exception\r\n      'invalid year';\r\n  end if;\r\n\r\n  if requested_month is null\r\n     or requested_month < 1\r\n     or requested_month > 12\r\n  then\r\n    raise exception\r\n      'invalid month';\r\n  end if;\r\n\r\n  if requested_submission_deadline is null then\r\n    raise exception\r\n      'submission deadline is required';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.morning_driver_availability_periods\r\n    where year = requested_year\r\n      and month = requested_month\r\n  ) then\r\n    raise exception\r\n      'morning driver availability period already exists';\r\n  end if;\r\n\r\n  insert into public.morning_driver_availability_periods (\r\n    year,\r\n    month,\r\n    status,\r\n    title,\r\n    instructions,\r\n    submission_deadline,\r\n    created_by,\r\n    updated_by\r\n  )\r\n  values (\r\n    requested_year,\r\n    requested_month,\r\n    'draft',\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_title,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    ),\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_instructions,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    ),\r\n    requested_submission_deadline,\r\n    current_user_id,\r\n    current_user_id\r\n  )\r\n  returning *\r\n  into created_period;\r\n\r\n  current_date_value :=\r\n    make_date(\r\n      requested_year,\r\n      requested_month,\r\n      1\r\n    );\r\n\r\n  last_date_value :=\r\n    (\r\n      current_date_value\r\n      + interval '1 month'\r\n      - interval '1 day'\r\n    )::date;\r\n\r\n  while current_date_value <= last_date_value loop\r\n    weekday_number_value :=\r\n      extract(\r\n        dow\r\n        from current_date_value\r\n      )::integer;\r\n\r\n    weekday_name_value :=\r\n      case weekday_number_value\r\n        when 0 then 'ראשון'\r\n        when 1 then 'שני'\r\n        when 2 then 'שלישי'\r\n        when 3 then 'רביעי'\r\n        when 4 then 'חמישי'\r\n        when 5 then 'שישי'\r\n        when 6 then 'שבת'\r\n      end;\r\n\r\n    /*\r\n     * ימים א׳–ה׳:\r\n     * 06:00–16:00 — שני עובדים.\r\n     * 15:00–23:00 — עובד אחד.\r\n     */\r\n    if weekday_number_value between 0 and 4 then\r\n      insert into public.morning_driver_availability_shifts (\r\n        period_id,\r\n        shift_date,\r\n        weekday_number,\r\n        weekday_name,\r\n        shift_type,\r\n        start_time,\r\n        end_time,\r\n        required_workers,\r\n        sort_order\r\n      )\r\n      values (\r\n        created_period.id,\r\n        current_date_value,\r\n        weekday_number_value,\r\n        weekday_name_value,\r\n        'weekday_morning',\r\n        time '06:00',\r\n        time '16:00',\r\n        2,\r\n        current_sort_order\r\n      );\r\n\r\n      created_shifts :=\r\n        created_shifts + 1;\r\n\r\n      current_sort_order :=\r\n        current_sort_order + 1;\r\n\r\n      insert into public.morning_driver_availability_shifts (\r\n        period_id,\r\n        shift_date,\r\n        weekday_number,\r\n        weekday_name,\r\n        shift_type,\r\n        start_time,\r\n        end_time,\r\n        required_workers,\r\n        sort_order\r\n      )\r\n      values (\r\n        created_period.id,\r\n        current_date_value,\r\n        weekday_number_value,\r\n        weekday_name_value,\r\n        'weekday_evening',\r\n        time '15:00',\r\n        time '23:00',\r\n        1,\r\n        current_sort_order\r\n      );\r\n\r\n      created_shifts :=\r\n        created_shifts + 1;\r\n\r\n      current_sort_order :=\r\n        current_sort_order + 1;\r\n\r\n    /*\r\n     * יום שישי:\r\n     * 06:00–14:00 — עובד אחד.\r\n     */\r\n    elsif weekday_number_value = 5 then\r\n      insert into public.morning_driver_availability_shifts (\r\n        period_id,\r\n        shift_date,\r\n        weekday_number,\r\n        weekday_name,\r\n        shift_type,\r\n        start_time,\r\n        end_time,\r\n        required_workers,\r\n        sort_order\r\n      )\r\n      values (\r\n        created_period.id,\r\n        current_date_value,\r\n        weekday_number_value,\r\n        weekday_name_value,\r\n        'friday_morning',\r\n        time '06:00',\r\n        time '14:00',\r\n        1,\r\n        current_sort_order\r\n      );\r\n\r\n      created_shifts :=\r\n        created_shifts + 1;\r\n\r\n      current_sort_order :=\r\n        current_sort_order + 1;\r\n    end if;\r\n\r\n    current_date_value :=\r\n      current_date_value + 1;\r\n  end loop;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'morning_driver_availability_period_created'\r\n        ::public.audit_action_type,\r\n\r\n    requested_target_user_id :=\r\n      null,\r\n\r\n    requested_summary :=\r\n      'נוצר חודש אילוצים לכונני בוקר',\r\n\r\n    requested_old_values :=\r\n      null,\r\n\r\n    requested_new_values :=\r\n      jsonb_build_object(\r\n        'periodId',\r\n          created_period.id,\r\n\r\n        'year',\r\n          created_period.year,\r\n\r\n        'month',\r\n          created_period.month,\r\n\r\n        'status',\r\n          created_period.status,\r\n\r\n        'createdShifts',\r\n          created_shifts\r\n      ),\r\n\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'entityType',\r\n          'morning_driver_availability_period'\r\n      )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      created_period.id,\r\n\r\n    'year',\r\n      created_period.year,\r\n\r\n    'month',\r\n      created_period.month,\r\n\r\n    'status',\r\n      created_period.status,\r\n\r\n    'title',\r\n      created_period.title,\r\n\r\n    'instructions',\r\n      created_period.instructions,\r\n\r\n    'submissionDeadline',\r\n      created_period.submission_deadline,\r\n\r\n    'createdShifts',\r\n      created_shifts\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_morning_driver_schedule_draft(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_morning_driver_schedule_draft(requested_availability_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  availability_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  schedule_period\r\n    public.morning_driver_schedule_periods%rowtype;\r\n\r\n  current_shift\r\n    public.morning_driver_availability_shifts%rowtype;\r\n\r\n  candidate_user_id uuid;\r\n\r\n  slot_number integer;\r\n\r\n  slots_to_create integer;\r\n\r\n  created_assignments integer := 0;\r\n\r\n  assigned_assignments integer := 0;\r\n\r\n  warning_count integer := 0;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_schedule.edit'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into availability_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id =\r\n    requested_availability_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver availability period not found';\r\n  end if;\r\n\r\n  if availability_period.status <>\r\n    'closed'\r\n  then\r\n    raise exception\r\n      'availability period must be closed before scheduling';\r\n  end if;\r\n\r\n  insert into public.morning_driver_schedule_periods (\r\n    year,\r\n    month,\r\n    status,\r\n    availability_period_id,\r\n    title,\r\n    created_by,\r\n    updated_by\r\n  )\r\n  values (\r\n    availability_period.year,\r\n\r\n    availability_period.month,\r\n\r\n    'draft',\r\n\r\n    availability_period.id,\r\n\r\n    coalesce(\r\n      availability_period.title,\r\n      format(\r\n        'לוח כונני בוקר %s/%s',\r\n        availability_period.month,\r\n        availability_period.year\r\n      )\r\n    ),\r\n\r\n    current_user_id,\r\n\r\n    current_user_id\r\n  )\r\n  on conflict (\r\n    availability_period_id\r\n  )\r\n  do update\r\n  set\r\n    updated_by =\r\n      excluded.updated_by,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  returning *\r\n  into schedule_period;\r\n\r\n  delete from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id =\r\n      schedule_period.id\r\n    and assignment.is_locked = false;\r\n\r\n  for current_shift\r\n  in\r\n    select *\r\n    from public.morning_driver_availability_shifts shift_item\r\n    where shift_item.period_id =\r\n      availability_period.id\r\n    order by\r\n      shift_item.shift_date,\r\n      shift_item.sort_order\r\n  loop\r\n    /*\r\n     * required_workers הוא מספר\r\n     * המקומות המומלץ.\r\n     *\r\n     * בוקר רגיל:\r\n     * 2 Slots.\r\n     *\r\n     * ערב ושישי:\r\n     * Slot אחד.\r\n     */\r\n    slots_to_create :=\r\n      least(\r\n        greatest(\r\n          coalesce(\r\n            current_shift.required_workers,\r\n            1\r\n          ),\r\n          1\r\n        ),\r\n        2\r\n      );\r\n\r\n    for slot_number\r\n    in 1..slots_to_create\r\n    loop\r\n      candidate_user_id :=\r\n        null;\r\n\r\n      select\r\n        candidate.id\r\n      into\r\n        candidate_user_id\r\n      from public.profiles candidate\r\n      where candidate.role =\r\n          'morning_driver'\r\n            ::public.user_role\r\n\r\n        and candidate.is_active = true\r\n\r\n        and exists (\r\n          select 1\r\n          from public.morning_driver_availability_entries entry\r\n          where entry.period_id =\r\n              availability_period.id\r\n\r\n            and entry.shift_id =\r\n              current_shift.id\r\n\r\n            and entry.user_id =\r\n              candidate.id\r\n\r\n            and entry.availability_status =\r\n              'available'\r\n        )\r\n\r\n        and not exists (\r\n          select 1\r\n          from public.morning_driver_schedule_assignments same_shift\r\n          where same_shift.schedule_period_id =\r\n              schedule_period.id\r\n\r\n            and same_shift.availability_shift_id =\r\n              current_shift.id\r\n\r\n            and same_shift.assigned_user_id =\r\n              candidate.id\r\n        )\r\n\r\n        and not exists (\r\n          select 1\r\n          from public.morning_driver_schedule_assignments same_day\r\n\r\n          join public.morning_driver_availability_shifts other_shift\r\n            on other_shift.id =\r\n              same_day.availability_shift_id\r\n\r\n          where same_day.schedule_period_id =\r\n              schedule_period.id\r\n\r\n            and same_day.assigned_user_id =\r\n              candidate.id\r\n\r\n            and other_shift.shift_date =\r\n              current_shift.shift_date\r\n        )\r\n\r\n      order by\r\n        (\r\n          select\r\n            count(*)\r\n          from public.morning_driver_schedule_assignments existing_assignment\r\n          where existing_assignment.schedule_period_id =\r\n              schedule_period.id\r\n\r\n            and existing_assignment.assigned_user_id =\r\n              candidate.id\r\n        ) asc,\r\n\r\n        candidate.id\r\n\r\n      limit 1;\r\n\r\n      insert into public.morning_driver_schedule_assignments (\r\n        schedule_period_id,\r\n        availability_shift_id,\r\n        assignment_slot,\r\n        assigned_user_id,\r\n        assignment_source,\r\n        is_locked,\r\n        notes\r\n      )\r\n      values (\r\n        schedule_period.id,\r\n\r\n        current_shift.id,\r\n\r\n        slot_number,\r\n\r\n        candidate_user_id,\r\n\r\n        case\r\n          when candidate_user_id\r\n            is null\r\n          then\r\n            null\r\n          else\r\n            'automatic'\r\n        end,\r\n\r\n        false,\r\n\r\n        case\r\n          when candidate_user_id\r\n            is null\r\n            and slot_number = 1\r\n          then\r\n            'לא נמצא כונן זמין למינימום הנדרש.'\r\n\r\n          when candidate_user_id\r\n            is null\r\n            and slot_number > 1\r\n          then\r\n            'לא נמצא כונן נוסף להשלמת ההמלצה.'\r\n\r\n          else\r\n            null\r\n        end\r\n      )\r\n      on conflict (\r\n        schedule_period_id,\r\n        availability_shift_id,\r\n        assignment_slot\r\n      )\r\n      do update\r\n      set\r\n        assigned_user_id =\r\n          case\r\n            when public\r\n              .morning_driver_schedule_assignments\r\n              .is_locked\r\n            then public\r\n              .morning_driver_schedule_assignments\r\n              .assigned_user_id\r\n            else\r\n              excluded.assigned_user_id\r\n          end,\r\n\r\n        assignment_source =\r\n          case\r\n            when public\r\n              .morning_driver_schedule_assignments\r\n              .is_locked\r\n            then public\r\n              .morning_driver_schedule_assignments\r\n              .assignment_source\r\n            else\r\n              excluded.assignment_source\r\n          end,\r\n\r\n        notes =\r\n          case\r\n            when public\r\n              .morning_driver_schedule_assignments\r\n              .is_locked\r\n            then public\r\n              .morning_driver_schedule_assignments\r\n              .notes\r\n            else\r\n              excluded.notes\r\n          end,\r\n\r\n        updated_at =\r\n          now();\r\n\r\n      created_assignments :=\r\n        created_assignments + 1;\r\n\r\n      if candidate_user_id is null then\r\n        warning_count :=\r\n          warning_count + 1;\r\n      else\r\n        assigned_assignments :=\r\n          assigned_assignments + 1;\r\n      end if;\r\n    end loop;\r\n  end loop;\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      schedule_period.id,\r\n\r\n    'year',\r\n      schedule_period.year,\r\n\r\n    'month',\r\n      schedule_period.month,\r\n\r\n    'status',\r\n      schedule_period.status,\r\n\r\n    'createdAssignments',\r\n      created_assignments,\r\n\r\n    'assignedAssignments',\r\n      assigned_assignments,\r\n\r\n    'warningCount',\r\n      warning_count\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_shift_swap_request(text,uuid,uuid,uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_shift_swap_request(requested_swap_type text, requested_requester_shift_id uuid, requested_counterparty_user_id uuid, requested_counterparty_shift_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  requester_shift public.schedule_shifts%rowtype;\r\n  counterparty_shift public.schedule_shifts%rowtype;\r\n  requester_period public.schedule_periods%rowtype;\r\n  requester_profile public.profiles%rowtype;\r\n  counterparty_profile public.profiles%rowtype;\r\n  validation_result jsonb;\r\n  created_request public.shift_swap_requests%rowtype;\r\n  israel_today date := (now() at time zone 'Asia/Jerusalem')::date;\r\n  current_month_start date := date_trunc('month', israel_today)::date;\r\n  next_month_start date := (date_trunc('month', israel_today) + interval '1 month')::date;\r\n  month_after_next_start date := (date_trunc('month', israel_today) + interval '2 months')::date;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'לא נמצאה התחברות פעילה.';\r\n  end if;\r\n\r\n  if not public.current_user_has_permission('shift_swaps.view') then\r\n    raise exception 'אין לך הרשאה להגיש בקשות להחלפת משמרות.';\r\n  end if;\r\n\r\n  if requested_swap_type not in ('one_way', 'two_way') then\r\n    raise exception 'סוג ההחלפה אינו תקין.';\r\n  end if;\r\n\r\n  select *\r\n  into requester_profile\r\n  from public.profiles\r\n  where id = current_user_id\r\n    and is_active = true;\r\n\r\n  if not found or requester_profile.role::text <> 'dispatcher' then\r\n    raise exception 'בקשות להחלפת משמרות זמינות למוקדנים בלבד.';\r\n  end if;\r\n\r\n  select *\r\n  into counterparty_profile\r\n  from public.profiles\r\n  where id = requested_counterparty_user_id\r\n    and is_active = true;\r\n\r\n  if not found or counterparty_profile.role::text <> 'dispatcher' then\r\n    raise exception 'המוקדן המחליף אינו משתמש מוקדן פעיל.';\r\n  end if;\r\n\r\n  if requested_counterparty_user_id = current_user_id then\r\n    raise exception 'לא ניתן להגיש בקשת החלפה מול עצמך.';\r\n  end if;\r\n\r\n  select *\r\n  into requester_shift\r\n  from public.schedule_shifts\r\n  where id = requested_requester_shift_id;\r\n\r\n  if not found then\r\n    raise exception 'המשמרת שנבחרה לא נמצאה.';\r\n  end if;\r\n\r\n  if requester_shift.assigned_user_id is distinct from current_user_id then\r\n    raise exception 'ניתן להגיש בקשה רק עבור משמרת שמשובצת אליך.';\r\n  end if;\r\n\r\n  if requester_shift.starts_at <= now() then\r\n    raise exception 'לא ניתן להגיש בקשה עבור משמרת שכבר התחילה.';\r\n  end if;\r\n\r\n  select *\r\n  into requester_period\r\n  from public.schedule_periods\r\n  where id = requester_shift.period_id;\r\n\r\n  if not found or requester_period.status::text <> 'published' then\r\n    raise exception 'ניתן להגיש בקשה רק עבור לוח שיבוצים שפורסם.';\r\n  end if;\r\n\r\n  if make_date(requester_period.year, requester_period.month, 1)\r\n      < current_month_start\r\n    or make_date(requester_period.year, requester_period.month, 1)\r\n      >= month_after_next_start then\r\n    raise exception 'ניתן להגיש בקשות רק עבור החודש הנוכחי או החודש הבא.';\r\n  end if;\r\n\r\n  if make_date(requester_period.year, requester_period.month, 1)\r\n      = next_month_start\r\n    and requester_period.status::text <> 'published' then\r\n    raise exception 'בקשות לחודש הבא זמינות רק לאחר פרסום הלוח.';\r\n  end if;\r\n\r\n  if requested_swap_type = 'one_way' then\r\n    if requested_counterparty_shift_id is not null then\r\n      raise exception 'בהחלפה חד-כיוונית אין לבחור משמרת נגדית.';\r\n    end if;\r\n  else\r\n    select *\r\n    into counterparty_shift\r\n    from public.schedule_shifts\r\n    where id = requested_counterparty_shift_id;\r\n\r\n    if not found then\r\n      raise exception 'המשמרת של המוקדן השני לא נמצאה.';\r\n    end if;\r\n\r\n    if counterparty_shift.period_id <> requester_shift.period_id then\r\n      raise exception 'בהחלפה דו-כיוונית שתי המשמרות חייבות להיות מאותו חודש שיבוץ.';\r\n    end if;\r\n\r\n    if counterparty_shift.assigned_user_id is distinct from requested_counterparty_user_id then\r\n      raise exception 'המשמרת שנבחרה אינה משובצת כרגע למוקדן השני.';\r\n    end if;\r\n\r\n    if counterparty_shift.starts_at <= now() then\r\n      raise exception 'לא ניתן להחליף משמרת שכבר התחילה.';\r\n    end if;\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.shift_swap_requests r\r\n    where r.status in ('pending_counterparty', 'pending_manager')\r\n      and (\r\n        r.requester_shift_id = requested_requester_shift_id\r\n        or r.counterparty_shift_id = requested_requester_shift_id\r\n        or (\r\n          requested_counterparty_shift_id is not null\r\n          and (\r\n            r.requester_shift_id = requested_counterparty_shift_id\r\n            or r.counterparty_shift_id = requested_counterparty_shift_id\r\n          )\r\n        )\r\n      )\r\n  ) then\r\n    raise exception 'קיימת כבר בקשת החלפה פעילה עבור אחת המשמרות שנבחרו.';\r\n  end if;\r\n\r\n  validation_result := public.validate_shift_swap_final_state(\r\n    requested_swap_type,\r\n    current_user_id,\r\n    requested_counterparty_user_id,\r\n    requested_requester_shift_id,\r\n    requested_counterparty_shift_id\r\n  );\r\n\r\n  if not coalesce((validation_result ->> 'valid')::boolean, false) then\r\n    raise exception '%', validation_result ->> 'message';\r\n  end if;\r\n\r\n  insert into public.shift_swap_requests (\r\n    swap_type,\r\n    status,\r\n    requester_user_id,\r\n    counterparty_user_id,\r\n    requester_shift_id,\r\n    counterparty_shift_id\r\n  )\r\n  values (\r\n    requested_swap_type,\r\n    'pending_counterparty',\r\n    current_user_id,\r\n    requested_counterparty_user_id,\r\n    requested_requester_shift_id,\r\n    requested_counterparty_shift_id\r\n  )\r\n  returning * into created_request;\r\n\r\n  return jsonb_build_object(\r\n    'id', created_request.id,\r\n    'swapType', created_request.swap_type,\r\n    'status', created_request.status,\r\n    'requesterUserId', created_request.requester_user_id,\r\n    'counterpartyUserId', created_request.counterparty_user_id,\r\n    'requesterShiftId', created_request.requester_shift_id,\r\n    'counterpartyShiftId', created_request.counterparty_shift_id,\r\n    'createdAt', created_request.created_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "create_shift_swap_workflow_notification(uuid[],uuid,uuid,text,text,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.create_shift_swap_workflow_notification(recipient_user_ids uuid[], requested_request_id uuid, requested_actor_user_id uuid, requested_event text, requested_title text, requested_body text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  created_notification_id uuid;\r\nbegin\r\n  if recipient_user_ids is null\r\n    or coalesce(array_length(recipient_user_ids, 1), 0) = 0 then\r\n    return null;\r\n  end if;\r\n\r\n  insert into public.notifications (\r\n    type,\r\n    priority,\r\n    source,\r\n    title,\r\n    body,\r\n    url,\r\n    data,\r\n    created_by,\r\n    expires_at\r\n  )\r\n  values (\r\n    'shift_swap',\r\n    'important',\r\n    'shift_swap',\r\n    requested_title,\r\n    requested_body,\r\n    '/shift-swaps',\r\n    jsonb_build_object(\r\n      'workflow', 'shift_swap',\r\n      'shiftSwapRequestId', requested_request_id,\r\n      'actorUserId', requested_actor_user_id,\r\n      'event', requested_event\r\n    ),\r\n    requested_actor_user_id,\r\n    now() + interval '90 days'\r\n  )\r\n  returning id into created_notification_id;\r\n\r\n  insert into public.notification_recipients (\r\n    notification_id,\r\n    user_id\r\n  )\r\n  select\r\n    created_notification_id,\r\n    recipient_id\r\n  from (\r\n    select distinct unnest(recipient_user_ids) as recipient_id\r\n  ) recipients\r\n  join public.profiles p\r\n    on p.id = recipients.recipient_id\r\n   and p.is_active = true;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.notification_recipients nr\r\n    where nr.notification_id = created_notification_id\r\n  ) then\r\n    delete from public.notifications\r\n    where id = created_notification_id;\r\n\r\n    return null;\r\n  end if;\r\n\r\n  return created_notification_id;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "current_user_created_notification(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.current_user_created_notification(requested_notification_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  select exists (\r\n    select 1\r\n    from public.notifications n\r\n    where n.id = requested_notification_id\r\n      and n.created_by = auth.uid()\r\n  );\r\n$function$\n"
  },
  {
    "function_signature": "current_user_has_permission(text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.current_user_has_permission(requested_permission text)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  select\r\n    coalesce(\r\n      to_jsonb(public.get_my_permissions())\r\n        @> jsonb_build_array(requested_permission),\r\n      false\r\n    );\r\n$function$\n"
  },
  {
    "function_signature": "current_user_role()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.current_user_role()\n RETURNS user_role\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  select profile.role\r\n  from public.profiles as profile\r\n  where profile.id = (select auth.uid())\r\n    and profile.is_active = true\r\n  limit 1;\r\n$function$\n"
  },
  {
    "function_signature": "delete_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.delete_availability_period(requested_period_id uuid)\n RETURNS TABLE(deleted_period_id uuid, deleted_period_title text, deleted_period_year integer, deleted_period_month integer, deleted_shift_slots integer, deleted_availability_rows integer, deleted_submissions integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_actor_email text;\r\n  current_actor_display_name text;\r\n\r\n  target_period_title text;\r\n  target_period_year integer;\r\n  target_period_month integer;\r\n  target_period_status text;\r\n\r\n  calculated_shift_slots integer;\r\n  calculated_availability_rows integer;\r\n  calculated_submissions integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_actor_email,\r\n    current_actor_display_name\r\n  from public.profiles profile\r\n  where profile.id =\r\n    current_user_id\r\n    and profile.is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to delete availability periods';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.title,\r\n    period.year,\r\n    period.month,\r\n    period.status\r\n  into\r\n    target_period_title,\r\n    target_period_year,\r\n    target_period_month,\r\n    target_period_status\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_shift_slots\r\n  from public.availability_shift_slots slot\r\n  where slot.period_id =\r\n    requested_period_id;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_availability_rows\r\n  from public.dispatcher_availability availability\r\n  where availability.period_id =\r\n    requested_period_id;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_submissions\r\n  from public.availability_submissions submission\r\n  where submission.period_id =\r\n    requested_period_id;\r\n\r\n  /*\r\n   * סדר המחיקה חשוב:\r\n   * קודם רשומות שתלויות במשמרות,\r\n   * אחר כך ההגשות והמשמרות,\r\n   * ולבסוף התקופה עצמה.\r\n   */\r\n\r\n  delete from\r\n    public.dispatcher_availability\r\n  where period_id =\r\n    requested_period_id;\r\n\r\n  delete from\r\n    public.availability_submissions\r\n  where period_id =\r\n    requested_period_id;\r\n\r\n  delete from\r\n    public.availability_shift_slots\r\n  where period_id =\r\n    requested_period_id;\r\n\r\n  delete from\r\n    public.availability_periods\r\n  where id =\r\n    requested_period_id;\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    'availability_period_deleted',\r\n\r\n    current_user_id,\r\n    current_actor_email,\r\n    current_actor_display_name,\r\n\r\n    null,\r\n    null,\r\n    null,\r\n\r\n    'availability_period',\r\n    requested_period_id,\r\n\r\n    format(\r\n      'נמחקה תקופת אילוצים: %s',\r\n      coalesce(\r\n        target_period_title,\r\n        format(\r\n          '%s/%s',\r\n          target_period_month,\r\n          target_period_year\r\n        )\r\n      )\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'id',\r\n      requested_period_id,\r\n\r\n      'title',\r\n      target_period_title,\r\n\r\n      'year',\r\n      target_period_year,\r\n\r\n      'month',\r\n      target_period_month,\r\n\r\n      'status',\r\n      target_period_status,\r\n\r\n      'shift_slots',\r\n      calculated_shift_slots,\r\n\r\n      'availability_rows',\r\n      calculated_availability_rows,\r\n\r\n      'submissions',\r\n      calculated_submissions\r\n    ),\r\n\r\n    null,\r\n\r\n    jsonb_build_object(\r\n      'source',\r\n      'delete-availability-period-rpc',\r\n\r\n      'deleted_by',\r\n      current_user_id\r\n    )\r\n  );\r\n\r\n  return query\r\n  select\r\n    requested_period_id,\r\n    target_period_title,\r\n    target_period_year,\r\n    target_period_month,\r\n    calculated_shift_slots,\r\n    calculated_availability_rows,\r\n    calculated_submissions;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "delete_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.delete_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  period_to_delete public.driver_availability_periods%rowtype;\r\n  deleted_days integer;\r\n  deleted_entries integer;\r\n  deleted_submissions integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not public.is_manager_or_admin() then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into period_to_delete\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_periods schedule_period\r\n    where schedule_period.availability_period_id =\r\n      requested_period_id\r\n  ) then\r\n    raise exception\r\n      'driver availability period already has a schedule';\r\n  end if;\r\n\r\n  select count(*)::integer\r\n  into deleted_days\r\n  from public.driver_availability_days\r\n  where period_id =\r\n    requested_period_id;\r\n\r\n  select count(*)::integer\r\n  into deleted_entries\r\n  from public.driver_availability_entries availability_entry\r\n  join public.driver_availability_days availability_day\r\n    on availability_day.id =\r\n      availability_entry.day_id\r\n  where availability_day.period_id =\r\n    requested_period_id;\r\n\r\n  select count(*)::integer\r\n  into deleted_submissions\r\n  from public.driver_availability_submissions\r\n  where period_id =\r\n    requested_period_id;\r\n\r\n  delete from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'driver_availability_period_deleted'::public.audit_action_type,\r\n    requested_target_user_id :=\r\n      null,\r\n    requested_summary :=\r\n      'Driver availability period deleted',\r\n    requested_old_values :=\r\n      jsonb_build_object(\r\n        'periodId',\r\n        period_to_delete.id,\r\n        'year',\r\n        period_to_delete.year,\r\n        'month',\r\n        period_to_delete.month,\r\n        'status',\r\n        period_to_delete.status\r\n      ),\r\n    requested_new_values :=\r\n      null,\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'deletedDays',\r\n        deleted_days,\r\n        'deletedEntries',\r\n        deleted_entries,\r\n        'deletedSubmissions',\r\n        deleted_submissions\r\n      )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'deletedPeriodId',\r\n      period_to_delete.id,\r\n    'year',\r\n      period_to_delete.year,\r\n    'month',\r\n      period_to_delete.month,\r\n    'title',\r\n      period_to_delete.title,\r\n    'deletedDays',\r\n      deleted_days,\r\n    'deletedEntries',\r\n      deleted_entries,\r\n    'deletedSubmissions',\r\n      deleted_submissions\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "delete_morning_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.delete_morning_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  deleted_shifts integer;\r\n  deleted_submissions integer;\r\n  deleted_entries integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods\r\n  where id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'draft' then\r\n    raise exception\r\n      'only draft periods can be deleted';\r\n  end if;\r\n\r\n  select count(*)\r\n  into deleted_shifts\r\n  from public.morning_driver_availability_shifts\r\n  where period_id = target_period.id;\r\n\r\n  select count(*)\r\n  into deleted_submissions\r\n  from public.morning_driver_availability_submissions\r\n  where period_id = target_period.id;\r\n\r\n  select count(*)\r\n  into deleted_entries\r\n  from public.morning_driver_availability_entries\r\n  where period_id = target_period.id;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'morning_driver_availability_period_deleted'\r\n        ::public.audit_action_type,\r\n\r\n    requested_target_user_id :=\r\n      null,\r\n\r\n    requested_summary :=\r\n      'נמחק חודש אילוצים לכונני בוקר',\r\n\r\n    requested_old_values :=\r\n      jsonb_build_object(\r\n        'periodId',\r\n          target_period.id,\r\n\r\n        'year',\r\n          target_period.year,\r\n\r\n        'month',\r\n          target_period.month,\r\n\r\n        'status',\r\n          target_period.status\r\n      ),\r\n\r\n    requested_new_values :=\r\n      null,\r\n\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'deletedShifts',\r\n          deleted_shifts,\r\n\r\n        'deletedSubmissions',\r\n          deleted_submissions,\r\n\r\n        'deletedEntries',\r\n          deleted_entries\r\n      )\r\n  );\r\n\r\n  delete from public.morning_driver_availability_periods\r\n  where id = target_period.id;\r\n\r\n  return jsonb_build_object(\r\n    'deletedPeriodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'deletedShifts',\r\n      deleted_shifts,\r\n\r\n    'deletedSubmissions',\r\n      deleted_submissions,\r\n\r\n    'deletedEntries',\r\n      deleted_entries\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "execute_schedule_excel_import(text,bigint,integer,integer,text,text,jsonb,jsonb,jsonb,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.execute_schedule_excel_import(requested_file_name text, requested_file_size_bytes bigint, requested_year integer, requested_month integer, requested_period_type text, requested_import_strategy text, requested_dispatcher_shifts jsonb, requested_driver_duties jsonb, requested_morning_driver_shifts jsonb, requested_warnings jsonb DEFAULT '[]'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  preview_result jsonb;\r\n\r\n  base_result jsonb;\r\n\r\n  morning_result jsonb;\r\nbegin\r\n  /*\r\n   * סימולציה משותפת לכל שלושת\r\n   * סוגי השיבוצים:\r\n   *\r\n   * - מוקדנים.\r\n   * - כוננים טכניים.\r\n   * - כונני בוקר.\r\n   */\r\n  preview_result :=\r\n    public.preview_schedule_excel_import(\r\n      requested_year,\r\n      requested_month,\r\n      requested_period_type,\r\n      requested_import_strategy,\r\n      requested_dispatcher_shifts,\r\n      requested_driver_duties,\r\n      requested_morning_driver_shifts\r\n    );\r\n\r\n  if not coalesce(\r\n    (\r\n      preview_result\r\n        ->> 'canImport'\r\n    )::boolean,\r\n    false\r\n  ) then\r\n    raise exception\r\n      'import blocked: %',\r\n      preview_result\r\n        -> 'blockers';\r\n  end if;\r\n\r\n  /*\r\n   * הפונקציה הקיימת בעלת תשעת\r\n   * הפרמטרים מטפלת במוקדנים\r\n   * ובכוננים הטכניים.\r\n   *\r\n   * הקריאה נעשית באמצעות שמות\r\n   * פרמטרים כדי למנוע דו־משמעות\r\n   * מול הגרסה החדשה של הפונקציה.\r\n   */\r\n  base_result :=\r\n    public.execute_schedule_excel_import(\r\n      requested_file_name =>\r\n        requested_file_name,\r\n\r\n      requested_file_size_bytes =>\r\n        requested_file_size_bytes,\r\n\r\n      requested_year =>\r\n        requested_year,\r\n\r\n      requested_month =>\r\n        requested_month,\r\n\r\n      requested_period_type =>\r\n        requested_period_type,\r\n\r\n      requested_import_strategy =>\r\n        requested_import_strategy,\r\n\r\n      requested_dispatcher_shifts =>\r\n        requested_dispatcher_shifts,\r\n\r\n      requested_driver_duties =>\r\n        requested_driver_duties,\r\n\r\n      requested_warnings =>\r\n        requested_warnings\r\n    );\r\n\r\n  /*\r\n   * שמירת שיבוצי כונני הבוקר\r\n   * כחלק מאותה טרנזקציה.\r\n   */\r\n  morning_result :=\r\n    public\r\n      .import_morning_driver_schedule_assignments(\r\n        (\r\n          base_result\r\n            ->> 'importRunId'\r\n        )::uuid,\r\n\r\n        requested_year,\r\n\r\n        requested_month,\r\n\r\n        requested_period_type,\r\n\r\n        requested_import_strategy,\r\n\r\n        requested_morning_driver_shifts\r\n      );\r\n\r\n  /*\r\n   * מחזירים תשובה משותפת הכוללת\r\n   * את שלושת סוגי השיבוצים.\r\n   */\r\n  return\r\n    base_result\r\n    ||\r\n    jsonb_build_object(\r\n      'morningDriverAvailabilityPeriodId',\r\n        morning_result\r\n          ->> 'availabilityPeriodId',\r\n\r\n      'morningDriverSchedulePeriodId',\r\n        morning_result\r\n          ->> 'schedulePeriodId',\r\n\r\n      'morningDriverShifts',\r\n        jsonb_build_object(\r\n          'detected',\r\n            coalesce(\r\n              (\r\n                morning_result\r\n                  ->> 'detected'\r\n              )::integer,\r\n              0\r\n            ),\r\n\r\n          'created',\r\n            coalesce(\r\n              (\r\n                morning_result\r\n                  ->> 'created'\r\n              )::integer,\r\n              0\r\n            ),\r\n\r\n          'updated',\r\n            coalesce(\r\n              (\r\n                morning_result\r\n                  ->> 'updated'\r\n              )::integer,\r\n              0\r\n            ),\r\n\r\n          'skipped',\r\n            coalesce(\r\n              (\r\n                morning_result\r\n                  ->> 'skipped'\r\n              )::integer,\r\n              0\r\n            ),\r\n\r\n          'deleted',\r\n            coalesce(\r\n              (\r\n                morning_result\r\n                  ->> 'deleted'\r\n              )::integer,\r\n              0\r\n            )\r\n        )\r\n    );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "execute_schedule_excel_import(text,bigint,integer,integer,text,text,jsonb,jsonb,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.execute_schedule_excel_import(requested_file_name text, requested_file_size_bytes bigint, requested_year integer, requested_month integer, requested_period_type text, requested_import_strategy text, requested_dispatcher_shifts jsonb, requested_driver_duties jsonb, requested_warnings jsonb DEFAULT '[]'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  preview_result jsonb;\r\n\r\n  import_run_id uuid;\r\n\r\n  resolved_schedule_period_id uuid;\r\n  resolved_driver_period_id uuid;\r\n\r\n  resolved_schedule_status\r\n    public.schedule_period_status;\r\n\r\n  resolved_driver_status\r\n    public.driver_schedule_period_status;\r\n\r\n  imported_at timestamptz :=\r\n    now();\r\n\r\n  dispatcher_created_count integer := 0;\r\n  dispatcher_updated_count integer := 0;\r\n  dispatcher_skipped_count integer := 0;\r\n  dispatcher_deleted_count integer := 0;\r\n\r\n  driver_created_count integer := 0;\r\n  driver_updated_count integer := 0;\r\n  driver_skipped_count integer := 0;\r\n  driver_deleted_count integer := 0;\r\n\r\n  dispatcher_detected_count integer := 0;\r\n  driver_detected_count integer := 0;\r\n\r\n  imported_warning_count integer := 0;\r\n\r\n  existing_schedule_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  existing_driver_period\r\n    public.driver_schedule_periods%rowtype;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile_row\r\n    where profile_row.id =\r\n      current_user_id\r\n      and profile_row.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n    or\r\n    'schedule.edit' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if nullif(\r\n    trim(\r\n      coalesce(\r\n        requested_file_name,\r\n        ''\r\n      )\r\n    ),\r\n    ''\r\n  ) is null then\r\n    raise exception\r\n      'import file name is required';\r\n  end if;\r\n\r\n  if requested_file_size_bytes is null\r\n    or requested_file_size_bytes < 0\r\n  then\r\n    raise exception\r\n      'import file size is invalid';\r\n  end if;\r\n\r\n  if requested_warnings is null then\r\n    requested_warnings :=\r\n      '[]'::jsonb;\r\n  end if;\r\n\r\n  if jsonb_typeof(\r\n    requested_warnings\r\n  ) <> 'array' then\r\n    raise exception\r\n      'import warnings must be a json array';\r\n  end if;\r\n\r\n  /*\r\n   * מריצים שוב את אותה סימולציה בצד השרת.\r\n   * כך אי אפשר לעקוף חסימות דרך ה-Frontend.\r\n   */\r\n  preview_result :=\r\n    public.preview_schedule_excel_import(\r\n      requested_year,\r\n      requested_month,\r\n      requested_period_type,\r\n      requested_import_strategy,\r\n      requested_dispatcher_shifts,\r\n      requested_driver_duties\r\n    );\r\n\r\n  if not coalesce(\r\n    (\r\n      preview_result\r\n        ->> 'canImport'\r\n    )::boolean,\r\n    false\r\n  ) then\r\n    raise exception\r\n      'import blocked: %',\r\n      preview_result\r\n        -> 'blockers';\r\n  end if;\r\n\r\n  dispatcher_detected_count :=\r\n    jsonb_array_length(\r\n      requested_dispatcher_shifts\r\n    );\r\n\r\n  driver_detected_count :=\r\n    jsonb_array_length(\r\n      requested_driver_duties\r\n    );\r\n\r\n  imported_warning_count :=\r\n    jsonb_array_length(\r\n      requested_warnings\r\n    )\r\n    +\r\n    jsonb_array_length(\r\n      coalesce(\r\n        preview_result\r\n          -> 'warnings',\r\n        '[]'::jsonb\r\n      )\r\n    );\r\n\r\n  dispatcher_created_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'dispatcherShifts'\r\n          ->> 'toCreate'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  dispatcher_updated_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'dispatcherShifts'\r\n          ->> 'toUpdate'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  dispatcher_skipped_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'dispatcherShifts'\r\n          ->> 'toSkip'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  dispatcher_deleted_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'dispatcherShifts'\r\n          ->> 'toDelete'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  driver_created_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'driverDuties'\r\n          ->> 'toCreate'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  driver_updated_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'driverDuties'\r\n          ->> 'toUpdate'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  driver_skipped_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'driverDuties'\r\n          ->> 'toSkip'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  driver_deleted_count :=\r\n    coalesce(\r\n      (\r\n        preview_result\r\n          -> 'driverDuties'\r\n          ->> 'toDelete'\r\n      )::integer,\r\n      0\r\n    );\r\n\r\n  if requested_period_type =\r\n    'historical'\r\n  then\r\n    resolved_schedule_status :=\r\n      'archived'::public.schedule_period_status;\r\n\r\n    resolved_driver_status :=\r\n      'archived'::public.driver_schedule_period_status;\r\n  else\r\n    resolved_schedule_status :=\r\n      'published'::public.schedule_period_status;\r\n\r\n    resolved_driver_status :=\r\n      'published'::public.driver_schedule_period_status;\r\n  end if;\r\n\r\n  /*\r\n   * פתיחת רשומת תיעוד הייבוא.\r\n   */\r\n  insert into public.schedule_import_runs (\r\n    file_name,\r\n    file_size_bytes,\r\n    year,\r\n    month,\r\n    period_type,\r\n    import_strategy,\r\n    status,\r\n    dispatcher_shifts_detected,\r\n    driver_duties_detected,\r\n    warning_count,\r\n    warnings,\r\n    imported_by,\r\n    started_at,\r\n    created_at,\r\n    updated_at\r\n  )\r\n  values (\r\n    trim(\r\n      requested_file_name\r\n    ),\r\n    requested_file_size_bytes,\r\n    requested_year,\r\n    requested_month,\r\n    requested_period_type,\r\n    requested_import_strategy,\r\n    'processing',\r\n    dispatcher_detected_count,\r\n    driver_detected_count,\r\n    imported_warning_count,\r\n    requested_warnings\r\n      ||\r\n      coalesce(\r\n        preview_result\r\n          -> 'warnings',\r\n        '[]'::jsonb\r\n      ),\r\n    current_user_id,\r\n    imported_at,\r\n    imported_at,\r\n    imported_at\r\n  )\r\n  returning id\r\n  into import_run_id;\r\n\r\n  /*\r\n   * תקופת שיבוץ מוקדנים.\r\n   */\r\n  select *\r\n  into existing_schedule_period\r\n  from public.schedule_periods\r\n  where year =\r\n    requested_year\r\n    and month =\r\n      requested_month\r\n  for update;\r\n\r\n  if found then\r\n    resolved_schedule_period_id :=\r\n      existing_schedule_period.id;\r\n\r\n    update public.schedule_periods\r\n    set\r\n      status =\r\n        resolved_schedule_status,\r\n\r\n      title =\r\n        coalesce(\r\n          existing_schedule_period.title,\r\n          concat(\r\n            'שיבוץ ',\r\n            requested_month,\r\n            '/',\r\n            requested_year\r\n          )\r\n        ),\r\n\r\n      published_at =\r\n        coalesce(\r\n          existing_schedule_period.published_at,\r\n          imported_at\r\n        ),\r\n\r\n      archived_at =\r\n        case\r\n          when requested_period_type =\r\n            'historical'\r\n          then\r\n            coalesce(\r\n              existing_schedule_period.archived_at,\r\n              imported_at\r\n            )\r\n          else\r\n            null\r\n        end,\r\n\r\n      approved_by =\r\n        coalesce(\r\n          existing_schedule_period.approved_by,\r\n          current_user_id\r\n        ),\r\n\r\n      approved_at =\r\n        coalesce(\r\n          existing_schedule_period.approved_at,\r\n          imported_at\r\n        ),\r\n\r\n      updated_at =\r\n        imported_at\r\n\r\n    where id =\r\n      resolved_schedule_period_id;\r\n  else\r\n    insert into public.schedule_periods (\r\n      year,\r\n      month,\r\n      status,\r\n      published_at,\r\n      archived_at,\r\n      title,\r\n      created_by,\r\n      approved_by,\r\n      approved_at,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    values (\r\n      requested_year,\r\n      requested_month,\r\n      resolved_schedule_status,\r\n      imported_at,\r\n      case\r\n        when requested_period_type =\r\n          'historical'\r\n        then imported_at\r\n        else null\r\n      end,\r\n      concat(\r\n        'שיבוץ ',\r\n        requested_month,\r\n        '/',\r\n        requested_year\r\n      ),\r\n      current_user_id,\r\n      current_user_id,\r\n      imported_at,\r\n      imported_at,\r\n      imported_at\r\n    )\r\n    returning id\r\n    into resolved_schedule_period_id;\r\n  end if;\r\n\r\n  /*\r\n   * תקופת לוח כוננים.\r\n   */\r\n  select *\r\n  into existing_driver_period\r\n  from public.driver_schedule_periods\r\n  where year =\r\n    requested_year\r\n    and month =\r\n      requested_month\r\n  for update;\r\n\r\n  if found then\r\n    resolved_driver_period_id :=\r\n      existing_driver_period.id;\r\n\r\n    update public.driver_schedule_periods\r\n    set\r\n      status =\r\n        resolved_driver_status,\r\n\r\n      title =\r\n        coalesce(\r\n          existing_driver_period.title,\r\n          concat(\r\n            'לוח כוננים ',\r\n            requested_month,\r\n            '/',\r\n            requested_year\r\n          )\r\n        ),\r\n\r\n      published_at =\r\n        coalesce(\r\n          existing_driver_period.published_at,\r\n          imported_at\r\n        ),\r\n\r\n      archived_at =\r\n        case\r\n          when requested_period_type =\r\n            'historical'\r\n          then\r\n            coalesce(\r\n              existing_driver_period.archived_at,\r\n              imported_at\r\n            )\r\n          else\r\n            null\r\n        end,\r\n\r\n      updated_by =\r\n        current_user_id,\r\n\r\n      updated_at =\r\n        imported_at\r\n\r\n    where id =\r\n      resolved_driver_period_id;\r\n  else\r\n    insert into public.driver_schedule_periods (\r\n      year,\r\n      month,\r\n      status,\r\n      title,\r\n      published_at,\r\n      archived_at,\r\n      created_by,\r\n      updated_by,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    values (\r\n      requested_year,\r\n      requested_month,\r\n      resolved_driver_status,\r\n      concat(\r\n        'לוח כוננים ',\r\n        requested_month,\r\n        '/',\r\n        requested_year\r\n      ),\r\n      imported_at,\r\n      case\r\n        when requested_period_type =\r\n          'historical'\r\n        then imported_at\r\n        else null\r\n      end,\r\n      current_user_id,\r\n      current_user_id,\r\n      imported_at,\r\n      imported_at\r\n    )\r\n    returning id\r\n    into resolved_driver_period_id;\r\n  end if;\r\n\r\n  /*\r\n   * rebuild מוחק את נתוני החודש לפני הייבוא.\r\n   */\r\n  if requested_import_strategy =\r\n    'rebuild'\r\n  then\r\n    delete from public.schedule_shifts\r\n    where period_id =\r\n      resolved_schedule_period_id;\r\n\r\n    delete from public.driver_schedule_days\r\n    where period_id =\r\n      resolved_driver_period_id;\r\n  end if;\r\n\r\n  /*\r\n   * משמרות מוקדנים.\r\n   */\r\n  if requested_import_strategy =\r\n    'missing_only'\r\n  then\r\n    insert into public.schedule_shifts (\r\n      period_id,\r\n      shift_date,\r\n      starts_at,\r\n      ends_at,\r\n      shift_code,\r\n      schedule_type,\r\n      is_premium,\r\n      holiday_name,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      import_run_id,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_schedule_period_id,\r\n\r\n      payload.shift_date,\r\n\r\n      (\r\n        payload.shift_date +\r\n        payload.start_time\r\n      ) at time zone\r\n        'Asia/Jerusalem',\r\n\r\n      (\r\n        payload.shift_date +\r\n        payload.end_time +\r\n        case\r\n          when payload.end_time <=\r\n            payload.start_time\r\n          then interval '1 day'\r\n          else interval '0 day'\r\n        end\r\n      ) at time zone\r\n        'Asia/Jerusalem',\r\n\r\n      concat(\r\n        to_char(\r\n          payload.shift_date,\r\n          'YYYYMMDD'\r\n        ),\r\n        '-',\r\n        to_char(\r\n          payload.start_time,\r\n          'HH24MI'\r\n        )\r\n      ),\r\n\r\n      payload.schedule_type,\r\n\r\n      payload.is_premium,\r\n\r\n      payload.holiday_name,\r\n\r\n      payload.user_id,\r\n\r\n      'import'::public.assignment_source,\r\n\r\n      requested_period_type =\r\n        'historical',\r\n\r\n      null,\r\n\r\n      import_run_id,\r\n\r\n      imported_at,\r\n\r\n      imported_at\r\n\r\n    from (\r\n      select\r\n        (\r\n          item ->> 'date'\r\n        )::date as shift_date,\r\n\r\n        (\r\n          item ->> 'startTime'\r\n        )::time as start_time,\r\n\r\n        (\r\n          item ->> 'endTime'\r\n        )::time as end_time,\r\n\r\n        (\r\n          item ->> 'userId'\r\n        )::uuid as user_id,\r\n\r\n        coalesce(\r\n          holiday_row.schedule_type,\r\n          case\r\n            when extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 5\r\n            then\r\n              'friday'::public.schedule_type\r\n\r\n            when extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 6\r\n            then\r\n              'saturday'::public.schedule_type\r\n\r\n            else\r\n              'weekday'::public.schedule_type\r\n          end\r\n        ) as schedule_type,\r\n\r\n        holiday_row.name as holiday_name,\r\n\r\n        case\r\n          when holiday_row.schedule_type =\r\n            'holiday_full'::public.schedule_type\r\n          then true\r\n\r\n          when (\r\n            holiday_row.schedule_type =\r\n              'holiday_eve'::public.schedule_type\r\n            or extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 5\r\n          )\r\n          then\r\n            (\r\n              item ->> 'startTime'\r\n            )::time >=\r\n              time '14:00'\r\n\r\n          when (\r\n            holiday_row.schedule_type =\r\n              'holiday_end'::public.schedule_type\r\n            or extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 6\r\n          )\r\n          then\r\n            (\r\n              item ->> 'startTime'\r\n            )::time <\r\n              time '22:00'\r\n\r\n          else false\r\n        end as is_premium\r\n\r\n      from jsonb_array_elements(\r\n        requested_dispatcher_shifts\r\n      ) item\r\n\r\n      left join lateral (\r\n        select\r\n          holiday_record.schedule_type,\r\n          holiday_record.name\r\n        from public.holidays holiday_record\r\n        where holiday_record.holiday_date =\r\n          (\r\n            item ->> 'date'\r\n          )::date\r\n        order by\r\n          holiday_record.is_manual_override desc,\r\n          holiday_record.updated_at desc\r\n        limit 1\r\n      ) holiday_row\r\n        on true\r\n    ) payload\r\n\r\n    on conflict (\r\n      period_id,\r\n      starts_at\r\n    )\r\n    do nothing;\r\n  else\r\n    insert into public.schedule_shifts (\r\n      period_id,\r\n      shift_date,\r\n      starts_at,\r\n      ends_at,\r\n      shift_code,\r\n      schedule_type,\r\n      is_premium,\r\n      holiday_name,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      import_run_id,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_schedule_period_id,\r\n\r\n      payload.shift_date,\r\n\r\n      (\r\n        payload.shift_date +\r\n        payload.start_time\r\n      ) at time zone\r\n        'Asia/Jerusalem',\r\n\r\n      (\r\n        payload.shift_date +\r\n        payload.end_time +\r\n        case\r\n          when payload.end_time <=\r\n            payload.start_time\r\n          then interval '1 day'\r\n          else interval '0 day'\r\n        end\r\n      ) at time zone\r\n        'Asia/Jerusalem',\r\n\r\n      concat(\r\n        to_char(\r\n          payload.shift_date,\r\n          'YYYYMMDD'\r\n        ),\r\n        '-',\r\n        to_char(\r\n          payload.start_time,\r\n          'HH24MI'\r\n        )\r\n      ),\r\n\r\n      payload.schedule_type,\r\n\r\n      payload.is_premium,\r\n\r\n      payload.holiday_name,\r\n\r\n      payload.user_id,\r\n\r\n      'import'::public.assignment_source,\r\n\r\n      requested_period_type =\r\n        'historical',\r\n\r\n      null,\r\n\r\n      import_run_id,\r\n\r\n      imported_at,\r\n\r\n      imported_at\r\n\r\n    from (\r\n      select\r\n        (\r\n          item ->> 'date'\r\n        )::date as shift_date,\r\n\r\n        (\r\n          item ->> 'startTime'\r\n        )::time as start_time,\r\n\r\n        (\r\n          item ->> 'endTime'\r\n        )::time as end_time,\r\n\r\n        (\r\n          item ->> 'userId'\r\n        )::uuid as user_id,\r\n\r\n        coalesce(\r\n          holiday_row.schedule_type,\r\n          case\r\n            when extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 5\r\n            then\r\n              'friday'::public.schedule_type\r\n\r\n            when extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 6\r\n            then\r\n              'saturday'::public.schedule_type\r\n\r\n            else\r\n              'weekday'::public.schedule_type\r\n          end\r\n        ) as schedule_type,\r\n\r\n        holiday_row.name as holiday_name,\r\n\r\n        case\r\n          when holiday_row.schedule_type =\r\n            'holiday_full'::public.schedule_type\r\n          then true\r\n\r\n          when (\r\n            holiday_row.schedule_type =\r\n              'holiday_eve'::public.schedule_type\r\n            or extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 5\r\n          )\r\n          then\r\n            (\r\n              item ->> 'startTime'\r\n            )::time >=\r\n              time '14:00'\r\n\r\n          when (\r\n            holiday_row.schedule_type =\r\n              'holiday_end'::public.schedule_type\r\n            or extract(\r\n              dow from\r\n              (\r\n                item ->> 'date'\r\n              )::date\r\n            )::integer = 6\r\n          )\r\n          then\r\n            (\r\n              item ->> 'startTime'\r\n            )::time <\r\n              time '22:00'\r\n\r\n          else false\r\n        end as is_premium\r\n\r\n      from jsonb_array_elements(\r\n        requested_dispatcher_shifts\r\n      ) item\r\n\r\n      left join lateral (\r\n        select\r\n          holiday_record.schedule_type,\r\n          holiday_record.name\r\n        from public.holidays holiday_record\r\n        where holiday_record.holiday_date =\r\n          (\r\n            item ->> 'date'\r\n          )::date\r\n        order by\r\n          holiday_record.is_manual_override desc,\r\n          holiday_record.updated_at desc\r\n        limit 1\r\n      ) holiday_row\r\n        on true\r\n    ) payload\r\n\r\n    on conflict (\r\n      period_id,\r\n      starts_at\r\n    )\r\n    do update set\r\n      shift_date =\r\n        excluded.shift_date,\r\n\r\n      ends_at =\r\n        excluded.ends_at,\r\n\r\n      shift_code =\r\n        excluded.shift_code,\r\n\r\n      schedule_type =\r\n        excluded.schedule_type,\r\n\r\n      is_premium =\r\n        excluded.is_premium,\r\n\r\n      holiday_name =\r\n        excluded.holiday_name,\r\n\r\n      assigned_user_id =\r\n        excluded.assigned_user_id,\r\n\r\n      assignment_source =\r\n        excluded.assignment_source,\r\n\r\n      is_locked =\r\n        excluded.is_locked,\r\n\r\n      notes =\r\n        excluded.notes,\r\n\r\n      import_run_id =\r\n        excluded.import_run_id,\r\n\r\n      updated_at =\r\n        imported_at;\r\n  end if;\r\n\r\n  /*\r\n   * כוננויות.\r\n   */\r\n  if requested_import_strategy =\r\n    'missing_only'\r\n  then\r\n    insert into public.driver_schedule_days (\r\n      period_id,\r\n      duty_date,\r\n      weekday_number,\r\n      weekday_name,\r\n      original_user_id,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      import_run_id,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_driver_period_id,\r\n\r\n      payload.duty_date,\r\n\r\n      extract(\r\n        dow from\r\n        payload.duty_date\r\n      )::integer,\r\n\r\n      case extract(\r\n        dow from\r\n        payload.duty_date\r\n      )::integer\r\n        when 0 then 'ראשון'\r\n        when 1 then 'שני'\r\n        when 2 then 'שלישי'\r\n        when 3 then 'רביעי'\r\n        when 4 then 'חמישי'\r\n        when 5 then 'שישי'\r\n        when 6 then 'שבת'\r\n      end,\r\n\r\n      payload.user_id,\r\n\r\n      payload.user_id,\r\n\r\n      'import'::public.driver_assignment_source,\r\n\r\n      requested_period_type =\r\n        'historical',\r\n\r\n      payload.note,\r\n\r\n      import_run_id,\r\n\r\n      imported_at,\r\n\r\n      imported_at\r\n\r\n    from (\r\n      select\r\n        (\r\n          item ->> 'date'\r\n        )::date as duty_date,\r\n\r\n        (\r\n          item ->> 'userId'\r\n        )::uuid as user_id,\r\n\r\n        nullif(\r\n          trim(\r\n            coalesce(\r\n              item ->> 'note',\r\n              ''\r\n            )\r\n          ),\r\n          ''\r\n        ) as note\r\n\r\n      from jsonb_array_elements(\r\n        requested_driver_duties\r\n      ) item\r\n    ) payload\r\n\r\n    on conflict (\r\n      period_id,\r\n      duty_date\r\n    )\r\n    do nothing;\r\n  else\r\n    insert into public.driver_schedule_days (\r\n      period_id,\r\n      duty_date,\r\n      weekday_number,\r\n      weekday_name,\r\n      original_user_id,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      import_run_id,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_driver_period_id,\r\n\r\n      payload.duty_date,\r\n\r\n      extract(\r\n        dow from\r\n        payload.duty_date\r\n      )::integer,\r\n\r\n      case extract(\r\n        dow from\r\n        payload.duty_date\r\n      )::integer\r\n        when 0 then 'ראשון'\r\n        when 1 then 'שני'\r\n        when 2 then 'שלישי'\r\n        when 3 then 'רביעי'\r\n        when 4 then 'חמישי'\r\n        when 5 then 'שישי'\r\n        when 6 then 'שבת'\r\n      end,\r\n\r\n      payload.user_id,\r\n\r\n      payload.user_id,\r\n\r\n      'import'::public.driver_assignment_source,\r\n\r\n      requested_period_type =\r\n        'historical',\r\n\r\n      payload.note,\r\n\r\n      import_run_id,\r\n\r\n      imported_at,\r\n\r\n      imported_at\r\n\r\n    from (\r\n      select\r\n        (\r\n          item ->> 'date'\r\n        )::date as duty_date,\r\n\r\n        (\r\n          item ->> 'userId'\r\n        )::uuid as user_id,\r\n\r\n        nullif(\r\n          trim(\r\n            coalesce(\r\n              item ->> 'note',\r\n              ''\r\n            )\r\n          ),\r\n          ''\r\n        ) as note\r\n\r\n      from jsonb_array_elements(\r\n        requested_driver_duties\r\n      ) item\r\n    ) payload\r\n\r\n    on conflict (\r\n      period_id,\r\n      duty_date\r\n    )\r\n    do update set\r\n      weekday_number =\r\n        excluded.weekday_number,\r\n\r\n      weekday_name =\r\n        excluded.weekday_name,\r\n\r\n      original_user_id =\r\n        excluded.original_user_id,\r\n\r\n      assigned_user_id =\r\n        excluded.assigned_user_id,\r\n\r\n      assignment_source =\r\n        excluded.assignment_source,\r\n\r\n      is_locked =\r\n        excluded.is_locked,\r\n\r\n      notes =\r\n        excluded.notes,\r\n\r\n      import_run_id =\r\n        excluded.import_run_id,\r\n\r\n      updated_at =\r\n        imported_at;\r\n  end if;\r\n\r\n  /*\r\n   * השלמת ריצת הייבוא.\r\n   */\r\n  update public.schedule_import_runs\r\n  set\r\n    status =\r\n      case\r\n        when imported_warning_count > 0\r\n        then 'completed_with_warnings'\r\n        else 'completed'\r\n      end,\r\n\r\n    dispatcher_shifts_created =\r\n      dispatcher_created_count,\r\n\r\n    dispatcher_shifts_updated =\r\n      dispatcher_updated_count,\r\n\r\n    dispatcher_shifts_skipped =\r\n      dispatcher_skipped_count,\r\n\r\n    driver_duties_created =\r\n      driver_created_count,\r\n\r\n    driver_duties_updated =\r\n      driver_updated_count,\r\n\r\n    driver_duties_skipped =\r\n      driver_skipped_count,\r\n\r\n    schedule_period_id =\r\n      resolved_schedule_period_id,\r\n\r\n    driver_schedule_period_id =\r\n      resolved_driver_period_id,\r\n\r\n    result_summary =\r\n      jsonb_build_object(\r\n        'dispatcherShifts',\r\n          jsonb_build_object(\r\n            'detected',\r\n              dispatcher_detected_count,\r\n            'created',\r\n              dispatcher_created_count,\r\n            'updated',\r\n              dispatcher_updated_count,\r\n            'skipped',\r\n              dispatcher_skipped_count,\r\n            'deleted',\r\n              dispatcher_deleted_count\r\n          ),\r\n\r\n        'driverDuties',\r\n          jsonb_build_object(\r\n            'detected',\r\n              driver_detected_count,\r\n            'created',\r\n              driver_created_count,\r\n            'updated',\r\n              driver_updated_count,\r\n            'skipped',\r\n              driver_skipped_count,\r\n            'deleted',\r\n              driver_deleted_count\r\n          )\r\n      ),\r\n\r\n    completed_at =\r\n      imported_at,\r\n\r\n    updated_at =\r\n      imported_at\r\n\r\n  where id =\r\n    import_run_id;\r\n\r\n  return jsonb_build_object(\r\n    'importRunId',\r\n      import_run_id,\r\n\r\n    'year',\r\n      requested_year,\r\n\r\n    'month',\r\n      requested_month,\r\n\r\n    'periodType',\r\n      requested_period_type,\r\n\r\n    'importStrategy',\r\n      requested_import_strategy,\r\n\r\n    'status',\r\n      case\r\n        when imported_warning_count > 0\r\n        then 'completed_with_warnings'\r\n        else 'completed'\r\n      end,\r\n\r\n    'schedulePeriodId',\r\n      resolved_schedule_period_id,\r\n\r\n    'driverSchedulePeriodId',\r\n      resolved_driver_period_id,\r\n\r\n    'dispatcherShifts',\r\n      jsonb_build_object(\r\n        'detected',\r\n          dispatcher_detected_count,\r\n\r\n        'created',\r\n          dispatcher_created_count,\r\n\r\n        'updated',\r\n          dispatcher_updated_count,\r\n\r\n        'skipped',\r\n          dispatcher_skipped_count,\r\n\r\n        'deleted',\r\n          dispatcher_deleted_count\r\n      ),\r\n\r\n    'driverDuties',\r\n      jsonb_build_object(\r\n        'detected',\r\n          driver_detected_count,\r\n\r\n        'created',\r\n          driver_created_count,\r\n\r\n        'updated',\r\n          driver_updated_count,\r\n\r\n        'skipped',\r\n          driver_skipped_count,\r\n\r\n        'deleted',\r\n          driver_deleted_count\r\n      ),\r\n\r\n    'warningCount',\r\n      imported_warning_count,\r\n\r\n    'completedAt',\r\n      imported_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_archive_periods()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_archive_periods()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  archive_rows jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile_row\r\n    where profile_row.id =\r\n      current_user_id\r\n      and profile_row.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'archive.view' =\r\n      any(current_permissions)\r\n    or\r\n    'statistics.view' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'year',\r\n            combined_period.year,\r\n\r\n          'month',\r\n            combined_period.month,\r\n\r\n          'dispatcherPeriodId',\r\n            combined_period\r\n              .dispatcher_period_id,\r\n\r\n          'driverPeriodId',\r\n            combined_period\r\n              .driver_period_id,\r\n\r\n          'dispatcherStatus',\r\n            combined_period\r\n              .dispatcher_status,\r\n\r\n          'driverStatus',\r\n            combined_period\r\n              .driver_status,\r\n\r\n          'dispatcherShiftCount',\r\n            combined_period\r\n              .dispatcher_shift_count,\r\n\r\n          'driverDutyCount',\r\n            combined_period\r\n              .driver_duty_count,\r\n\r\n          'dispatcherCount',\r\n            combined_period\r\n              .dispatcher_count,\r\n\r\n          'driverCount',\r\n            combined_period\r\n              .driver_count,\r\n\r\n          'dispatcherPublishedAt',\r\n            combined_period\r\n              .dispatcher_published_at,\r\n\r\n          'driverPublishedAt',\r\n            combined_period\r\n              .driver_published_at,\r\n\r\n          'dispatcherArchivedAt',\r\n            combined_period\r\n              .dispatcher_archived_at,\r\n\r\n          'driverArchivedAt',\r\n            combined_period\r\n              .driver_archived_at,\r\n\r\n          'importRunId',\r\n            combined_period\r\n              .import_run_id,\r\n\r\n          'importFileName',\r\n            combined_period\r\n              .import_file_name,\r\n\r\n          'importedAt',\r\n            combined_period\r\n              .imported_at,\r\n\r\n          'importedBy',\r\n            combined_period\r\n              .imported_by,\r\n\r\n          'isFullyArchived',\r\n            (\r\n              combined_period\r\n                .dispatcher_status =\r\n                'archived'\r\n              and\r\n              combined_period\r\n                .driver_status =\r\n                'archived'\r\n            ),\r\n\r\n          'hasDispatcherSchedule',\r\n            combined_period\r\n              .dispatcher_period_id\r\n              is not null,\r\n\r\n          'hasDriverSchedule',\r\n            combined_period\r\n              .driver_period_id\r\n              is not null\r\n        )\r\n        order by\r\n          combined_period.year desc,\r\n          combined_period.month desc\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into archive_rows\r\n\r\n  from (\r\n    select\r\n      coalesce(\r\n        dispatcher_period.year,\r\n        driver_period.year\r\n      ) as year,\r\n\r\n      coalesce(\r\n        dispatcher_period.month,\r\n        driver_period.month\r\n      ) as month,\r\n\r\n      dispatcher_period.id\r\n        as dispatcher_period_id,\r\n\r\n      driver_period.id\r\n        as driver_period_id,\r\n\r\n      dispatcher_period.status::text\r\n        as dispatcher_status,\r\n\r\n      driver_period.status::text\r\n        as driver_status,\r\n\r\n      dispatcher_period.published_at\r\n        as dispatcher_published_at,\r\n\r\n      driver_period.published_at\r\n        as driver_published_at,\r\n\r\n      dispatcher_period.archived_at\r\n        as dispatcher_archived_at,\r\n\r\n      driver_period.archived_at\r\n        as driver_archived_at,\r\n\r\n      coalesce(\r\n        dispatcher_stats.shift_count,\r\n        0\r\n      )::integer\r\n        as dispatcher_shift_count,\r\n\r\n      coalesce(\r\n        dispatcher_stats.dispatcher_count,\r\n        0\r\n      )::integer\r\n        as dispatcher_count,\r\n\r\n      coalesce(\r\n        driver_stats.duty_count,\r\n        0\r\n      )::integer\r\n        as driver_duty_count,\r\n\r\n      coalesce(\r\n        driver_stats.driver_count,\r\n        0\r\n      )::integer\r\n        as driver_count,\r\n\r\n      import_run.id\r\n        as import_run_id,\r\n\r\n      import_run.file_name\r\n        as import_file_name,\r\n\r\n      import_run.completed_at\r\n        as imported_at,\r\n\r\n      importer.display_name\r\n        as imported_by\r\n\r\n    from public.schedule_periods\r\n      dispatcher_period\r\n\r\n    full join public.driver_schedule_periods\r\n      driver_period\r\n      on driver_period.year =\r\n        dispatcher_period.year\r\n      and driver_period.month =\r\n        dispatcher_period.month\r\n\r\n    left join lateral (\r\n      select\r\n        count(*)::integer\r\n          as shift_count,\r\n\r\n        count(\r\n          distinct\r\n          schedule_shift\r\n            .assigned_user_id\r\n        ) filter (\r\n          where schedule_shift\r\n            .assigned_user_id\r\n            is not null\r\n        )::integer\r\n          as dispatcher_count\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      where schedule_shift.period_id =\r\n        dispatcher_period.id\r\n    ) dispatcher_stats\r\n      on true\r\n\r\n    left join lateral (\r\n      select\r\n        count(*)::integer\r\n          as duty_count,\r\n\r\n        count(\r\n          distinct\r\n          driver_day\r\n            .assigned_user_id\r\n        ) filter (\r\n          where driver_day\r\n            .assigned_user_id\r\n            is not null\r\n        )::integer\r\n          as driver_count\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      where driver_day.period_id =\r\n        driver_period.id\r\n    ) driver_stats\r\n      on true\r\n\r\n    left join lateral (\r\n      select\r\n        import_record.*\r\n      from public.schedule_import_runs\r\n        import_record\r\n\r\n      where\r\n        (\r\n          import_record\r\n            .schedule_period_id =\r\n            dispatcher_period.id\r\n          or\r\n          import_record\r\n            .driver_schedule_period_id =\r\n            driver_period.id\r\n        )\r\n\r\n      order by\r\n        import_record.created_at desc\r\n\r\n      limit 1\r\n    ) import_run\r\n      on true\r\n\r\n    left join public.profiles\r\n      importer\r\n      on importer.id =\r\n        import_run.imported_by\r\n\r\n    where\r\n      dispatcher_period.status =\r\n        'archived'\r\n      or\r\n      driver_period.status =\r\n        'archived'\r\n  ) combined_period;\r\n\r\n  return jsonb_build_object(\r\n    'periods',\r\n      archive_rows,\r\n\r\n    'count',\r\n      jsonb_array_length(\r\n        archive_rows\r\n      ),\r\n\r\n    'generatedAt',\r\n      now()\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_audit_logs(integer,integer,text,uuid,uuid,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_audit_logs(requested_limit integer DEFAULT 100, requested_offset integer DEFAULT 0, requested_action text DEFAULT NULL::text, requested_actor_user_id uuid DEFAULT NULL::uuid, requested_target_user_id uuid DEFAULT NULL::uuid, requested_search_term text DEFAULT NULL::text)\n RETURNS TABLE(id uuid, action text, actor_user_id uuid, actor_email text, actor_display_name text, target_user_id uuid, target_email text, target_display_name text, entity_type text, summary text, old_values jsonb, new_values jsonb, metadata jsonb, created_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  normalized_limit integer;\r\n  normalized_offset integer;\r\n  normalized_search_term text;\r\nbegin\r\n  if auth.uid() is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions up\r\n    where up.user_id = auth.uid()\r\n      and up.permission_key =\r\n        'audit.view'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to view audit logs';\r\n  end if;\r\n\r\n  normalized_limit :=\r\n    greatest(\r\n      1,\r\n      least(\r\n        coalesce(requested_limit, 100),\r\n        500\r\n      )\r\n    );\r\n\r\n  normalized_offset :=\r\n    greatest(\r\n      coalesce(requested_offset, 0),\r\n      0\r\n    );\r\n\r\n  normalized_search_term :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_search_term,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  return query\r\n  select\r\n    log.id,\r\n    log.action,\r\n    log.actor_user_id,\r\n    log.actor_email,\r\n    log.actor_display_name,\r\n    log.target_user_id,\r\n    log.target_email,\r\n    log.target_display_name,\r\n    log.entity_type,\r\n    log.summary,\r\n    log.old_values,\r\n    log.new_values,\r\n    log.metadata,\r\n    log.created_at\r\n  from public.audit_logs log\r\n  where\r\n    (\r\n      requested_action is null\r\n      or log.action = requested_action\r\n    )\r\n    and (\r\n      requested_actor_user_id is null\r\n      or log.actor_user_id =\r\n        requested_actor_user_id\r\n    )\r\n    and (\r\n      requested_target_user_id is null\r\n      or log.target_user_id =\r\n        requested_target_user_id\r\n    )\r\n    and (\r\n      normalized_search_term is null\r\n      or log.summary ilike\r\n        '%' || normalized_search_term || '%'\r\n      or coalesce(\r\n        log.actor_display_name,\r\n        ''\r\n      ) ilike\r\n        '%' || normalized_search_term || '%'\r\n      or coalesce(\r\n        log.actor_email,\r\n        ''\r\n      ) ilike\r\n        '%' || normalized_search_term || '%'\r\n      or coalesce(\r\n        log.target_display_name,\r\n        ''\r\n      ) ilike\r\n        '%' || normalized_search_term || '%'\r\n      or coalesce(\r\n        log.target_email,\r\n        ''\r\n      ) ilike\r\n        '%' || normalized_search_term || '%'\r\n    )\r\n  order by log.created_at desc\r\n  limit normalized_limit\r\n  offset normalized_offset;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_availability_assignment_candidates(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_availability_assignment_candidates(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, period_year integer, period_month integer, period_title text, period_status text, shift_slot_id uuid, shift_date date, weekday_number integer, weekday_name text, start_time time without time zone, end_time time without time zone, ends_next_day boolean, schedule_type text, holiday_name text, is_premium boolean, sort_order integer, total_dispatchers integer, available_dispatchers integer, unavailable_dispatchers integer, assignment_state text, sole_available_user_id uuid, sole_available_display_name text, sole_available_schedule_name text, available_user_ids uuid[], available_display_names text[], available_schedule_names text[])\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  target_period_year integer;\r\n  target_period_status text;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id =\r\n      current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'schedule.edit'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to prepare schedule assignments';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.year,\r\n    period.status\r\n  into\r\n    target_period_year,\r\n    target_period_status\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  if target_period_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  if target_period_status <> 'closed' then\r\n    raise exception\r\n      'Availability period must be closed before assignment analysis';\r\n  end if;\r\n\r\n  return query\r\n\r\n  with active_dispatchers as (\r\n    select\r\n      profile.id,\r\n      profile.display_name,\r\n      profile.schedule_name\r\n    from public.profiles profile\r\n    where profile.role::text =\r\n      'dispatcher'\r\n      and profile.is_active = true\r\n  ),\r\n\r\n  submitted_dispatchers as (\r\n    select\r\n      submission.user_id\r\n    from public.availability_submissions submission\r\n    where submission.period_id =\r\n      requested_period_id\r\n      and submission.status =\r\n        'submitted'\r\n  ),\r\n\r\n  shift_availability as (\r\n    select\r\n      slot.id\r\n        as analyzed_shift_slot_id,\r\n\r\n      count(\r\n        dispatcher.id\r\n      )::integer\r\n        as total_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          availability.availability_status =\r\n            'available'\r\n          and submitted.user_id\r\n            is not null\r\n      )::integer\r\n        as available_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          availability.availability_status =\r\n            'unavailable'\r\n          and submitted.user_id\r\n            is not null\r\n      )::integer\r\n        as unavailable_dispatchers,\r\n\r\n      array_agg(\r\n        dispatcher.id\r\n        order by\r\n          dispatcher.display_name\r\n      ) filter (\r\n        where\r\n          availability.availability_status =\r\n            'available'\r\n          and submitted.user_id\r\n            is not null\r\n      )\r\n        as available_user_ids,\r\n\r\n      array_agg(\r\n        dispatcher.display_name\r\n        order by\r\n          dispatcher.display_name\r\n      ) filter (\r\n        where\r\n          availability.availability_status =\r\n            'available'\r\n          and submitted.user_id\r\n            is not null\r\n      )\r\n        as available_display_names,\r\n\r\n      array_agg(\r\n        dispatcher.schedule_name\r\n        order by\r\n          dispatcher.display_name\r\n      ) filter (\r\n        where\r\n          availability.availability_status =\r\n            'available'\r\n          and submitted.user_id\r\n            is not null\r\n      )\r\n        as available_schedule_names\r\n\r\n    from public.availability_shift_slots slot\r\n\r\n    cross join active_dispatchers\r\n      dispatcher\r\n\r\n    left join submitted_dispatchers\r\n      submitted\r\n      on submitted.user_id =\r\n        dispatcher.id\r\n\r\n    left join public.dispatcher_availability\r\n      availability\r\n      on availability.period_id =\r\n        requested_period_id\r\n      and availability.shift_slot_id =\r\n        slot.id\r\n      and availability.user_id =\r\n        dispatcher.id\r\n\r\n    where slot.period_id =\r\n      requested_period_id\r\n\r\n    group by slot.id\r\n  )\r\n\r\n  select\r\n    period.id,\r\n    period.year,\r\n    period.month,\r\n    period.title,\r\n    period.status,\r\n\r\n    slot.id,\r\n    slot.shift_date,\r\n    slot.weekday_number,\r\n    slot.weekday_name,\r\n    slot.start_time,\r\n    slot.end_time,\r\n    slot.ends_next_day,\r\n    slot.schedule_type,\r\n    slot.holiday_name,\r\n    slot.is_premium,\r\n    slot.sort_order,\r\n\r\n    analysis.total_dispatchers,\r\n    analysis.available_dispatchers,\r\n    analysis.unavailable_dispatchers,\r\n\r\n    case\r\n      when analysis.available_dispatchers = 0\r\n        then 'no_available'\r\n\r\n      when analysis.available_dispatchers = 1\r\n        then 'single_available'\r\n\r\n      else 'multiple_available'\r\n    end\r\n      as assignment_state,\r\n\r\n    case\r\n      when analysis.available_dispatchers = 1\r\n        then analysis.available_user_ids[1]\r\n      else null\r\n    end\r\n      as sole_available_user_id,\r\n\r\n    case\r\n      when analysis.available_dispatchers = 1\r\n        then analysis.available_display_names[1]\r\n      else null\r\n    end\r\n      as sole_available_display_name,\r\n\r\n    case\r\n      when analysis.available_dispatchers = 1\r\n        then analysis.available_schedule_names[1]\r\n      else null\r\n    end\r\n      as sole_available_schedule_name,\r\n\r\n    coalesce(\r\n      analysis.available_user_ids,\r\n      array[]::uuid[]\r\n    ),\r\n\r\n    coalesce(\r\n      analysis.available_display_names,\r\n      array[]::text[]\r\n    ),\r\n\r\n    coalesce(\r\n      analysis.available_schedule_names,\r\n      array[]::text[]\r\n    )\r\n\r\n  from public.availability_periods period\r\n\r\n  join public.availability_shift_slots slot\r\n    on slot.period_id =\r\n      period.id\r\n\r\n  join shift_availability analysis\r\n    on analysis.analyzed_shift_slot_id =\r\n      slot.id\r\n\r\n  where period.id =\r\n    requested_period_id\r\n\r\n  order by\r\n    case\r\n      when analysis.available_dispatchers = 0\r\n        then 1\r\n      when analysis.available_dispatchers = 1\r\n        then 2\r\n      else 3\r\n    end,\r\n    slot.shift_date,\r\n    slot.sort_order;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_availability_period_matrix(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_availability_period_matrix(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, period_year integer, period_month integer, period_title text, period_status text, shift_slot_id uuid, shift_date date, weekday_number integer, weekday_name text, start_time time without time zone, end_time time without time zone, ends_next_day boolean, schedule_type text, holiday_name text, is_premium boolean, sort_order integer, total_dispatchers integer, available_dispatchers integer, unavailable_dispatchers integer, unanswered_dispatchers integer, user_id uuid, display_name text, email text, schedule_name text, submission_status text, availability_status text, availability_note text, availability_updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  target_period_year integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id =\r\n      current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.year\r\n  into\r\n    target_period_year\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  if target_period_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  return query\r\n\r\n  with active_dispatchers as (\r\n    select\r\n      profile.id,\r\n      profile.display_name,\r\n      profile.email,\r\n      profile.schedule_name\r\n    from public.profiles profile\r\n    where profile.role::text =\r\n      'dispatcher'\r\n      and profile.is_active = true\r\n  ),\r\n\r\n  matrix_rows as (\r\n    select\r\n      period.id\r\n        as matrix_period_id,\r\n\r\n      period.year\r\n        as matrix_period_year,\r\n\r\n      period.month\r\n        as matrix_period_month,\r\n\r\n      period.title\r\n        as matrix_period_title,\r\n\r\n      period.status\r\n        as matrix_period_status,\r\n\r\n      slot.id\r\n        as matrix_shift_slot_id,\r\n\r\n      slot.shift_date,\r\n      slot.weekday_number,\r\n      slot.weekday_name,\r\n      slot.start_time,\r\n      slot.end_time,\r\n      slot.ends_next_day,\r\n      slot.schedule_type,\r\n      slot.holiday_name,\r\n      slot.is_premium,\r\n      slot.sort_order,\r\n\r\n      dispatcher.id\r\n        as dispatcher_user_id,\r\n\r\n      dispatcher.display_name,\r\n      dispatcher.email,\r\n      dispatcher.schedule_name,\r\n\r\n      coalesce(\r\n        submission.status,\r\n        'not_started'\r\n      )\r\n        as matrix_submission_status,\r\n\r\n      availability.availability_status\r\n        as matrix_availability_status,\r\n\r\n      availability.note\r\n        as matrix_availability_note,\r\n\r\n      availability.updated_at\r\n        as matrix_availability_updated_at\r\n\r\n    from public.availability_periods period\r\n\r\n    join public.availability_shift_slots slot\r\n      on slot.period_id =\r\n        period.id\r\n\r\n    cross join active_dispatchers\r\n      dispatcher\r\n\r\n    left join public.availability_submissions\r\n      submission\r\n      on submission.period_id =\r\n        period.id\r\n      and submission.user_id =\r\n        dispatcher.id\r\n\r\n    left join public.dispatcher_availability\r\n      availability\r\n      on availability.period_id =\r\n        period.id\r\n      and availability.shift_slot_id =\r\n        slot.id\r\n      and availability.user_id =\r\n        dispatcher.id\r\n\r\n    where period.id =\r\n      requested_period_id\r\n  ),\r\n\r\n  shift_summary as (\r\n    select\r\n      row_data.matrix_shift_slot_id,\r\n\r\n      count(*)::integer\r\n        as total_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          row_data\r\n            .matrix_availability_status =\r\n            'available'\r\n      )::integer\r\n        as available_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          row_data\r\n            .matrix_availability_status =\r\n            'unavailable'\r\n      )::integer\r\n        as unavailable_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          row_data\r\n            .matrix_availability_status\r\n          is null\r\n      )::integer\r\n        as unanswered_dispatchers\r\n\r\n    from matrix_rows row_data\r\n\r\n    group by\r\n      row_data.matrix_shift_slot_id\r\n  )\r\n\r\n  select\r\n    row_data.matrix_period_id,\r\n    row_data.matrix_period_year,\r\n    row_data.matrix_period_month,\r\n    row_data.matrix_period_title,\r\n    row_data.matrix_period_status,\r\n\r\n    row_data.matrix_shift_slot_id,\r\n    row_data.shift_date,\r\n    row_data.weekday_number,\r\n    row_data.weekday_name,\r\n    row_data.start_time,\r\n    row_data.end_time,\r\n    row_data.ends_next_day,\r\n    row_data.schedule_type,\r\n    row_data.holiday_name,\r\n    row_data.is_premium,\r\n    row_data.sort_order,\r\n\r\n    summary.total_dispatchers,\r\n    summary.available_dispatchers,\r\n    summary.unavailable_dispatchers,\r\n    summary.unanswered_dispatchers,\r\n\r\n    row_data.dispatcher_user_id,\r\n    row_data.display_name,\r\n    row_data.email,\r\n    row_data.schedule_name,\r\n\r\n    row_data.matrix_submission_status,\r\n    row_data.matrix_availability_status,\r\n    row_data.matrix_availability_note,\r\n    row_data.matrix_availability_updated_at\r\n\r\n  from matrix_rows row_data\r\n\r\n  join shift_summary summary\r\n    on summary.matrix_shift_slot_id =\r\n      row_data.matrix_shift_slot_id\r\n\r\n  order by\r\n    row_data.shift_date,\r\n    row_data.sort_order,\r\n    row_data.display_name;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_availability_period_submissions(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_availability_period_submissions(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, period_year integer, period_month integer, period_title text, period_status text, submission_deadline timestamp with time zone, total_dispatchers integer, submitted_dispatchers integer, draft_dispatchers integer, not_started_dispatchers integer, user_id uuid, display_name text, email text, schedule_name text, submission_status text, submitted_at timestamp with time zone, last_saved_at timestamp with time zone, available_count integer, unavailable_count integer, answered_count integer, unanswered_count integer, total_shift_count integer, completion_percentage integer)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  target_period_year integer;\r\n  target_period_month integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id =\r\n      current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.year,\r\n    period.month\r\n  into\r\n    target_period_year,\r\n    target_period_month\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  if target_period_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  return query\r\n\r\n  with period_data as (\r\n    select\r\n      period.id,\r\n      period.year,\r\n      period.month,\r\n      period.title,\r\n      period.status,\r\n      period.submission_deadline,\r\n\r\n      (\r\n        select count(*)::integer\r\n        from public.availability_shift_slots slot\r\n        where slot.period_id =\r\n          period.id\r\n      ) as total_shift_count\r\n\r\n    from public.availability_periods period\r\n    where period.id =\r\n      requested_period_id\r\n  ),\r\n\r\n  dispatcher_rows as (\r\n    select\r\n      profile.id\r\n        as dispatcher_user_id,\r\n\r\n      profile.display_name,\r\n      profile.email,\r\n      profile.schedule_name,\r\n\r\n      submission.status\r\n        as stored_submission_status,\r\n\r\n      submission.submitted_at,\r\n      submission.last_saved_at,\r\n\r\n      coalesce(\r\n        submission.available_count,\r\n        0\r\n      )::integer\r\n        as available_count,\r\n\r\n      coalesce(\r\n        submission.unavailable_count,\r\n        0\r\n      )::integer\r\n        as unavailable_count,\r\n\r\n      period_data.total_shift_count,\r\n\r\n      (\r\n        coalesce(\r\n          submission.available_count,\r\n          0\r\n        )\r\n        +\r\n        coalesce(\r\n          submission.unavailable_count,\r\n          0\r\n        )\r\n      )::integer\r\n        as answered_count\r\n\r\n    from public.profiles profile\r\n\r\n    cross join period_data\r\n\r\n    left join\r\n      public.availability_submissions\r\n        submission\r\n      on submission.period_id =\r\n        requested_period_id\r\n      and submission.user_id =\r\n        profile.id\r\n\r\n    where profile.role::text =\r\n      'dispatcher'\r\n      and profile.is_active = true\r\n  ),\r\n\r\n  classified_dispatchers as (\r\n    select\r\n      dispatcher_row.*,\r\n\r\n      case\r\n        when dispatcher_row\r\n          .stored_submission_status =\r\n          'submitted'\r\n          then 'submitted'\r\n\r\n        when dispatcher_row\r\n          .answered_count > 0\r\n          then coalesce(\r\n            dispatcher_row\r\n              .stored_submission_status,\r\n            'draft'\r\n          )\r\n\r\n        else 'not_started'\r\n      end\r\n        as effective_submission_status,\r\n\r\n      greatest(\r\n        dispatcher_row.total_shift_count\r\n        -\r\n        dispatcher_row.answered_count,\r\n        0\r\n      )::integer\r\n        as unanswered_count,\r\n\r\n      case\r\n        when dispatcher_row\r\n          .total_shift_count = 0\r\n          then 0\r\n\r\n        else round(\r\n          (\r\n            dispatcher_row\r\n              .answered_count::numeric\r\n            /\r\n            dispatcher_row\r\n              .total_shift_count::numeric\r\n          )\r\n          * 100\r\n        )::integer\r\n      end\r\n        as completion_percentage\r\n\r\n    from dispatcher_rows\r\n      dispatcher_row\r\n  ),\r\n\r\n  summary_data as (\r\n    select\r\n      count(*)::integer\r\n        as total_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          effective_submission_status =\r\n            'submitted'\r\n      )::integer\r\n        as submitted_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          effective_submission_status =\r\n            'draft'\r\n      )::integer\r\n        as draft_dispatchers,\r\n\r\n      count(*) filter (\r\n        where\r\n          effective_submission_status =\r\n            'not_started'\r\n      )::integer\r\n        as not_started_dispatchers\r\n\r\n    from classified_dispatchers\r\n  )\r\n\r\n  select\r\n    period_data.id,\r\n    period_data.year,\r\n    period_data.month,\r\n    period_data.title,\r\n    period_data.status,\r\n    period_data.submission_deadline,\r\n\r\n    summary_data.total_dispatchers,\r\n    summary_data.submitted_dispatchers,\r\n    summary_data.draft_dispatchers,\r\n    summary_data.not_started_dispatchers,\r\n\r\n    dispatcher.dispatcher_user_id,\r\n    dispatcher.display_name,\r\n    dispatcher.email,\r\n    dispatcher.schedule_name,\r\n\r\n    dispatcher.effective_submission_status,\r\n    dispatcher.submitted_at,\r\n    dispatcher.last_saved_at,\r\n\r\n    dispatcher.available_count,\r\n    dispatcher.unavailable_count,\r\n    dispatcher.answered_count,\r\n    dispatcher.unanswered_count,\r\n    dispatcher.total_shift_count,\r\n    dispatcher.completion_percentage\r\n\r\n  from period_data\r\n\r\n  cross join summary_data\r\n\r\n  join classified_dispatchers\r\n    dispatcher\r\n    on true\r\n\r\n  order by\r\n    case\r\n      dispatcher.effective_submission_status\r\n        when 'not_started'\r\n          then 1\r\n        when 'draft'\r\n          then 2\r\n        when 'submitted'\r\n          then 3\r\n        else 4\r\n    end,\r\n\r\n    dispatcher.display_name;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_current_schedule()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_current_schedule()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_profile\r\n    public.profiles%rowtype;\r\n\r\n  current_year integer;\r\n  current_month integer;\r\n\r\n  resolved_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  user_permissions text[];\r\n\r\n  can_view_schedule boolean := false;\r\n  can_edit_schedule boolean := false;\r\n  can_view_team_schedule boolean := false;\r\n\r\n  default_view_mode text := 'personal';\r\n\r\n  can_access_current_period boolean := false;\r\n\r\n  all_shifts_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  visible_shifts_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  personal_statistics_json jsonb :=\r\n    null;\r\n\r\n  dispatcher_statistics_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  team_statistics_json jsonb;\r\n\r\n  generated_at timestamptz :=\r\n    now();\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  select *\r\n  into current_profile\r\n  from public.profiles\r\n  where id =\r\n    current_user_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'profile not found';\r\n  end if;\r\n\r\n  if not current_profile.is_active then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  user_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  can_view_schedule :=\r\n    (\r\n      'schedule.view' =\r\n      any(user_permissions)\r\n    )\r\n    or\r\n    (\r\n      'schedule.view_team' =\r\n      any(user_permissions)\r\n    )\r\n    or\r\n    (\r\n      'schedule.edit' =\r\n      any(user_permissions)\r\n    );\r\n\r\n  can_edit_schedule :=\r\n    'schedule.edit' =\r\n    any(user_permissions);\r\n\r\n  can_view_team_schedule :=\r\n    'schedule.view_team' =\r\n    any(user_permissions);\r\n\r\n  if not can_view_schedule then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if can_view_team_schedule then\r\n    default_view_mode :=\r\n      'team';\r\n  else\r\n    default_view_mode :=\r\n      'personal';\r\n  end if;\r\n\r\n  select\r\n    extract(\r\n      year\r\n      from now()\r\n        at time zone\r\n        'Asia/Jerusalem'\r\n    )::integer,\r\n\r\n    extract(\r\n      month\r\n      from now()\r\n        at time zone\r\n        'Asia/Jerusalem'\r\n    )::integer\r\n\r\n  into\r\n    current_year,\r\n    current_month;\r\n\r\n  select *\r\n  into resolved_period\r\n  from public.schedule_periods\r\n  where year =\r\n    current_year\r\n    and month =\r\n      current_month\r\n  limit 1;\r\n\r\n  if not found then\r\n    return jsonb_build_object(\r\n      'access',\r\n      jsonb_build_object(\r\n        'userId',\r\n          current_user_id,\r\n\r\n        'role',\r\n          current_profile.role::text,\r\n\r\n        'canViewSchedule',\r\n          can_view_schedule,\r\n\r\n        'canEditSchedule',\r\n          can_edit_schedule,\r\n\r\n        'canViewTeamSchedule',\r\n          can_view_team_schedule,\r\n\r\n        'defaultViewMode',\r\n          default_view_mode\r\n      ),\r\n\r\n      'period',\r\n        null,\r\n\r\n      'shifts',\r\n        '[]'::jsonb,\r\n\r\n      'visibleShifts',\r\n        '[]'::jsonb,\r\n\r\n      'personalStatistics',\r\n        null,\r\n\r\n      'dispatcherStatistics',\r\n        '[]'::jsonb,\r\n\r\n      'teamStatistics',\r\n        jsonb_build_object(\r\n          'totalShifts', 0,\r\n          'completedShifts', 0,\r\n          'remainingShifts', 0,\r\n          'completionPercentage', 0,\r\n          'assignedDispatchers', 0,\r\n          'premiumShifts', 0,\r\n          'holidayShifts', 0,\r\n          'manualAssignments', 0,\r\n          'automaticAssignments', 0\r\n        ),\r\n\r\n      'generatedAt',\r\n        generated_at\r\n    );\r\n  end if;\r\n\r\n  can_access_current_period :=\r\n    can_view_team_schedule\r\n    or\r\n    resolved_period.status =\r\n      'published'::public.schedule_period_status;\r\n\r\n  if not can_access_current_period then\r\n    return jsonb_build_object(\r\n      'access',\r\n      jsonb_build_object(\r\n        'userId',\r\n          current_user_id,\r\n\r\n        'role',\r\n          current_profile.role::text,\r\n\r\n        'canViewSchedule',\r\n          can_view_schedule,\r\n\r\n        'canEditSchedule',\r\n          can_edit_schedule,\r\n\r\n        'canViewTeamSchedule',\r\n          can_view_team_schedule,\r\n\r\n        'defaultViewMode',\r\n          default_view_mode\r\n      ),\r\n\r\n      'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          resolved_period.id,\r\n\r\n        'availabilityPeriodId',\r\n          resolved_period.availability_period_id,\r\n\r\n        'year',\r\n          resolved_period.year,\r\n\r\n        'month',\r\n          resolved_period.month,\r\n\r\n        'title',\r\n          resolved_period.title,\r\n\r\n        'status',\r\n          resolved_period.status::text,\r\n\r\n        'publishedAt',\r\n          resolved_period.published_at,\r\n\r\n        'approvedAt',\r\n          resolved_period.approved_at,\r\n\r\n        'createdAt',\r\n          resolved_period.created_at,\r\n\r\n        'updatedAt',\r\n          resolved_period.updated_at\r\n      ),\r\n\r\n      'shifts',\r\n        '[]'::jsonb,\r\n\r\n      'visibleShifts',\r\n        '[]'::jsonb,\r\n\r\n      'personalStatistics',\r\n        null,\r\n\r\n      'dispatcherStatistics',\r\n        '[]'::jsonb,\r\n\r\n      'teamStatistics',\r\n        jsonb_build_object(\r\n          'totalShifts', 0,\r\n          'completedShifts', 0,\r\n          'remainingShifts', 0,\r\n          'completionPercentage', 0,\r\n          'assignedDispatchers', 0,\r\n          'premiumShifts', 0,\r\n          'holidayShifts', 0,\r\n          'manualAssignments', 0,\r\n          'automaticAssignments', 0\r\n        ),\r\n\r\n      'generatedAt',\r\n        generated_at\r\n    );\r\n  end if;\r\n\r\n  with schedule_rows as (\r\n    select\r\n      schedule_shift.id,\r\n      schedule_shift.period_id,\r\n      schedule_shift.availability_shift_slot_id,\r\n      schedule_shift.shift_date,\r\n      schedule_shift.starts_at,\r\n      schedule_shift.ends_at,\r\n      schedule_shift.shift_code,\r\n      schedule_shift.schedule_type,\r\n      schedule_shift.is_premium,\r\n      schedule_shift.holiday_name,\r\n      schedule_shift.assigned_user_id,\r\n      schedule_shift.assignment_source,\r\n      schedule_shift.assignment_score,\r\n      schedule_shift.assignment_reasons,\r\n      schedule_shift.is_locked,\r\n      schedule_shift.notes,\r\n\r\n      assigned_profile.display_name,\r\n      assigned_profile.schedule_name,\r\n      assigned_profile.role,\r\n\r\n      case\r\n        when schedule_shift.ends_at <=\r\n          generated_at\r\n        then\r\n          'completed'\r\n\r\n        when schedule_shift.starts_at <=\r\n          generated_at\r\n          and schedule_shift.ends_at >\r\n            generated_at\r\n        then\r\n          'current'\r\n\r\n        else\r\n          'upcoming'\r\n      end as progress_state\r\n\r\n    from public.schedule_shifts\r\n      schedule_shift\r\n\r\n    left join public.profiles\r\n      assigned_profile\r\n      on assigned_profile.id =\r\n        schedule_shift.assigned_user_id\r\n\r\n    where schedule_shift.period_id =\r\n      resolved_period.id\r\n  ),\r\n\r\n  mapped_rows as (\r\n    select\r\n      jsonb_build_object(\r\n        'id',\r\n          schedule_row.id,\r\n\r\n        'periodId',\r\n          schedule_row.period_id,\r\n\r\n        'availabilityShiftSlotId',\r\n          schedule_row.availability_shift_slot_id,\r\n\r\n        'shiftDate',\r\n          schedule_row.shift_date,\r\n\r\n        'startsAt',\r\n          schedule_row.starts_at,\r\n\r\n        'endsAt',\r\n          schedule_row.ends_at,\r\n\r\n        'shiftCode',\r\n          schedule_row.shift_code,\r\n\r\n        'scheduleType',\r\n          schedule_row.schedule_type::text,\r\n\r\n        'isPremium',\r\n          schedule_row.is_premium,\r\n\r\n        'holidayName',\r\n          schedule_row.holiday_name,\r\n\r\n        'assignedUser',\r\n          case\r\n            when schedule_row.assigned_user_id\r\n              is null\r\n            then null\r\n\r\n            else jsonb_build_object(\r\n              'id',\r\n                schedule_row.assigned_user_id,\r\n\r\n              'displayName',\r\n                schedule_row.display_name,\r\n\r\n              'scheduleName',\r\n                schedule_row.schedule_name,\r\n\r\n              'role',\r\n                schedule_row.role::text\r\n            )\r\n          end,\r\n\r\n        'assignmentSource',\r\n          case\r\n            when schedule_row.assignment_source\r\n              is null\r\n            then null\r\n\r\n            else\r\n              schedule_row.assignment_source::text\r\n          end,\r\n\r\n        'assignmentScore',\r\n          schedule_row.assignment_score,\r\n\r\n        'assignmentReasons',\r\n          coalesce(\r\n            schedule_row.assignment_reasons,\r\n            '[]'::jsonb\r\n          ),\r\n\r\n        'isLocked',\r\n          schedule_row.is_locked,\r\n\r\n        'notes',\r\n          schedule_row.notes,\r\n\r\n        'progressState',\r\n          schedule_row.progress_state\r\n      ) as shift_json,\r\n\r\n      schedule_row.assigned_user_id,\r\n      schedule_row.shift_date,\r\n      schedule_row.starts_at\r\n\r\n    from schedule_rows\r\n      schedule_row\r\n  )\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        mapped_row.shift_json\r\n        order by\r\n          mapped_row.shift_date,\r\n          mapped_row.starts_at\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n\r\n  into all_shifts_json\r\n\r\n  from mapped_rows\r\n    mapped_row;\r\n\r\n  if can_view_team_schedule then\r\n    visible_shifts_json :=\r\n      all_shifts_json;\r\n  else\r\n    with personal_rows as (\r\n      select\r\n        schedule_shift.id,\r\n        schedule_shift.period_id,\r\n        schedule_shift.availability_shift_slot_id,\r\n        schedule_shift.shift_date,\r\n        schedule_shift.starts_at,\r\n        schedule_shift.ends_at,\r\n        schedule_shift.shift_code,\r\n        schedule_shift.schedule_type,\r\n        schedule_shift.is_premium,\r\n        schedule_shift.holiday_name,\r\n        schedule_shift.assigned_user_id,\r\n        schedule_shift.assignment_source,\r\n        schedule_shift.assignment_score,\r\n        schedule_shift.assignment_reasons,\r\n        schedule_shift.is_locked,\r\n        schedule_shift.notes,\r\n\r\n        assigned_profile.display_name,\r\n        assigned_profile.schedule_name,\r\n        assigned_profile.role,\r\n\r\n        case\r\n          when schedule_shift.ends_at <=\r\n            generated_at\r\n          then\r\n            'completed'\r\n\r\n          when schedule_shift.starts_at <=\r\n            generated_at\r\n            and schedule_shift.ends_at >\r\n              generated_at\r\n          then\r\n            'current'\r\n\r\n          else\r\n            'upcoming'\r\n        end as progress_state\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      left join public.profiles\r\n        assigned_profile\r\n        on assigned_profile.id =\r\n          schedule_shift.assigned_user_id\r\n\r\n      where schedule_shift.period_id =\r\n        resolved_period.id\r\n\r\n        and schedule_shift.assigned_user_id =\r\n          current_user_id\r\n    )\r\n\r\n    select\r\n      coalesce(\r\n        jsonb_agg(\r\n          jsonb_build_object(\r\n            'id',\r\n              personal_row.id,\r\n\r\n            'periodId',\r\n              personal_row.period_id,\r\n\r\n            'availabilityShiftSlotId',\r\n              personal_row.availability_shift_slot_id,\r\n\r\n            'shiftDate',\r\n              personal_row.shift_date,\r\n\r\n            'startsAt',\r\n              personal_row.starts_at,\r\n\r\n            'endsAt',\r\n              personal_row.ends_at,\r\n\r\n            'shiftCode',\r\n              personal_row.shift_code,\r\n\r\n            'scheduleType',\r\n              personal_row.schedule_type::text,\r\n\r\n            'isPremium',\r\n              personal_row.is_premium,\r\n\r\n            'holidayName',\r\n              personal_row.holiday_name,\r\n\r\n            'assignedUser',\r\n              jsonb_build_object(\r\n                'id',\r\n                  personal_row.assigned_user_id,\r\n\r\n                'displayName',\r\n                  personal_row.display_name,\r\n\r\n                'scheduleName',\r\n                  personal_row.schedule_name,\r\n\r\n                'role',\r\n                  personal_row.role::text\r\n              ),\r\n\r\n            'assignmentSource',\r\n              case\r\n                when personal_row.assignment_source\r\n                  is null\r\n                then null\r\n\r\n                else\r\n                  personal_row.assignment_source::text\r\n              end,\r\n\r\n            'assignmentScore',\r\n              personal_row.assignment_score,\r\n\r\n            'assignmentReasons',\r\n              coalesce(\r\n                personal_row.assignment_reasons,\r\n                '[]'::jsonb\r\n              ),\r\n\r\n            'isLocked',\r\n              personal_row.is_locked,\r\n\r\n            'notes',\r\n              personal_row.notes,\r\n\r\n            'progressState',\r\n              personal_row.progress_state\r\n          )\r\n\r\n          order by\r\n            personal_row.shift_date,\r\n            personal_row.starts_at\r\n        ),\r\n        '[]'::jsonb\r\n      )\r\n\r\n    into visible_shifts_json\r\n\r\n    from personal_rows\r\n      personal_row;\r\n  end if;\r\n\r\n  with user_shift_statistics as (\r\n    select\r\n      assigned_profile.id\r\n        as user_id,\r\n\r\n      assigned_profile.display_name,\r\n      assigned_profile.schedule_name,\r\n\r\n      count(schedule_shift.id)::integer\r\n        as total_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.ends_at <=\r\n          generated_at\r\n      )::integer\r\n        as completed_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.ends_at >\r\n          generated_at\r\n      )::integer\r\n        as remaining_shifts,\r\n\r\n      coalesce(\r\n        round(\r\n          sum(\r\n            extract(\r\n              epoch\r\n              from (\r\n                schedule_shift.ends_at -\r\n                schedule_shift.starts_at\r\n              )\r\n            ) / 3600\r\n          )::numeric,\r\n          2\r\n        ),\r\n        0\r\n      ) as total_scheduled_hours,\r\n\r\n      coalesce(\r\n        round(\r\n          sum(\r\n            case\r\n              when schedule_shift.ends_at <=\r\n                generated_at\r\n              then\r\n                extract(\r\n                  epoch\r\n                  from (\r\n                    schedule_shift.ends_at -\r\n                    schedule_shift.starts_at\r\n                  )\r\n                ) / 3600\r\n\r\n              else 0\r\n            end\r\n          )::numeric,\r\n          2\r\n        ),\r\n        0\r\n      ) as completed_hours,\r\n\r\n      coalesce(\r\n        round(\r\n          sum(\r\n            case\r\n              when schedule_shift.ends_at >\r\n                generated_at\r\n              then\r\n                extract(\r\n                  epoch\r\n                  from (\r\n                    schedule_shift.ends_at -\r\n                    schedule_shift.starts_at\r\n                  )\r\n                ) / 3600\r\n\r\n              else 0\r\n            end\r\n          )::numeric,\r\n          2\r\n        ),\r\n        0\r\n      ) as remaining_hours,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'weekday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '16:00'\r\n      )::integer\r\n        as weekday_evening_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'weekday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '23:00'\r\n      )::integer\r\n        as weekday_night_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'friday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '06:00'\r\n      )::integer\r\n        as friday_morning_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'friday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '14:00'\r\n      )::integer\r\n        as friday_afternoon_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'friday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '22:00'\r\n      )::integer\r\n        as friday_night_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'saturday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '06:00'\r\n      )::integer\r\n        as saturday_morning_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'saturday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '14:00'\r\n      )::integer\r\n        as saturday_afternoon_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'saturday'\r\n\r\n          and (\r\n            schedule_shift.starts_at\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )::time =\r\n            time '22:00'\r\n      )::integer\r\n        as saturday_night_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.is_premium\r\n      )::integer\r\n        as premium_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type\r\n          in (\r\n            'holiday_eve',\r\n            'holiday_full',\r\n            'holiday_end'\r\n          )\r\n      )::integer\r\n        as holiday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.assignment_source =\r\n          'manual'\r\n      )::integer\r\n        as manual_assignments,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.assignment_source =\r\n          'automatic'\r\n      )::integer\r\n        as automatic_assignments\r\n\r\n    from public.profiles\r\n      assigned_profile\r\n\r\n    join public.schedule_shifts\r\n      schedule_shift\r\n      on schedule_shift.assigned_user_id =\r\n        assigned_profile.id\r\n\r\n      and schedule_shift.period_id =\r\n        resolved_period.id\r\n\r\n    group by\r\n      assigned_profile.id,\r\n      assigned_profile.display_name,\r\n      assigned_profile.schedule_name\r\n  ),\r\n\r\n  mapped_statistics as (\r\n    select\r\n      statistics.user_id,\r\n\r\n      jsonb_build_object(\r\n        'userId',\r\n          statistics.user_id,\r\n\r\n        'displayName',\r\n          statistics.display_name,\r\n\r\n        'scheduleName',\r\n          statistics.schedule_name,\r\n\r\n        'totalShifts',\r\n          statistics.total_shifts,\r\n\r\n        'completedShifts',\r\n          statistics.completed_shifts,\r\n\r\n        'remainingShifts',\r\n          statistics.remaining_shifts,\r\n\r\n        'completionPercentage',\r\n          case\r\n            when statistics.total_shifts =\r\n              0\r\n            then 0\r\n\r\n            else round(\r\n              (\r\n                statistics.completed_shifts::numeric /\r\n                statistics.total_shifts::numeric\r\n              ) * 100\r\n            )::integer\r\n          end,\r\n\r\n        'totalScheduledHours',\r\n          statistics.total_scheduled_hours,\r\n\r\n        'completedHours',\r\n          statistics.completed_hours,\r\n\r\n        'remainingHours',\r\n          statistics.remaining_hours,\r\n\r\n        'weekdayEveningShifts',\r\n          statistics.weekday_evening_shifts,\r\n\r\n        'weekdayNightShifts',\r\n          statistics.weekday_night_shifts,\r\n\r\n        'fridayMorningShifts',\r\n          statistics.friday_morning_shifts,\r\n\r\n        'fridayAfternoonShifts',\r\n          statistics.friday_afternoon_shifts,\r\n\r\n        'fridayNightShifts',\r\n          statistics.friday_night_shifts,\r\n\r\n        'saturdayMorningShifts',\r\n          statistics.saturday_morning_shifts,\r\n\r\n        'saturdayAfternoonShifts',\r\n          statistics.saturday_afternoon_shifts,\r\n\r\n        'saturdayNightShifts',\r\n          statistics.saturday_night_shifts,\r\n\r\n        'premiumShifts',\r\n          statistics.premium_shifts,\r\n\r\n        'holidayShifts',\r\n          statistics.holiday_shifts,\r\n\r\n        'manualAssignments',\r\n          statistics.manual_assignments,\r\n\r\n        'automaticAssignments',\r\n          statistics.automatic_assignments\r\n      ) as statistics_json\r\n\r\n    from user_shift_statistics\r\n      statistics\r\n  )\r\n\r\n  select\r\n    (\r\n      select\r\n        mapped.statistics_json\r\n\r\n      from mapped_statistics\r\n        mapped\r\n\r\n      where mapped.user_id =\r\n        current_user_id\r\n\r\n      limit 1\r\n    ),\r\n\r\n    case\r\n      when can_view_team_schedule\r\n      then coalesce(\r\n        (\r\n          select jsonb_agg(\r\n            mapped.statistics_json\r\n            order by\r\n              mapped.statistics_json\r\n                ->> 'displayName'\r\n          )\r\n\r\n          from mapped_statistics\r\n            mapped\r\n        ),\r\n        '[]'::jsonb\r\n      )\r\n\r\n      else\r\n        '[]'::jsonb\r\n    end\r\n\r\n  into\r\n    personal_statistics_json,\r\n    dispatcher_statistics_json;\r\n\r\n  if personal_statistics_json is null then\r\n    personal_statistics_json :=\r\n      jsonb_build_object(\r\n        'userId',\r\n          current_user_id,\r\n\r\n        'displayName',\r\n          current_profile.display_name,\r\n\r\n        'scheduleName',\r\n          current_profile.schedule_name,\r\n\r\n        'totalShifts', 0,\r\n        'completedShifts', 0,\r\n        'remainingShifts', 0,\r\n        'completionPercentage', 0,\r\n\r\n        'totalScheduledHours', 0,\r\n        'completedHours', 0,\r\n        'remainingHours', 0,\r\n\r\n        'weekdayEveningShifts', 0,\r\n        'weekdayNightShifts', 0,\r\n\r\n        'fridayMorningShifts', 0,\r\n        'fridayAfternoonShifts', 0,\r\n        'fridayNightShifts', 0,\r\n\r\n        'saturdayMorningShifts', 0,\r\n        'saturdayAfternoonShifts', 0,\r\n        'saturdayNightShifts', 0,\r\n\r\n        'premiumShifts', 0,\r\n        'holidayShifts', 0,\r\n\r\n        'manualAssignments', 0,\r\n        'automaticAssignments', 0\r\n      );\r\n  end if;\r\n\r\n  if can_view_team_schedule then\r\n    select\r\n      jsonb_build_object(\r\n        'totalShifts',\r\n          count(\r\n            schedule_shift.id\r\n          )::integer,\r\n\r\n        'completedShifts',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.ends_at <=\r\n              generated_at\r\n          )::integer,\r\n\r\n        'remainingShifts',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.ends_at >\r\n              generated_at\r\n          )::integer,\r\n\r\n        'completionPercentage',\r\n          case\r\n            when count(\r\n              schedule_shift.id\r\n            ) = 0\r\n            then 0\r\n\r\n            else round(\r\n              (\r\n                count(\r\n                  schedule_shift.id\r\n                ) filter (\r\n                  where schedule_shift.ends_at <=\r\n                    generated_at\r\n                )::numeric /\r\n                count(\r\n                  schedule_shift.id\r\n                )::numeric\r\n              ) * 100\r\n            )::integer\r\n          end,\r\n\r\n        'assignedDispatchers',\r\n          count(\r\n            distinct\r\n            schedule_shift.assigned_user_id\r\n          ) filter (\r\n            where schedule_shift.assigned_user_id\r\n              is not null\r\n          )::integer,\r\n\r\n        'premiumShifts',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.is_premium\r\n          )::integer,\r\n\r\n        'holidayShifts',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.schedule_type\r\n              in (\r\n                'holiday_eve',\r\n                'holiday_full',\r\n                'holiday_end'\r\n              )\r\n          )::integer,\r\n\r\n        'manualAssignments',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.assignment_source =\r\n              'manual'\r\n          )::integer,\r\n\r\n        'automaticAssignments',\r\n          count(\r\n            schedule_shift.id\r\n          ) filter (\r\n            where schedule_shift.assignment_source =\r\n              'automatic'\r\n          )::integer\r\n      )\r\n\r\n    into team_statistics_json\r\n\r\n    from public.schedule_shifts\r\n      schedule_shift\r\n\r\n    where schedule_shift.period_id =\r\n      resolved_period.id;\r\n  else\r\n    team_statistics_json :=\r\n      jsonb_build_object(\r\n        'totalShifts', 0,\r\n        'completedShifts', 0,\r\n        'remainingShifts', 0,\r\n        'completionPercentage', 0,\r\n        'assignedDispatchers', 0,\r\n        'premiumShifts', 0,\r\n        'holidayShifts', 0,\r\n        'manualAssignments', 0,\r\n        'automaticAssignments', 0\r\n      );\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'access',\r\n    jsonb_build_object(\r\n      'userId',\r\n        current_user_id,\r\n\r\n      'role',\r\n        current_profile.role::text,\r\n\r\n      'canViewSchedule',\r\n        can_view_schedule,\r\n\r\n      'canEditSchedule',\r\n        can_edit_schedule,\r\n\r\n      'canViewTeamSchedule',\r\n        can_view_team_schedule,\r\n\r\n      'defaultViewMode',\r\n        default_view_mode\r\n    ),\r\n\r\n    'period',\r\n    jsonb_build_object(\r\n      'id',\r\n        resolved_period.id,\r\n\r\n      'availabilityPeriodId',\r\n        resolved_period.availability_period_id,\r\n\r\n      'year',\r\n        resolved_period.year,\r\n\r\n      'month',\r\n        resolved_period.month,\r\n\r\n      'title',\r\n        resolved_period.title,\r\n\r\n      'status',\r\n        resolved_period.status::text,\r\n\r\n      'publishedAt',\r\n        resolved_period.published_at,\r\n\r\n      'approvedAt',\r\n        resolved_period.approved_at,\r\n\r\n      'createdAt',\r\n        resolved_period.created_at,\r\n\r\n      'updatedAt',\r\n        resolved_period.updated_at\r\n    ),\r\n\r\n    'shifts',\r\n      case\r\n        when can_view_team_schedule\r\n        then all_shifts_json\r\n        else visible_shifts_json\r\n      end,\r\n\r\n    'visibleShifts',\r\n      visible_shifts_json,\r\n\r\n    'personalStatistics',\r\n      personal_statistics_json,\r\n\r\n    'dispatcherStatistics',\r\n      dispatcher_statistics_json,\r\n\r\n    'teamStatistics',\r\n      team_statistics_json,\r\n\r\n    'generatedAt',\r\n      generated_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_current_schedule_edit_options()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_current_schedule_edit_options()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  actor_user_id uuid := (select auth.uid());\r\n  has_schedule_edit boolean := false;\r\n  dispatcher_rows jsonb;\r\nbegin\r\n  if actor_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = actor_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception 'user not active';\r\n  end if;\r\n\r\n  select exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id = actor_user_id\r\n      and permission.permission_key = 'schedule.edit'\r\n  )\r\n  into has_schedule_edit;\r\n\r\n  if not has_schedule_edit then\r\n    raise exception 'schedule edit permission required';\r\n  end if;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id', profile.id,\r\n        'displayName', profile.display_name,\r\n        'scheduleName', profile.schedule_name\r\n      )\r\n      order by coalesce(profile.schedule_name, profile.display_name)\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into dispatcher_rows\r\n  from public.profiles profile\r\n  where profile.is_active = true\r\n    and profile.role = 'dispatcher';\r\n\r\n  return jsonb_build_object(\r\n    'dispatchers', dispatcher_rows\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_dispatcher_schedule_by_month(integer,integer)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_dispatcher_schedule_by_month(requested_year integer, requested_month integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  requesting_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  selected_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  can_view_team boolean :=\r\n    false;\r\n\r\n  can_view_personal boolean :=\r\n    false;\r\nbegin\r\n  requesting_user_id :=\r\n    auth.uid();\r\n\r\n  if requesting_user_id\r\n    is null\r\n  then\r\n    raise exception\r\n      'Authentication is required.';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      requesting_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'Active user profile was not found.';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  can_view_team :=\r\n    (\r\n      'schedule.view_team' =\r\n        any(current_permissions)\r\n      or\r\n      'schedule.edit' =\r\n        any(current_permissions)\r\n    );\r\n\r\n  can_view_personal :=\r\n    (\r\n      'schedule.view' =\r\n        any(current_permissions)\r\n    );\r\n\r\n  if not (\r\n    can_view_team\r\n    or\r\n    can_view_personal\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_year < 2020\r\n     or requested_year > 2100\r\n  then\r\n    raise exception\r\n      'Invalid schedule year.';\r\n  end if;\r\n\r\n  if requested_month < 1\r\n     or requested_month > 12\r\n  then\r\n    raise exception\r\n      'Invalid schedule month.';\r\n  end if;\r\n\r\n  select *\r\n  into selected_period\r\n  from public.schedule_periods\r\n  where year =\r\n      requested_year\r\n    and month =\r\n      requested_month\r\n  limit 1;\r\n\r\n  if not found then\r\n    return jsonb_build_object(\r\n      'period',\r\n        null,\r\n\r\n      'shifts',\r\n        '[]'::jsonb\r\n    );\r\n  end if;\r\n\r\n  /*\r\n   * משתמש אישי לא אמור לראות\r\n   * טיוטה או חודש שטרם פורסם.\r\n   */\r\n  if (\r\n    not can_view_team\r\n    and\r\n    selected_period.status not in (\r\n      'published',\r\n      'archived'\r\n    )\r\n  ) then\r\n    return jsonb_build_object(\r\n      'period',\r\n        null,\r\n\r\n      'shifts',\r\n        '[]'::jsonb\r\n    );\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          selected_period.id,\r\n\r\n        'year',\r\n          selected_period.year,\r\n\r\n        'month',\r\n          selected_period.month,\r\n\r\n        'status',\r\n          selected_period.status,\r\n\r\n        'publishedAt',\r\n          selected_period.published_at,\r\n\r\n        'createdAt',\r\n          selected_period.created_at,\r\n\r\n        'updatedAt',\r\n          selected_period.updated_at\r\n      ),\r\n\r\n    'shifts',\r\n      coalesce(\r\n        (\r\n          select jsonb_agg(\r\n            jsonb_build_object(\r\n              'id',\r\n                shift.id,\r\n\r\n              'periodId',\r\n                shift.period_id,\r\n\r\n              'shiftDate',\r\n                shift.shift_date,\r\n\r\n              'startsAt',\r\n                shift.starts_at,\r\n\r\n              'endsAt',\r\n                shift.ends_at,\r\n\r\n              'shiftCode',\r\n                shift.shift_code,\r\n\r\n              'scheduleType',\r\n                shift.schedule_type,\r\n\r\n              'isPremium',\r\n                shift.is_premium,\r\n\r\n              'holidayName',\r\n                shift.holiday_name,\r\n\r\n              'assignedUserId',\r\n                shift.assigned_user_id,\r\n\r\n              'assignedUserName',\r\n                coalesce(\r\n                  assigned_profile.schedule_name,\r\n                  assigned_profile.display_name\r\n                ),\r\n\r\n              'isLocked',\r\n                shift.is_locked,\r\n\r\n              'notes',\r\n                shift.notes\r\n            )\r\n            order by\r\n              shift.shift_date,\r\n              shift.starts_at\r\n          )\r\n\r\n          from public.schedule_shifts\r\n            shift\r\n\r\n          left join public.profiles\r\n            assigned_profile\r\n            on assigned_profile.id =\r\n              shift.assigned_user_id\r\n\r\n          where shift.period_id =\r\n            selected_period.id\r\n\r\n            and (\r\n              can_view_team\r\n              or\r\n              shift.assigned_user_id =\r\n                requesting_user_id\r\n            )\r\n        ),\r\n        '[]'::jsonb\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_driver_availability_management(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_driver_availability_management(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  days_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  drivers_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  submissions_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  entries_json jsonb :=\r\n    '[]'::jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            day_row.id,\r\n\r\n          'periodId',\r\n            day_row.period_id,\r\n\r\n          'availabilityDate',\r\n            day_row.availability_date,\r\n\r\n          'weekdayNumber',\r\n            day_row.weekday_number,\r\n\r\n          'weekdayName',\r\n            day_row.weekday_name,\r\n\r\n          'sortOrder',\r\n            day_row.sort_order,\r\n\r\n          'createdAt',\r\n            day_row.created_at\r\n        )\r\n        order by\r\n          day_row.availability_date\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into days_json\r\n  from public.driver_availability_days\r\n    day_row\r\n  where day_row.period_id =\r\n    target_period.id;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile.id,\r\n\r\n          'displayName',\r\n            profile.display_name,\r\n\r\n          'scheduleName',\r\n            profile.schedule_name,\r\n\r\n          'email',\r\n            profile.email,\r\n\r\n          'role',\r\n            profile.role::text,\r\n\r\n          'isActive',\r\n            profile.is_active\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile.schedule_name,\r\n            profile.display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into drivers_json\r\n  from public.profiles\r\n    profile\r\n  where profile.role =\r\n    'on_call'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            submission.id,\r\n\r\n          'periodId',\r\n            submission.period_id,\r\n\r\n          'userId',\r\n            submission.user_id,\r\n\r\n          'status',\r\n            submission.status,\r\n\r\n          'submittedAt',\r\n            submission.submitted_at,\r\n\r\n          'reopenedAt',\r\n            submission.reopened_at,\r\n\r\n          'lastSavedAt',\r\n            submission.last_saved_at,\r\n\r\n          'availableCount',\r\n            submission.available_count,\r\n\r\n          'unavailableCount',\r\n            submission.unavailable_count,\r\n\r\n          'createdAt',\r\n            submission.created_at,\r\n\r\n          'updatedAt',\r\n            submission.updated_at\r\n        )\r\n        order by\r\n          submission.user_id\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into submissions_json\r\n  from public.driver_availability_submissions\r\n    submission\r\n  where submission.period_id =\r\n    target_period.id;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            entry.id,\r\n\r\n          'periodId',\r\n            entry.period_id,\r\n\r\n          'dayId',\r\n            entry.day_id,\r\n\r\n          'userId',\r\n            entry.user_id,\r\n\r\n          'availabilityStatus',\r\n            entry.availability_status,\r\n\r\n          'note',\r\n            entry.note,\r\n\r\n          'createdAt',\r\n            entry.created_at,\r\n\r\n          'updatedAt',\r\n            entry.updated_at\r\n        )\r\n        order by\r\n          day_row.availability_date,\r\n          entry.user_id\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into entries_json\r\n  from public.driver_availability_entries\r\n    entry\r\n  join public.driver_availability_days\r\n    day_row\r\n    on day_row.id =\r\n      entry.day_id\r\n  where entry.period_id =\r\n    target_period.id;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_period.id,\r\n\r\n        'year',\r\n          target_period.year,\r\n\r\n        'month',\r\n          target_period.month,\r\n\r\n        'status',\r\n          target_period.status,\r\n\r\n        'title',\r\n          target_period.title,\r\n\r\n        'instructions',\r\n          target_period.instructions,\r\n\r\n        'submissionDeadline',\r\n          target_period.submission_deadline,\r\n\r\n        'openedAt',\r\n          target_period.opened_at,\r\n\r\n        'closedAt',\r\n          target_period.closed_at,\r\n\r\n        'createdBy',\r\n          target_period.created_by,\r\n\r\n        'updatedBy',\r\n          target_period.updated_by,\r\n\r\n        'createdAt',\r\n          target_period.created_at,\r\n\r\n        'updatedAt',\r\n          target_period.updated_at\r\n      ),\r\n\r\n    'days',\r\n      days_json,\r\n\r\n    'drivers',\r\n      drivers_json,\r\n\r\n    'submissions',\r\n      submissions_json,\r\n\r\n    'entries',\r\n      entries_json,\r\n\r\n    'statistics',\r\n      jsonb_build_object(\r\n        'totalDrivers',\r\n          jsonb_array_length(\r\n            drivers_json\r\n          ),\r\n\r\n        'submittedDrivers',\r\n          (\r\n            select\r\n              count(*)::integer\r\n            from public.driver_availability_submissions\r\n            where period_id =\r\n              target_period.id\r\n              and status =\r\n                'submitted'\r\n          ),\r\n\r\n        'draftDrivers',\r\n          (\r\n            select\r\n              count(*)::integer\r\n            from public.driver_availability_submissions\r\n            where period_id =\r\n              target_period.id\r\n              and status in (\r\n                'draft',\r\n                'reopened'\r\n              )\r\n          ),\r\n\r\n        'notStartedDrivers',\r\n          greatest(\r\n            jsonb_array_length(\r\n              drivers_json\r\n            ) -\r\n            (\r\n              select\r\n                count(\r\n                  distinct user_id\r\n                )::integer\r\n              from public.driver_availability_submissions\r\n              where period_id =\r\n                target_period.id\r\n            ),\r\n            0\r\n          )\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_driver_availability_periods()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_driver_availability_periods()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  can_view boolean := false;\r\n  can_manage boolean := false;\r\n\r\n  periods_json jsonb :=\r\n    '[]'::jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  can_view :=\r\n    'driver_availability.view' =\r\n      any(current_permissions);\r\n\r\n  can_manage :=\r\n    'driver_availability.manage' =\r\n      any(current_permissions);\r\n\r\n  if not (\r\n    can_view or\r\n    can_manage\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            period.id,\r\n\r\n          'year',\r\n            period.year,\r\n\r\n          'month',\r\n            period.month,\r\n\r\n          'status',\r\n            period.status,\r\n\r\n          'title',\r\n            period.title,\r\n\r\n          'instructions',\r\n            period.instructions,\r\n\r\n          'submissionDeadline',\r\n            period.submission_deadline,\r\n\r\n          'openedAt',\r\n            period.opened_at,\r\n\r\n          'closedAt',\r\n            period.closed_at,\r\n\r\n          'createdBy',\r\n            period.created_by,\r\n\r\n          'updatedBy',\r\n            period.updated_by,\r\n\r\n          'createdAt',\r\n            period.created_at,\r\n\r\n          'updatedAt',\r\n            period.updated_at,\r\n\r\n          'daysCount',\r\n            (\r\n              select\r\n                count(*)::integer\r\n              from public.driver_availability_days day_row\r\n              where day_row.period_id =\r\n                period.id\r\n            ),\r\n\r\n          'submissionsCount',\r\n            (\r\n              select\r\n                count(*)::integer\r\n              from public.driver_availability_submissions submission\r\n              where submission.period_id =\r\n                period.id\r\n            ),\r\n\r\n          'submittedCount',\r\n            (\r\n              select\r\n                count(*)::integer\r\n              from public.driver_availability_submissions submission\r\n              where submission.period_id =\r\n                period.id\r\n                and submission.status =\r\n                  'submitted'\r\n            )\r\n        )\r\n        order by\r\n          period.year desc,\r\n          period.month desc\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into periods_json\r\n  from public.driver_availability_periods period\r\n  where\r\n    can_manage\r\n    or\r\n    (\r\n      can_view\r\n      and period.status in (\r\n        'open',\r\n        'closed'\r\n      )\r\n    );\r\n\r\n  return periods_json;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_driver_schedule_draft(uuid,integer,integer)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_driver_schedule_draft(requested_schedule_period_id uuid DEFAULT NULL::uuid, requested_year integer DEFAULT NULL::integer, requested_month integer DEFAULT NULL::integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  days_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  drivers_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  assigned_days_count integer := 0;\r\n  unassigned_days_count integer := 0;\r\n  warning_count integer := 0;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_schedule.view' =\r\n      any(current_permissions)\r\n    or\r\n    'driver_schedule.view_team' =\r\n      any(current_permissions)\r\n    or\r\n    'driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_period_id\r\n    is not null\r\n  then\r\n    select *\r\n    into target_period\r\n    from public.driver_schedule_periods\r\n    where id =\r\n      requested_schedule_period_id\r\n    limit 1;\r\n  elsif (\r\n    requested_year is not null\r\n    and requested_month is not null\r\n  ) then\r\n    select *\r\n    into target_period\r\n    from public.driver_schedule_periods\r\n    where year =\r\n      requested_year\r\n      and month =\r\n        requested_month\r\n    limit 1;\r\n  else\r\n    select *\r\n    into target_period\r\n    from public.driver_schedule_periods\r\n    order by\r\n      year desc,\r\n      month desc,\r\n      created_at desc\r\n    limit 1;\r\n  end if;\r\n\r\n  if not found then\r\n    return jsonb_build_object(\r\n      'period',\r\n        null,\r\n\r\n      'days',\r\n        '[]'::jsonb,\r\n\r\n      'drivers',\r\n        '[]'::jsonb,\r\n\r\n      'statistics',\r\n        jsonb_build_object(\r\n          'totalDays',\r\n            0,\r\n\r\n          'assignedDays',\r\n            0,\r\n\r\n          'unassignedDays',\r\n            0,\r\n\r\n          'warningCount',\r\n            0\r\n        )\r\n    );\r\n  end if;\r\n\r\n  select\r\n    count(*) filter (\r\n      where assigned_user_id\r\n        is not null\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where assigned_user_id\r\n        is null\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where notes is not null\r\n    )::integer\r\n\r\n  into\r\n    assigned_days_count,\r\n    unassigned_days_count,\r\n    warning_count\r\n\r\n  from public.driver_schedule_days\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            schedule_day.id,\r\n\r\n          'periodId',\r\n            schedule_day.period_id,\r\n\r\n          'dutyDate',\r\n            schedule_day.duty_date,\r\n\r\n          'weekdayNumber',\r\n            schedule_day.weekday_number,\r\n\r\n          'weekdayName',\r\n            schedule_day.weekday_name,\r\n\r\n          'originalUserId',\r\n            schedule_day.original_user_id,\r\n\r\n          'originalUserName',\r\n            coalesce(\r\n              original_profile.schedule_name,\r\n              original_profile.display_name\r\n            ),\r\n\r\n          'assignedUserId',\r\n            schedule_day.assigned_user_id,\r\n\r\n          'assignedUserName',\r\n            coalesce(\r\n              assigned_profile.schedule_name,\r\n              assigned_profile.display_name\r\n            ),\r\n\r\n          'assignmentSource',\r\n            schedule_day.assignment_source,\r\n\r\n          'isLocked',\r\n            schedule_day.is_locked,\r\n\r\n          'notes',\r\n            schedule_day.notes,\r\n\r\n          'spacingWarning',\r\n            schedule_day.notes\r\n              is not null,\r\n\r\n          'createdAt',\r\n            schedule_day.created_at,\r\n\r\n          'updatedAt',\r\n            schedule_day.updated_at\r\n        )\r\n        order by\r\n          schedule_day.duty_date\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into days_json\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n\r\n  left join public.profiles\r\n    original_profile\r\n    on original_profile.id =\r\n      schedule_day.original_user_id\r\n\r\n  left join public.profiles\r\n    assigned_profile\r\n    on assigned_profile.id =\r\n      schedule_day.assigned_user_id\r\n\r\n  where schedule_day.period_id =\r\n    target_period.id\r\n\r\n    and (\r\n      'driver_schedule.view_team' =\r\n        any(current_permissions)\r\n\r\n      or\r\n\r\n      'driver_schedule.edit' =\r\n        any(current_permissions)\r\n\r\n      or\r\n\r\n      schedule_day.assigned_user_id =\r\n        current_user_id\r\n    );\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile.id,\r\n\r\n          'displayName',\r\n            profile.display_name,\r\n\r\n          'scheduleName',\r\n            profile.schedule_name,\r\n\r\n          'email',\r\n            profile.email,\r\n\r\n          'isActive',\r\n            profile.is_active\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile.schedule_name,\r\n            profile.display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into drivers_json\r\n  from public.profiles\r\n    profile\r\n  where profile.role =\r\n    'on_call'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_period.id,\r\n\r\n        'year',\r\n          target_period.year,\r\n\r\n        'month',\r\n          target_period.month,\r\n\r\n        'status',\r\n          target_period.status,\r\n\r\n        'availabilityPeriodId',\r\n          target_period.availability_period_id,\r\n\r\n        'title',\r\n          target_period.title,\r\n\r\n        'publishedAt',\r\n          target_period.published_at,\r\n\r\n        'archivedAt',\r\n          target_period.archived_at,\r\n\r\n        'createdBy',\r\n          target_period.created_by,\r\n\r\n        'updatedBy',\r\n          target_period.updated_by,\r\n\r\n        'createdAt',\r\n          target_period.created_at,\r\n\r\n        'updatedAt',\r\n          target_period.updated_at\r\n      ),\r\n\r\n    'days',\r\n      days_json,\r\n\r\n    'drivers',\r\n      drivers_json,\r\n\r\n    'statistics',\r\n      jsonb_build_object(\r\n        'totalDays',\r\n          assigned_days_count +\r\n          unassigned_days_count,\r\n\r\n        'assignedDays',\r\n          assigned_days_count,\r\n\r\n        'unassignedDays',\r\n          unassigned_days_count,\r\n\r\n        'warningCount',\r\n          warning_count\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_morning_driver_archive_summary()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_morning_driver_archive_summary()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n  result_json jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'archive.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'year',\r\n            period.year,\r\n\r\n          'month',\r\n            period.month,\r\n\r\n          'periodId',\r\n            period.id,\r\n\r\n          'status',\r\n            period.status,\r\n\r\n          'assignmentCount',\r\n            coalesce(\r\n              stats.assignment_count,\r\n              0\r\n            ),\r\n\r\n          'driverCount',\r\n            coalesce(\r\n              stats.driver_count,\r\n              0\r\n            ),\r\n\r\n          /*\r\n           * בטבלת morning_driver_schedule_periods\r\n           * אין archived_at.\r\n           * נשאיר null במקום להמציא תאריך ארכוב.\r\n           */\r\n          'archivedAt',\r\n            null,\r\n\r\n          'hasSchedule',\r\n            true\r\n        )\r\n        order by\r\n          period.year desc,\r\n          period.month desc\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n\r\n  into result_json\r\n\r\n  from public.morning_driver_schedule_periods\r\n    period\r\n\r\n  left join lateral (\r\n    select\r\n      count(*) filter (\r\n        where\r\n          assignment.assigned_user_id\r\n            is not null\r\n      )::integer\r\n        as assignment_count,\r\n\r\n      count(\r\n        distinct\r\n        assignment.assigned_user_id\r\n      ) filter (\r\n        where\r\n          assignment.assigned_user_id\r\n            is not null\r\n      )::integer\r\n        as driver_count\r\n\r\n    from public.morning_driver_schedule_assignments\r\n      assignment\r\n\r\n    where\r\n      assignment.schedule_period_id =\r\n        period.id\r\n  ) stats\r\n    on true\r\n\r\n  where\r\n    period.status =\r\n      'archived';\r\n\r\n  return result_json;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_morning_driver_availability_management(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_morning_driver_availability_management(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  drivers_json jsonb;\r\n  submissions_json jsonb;\r\n  shifts_json jsonb;\r\n  entries_json jsonb;\r\n\r\n  total_drivers integer := 0;\r\n  submitted_drivers integer := 0;\r\n  draft_drivers integer := 0;\r\n  reopened_drivers integer := 0;\r\n  not_started_drivers integer := 0;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception 'period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id = requested_period_id;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          profile.id,\r\n\r\n        'displayName',\r\n          profile.display_name,\r\n\r\n        'scheduleName',\r\n          profile.schedule_name,\r\n\r\n        'email',\r\n          profile.email,\r\n\r\n        'isActive',\r\n          profile.is_active\r\n      )\r\n      order by\r\n        coalesce(\r\n          profile.schedule_name,\r\n          profile.display_name\r\n        )\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into drivers_json\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          submission.id,\r\n\r\n        'periodId',\r\n          submission.period_id,\r\n\r\n        'userId',\r\n          submission.user_id,\r\n\r\n        'status',\r\n          submission.status,\r\n\r\n        'submittedAt',\r\n          submission.submitted_at,\r\n\r\n        'lastSavedAt',\r\n          submission.last_saved_at,\r\n\r\n        'createdAt',\r\n          submission.created_at,\r\n\r\n        'updatedAt',\r\n          submission.updated_at,\r\n\r\n        'availableCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_entries entry\r\n            where entry.period_id = target_period.id\r\n              and entry.user_id = submission.user_id\r\n              and entry.availability_status = 'available'\r\n          ),\r\n\r\n        'unavailableCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_entries entry\r\n            where entry.period_id = target_period.id\r\n              and entry.user_id = submission.user_id\r\n              and entry.availability_status = 'unavailable'\r\n          ),\r\n\r\n        'unmarkedCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_shifts shift_item\r\n            left join public.morning_driver_availability_entries entry\r\n              on entry.shift_id = shift_item.id\r\n             and entry.user_id = submission.user_id\r\n            where shift_item.period_id = target_period.id\r\n              and entry.id is null\r\n          )\r\n      )\r\n      order by submission.created_at\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into submissions_json\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          shift_item.id,\r\n\r\n        'periodId',\r\n          shift_item.period_id,\r\n\r\n        'shiftDate',\r\n          shift_item.shift_date,\r\n\r\n        'weekdayNumber',\r\n          shift_item.weekday_number,\r\n\r\n        'weekdayName',\r\n          shift_item.weekday_name,\r\n\r\n        'shiftType',\r\n          shift_item.shift_type,\r\n\r\n        'startTime',\r\n          shift_item.start_time,\r\n\r\n        'endTime',\r\n          shift_item.end_time,\r\n\r\n        'minimumWorkers',\r\n          1,\r\n\r\n        'recommendedWorkers',\r\n          shift_item.required_workers,\r\n\r\n        'sortOrder',\r\n          shift_item.sort_order\r\n      )\r\n      order by\r\n        shift_item.shift_date,\r\n        shift_item.sort_order\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into shifts_json\r\n  from public.morning_driver_availability_shifts shift_item\r\n  where shift_item.period_id = target_period.id;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          entry.id,\r\n\r\n        'periodId',\r\n          entry.period_id,\r\n\r\n        'shiftId',\r\n          entry.shift_id,\r\n\r\n        'userId',\r\n          entry.user_id,\r\n\r\n        'availabilityStatus',\r\n          entry.availability_status,\r\n\r\n        'note',\r\n          entry.note,\r\n\r\n        'createdAt',\r\n          entry.created_at,\r\n\r\n        'updatedAt',\r\n          entry.updated_at\r\n      )\r\n      order by entry.created_at\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into entries_json\r\n  from public.morning_driver_availability_entries entry\r\n  where entry.period_id = target_period.id;\r\n\r\n  select count(*)\r\n  into total_drivers\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  select count(*)\r\n  into submitted_drivers\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.status = 'submitted';\r\n\r\n  select count(*)\r\n  into draft_drivers\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.status = 'draft';\r\n\r\n  select count(*)\r\n  into reopened_drivers\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.status = 'reopened';\r\n\r\n  not_started_drivers :=\r\n    greatest(\r\n      total_drivers\r\n      - submitted_drivers\r\n      - draft_drivers\r\n      - reopened_drivers,\r\n      0\r\n    );\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_period.id,\r\n\r\n        'year',\r\n          target_period.year,\r\n\r\n        'month',\r\n          target_period.month,\r\n\r\n        'status',\r\n          target_period.status,\r\n\r\n        'title',\r\n          target_period.title,\r\n\r\n        'instructions',\r\n          target_period.instructions,\r\n\r\n        'submissionDeadline',\r\n          target_period.submission_deadline,\r\n\r\n        'openedAt',\r\n          target_period.opened_at,\r\n\r\n        'closedAt',\r\n          target_period.closed_at,\r\n\r\n        'createdAt',\r\n          target_period.created_at\r\n      ),\r\n\r\n    'drivers',\r\n      drivers_json,\r\n\r\n    'submissions',\r\n      submissions_json,\r\n\r\n    'shifts',\r\n      shifts_json,\r\n\r\n    'entries',\r\n      entries_json,\r\n\r\n    'statistics',\r\n      jsonb_build_object(\r\n        'totalDrivers',\r\n          total_drivers,\r\n\r\n        'submittedDrivers',\r\n          submitted_drivers,\r\n\r\n        'draftDrivers',\r\n          draft_drivers,\r\n\r\n        'reopenedDrivers',\r\n          reopened_drivers,\r\n\r\n        'notStartedDrivers',\r\n          not_started_drivers\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
