    "function_signature": "get_morning_driver_availability_periods()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_morning_driver_availability_periods()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n  periods_json jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.view'\r\n      = any(current_permissions)\r\n    or\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          period.id,\r\n\r\n        'year',\r\n          period.year,\r\n\r\n        'month',\r\n          period.month,\r\n\r\n        'status',\r\n          period.status,\r\n\r\n        'title',\r\n          period.title,\r\n\r\n        'instructions',\r\n          period.instructions,\r\n\r\n        'submissionDeadline',\r\n          period.submission_deadline,\r\n\r\n        'openedAt',\r\n          period.opened_at,\r\n\r\n        'closedAt',\r\n          period.closed_at,\r\n\r\n        'createdAt',\r\n          period.created_at,\r\n\r\n        'shiftsCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_shifts shift_item\r\n            where shift_item.period_id = period.id\r\n          ),\r\n\r\n        'submissionsCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_submissions submission\r\n            where submission.period_id = period.id\r\n          ),\r\n\r\n        'submittedCount',\r\n          (\r\n            select count(*)\r\n            from public.morning_driver_availability_submissions submission\r\n            where submission.period_id = period.id\r\n              and submission.status = 'submitted'\r\n          )\r\n      )\r\n      order by\r\n        period.year desc,\r\n        period.month desc\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into periods_json\r\n  from public.morning_driver_availability_periods period;\r\n\r\n  return periods_json;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_morning_driver_schedule(uuid,integer,integer)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_morning_driver_schedule(requested_schedule_period_id uuid DEFAULT NULL::uuid, requested_year integer DEFAULT NULL::integer, requested_month integer DEFAULT NULL::integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  schedule_period\r\n    public.morning_driver_schedule_periods%rowtype;\r\n\r\n  can_view_team boolean;\r\n\r\n  can_edit boolean;\r\n\r\n  can_view_personal boolean;\r\n\r\n  drivers_json jsonb;\r\n\r\n  assignments_json jsonb;\r\n\r\n  total_assignments integer := 0;\r\n\r\n  assigned_assignments integer := 0;\r\n\r\n  minimum_unfilled integer := 0;\r\n\r\n  recommendation_unfilled integer := 0;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  can_view_personal :=\r\n    'morning_driver_schedule.view'\r\n      = any(current_permissions);\r\n\r\n  can_view_team :=\r\n    'morning_driver_schedule.view_team'\r\n      = any(current_permissions);\r\n\r\n  can_edit :=\r\n    'morning_driver_schedule.edit'\r\n      = any(current_permissions);\r\n\r\n  if not (\r\n    can_view_personal\r\n    or can_view_team\r\n    or can_edit\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_period_id\r\n    is not null\r\n  then\r\n    select *\r\n    into schedule_period\r\n    from public.morning_driver_schedule_periods period\r\n    where period.id =\r\n      requested_schedule_period_id;\r\n\r\n  elsif requested_year is not null\r\n    and requested_month is not null\r\n  then\r\n    select *\r\n    into schedule_period\r\n    from public.morning_driver_schedule_periods period\r\n    where period.year =\r\n      requested_year\r\n      and period.month =\r\n        requested_month\r\n    limit 1;\r\n\r\n  else\r\n    select *\r\n    into schedule_period\r\n    from public.morning_driver_schedule_periods period\r\n    order by\r\n      period.year desc,\r\n      period.month desc\r\n    limit 1;\r\n  end if;\r\n\r\n  if not found then\r\n    return null;\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile.id,\r\n\r\n          'displayName',\r\n            profile.display_name,\r\n\r\n          'scheduleName',\r\n            profile.schedule_name,\r\n\r\n          'email',\r\n            profile.email\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile.schedule_name,\r\n            profile.display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    drivers_json\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'\r\n        ::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            assignment.id,\r\n\r\n          'schedulePeriodId',\r\n            assignment.schedule_period_id,\r\n\r\n          'availabilityShiftId',\r\n            shift_item.id,\r\n\r\n          'shiftDate',\r\n            shift_item.shift_date,\r\n\r\n          'weekdayNumber',\r\n            shift_item.weekday_number,\r\n\r\n          'weekdayName',\r\n            shift_item.weekday_name,\r\n\r\n          'shiftType',\r\n            shift_item.shift_type,\r\n\r\n          'startTime',\r\n            shift_item.start_time,\r\n\r\n          'endTime',\r\n            shift_item.end_time,\r\n\r\n          /*\r\n           * במבנה הקיים:\r\n           * המינימום הוא תמיד עובד אחד.\r\n           */\r\n          'minimumWorkers',\r\n            1,\r\n\r\n          /*\r\n           * required_workers משמש\r\n           * ככמות העובדים המומלצת.\r\n           *\r\n           * בוקר רגיל:\r\n           * 2.\r\n           *\r\n           * ערב או שישי:\r\n           * 1.\r\n           */\r\n          'recommendedWorkers',\r\n            coalesce(\r\n              shift_item.required_workers,\r\n              1\r\n            ),\r\n\r\n          'assignmentSlot',\r\n            assignment.assignment_slot,\r\n\r\n          'assignedUserId',\r\n            assignment.assigned_user_id,\r\n\r\n          'assignedUserName',\r\n            coalesce(\r\n              assigned_profile.schedule_name,\r\n              assigned_profile.display_name\r\n            ),\r\n\r\n          'assignmentSource',\r\n            assignment.assignment_source,\r\n\r\n          'isLocked',\r\n            assignment.is_locked,\r\n\r\n          'notes',\r\n            assignment.notes,\r\n\r\n          'updatedAt',\r\n            assignment.updated_at\r\n        )\r\n        order by\r\n          shift_item.shift_date,\r\n          shift_item.sort_order,\r\n          assignment.assignment_slot\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    assignments_json\r\n  from public.morning_driver_schedule_assignments assignment\r\n\r\n  join public.morning_driver_availability_shifts shift_item\r\n    on shift_item.id =\r\n      assignment.availability_shift_id\r\n\r\n  left join public.profiles assigned_profile\r\n    on assigned_profile.id =\r\n      assignment.assigned_user_id\r\n\r\n  where assignment.schedule_period_id =\r\n      schedule_period.id\r\n\r\n    and (\r\n      can_view_team\r\n      or can_edit\r\n      or assignment.assigned_user_id =\r\n        current_user_id\r\n    );\r\n\r\n  select\r\n    count(*)\r\n  into\r\n    total_assignments\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id =\r\n    schedule_period.id;\r\n\r\n  select\r\n    count(*)\r\n  into\r\n    assigned_assignments\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id =\r\n      schedule_period.id\r\n    and assignment.assigned_user_id\r\n      is not null;\r\n\r\n  select\r\n    count(*)\r\n  into\r\n    minimum_unfilled\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id =\r\n      schedule_period.id\r\n    and assignment.assignment_slot = 1\r\n    and assignment.assigned_user_id\r\n      is null;\r\n\r\n  select\r\n    count(*)\r\n  into\r\n    recommendation_unfilled\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id =\r\n      schedule_period.id\r\n    and assignment.assignment_slot > 1\r\n    and assignment.assigned_user_id\r\n      is null;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          schedule_period.id,\r\n\r\n        'year',\r\n          schedule_period.year,\r\n\r\n        'month',\r\n          schedule_period.month,\r\n\r\n        'status',\r\n          schedule_period.status,\r\n\r\n        'availabilityPeriodId',\r\n          schedule_period.availability_period_id,\r\n\r\n        'title',\r\n          schedule_period.title,\r\n\r\n        'publishedAt',\r\n          schedule_period.published_at,\r\n\r\n        'createdAt',\r\n          schedule_period.created_at,\r\n\r\n        'updatedAt',\r\n          schedule_period.updated_at\r\n      ),\r\n\r\n    'drivers',\r\n      drivers_json,\r\n\r\n    'assignments',\r\n      assignments_json,\r\n\r\n    'statistics',\r\n      jsonb_build_object(\r\n        'totalAssignments',\r\n          total_assignments,\r\n\r\n        'assignedAssignments',\r\n          assigned_assignments,\r\n\r\n        'unassignedAssignments',\r\n          greatest(\r\n            total_assignments -\r\n            assigned_assignments,\r\n            0\r\n          ),\r\n\r\n        'minimumUnfilled',\r\n          minimum_unfilled,\r\n\r\n        'recommendationUnfilled',\r\n          recommendation_unfilled\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_morning_driver_schedule_by_month(integer,integer)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_morning_driver_schedule_by_month(requested_year integer, requested_month integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n  target_period public.morning_driver_schedule_periods%rowtype;\r\n  assignments_json jsonb := '[]'::jsonb;\r\n  drivers_json jsonb := '[]'::jsonb;\r\n  total_assignments integer := 0;\r\n  assigned_assignments integer := 0;\r\n  unassigned_assignments integer := 0;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception 'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_schedule.view' =\r\n      any(current_permissions)\r\n    or\r\n    'morning_driver_schedule.view_team' =\r\n      any(current_permissions)\r\n    or\r\n    'morning_driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_year < 2020\r\n    or requested_year > 2100\r\n    or requested_month < 1\r\n    or requested_month > 12\r\n  then\r\n    raise exception 'invalid year or month';\r\n  end if;\r\n\r\n  select period.*\r\n  into target_period\r\n  from public.morning_driver_schedule_periods period\r\n  where period.year = requested_year\r\n    and period.month = requested_month\r\n  order by period.created_at desc\r\n  limit 1;\r\n\r\n  if not found then\r\n    return null;\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer,\r\n    count(*) filter (\r\n      where assignment.assigned_user_id is not null\r\n    )::integer,\r\n    count(*) filter (\r\n      where assignment.assigned_user_id is null\r\n    )::integer\r\n  into\r\n    total_assignments,\r\n    assigned_assignments,\r\n    unassigned_assignments\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id = target_period.id\r\n    and (\r\n      'morning_driver_schedule.view_team' =\r\n        any(current_permissions)\r\n      or\r\n      'morning_driver_schedule.edit' =\r\n        any(current_permissions)\r\n      or\r\n      assignment.assigned_user_id =\r\n        current_user_id\r\n    );\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            assignment.id,\r\n          'schedulePeriodId',\r\n            assignment.schedule_period_id,\r\n          'availabilityShiftId',\r\n            assignment.availability_shift_id,\r\n          'shiftDate',\r\n            availability_shift.shift_date,\r\n          'weekdayNumber',\r\n            availability_shift.weekday_number,\r\n          'weekdayName',\r\n            availability_shift.weekday_name,\r\n          'shiftType',\r\n            availability_shift.shift_type,\r\n          'startTime',\r\n            availability_shift.start_time,\r\n          'endTime',\r\n            availability_shift.end_time,\r\n          'minimumWorkers',\r\n            availability_shift.minimum_workers,\r\n          'recommendedWorkers',\r\n            availability_shift.recommended_workers,\r\n          'assignmentSlot',\r\n            assignment.assignment_slot,\r\n          'assignedUserId',\r\n            assignment.assigned_user_id,\r\n          'assignedUserName',\r\n            coalesce(\r\n              profile.schedule_name,\r\n              profile.display_name\r\n            ),\r\n          'assignmentSource',\r\n            assignment.assignment_source,\r\n          'isLocked',\r\n            assignment.is_locked,\r\n          'notes',\r\n            assignment.notes,\r\n          'updatedAt',\r\n            assignment.updated_at\r\n        )\r\n        order by\r\n          availability_shift.shift_date,\r\n          availability_shift.sort_order,\r\n          assignment.assignment_slot\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into assignments_json\r\n  from public.morning_driver_schedule_assignments assignment\r\n  join public.morning_driver_availability_shifts availability_shift\r\n    on availability_shift.id =\r\n      assignment.availability_shift_id\r\n  left join public.profiles profile\r\n    on profile.id =\r\n      assignment.assigned_user_id\r\n  where assignment.schedule_period_id =\r\n    target_period.id\r\n    and (\r\n      'morning_driver_schedule.view_team' =\r\n        any(current_permissions)\r\n      or\r\n      'morning_driver_schedule.edit' =\r\n        any(current_permissions)\r\n      or\r\n      assignment.assigned_user_id =\r\n        current_user_id\r\n    );\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile.id,\r\n          'displayName',\r\n            profile.display_name,\r\n          'scheduleName',\r\n            profile.schedule_name,\r\n          'email',\r\n            profile.email\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile.schedule_name,\r\n            profile.display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into drivers_json\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_period.id,\r\n        'year',\r\n          target_period.year,\r\n        'month',\r\n          target_period.month,\r\n        'status',\r\n          target_period.status,\r\n        'availabilityPeriodId',\r\n          target_period.availability_period_id,\r\n        'title',\r\n          target_period.title,\r\n        'publishedAt',\r\n          target_period.published_at,\r\n        'createdAt',\r\n          target_period.created_at,\r\n        'updatedAt',\r\n          target_period.updated_at\r\n      ),\r\n    'drivers',\r\n      drivers_json,\r\n    'assignments',\r\n      assignments_json,\r\n    'statistics',\r\n      jsonb_build_object(\r\n        'totalAssignments',\r\n          total_assignments,\r\n        'assignedAssignments',\r\n          assigned_assignments,\r\n        'unassignedAssignments',\r\n          unassigned_assignments,\r\n        'minimumUnfilled',\r\n          0,\r\n        'recommendationUnfilled',\r\n          0\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_my_dashboard()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_my_dashboard()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_user_role text;\r\n  current_permissions text[];\r\n\r\n  current_local_timestamp timestamp;\r\n  current_local_date date;\r\n  current_year integer;\r\n  current_month integer;\r\n\r\n  dispatcher_dashboard jsonb := null;\r\n  driver_dashboard jsonb := null;\r\n  manager_dashboard jsonb := null;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile_row.role::text\r\n  into\r\n    current_user_role\r\n  from public.profiles profile_row\r\n  where profile_row.id =\r\n    current_user_id\r\n    and profile_row.is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'dashboard.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  current_local_timestamp :=\r\n    now() at time zone\r\n      'Asia/Jerusalem';\r\n\r\n  current_local_date :=\r\n    current_local_timestamp::date;\r\n\r\n  current_year :=\r\n    extract(\r\n      year from current_local_date\r\n    )::integer;\r\n\r\n  current_month :=\r\n    extract(\r\n      month from current_local_date\r\n    )::integer;\r\n\r\n  if current_user_role in (\r\n    'dispatcher',\r\n    'admin',\r\n    'manager'\r\n  ) then\r\n    with current_shift as (\r\n      select\r\n        schedule_shift.id,\r\n        schedule_shift.shift_date,\r\n        schedule_shift.starts_at,\r\n        schedule_shift.ends_at,\r\n        schedule_shift.shift_code,\r\n        schedule_shift.schedule_type::text\r\n          as schedule_type,\r\n        schedule_shift.is_premium,\r\n        schedule_shift.holiday_name,\r\n\r\n        driver_day.assigned_user_id\r\n          as driver_user_id,\r\n\r\n        driver_profile.display_name\r\n          as driver_display_name,\r\n\r\n        driver_profile.schedule_name\r\n          as driver_schedule_name\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      join public.schedule_periods\r\n        schedule_period\r\n        on schedule_period.id =\r\n          schedule_shift.period_id\r\n\r\n      left join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.year =\r\n          extract(\r\n            year from schedule_shift.shift_date\r\n          )::integer\r\n        and driver_period.month =\r\n          extract(\r\n            month from schedule_shift.shift_date\r\n          )::integer\r\n        and driver_period.status =\r\n          'published'::public.driver_schedule_period_status\r\n\r\n      left join public.driver_schedule_days\r\n        driver_day\r\n        on driver_day.period_id =\r\n          driver_period.id\r\n        and driver_day.duty_date =\r\n          schedule_shift.shift_date\r\n\r\n      left join public.profiles\r\n        driver_profile\r\n        on driver_profile.id =\r\n          driver_day.assigned_user_id\r\n\r\n      where schedule_period.status =\r\n        'published'::public.schedule_period_status\r\n\r\n        and schedule_shift.assigned_user_id =\r\n          current_user_id\r\n\r\n        and schedule_shift.starts_at <=\r\n          now()\r\n\r\n        and schedule_shift.ends_at >\r\n          now()\r\n\r\n      order by\r\n        schedule_shift.starts_at\r\n\r\n      limit 1\r\n    ),\r\n\r\n    next_shift as (\r\n      select\r\n        schedule_shift.id,\r\n        schedule_shift.shift_date,\r\n        schedule_shift.starts_at,\r\n        schedule_shift.ends_at,\r\n        schedule_shift.shift_code,\r\n        schedule_shift.schedule_type::text\r\n          as schedule_type,\r\n        schedule_shift.is_premium,\r\n        schedule_shift.holiday_name,\r\n\r\n        driver_day.assigned_user_id\r\n          as driver_user_id,\r\n\r\n        driver_profile.display_name\r\n          as driver_display_name,\r\n\r\n        driver_profile.schedule_name\r\n          as driver_schedule_name\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      join public.schedule_periods\r\n        schedule_period\r\n        on schedule_period.id =\r\n          schedule_shift.period_id\r\n\r\n      left join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.year =\r\n          extract(\r\n            year from schedule_shift.shift_date\r\n          )::integer\r\n        and driver_period.month =\r\n          extract(\r\n            month from schedule_shift.shift_date\r\n          )::integer\r\n        and driver_period.status =\r\n          'published'::public.driver_schedule_period_status\r\n\r\n      left join public.driver_schedule_days\r\n        driver_day\r\n        on driver_day.period_id =\r\n          driver_period.id\r\n        and driver_day.duty_date =\r\n          schedule_shift.shift_date\r\n\r\n      left join public.profiles\r\n        driver_profile\r\n        on driver_profile.id =\r\n          driver_day.assigned_user_id\r\n\r\n      where schedule_period.status =\r\n        'published'::public.schedule_period_status\r\n\r\n        and schedule_shift.assigned_user_id =\r\n          current_user_id\r\n\r\n        and schedule_shift.starts_at >\r\n          now()\r\n\r\n      order by\r\n        schedule_shift.starts_at\r\n\r\n      limit 1\r\n    ),\r\n\r\n    monthly_progress as (\r\n      select\r\n        count(schedule_shift.id)::integer\r\n          as total_shifts,\r\n\r\n        count(schedule_shift.id) filter (\r\n          where schedule_shift.ends_at <=\r\n            now()\r\n        )::integer\r\n          as completed_shifts\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      join public.schedule_periods\r\n        schedule_period\r\n        on schedule_period.id =\r\n          schedule_shift.period_id\r\n\r\n      where schedule_period.year =\r\n        current_year\r\n\r\n        and schedule_period.month =\r\n          current_month\r\n\r\n        and schedule_period.status =\r\n          'published'::public.schedule_period_status\r\n\r\n        and schedule_shift.assigned_user_id =\r\n          current_user_id\r\n    )\r\n\r\n    select\r\n      jsonb_build_object(\r\n        'currentShift',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'id',\r\n                  current_shift.id,\r\n\r\n                'shiftDate',\r\n                  current_shift.shift_date,\r\n\r\n                'startsAt',\r\n                  current_shift.starts_at,\r\n\r\n                'endsAt',\r\n                  current_shift.ends_at,\r\n\r\n                'shiftCode',\r\n                  current_shift.shift_code,\r\n\r\n                'scheduleType',\r\n                  current_shift.schedule_type,\r\n\r\n                'isPremium',\r\n                  current_shift.is_premium,\r\n\r\n                'holidayName',\r\n                  current_shift.holiday_name,\r\n\r\n                'driver',\r\n                  case\r\n                    when current_shift.driver_user_id\r\n                      is null\r\n                    then null\r\n                    else jsonb_build_object(\r\n                      'id',\r\n                        current_shift.driver_user_id,\r\n\r\n                      'displayName',\r\n                        current_shift.driver_display_name,\r\n\r\n                      'scheduleName',\r\n                        current_shift.driver_schedule_name\r\n                    )\r\n                  end\r\n              )\r\n            from current_shift\r\n          ),\r\n\r\n        'nextShift',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'id',\r\n                  next_shift.id,\r\n\r\n                'shiftDate',\r\n                  next_shift.shift_date,\r\n\r\n                'startsAt',\r\n                  next_shift.starts_at,\r\n\r\n                'endsAt',\r\n                  next_shift.ends_at,\r\n\r\n                'shiftCode',\r\n                  next_shift.shift_code,\r\n\r\n                'scheduleType',\r\n                  next_shift.schedule_type,\r\n\r\n                'isPremium',\r\n                  next_shift.is_premium,\r\n\r\n                'holidayName',\r\n                  next_shift.holiday_name,\r\n\r\n                'driver',\r\n                  case\r\n                    when next_shift.driver_user_id\r\n                      is null\r\n                    then null\r\n                    else jsonb_build_object(\r\n                      'id',\r\n                        next_shift.driver_user_id,\r\n\r\n                      'displayName',\r\n                        next_shift.driver_display_name,\r\n\r\n                      'scheduleName',\r\n                        next_shift.driver_schedule_name\r\n                    )\r\n                  end\r\n              )\r\n            from next_shift\r\n          ),\r\n\r\n        'monthlyProgress',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'year',\r\n                  current_year,\r\n\r\n                'month',\r\n                  current_month,\r\n\r\n                'completed',\r\n                  monthly_progress.completed_shifts,\r\n\r\n                'total',\r\n                  monthly_progress.total_shifts,\r\n\r\n                'percentage',\r\n                  case\r\n                    when monthly_progress.total_shifts = 0\r\n                    then 0\r\n                    else round(\r\n                      (\r\n                        monthly_progress.completed_shifts::numeric /\r\n                        monthly_progress.total_shifts::numeric\r\n                      ) * 100,\r\n                      1\r\n                    )\r\n                  end\r\n              )\r\n            from monthly_progress\r\n          )\r\n      )\r\n    into dispatcher_dashboard;\r\n  end if;\r\n\r\n  if current_user_role in (\r\n    'on_call',\r\n    'admin',\r\n    'manager'\r\n  ) then\r\n    with current_duty as (\r\n      select\r\n        driver_day.id,\r\n        driver_day.duty_date,\r\n        driver_day.weekday_number,\r\n        driver_day.weekday_name,\r\n        driver_day.assigned_user_id,\r\n        driver_day.notes\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.id =\r\n          driver_day.period_id\r\n\r\n      where driver_period.status =\r\n        'published'::public.driver_schedule_period_status\r\n\r\n        and driver_day.assigned_user_id =\r\n          current_user_id\r\n\r\n        and driver_day.duty_date =\r\n          current_local_date\r\n\r\n      limit 1\r\n    ),\r\n\r\n    next_duty as (\r\n      select\r\n        driver_day.id,\r\n        driver_day.duty_date,\r\n        driver_day.weekday_number,\r\n        driver_day.weekday_name,\r\n        driver_day.assigned_user_id,\r\n        driver_day.notes\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.id =\r\n          driver_day.period_id\r\n\r\n      where driver_period.status =\r\n        'published'::public.driver_schedule_period_status\r\n\r\n        and driver_day.assigned_user_id =\r\n          current_user_id\r\n\r\n        and driver_day.duty_date >\r\n          current_local_date\r\n\r\n      order by\r\n        driver_day.duty_date\r\n\r\n      limit 1\r\n    ),\r\n\r\n    monthly_progress as (\r\n      select\r\n        count(driver_day.id)::integer\r\n          as total_duties,\r\n\r\n        count(driver_day.id) filter (\r\n          where driver_day.duty_date <\r\n            current_local_date\r\n        )::integer\r\n          as completed_duties\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.id =\r\n          driver_day.period_id\r\n\r\n      where driver_period.year =\r\n        current_year\r\n\r\n        and driver_period.month =\r\n          current_month\r\n\r\n        and driver_period.status =\r\n          'published'::public.driver_schedule_period_status\r\n\r\n        and driver_day.assigned_user_id =\r\n          current_user_id\r\n    )\r\n\r\n    select\r\n      jsonb_build_object(\r\n        'currentDuty',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'id',\r\n                  current_duty.id,\r\n\r\n                'dutyDate',\r\n                  current_duty.duty_date,\r\n\r\n                'weekdayNumber',\r\n                  current_duty.weekday_number,\r\n\r\n                'weekdayName',\r\n                  current_duty.weekday_name,\r\n\r\n                'notes',\r\n                  current_duty.notes,\r\n\r\n                'dispatcherShifts',\r\n                  coalesce(\r\n                    (\r\n                      select\r\n                        jsonb_agg(\r\n                          jsonb_build_object(\r\n                            'id',\r\n                              schedule_shift.id,\r\n\r\n                            'startsAt',\r\n                              schedule_shift.starts_at,\r\n\r\n                            'endsAt',\r\n                              schedule_shift.ends_at,\r\n\r\n                            'displayName',\r\n                              dispatcher_profile.display_name,\r\n\r\n                            'scheduleName',\r\n                              dispatcher_profile.schedule_name\r\n                          )\r\n                          order by\r\n                            schedule_shift.starts_at\r\n                        )\r\n\r\n                      from public.schedule_shifts\r\n                        schedule_shift\r\n\r\n                      join public.schedule_periods\r\n                        schedule_period\r\n                        on schedule_period.id =\r\n                          schedule_shift.period_id\r\n\r\n                      left join public.profiles\r\n                        dispatcher_profile\r\n                        on dispatcher_profile.id =\r\n                          schedule_shift.assigned_user_id\r\n\r\n                      where schedule_period.status =\r\n                        'published'::public.schedule_period_status\r\n\r\n                        and schedule_shift.shift_date =\r\n                          current_duty.duty_date\r\n                    ),\r\n                    '[]'::jsonb\r\n                  )\r\n              )\r\n            from current_duty\r\n          ),\r\n\r\n        'nextDuty',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'id',\r\n                  next_duty.id,\r\n\r\n                'dutyDate',\r\n                  next_duty.duty_date,\r\n\r\n                'weekdayNumber',\r\n                  next_duty.weekday_number,\r\n\r\n                'weekdayName',\r\n                  next_duty.weekday_name,\r\n\r\n                'notes',\r\n                  next_duty.notes,\r\n\r\n                'dispatcherShifts',\r\n                  coalesce(\r\n                    (\r\n                      select\r\n                        jsonb_agg(\r\n                          jsonb_build_object(\r\n                            'id',\r\n                              schedule_shift.id,\r\n\r\n                            'startsAt',\r\n                              schedule_shift.starts_at,\r\n\r\n                            'endsAt',\r\n                              schedule_shift.ends_at,\r\n\r\n                            'displayName',\r\n                              dispatcher_profile.display_name,\r\n\r\n                            'scheduleName',\r\n                              dispatcher_profile.schedule_name\r\n                          )\r\n                          order by\r\n                            schedule_shift.starts_at\r\n                        )\r\n\r\n                      from public.schedule_shifts\r\n                        schedule_shift\r\n\r\n                      join public.schedule_periods\r\n                        schedule_period\r\n                        on schedule_period.id =\r\n                          schedule_shift.period_id\r\n\r\n                      left join public.profiles\r\n                        dispatcher_profile\r\n                        on dispatcher_profile.id =\r\n                          schedule_shift.assigned_user_id\r\n\r\n                      where schedule_period.status =\r\n                        'published'::public.schedule_period_status\r\n\r\n                        and schedule_shift.shift_date =\r\n                          next_duty.duty_date\r\n                    ),\r\n                    '[]'::jsonb\r\n                  )\r\n              )\r\n            from next_duty\r\n          ),\r\n\r\n        'monthlyProgress',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'year',\r\n                  current_year,\r\n\r\n                'month',\r\n                  current_month,\r\n\r\n                'completed',\r\n                  monthly_progress.completed_duties,\r\n\r\n                'total',\r\n                  monthly_progress.total_duties,\r\n\r\n                'percentage',\r\n                  case\r\n                    when monthly_progress.total_duties = 0\r\n                    then 0\r\n                    else round(\r\n                      (\r\n                        monthly_progress.completed_duties::numeric /\r\n                        monthly_progress.total_duties::numeric\r\n                      ) * 100,\r\n                      1\r\n                    )\r\n                  end\r\n              )\r\n            from monthly_progress\r\n          )\r\n      )\r\n    into driver_dashboard;\r\n  end if;\r\n\r\n  if current_user_role in (\r\n    'admin',\r\n    'manager'\r\n  ) then\r\n    with current_dispatcher_shift as (\r\n      select\r\n        schedule_shift.id,\r\n        schedule_shift.starts_at,\r\n        schedule_shift.ends_at,\r\n        dispatcher_profile.id\r\n          as user_id,\r\n        dispatcher_profile.display_name,\r\n        dispatcher_profile.schedule_name\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      join public.schedule_periods\r\n        schedule_period\r\n        on schedule_period.id =\r\n          schedule_shift.period_id\r\n\r\n      left join public.profiles\r\n        dispatcher_profile\r\n        on dispatcher_profile.id =\r\n          schedule_shift.assigned_user_id\r\n\r\n      where schedule_period.status =\r\n        'published'::public.schedule_period_status\r\n\r\n        and schedule_shift.starts_at <=\r\n          now()\r\n\r\n        and schedule_shift.ends_at >\r\n          now()\r\n\r\n      order by\r\n        schedule_shift.starts_at\r\n\r\n      limit 1\r\n    ),\r\n\r\n    current_driver_duty as (\r\n      select\r\n        driver_day.id,\r\n        driver_day.duty_date,\r\n        driver_profile.id\r\n          as user_id,\r\n        driver_profile.display_name,\r\n        driver_profile.schedule_name\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.id =\r\n          driver_day.period_id\r\n\r\n      left join public.profiles\r\n        driver_profile\r\n        on driver_profile.id =\r\n          driver_day.assigned_user_id\r\n\r\n      where driver_period.status =\r\n        'published'::public.driver_schedule_period_status\r\n\r\n        and driver_day.duty_date =\r\n          current_local_date\r\n\r\n      limit 1\r\n    ),\r\n\r\n    schedule_summary as (\r\n      select\r\n        count(schedule_shift.id)::integer\r\n          as total_shifts,\r\n\r\n        count(schedule_shift.id) filter (\r\n          where schedule_shift.assigned_user_id\r\n            is null\r\n        )::integer\r\n          as unassigned_shifts,\r\n\r\n        count(schedule_shift.id) filter (\r\n          where schedule_shift.ends_at <=\r\n            now()\r\n        )::integer\r\n          as completed_shifts\r\n\r\n      from public.schedule_shifts\r\n        schedule_shift\r\n\r\n      join public.schedule_periods\r\n        schedule_period\r\n        on schedule_period.id =\r\n          schedule_shift.period_id\r\n\r\n      where schedule_period.year =\r\n        current_year\r\n\r\n        and schedule_period.month =\r\n          current_month\r\n\r\n        and schedule_period.status =\r\n          'published'::public.schedule_period_status\r\n    ),\r\n\r\n    driver_summary as (\r\n      select\r\n        count(driver_day.id)::integer\r\n          as total_duties,\r\n\r\n        count(driver_day.id) filter (\r\n          where driver_day.assigned_user_id\r\n            is null\r\n        )::integer\r\n          as unassigned_duties,\r\n\r\n        count(driver_day.id) filter (\r\n          where driver_day.duty_date <\r\n            current_local_date\r\n        )::integer\r\n          as completed_duties\r\n\r\n      from public.driver_schedule_days\r\n        driver_day\r\n\r\n      join public.driver_schedule_periods\r\n        driver_period\r\n        on driver_period.id =\r\n          driver_day.period_id\r\n\r\n      where driver_period.year =\r\n        current_year\r\n\r\n        and driver_period.month =\r\n          current_month\r\n\r\n        and driver_period.status =\r\n          'published'::public.driver_schedule_period_status\r\n    )\r\n\r\n    select\r\n      jsonb_build_object(\r\n        'currentDispatcher',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'shiftId',\r\n                  current_dispatcher_shift.id,\r\n\r\n                'startsAt',\r\n                  current_dispatcher_shift.starts_at,\r\n\r\n                'endsAt',\r\n                  current_dispatcher_shift.ends_at,\r\n\r\n                'userId',\r\n                  current_dispatcher_shift.user_id,\r\n\r\n                'displayName',\r\n                  current_dispatcher_shift.display_name,\r\n\r\n                'scheduleName',\r\n                  current_dispatcher_shift.schedule_name\r\n              )\r\n            from current_dispatcher_shift\r\n          ),\r\n\r\n        'currentDriver',\r\n          (\r\n            select\r\n              jsonb_build_object(\r\n                'dutyId',\r\n                  current_driver_duty.id,\r\n\r\n                'dutyDate',\r\n                  current_driver_duty.duty_date,\r\n\r\n                'userId',\r\n                  current_driver_duty.user_id,\r\n\r\n                'displayName',\r\n                  current_driver_duty.display_name,\r\n\r\n                'scheduleName',\r\n                  current_driver_duty.schedule_name\r\n              )\r\n            from current_driver_duty\r\n          ),\r\n\r\n        'monthlySummary',\r\n          jsonb_build_object(\r\n            'year',\r\n              current_year,\r\n\r\n            'month',\r\n              current_month,\r\n\r\n            'dispatcherShifts',\r\n              (\r\n                select\r\n                  jsonb_build_object(\r\n                    'completed',\r\n                      schedule_summary.completed_shifts,\r\n\r\n                    'total',\r\n                      schedule_summary.total_shifts,\r\n\r\n                    'unassigned',\r\n                      schedule_summary.unassigned_shifts,\r\n\r\n                    'percentage',\r\n                      case\r\n                        when schedule_summary.total_shifts = 0\r\n                        then 0\r\n                        else round(\r\n                          (\r\n                            schedule_summary.completed_shifts::numeric /\r\n                            schedule_summary.total_shifts::numeric\r\n                          ) * 100,\r\n                          1\r\n                        )\r\n                      end\r\n                  )\r\n                from schedule_summary\r\n              ),\r\n\r\n            'driverDuties',\r\n              (\r\n                select\r\n                  jsonb_build_object(\r\n                    'completed',\r\n                      driver_summary.completed_duties,\r\n\r\n                    'total',\r\n                      driver_summary.total_duties,\r\n\r\n                    'unassigned',\r\n                      driver_summary.unassigned_duties,\r\n\r\n                    'percentage',\r\n                      case\r\n                        when driver_summary.total_duties = 0\r\n                        then 0\r\n                        else round(\r\n                          (\r\n                            driver_summary.completed_duties::numeric /\r\n                            driver_summary.total_duties::numeric\r\n                          ) * 100,\r\n                          1\r\n                        )\r\n                      end\r\n                  )\r\n                from driver_summary\r\n              )\r\n          )\r\n      )\r\n    into manager_dashboard;\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'user',\r\n      jsonb_build_object(\r\n        'id',\r\n          current_user_id,\r\n\r\n        'role',\r\n          current_user_role\r\n      ),\r\n\r\n    'dispatcher',\r\n      dispatcher_dashboard,\r\n\r\n    'driver',\r\n      driver_dashboard,\r\n\r\n    'manager',\r\n      manager_dashboard,\r\n\r\n    'generatedAt',\r\n      now()\r\n  );\r\nend;\r\n$function$\n"
