  {
    "function_signature": "get_my_driver_availability(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_my_driver_availability(requested_period_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  selected_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  days_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  entries_json jsonb :=\r\n    '[]'::jsonb;\r\n\r\n  submission_json jsonb :=\r\n    null;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is not null then\r\n    select *\r\n    into selected_period\r\n    from public.driver_availability_periods\r\n    where id =\r\n      requested_period_id\r\n      and status in (\r\n        'open',\r\n        'closed'\r\n      )\r\n    limit 1;\r\n  else\r\n    select *\r\n    into selected_period\r\n    from public.driver_availability_periods\r\n    where status =\r\n      'open'\r\n    order by\r\n      year desc,\r\n      month desc\r\n    limit 1;\r\n  end if;\r\n\r\n  if not found then\r\n    return jsonb_build_object(\r\n      'period',\r\n        null,\r\n\r\n      'days',\r\n        '[]'::jsonb,\r\n\r\n      'entries',\r\n        '[]'::jsonb,\r\n\r\n      'submission',\r\n        null\r\n    );\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            day_row.id,\r\n\r\n          'periodId',\r\n            day_row.period_id,\r\n\r\n          'availabilityDate',\r\n            day_row.availability_date,\r\n\r\n          'weekdayNumber',\r\n            day_row.weekday_number,\r\n\r\n          'weekdayName',\r\n            day_row.weekday_name,\r\n\r\n          'sortOrder',\r\n            day_row.sort_order,\r\n\r\n          'createdAt',\r\n            day_row.created_at\r\n        )\r\n        order by\r\n          day_row.availability_date\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into days_json\r\n  from public.driver_availability_days\r\n    day_row\r\n  where day_row.period_id =\r\n    selected_period.id;\r\n\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            entry.id,\r\n\r\n          'periodId',\r\n            entry.period_id,\r\n\r\n          'dayId',\r\n            entry.day_id,\r\n\r\n          'userId',\r\n            entry.user_id,\r\n\r\n          'availabilityStatus',\r\n            entry.availability_status,\r\n\r\n          'note',\r\n            entry.note,\r\n\r\n          'createdAt',\r\n            entry.created_at,\r\n\r\n          'updatedAt',\r\n            entry.updated_at\r\n        )\r\n        order by\r\n          day_row.availability_date\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into entries_json\r\n  from public.driver_availability_entries\r\n    entry\r\n  join public.driver_availability_days\r\n    day_row\r\n    on day_row.id =\r\n      entry.day_id\r\n  where entry.period_id =\r\n    selected_period.id\r\n    and entry.user_id =\r\n      current_user_id;\r\n\r\n  select\r\n    jsonb_build_object(\r\n      'id',\r\n        submission.id,\r\n\r\n      'periodId',\r\n        submission.period_id,\r\n\r\n      'userId',\r\n        submission.user_id,\r\n\r\n      'status',\r\n        submission.status,\r\n\r\n      'submittedAt',\r\n        submission.submitted_at,\r\n\r\n      'reopenedAt',\r\n        submission.reopened_at,\r\n\r\n      'lastSavedAt',\r\n        submission.last_saved_at,\r\n\r\n      'availableCount',\r\n        submission.available_count,\r\n\r\n      'unavailableCount',\r\n        submission.unavailable_count,\r\n\r\n      'createdAt',\r\n        submission.created_at,\r\n\r\n      'updatedAt',\r\n        submission.updated_at\r\n    )\r\n  into submission_json\r\n  from public.driver_availability_submissions\r\n    submission\r\n  where submission.period_id =\r\n    selected_period.id\r\n    and submission.user_id =\r\n      current_user_id\r\n  limit 1;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          selected_period.id,\r\n\r\n        'year',\r\n          selected_period.year,\r\n\r\n        'month',\r\n          selected_period.month,\r\n\r\n        'status',\r\n          selected_period.status,\r\n\r\n        'title',\r\n          selected_period.title,\r\n\r\n        'instructions',\r\n          selected_period.instructions,\r\n\r\n        'submissionDeadline',\r\n          selected_period.submission_deadline,\r\n\r\n        'openedAt',\r\n          selected_period.opened_at,\r\n\r\n        'closedAt',\r\n          selected_period.closed_at,\r\n\r\n        'createdBy',\r\n          selected_period.created_by,\r\n\r\n        'updatedBy',\r\n          selected_period.updated_by,\r\n\r\n        'createdAt',\r\n          selected_period.created_at,\r\n\r\n        'updatedAt',\r\n          selected_period.updated_at\r\n      ),\r\n\r\n    'days',\r\n      days_json,\r\n\r\n    'entries',\r\n      entries_json,\r\n\r\n    'submission',\r\n      submission_json\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_my_morning_driver_availability(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_my_morning_driver_availability(requested_period_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_period public.morning_driver_availability_periods%rowtype;\r\n  target_submission public.morning_driver_availability_submissions%rowtype;\r\n  shifts_json jsonb;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception 'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.view'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    select *\r\n    into target_period\r\n    from public.morning_driver_availability_periods period\r\n    where period.status = 'open'\r\n    order by\r\n      period.year desc,\r\n      period.month desc,\r\n      period.opened_at desc nulls last\r\n    limit 1;\r\n  else\r\n    select *\r\n    into target_period\r\n    from public.morning_driver_availability_periods period\r\n    where period.id = requested_period_id\r\n      and period.status in (\r\n        'open',\r\n        'closed',\r\n        'archived'\r\n      )\r\n    limit 1;\r\n  end if;\r\n\r\n  if not found then\r\n    return null;\r\n  end if;\r\n\r\n  select *\r\n  into target_submission\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.user_id = current_user_id\r\n  limit 1;\r\n\r\n  if not found then\r\n    insert into public.morning_driver_availability_submissions (\r\n      period_id,\r\n      user_id,\r\n      status\r\n    )\r\n    values (\r\n      target_period.id,\r\n      current_user_id,\r\n      'draft'\r\n    )\r\n    returning *\r\n    into target_submission;\r\n  end if;\r\n\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id',\r\n          shift_item.id,\r\n        'periodId',\r\n          shift_item.period_id,\r\n        'shiftDate',\r\n          shift_item.shift_date,\r\n        'weekdayNumber',\r\n          shift_item.weekday_number,\r\n        'weekdayName',\r\n          shift_item.weekday_name,\r\n        'shiftType',\r\n          shift_item.shift_type,\r\n        'startTime',\r\n          shift_item.start_time,\r\n        'endTime',\r\n          shift_item.end_time,\r\n        'minimumWorkers',\r\n          1,\r\n\r\n        'recommendedWorkers',\r\n          shift_item.required_workers,\r\n        'sortOrder',\r\n          shift_item.sort_order,\r\n        'availabilityStatus',\r\n          entry.availability_status,\r\n        'note',\r\n          entry.note\r\n      )\r\n      order by\r\n        shift_item.shift_date,\r\n        shift_item.sort_order\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  into shifts_json\r\n  from public.morning_driver_availability_shifts shift_item\r\n  left join public.morning_driver_availability_entries entry\r\n    on entry.shift_id = shift_item.id\r\n   and entry.user_id = current_user_id\r\n  where shift_item.period_id = target_period.id;\r\n\r\n  return jsonb_build_object(\r\n    'period',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_period.id,\r\n        'year',\r\n          target_period.year,\r\n        'month',\r\n          target_period.month,\r\n        'status',\r\n          target_period.status,\r\n        'title',\r\n          target_period.title,\r\n        'instructions',\r\n          target_period.instructions,\r\n        'submissionDeadline',\r\n          target_period.submission_deadline,\r\n        'openedAt',\r\n          target_period.opened_at,\r\n        'closedAt',\r\n          target_period.closed_at,\r\n        'createdAt',\r\n          target_period.created_at\r\n      ),\r\n    'submission',\r\n      jsonb_build_object(\r\n        'id',\r\n          target_submission.id,\r\n        'periodId',\r\n          target_submission.period_id,\r\n        'userId',\r\n          target_submission.user_id,\r\n        'status',\r\n          target_submission.status,\r\n        'submittedAt',\r\n          target_submission.submitted_at,\r\n        'lastSavedAt',\r\n          target_submission.last_saved_at,\r\n        'createdAt',\r\n          target_submission.created_at,\r\n        'updatedAt',\r\n          target_submission.updated_at\r\n      ),\r\n    'shifts',\r\n      shifts_json\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_my_open_availability()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_my_open_availability()\n RETURNS TABLE(period_id uuid, period_year integer, period_month integer, period_title text, period_instructions text, submission_deadline timestamp with time zone, period_status text, submission_status text, submitted_at timestamp with time zone, last_saved_at timestamp with time zone, available_count integer, unavailable_count integer, shift_slot_id uuid, shift_date date, weekday_number integer, weekday_name text, start_time time without time zone, end_time time without time zone, ends_next_day boolean, schedule_type text, holiday_name text, is_premium boolean, sort_order integer, availability_status text, availability_note text, availability_updated_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  open_period_id uuid;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.view'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to view availability';\r\n  end if;\r\n\r\n  select\r\n    period.id\r\n  into\r\n    open_period_id\r\n  from public.availability_periods period\r\n  where period.status = 'open'\r\n  order by\r\n    period.year desc,\r\n    period.month desc,\r\n    period.opened_at desc nulls last\r\n  limit 1;\r\n\r\n  if open_period_id is null then\r\n    return;\r\n  end if;\r\n\r\n  return query\r\n  select\r\n    period.id,\r\n    period.year,\r\n    period.month,\r\n    period.title,\r\n    period.instructions,\r\n    period.submission_deadline,\r\n    period.status,\r\n\r\n    coalesce(\r\n      submission.status,\r\n      'draft'\r\n    ),\r\n    submission.submitted_at,\r\n    submission.last_saved_at,\r\n    coalesce(\r\n      submission.available_count,\r\n      0\r\n    ),\r\n    coalesce(\r\n      submission.unavailable_count,\r\n      0\r\n    ),\r\n\r\n    slot.id,\r\n    slot.shift_date,\r\n    slot.weekday_number,\r\n    slot.weekday_name,\r\n    slot.start_time,\r\n    slot.end_time,\r\n    slot.ends_next_day,\r\n    slot.schedule_type,\r\n    slot.holiday_name,\r\n    slot.is_premium,\r\n    slot.sort_order,\r\n\r\n    availability.availability_status,\r\n    availability.note,\r\n    availability.updated_at\r\n\r\n  from public.availability_periods period\r\n\r\n  join public.availability_shift_slots slot\r\n    on slot.period_id =\r\n      period.id\r\n\r\n  left join public.availability_submissions submission\r\n    on submission.period_id =\r\n      period.id\r\n    and submission.user_id =\r\n      current_user_id\r\n\r\n  left join public.dispatcher_availability availability\r\n    on availability.period_id =\r\n      period.id\r\n    and availability.shift_slot_id =\r\n      slot.id\r\n    and availability.user_id =\r\n      current_user_id\r\n\r\n  where period.id =\r\n    open_period_id\r\n\r\n  order by\r\n    slot.shift_date,\r\n    slot.sort_order;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_my_permissions()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_my_permissions()\n RETURNS text[]\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  select coalesce(\r\n    array_agg(\r\n      up.permission_key\r\n      order by p.sort_order, up.permission_key\r\n    ),\r\n    array[]::text[]\r\n  )\r\n  from public.user_permissions up\r\n  join public.permissions p\r\n    on p.permission_key = up.permission_key\r\n  where up.user_id = auth.uid();\r\n$function$\n"
  },
  {
    "function_signature": "get_payroll_statistics(integer[],integer[])",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_payroll_statistics(requested_years integer[] DEFAULT NULL::integer[], requested_months integer[] DEFAULT NULL::integer[])\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  dispatchers_json jsonb := '[]'::jsonb;\r\n  drivers_json jsonb := '[]'::jsonb;\r\n  projected_dispatcher_pay numeric := 0;\r\n  projected_driver_pay numeric := 0;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'payroll.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception 'payroll view permission required';\r\n  end if;\r\n\r\n  with dispatcher_totals as (\r\n    select\r\n      profile.id as user_id,\r\n      profile.display_name,\r\n      profile.schedule_name,\r\n      profile.hourly_rate,\r\n      round(\r\n        coalesce(\r\n          sum(\r\n            case\r\n              when schedule_period.id is not null\r\n              then\r\n                extract(\r\n                  epoch from (\r\n                    schedule_shift.ends_at -\r\n                    schedule_shift.starts_at\r\n                  )\r\n                ) / 3600.0\r\n              else 0\r\n            end\r\n          ),\r\n          0\r\n        )::numeric,\r\n        2\r\n      ) as scheduled_hours,\r\n      round(\r\n        coalesce(\r\n          sum(\r\n            case\r\n              when schedule_period.id is not null\r\n                and schedule_shift.is_premium\r\n              then\r\n                extract(\r\n                  epoch from (\r\n                    schedule_shift.ends_at -\r\n                    schedule_shift.starts_at\r\n                  )\r\n                ) / 3600.0\r\n              else 0\r\n            end\r\n          ),\r\n          0\r\n        )::numeric,\r\n        2\r\n      ) as premium_hours\r\n    from public.profiles profile\r\n    left join public.schedule_shifts schedule_shift\r\n      on schedule_shift.assigned_user_id =\r\n        profile.id\r\n    left join public.schedule_periods schedule_period\r\n      on schedule_period.id =\r\n        schedule_shift.period_id\r\n      and schedule_period.status::text in (\r\n        'published',\r\n        'archived'\r\n      )\r\n      and (\r\n        requested_years is null\r\n        or cardinality(requested_years) = 0\r\n        or schedule_period.year =\r\n          any(requested_years)\r\n      )\r\n      and (\r\n        requested_months is null\r\n        or cardinality(requested_months) = 0\r\n        or schedule_period.month =\r\n          any(requested_months)\r\n      )\r\n    where profile.role =\r\n      'dispatcher'::public.user_role\r\n      and profile.is_active = true\r\n    group by\r\n      profile.id,\r\n      profile.display_name,\r\n      profile.schedule_name,\r\n      profile.hourly_rate\r\n  ),\r\n  dispatcher_rows as (\r\n    select\r\n      *,\r\n      case\r\n        when hourly_rate is null\r\n        then null\r\n        else round(\r\n          hourly_rate *\r\n          (\r\n            scheduled_hours +\r\n            premium_hours\r\n          ),\r\n          2\r\n        )\r\n      end as projected_pay\r\n    from dispatcher_totals\r\n  )\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId', user_id,\r\n          'displayName', display_name,\r\n          'scheduleName', schedule_name,\r\n          'hourlyRate', hourly_rate,\r\n          'scheduledHours', scheduled_hours,\r\n          'premiumHours', premium_hours,\r\n          'projectedPay', projected_pay\r\n        )\r\n        order by\r\n          coalesce(\r\n            schedule_name,\r\n            display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    ),\r\n    coalesce(\r\n      sum(projected_pay),\r\n      0\r\n    )\r\n  into\r\n    dispatchers_json,\r\n    projected_dispatcher_pay\r\n  from dispatcher_rows;\r\n\r\n  with driver_totals as (\r\n    select\r\n      profile.id as user_id,\r\n      profile.display_name,\r\n      profile.schedule_name,\r\n      profile.daily_duty_rate,\r\n      count(\r\n        schedule_day.id\r\n      ) filter (\r\n        where schedule_period.id\r\n          is not null\r\n      )::integer as total_duties\r\n    from public.profiles profile\r\n    left join public.driver_schedule_days schedule_day\r\n      on schedule_day.assigned_user_id =\r\n        profile.id\r\n    left join public.driver_schedule_periods schedule_period\r\n      on schedule_period.id =\r\n        schedule_day.period_id\r\n      and schedule_period.status::text in (\r\n        'published',\r\n        'archived'\r\n      )\r\n      and (\r\n        requested_years is null\r\n        or cardinality(requested_years) = 0\r\n        or schedule_period.year =\r\n          any(requested_years)\r\n      )\r\n      and (\r\n        requested_months is null\r\n        or cardinality(requested_months) = 0\r\n        or schedule_period.month =\r\n          any(requested_months)\r\n      )\r\n    where profile.role =\r\n      'on_call'::public.user_role\r\n      and profile.is_active = true\r\n    group by\r\n      profile.id,\r\n      profile.display_name,\r\n      profile.schedule_name,\r\n      profile.daily_duty_rate\r\n  ),\r\n  driver_rows as (\r\n    select\r\n      *,\r\n      case\r\n        when daily_duty_rate is null\r\n        then null\r\n        else round(\r\n          daily_duty_rate *\r\n          total_duties,\r\n          2\r\n        )\r\n      end as projected_pay\r\n    from driver_totals\r\n  )\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId', user_id,\r\n          'displayName', display_name,\r\n          'scheduleName', schedule_name,\r\n          'dailyDutyRate', daily_duty_rate,\r\n          'totalDuties', total_duties,\r\n          'projectedPay', projected_pay\r\n        )\r\n        order by\r\n          coalesce(\r\n            schedule_name,\r\n            display_name\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    ),\r\n    coalesce(\r\n      sum(projected_pay),\r\n      0\r\n    )\r\n  into\r\n    drivers_json,\r\n    projected_driver_pay\r\n  from driver_rows;\r\n\r\n  return jsonb_build_object(\r\n    'dispatchers', dispatchers_json,\r\n    'drivers', drivers_json,\r\n    'projectedDispatcherPay',\r\n      projected_dispatcher_pay,\r\n    'projectedDriverPay',\r\n      projected_driver_pay,\r\n    'actualPayAvailable', false,\r\n    'attendanceAvailable', false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_schedule_import_users()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_schedule_import_users()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  dispatcher_users jsonb;\r\n\r\n  on_call_users jsonb;\r\n\r\n  morning_driver_users jsonb;\r\n\r\n  aliases jsonb;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile_row\r\n    where profile_row.id =\r\n      current_user_id\r\n      and profile_row.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n    or\r\n    'morning_driver_availability.manage' =\r\n      any(current_permissions)\r\n    or\r\n    'morning_driver_schedule.edit' =\r\n      any(current_permissions)\r\n    or\r\n    'schedule.edit' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  /*\r\n   * מוקדנים פעילים.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile_row.id,\r\n\r\n          'displayName',\r\n            profile_row.display_name,\r\n\r\n          'scheduleName',\r\n            profile_row.schedule_name,\r\n\r\n          'email',\r\n            profile_row.email,\r\n\r\n          'role',\r\n            profile_row.role,\r\n\r\n          'isActive',\r\n            profile_row.is_active\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile_row.schedule_name,\r\n            profile_row.display_name,\r\n            profile_row.email\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    dispatcher_users\r\n  from public.profiles profile_row\r\n  where profile_row.is_active = true\r\n    and profile_row.role =\r\n      'dispatcher'::public.user_role;\r\n\r\n  /*\r\n   * כוננים טכניים פעילים.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile_row.id,\r\n\r\n          'displayName',\r\n            profile_row.display_name,\r\n\r\n          'scheduleName',\r\n            profile_row.schedule_name,\r\n\r\n          'email',\r\n            profile_row.email,\r\n\r\n          'role',\r\n            profile_row.role,\r\n\r\n          'isActive',\r\n            profile_row.is_active\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile_row.schedule_name,\r\n            profile_row.display_name,\r\n            profile_row.email\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    on_call_users\r\n  from public.profiles profile_row\r\n  where profile_row.is_active = true\r\n    and profile_row.role =\r\n      'on_call'::public.user_role;\r\n\r\n  /*\r\n   * כונני בוקר פעילים.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            profile_row.id,\r\n\r\n          'displayName',\r\n            profile_row.display_name,\r\n\r\n          'scheduleName',\r\n            profile_row.schedule_name,\r\n\r\n          'email',\r\n            profile_row.email,\r\n\r\n          'role',\r\n            profile_row.role,\r\n\r\n          'isActive',\r\n            profile_row.is_active\r\n        )\r\n        order by\r\n          coalesce(\r\n            profile_row.schedule_name,\r\n            profile_row.display_name,\r\n            profile_row.email\r\n          )\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    morning_driver_users\r\n  from public.profiles profile_row\r\n  where profile_row.is_active = true\r\n    and profile_row.role =\r\n      'morning_driver'::public.user_role;\r\n\r\n  /*\r\n   * התאמות שמות שמורות מכל סוגי המשתמשים.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'id',\r\n            alias_row.id,\r\n\r\n          'sourceName',\r\n            alias_row.source_name,\r\n\r\n          'normalizedSourceName',\r\n            alias_row.normalized_source_name,\r\n\r\n          'userId',\r\n            alias_row.user_id,\r\n\r\n          'userType',\r\n            alias_row.user_type\r\n        )\r\n        order by\r\n          alias_row.user_type,\r\n          alias_row.normalized_source_name\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into\r\n    aliases\r\n  from public.schedule_import_name_aliases alias_row;\r\n\r\n  return jsonb_build_object(\r\n    'dispatchers',\r\n      dispatcher_users,\r\n\r\n    'onCallDrivers',\r\n      on_call_users,\r\n\r\n    'morningDrivers',\r\n      morning_driver_users,\r\n\r\n    'aliases',\r\n      aliases\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_shift_swap_create_options()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_shift_swap_create_options()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  with date_bounds as (\r\n    select\r\n      date_trunc(\r\n        'month',\r\n        (now() at time zone 'Asia/Jerusalem')::date\r\n      )::date as current_month_start,\r\n      (\r\n        date_trunc(\r\n          'month',\r\n          (now() at time zone 'Asia/Jerusalem')::date\r\n        ) + interval '2 months'\r\n      )::date as month_after_next_start\r\n  ),\r\n  eligible_periods as (\r\n    select p.*\r\n    from public.schedule_periods p\r\n    cross join date_bounds b\r\n    where p.status = 'published'\r\n      and make_date(p.year, p.month, 1) >= b.current_month_start\r\n      and make_date(p.year, p.month, 1) < b.month_after_next_start\r\n  ),\r\n  eligible_shifts as (\r\n    select s.*\r\n    from public.schedule_shifts s\r\n    join eligible_periods p on p.id = s.period_id\r\n    where s.starts_at > now()\r\n  )\r\n  select jsonb_build_object(\r\n    'myShifts', coalesce((\r\n      select jsonb_agg(\r\n        jsonb_build_object(\r\n          'id', s.id,\r\n          'periodId', s.period_id,\r\n          'shiftDate', s.shift_date,\r\n          'startsAt', s.starts_at,\r\n          'endsAt', s.ends_at,\r\n          'shiftCode', s.shift_code,\r\n          'scheduleType', s.schedule_type,\r\n          'isPremium', s.is_premium,\r\n          'holidayName', s.holiday_name,\r\n          'periodYear', p.year,\r\n          'periodMonth', p.month\r\n        )\r\n        order by s.starts_at\r\n      )\r\n      from eligible_shifts s\r\n      join eligible_periods p on p.id = s.period_id\r\n      where s.assigned_user_id = auth.uid()\r\n    ), '[]'::jsonb),\r\n    'dispatchers', coalesce((\r\n      select jsonb_agg(\r\n        jsonb_build_object(\r\n          'id', profile.id,\r\n          'displayName', profile.display_name,\r\n          'scheduleName', profile.schedule_name\r\n        )\r\n        order by coalesce(profile.schedule_name, profile.display_name)\r\n      )\r\n      from public.profiles profile\r\n      where profile.is_active = true\r\n        and profile.role::text = 'dispatcher'\r\n        and profile.id <> auth.uid()\r\n    ), '[]'::jsonb),\r\n    'counterpartyShifts', coalesce((\r\n      select jsonb_agg(\r\n        jsonb_build_object(\r\n          'id', s.id,\r\n          'periodId', s.period_id,\r\n          'assignedUserId', s.assigned_user_id,\r\n          'shiftDate', s.shift_date,\r\n          'startsAt', s.starts_at,\r\n          'endsAt', s.ends_at,\r\n          'shiftCode', s.shift_code,\r\n          'scheduleType', s.schedule_type,\r\n          'isPremium', s.is_premium,\r\n          'holidayName', s.holiday_name,\r\n          'periodYear', p.year,\r\n          'periodMonth', p.month\r\n        )\r\n        order by s.starts_at\r\n      )\r\n      from eligible_shifts s\r\n      join eligible_periods p on p.id = s.period_id\r\n      where s.assigned_user_id is not null\r\n        and s.assigned_user_id <> auth.uid()\r\n    ), '[]'::jsonb)\r\n  )\r\n  where auth.uid() is not null\r\n    and public.current_user_has_permission('shift_swaps.view');\r\n$function$\n"
  },
  {
    "function_signature": "get_shift_swap_requests()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_shift_swap_requests()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  select coalesce(\r\n    jsonb_agg(\r\n      jsonb_build_object(\r\n        'id', r.id,\r\n        'swapType', r.swap_type,\r\n        'status', r.status,\r\n        'requesterUserId', r.requester_user_id,\r\n        'requesterName', requester.display_name,\r\n        'counterpartyUserId', r.counterparty_user_id,\r\n        'counterpartyName', counterparty.display_name,\r\n        'requesterShiftId', r.requester_shift_id,\r\n        'requesterShiftDate', requester_shift.shift_date,\r\n        'requesterStartsAt', requester_shift.starts_at,\r\n        'requesterEndsAt', requester_shift.ends_at,\r\n        'counterpartyShiftId', r.counterparty_shift_id,\r\n        'counterpartyShiftDate', counterparty_shift.shift_date,\r\n        'counterpartyStartsAt', counterparty_shift.starts_at,\r\n        'counterpartyEndsAt', counterparty_shift.ends_at,\r\n        'rejectionReason', r.rejection_reason,\r\n        'counterpartyRespondedAt', r.counterparty_responded_at,\r\n        'managerReviewedAt', r.manager_reviewed_at,\r\n        'managerUserId', r.manager_user_id,\r\n        'createdAt', r.created_at,\r\n        'updatedAt', r.updated_at\r\n      )\r\n      order by r.created_at desc\r\n    ),\r\n    '[]'::jsonb\r\n  )\r\n  from public.shift_swap_requests r\r\n  join public.profiles requester\r\n    on requester.id = r.requester_user_id\r\n  join public.profiles counterparty\r\n    on counterparty.id = r.counterparty_user_id\r\n  join public.schedule_shifts requester_shift\r\n    on requester_shift.id = r.requester_shift_id\r\n  left join public.schedule_shifts counterparty_shift\r\n    on counterparty_shift.id = r.counterparty_shift_id\r\n  where\r\n    auth.uid() is not null\r\n    and (\r\n      r.requester_user_id = auth.uid()\r\n      or r.counterparty_user_id = auth.uid()\r\n      or public.current_user_has_permission('shift_swaps.approve')\r\n    );\r\n$function$\n"
  },
  {
    "function_signature": "get_statistics_dashboard(integer,integer)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_statistics_dashboard(requested_year integer DEFAULT NULL::integer, requested_month integer DEFAULT NULL::integer)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  dispatcher_statistics jsonb;\r\n  driver_statistics jsonb;\r\n  monthly_statistics jsonb;\r\n\r\n  dispatcher_monthly_breakdown jsonb;\r\n  driver_monthly_breakdown jsonb;\r\n  summary_statistics jsonb;\r\n\r\n  selected_year integer;\r\n  selected_month integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile_row\r\n    where profile_row.id =\r\n      current_user_id\r\n      and profile_row.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'statistics.view' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if (\r\n    requested_month is not null\r\n    and (\r\n      requested_month < 1\r\n      or requested_month > 12\r\n    )\r\n  ) then\r\n    raise exception\r\n      'statistics month is invalid';\r\n  end if;\r\n\r\n  if (\r\n    requested_year is not null\r\n    and (\r\n      requested_year < 2020\r\n      or requested_year > 2100\r\n    )\r\n  ) then\r\n    raise exception\r\n      'statistics year is invalid';\r\n  end if;\r\n\r\n  if (\r\n    requested_month is not null\r\n    and requested_year is null\r\n  ) then\r\n    raise exception\r\n      'statistics year is required when month is selected';\r\n  end if;\r\n\r\n  selected_year :=\r\n    requested_year;\r\n\r\n  selected_month :=\r\n    requested_month;\r\n\r\n  /*\r\n   * סטטיסטיקות מוקדנים לתקופה שנבחרה.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId',\r\n            dispatcher_row.user_id,\r\n\r\n          'displayName',\r\n            dispatcher_row.display_name,\r\n\r\n          'scheduleName',\r\n            dispatcher_row.schedule_name,\r\n\r\n          'totalShifts',\r\n            dispatcher_row.total_shifts,\r\n\r\n          'premiumShifts',\r\n            dispatcher_row.premium_shifts,\r\n\r\n          'regularShifts',\r\n            dispatcher_row.regular_shifts,\r\n\r\n          'weekdayShifts',\r\n            dispatcher_row.weekday_shifts,\r\n\r\n          'fridayShifts',\r\n            dispatcher_row.friday_shifts,\r\n\r\n          'saturdayShifts',\r\n            dispatcher_row.saturday_shifts,\r\n\r\n          'holidayShifts',\r\n            dispatcher_row.holiday_shifts,\r\n\r\n          'nightShifts',\r\n            dispatcher_row.night_shifts,\r\n\r\n          'importedShifts',\r\n            dispatcher_row.imported_shifts\r\n        )\r\n        order by\r\n          dispatcher_row.total_shifts desc,\r\n          dispatcher_row.display_name\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into dispatcher_statistics\r\n  from (\r\n    select\r\n      profile_row.id\r\n        as user_id,\r\n\r\n      profile_row.display_name,\r\n\r\n      profile_row.schedule_name,\r\n\r\n      count(schedule_shift.id)::integer\r\n        as total_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.is_premium = true\r\n      )::integer\r\n        as premium_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.is_premium = false\r\n      )::integer\r\n        as regular_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'weekday'::public.schedule_type\r\n      )::integer\r\n        as weekday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'friday'::public.schedule_type\r\n      )::integer\r\n        as friday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'saturday'::public.schedule_type\r\n      )::integer\r\n        as saturday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type in (\r\n          'holiday_eve'::public.schedule_type,\r\n          'holiday_full'::public.schedule_type,\r\n          'holiday_end'::public.schedule_type,\r\n          'chol_hamoed'::public.schedule_type\r\n        )\r\n      )::integer\r\n        as holiday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where\r\n          (\r\n            schedule_shift.starts_at\r\n              at time zone 'Asia/Jerusalem'\r\n          )::time >= time '22:00'\r\n          or\r\n          (\r\n            schedule_shift.starts_at\r\n              at time zone 'Asia/Jerusalem'\r\n          )::time < time '06:00'\r\n      )::integer\r\n        as night_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.assignment_source::text =\r\n          'import'\r\n      )::integer\r\n        as imported_shifts\r\n\r\n    from public.profiles profile_row\r\n\r\n    join public.schedule_shifts schedule_shift\r\n      on schedule_shift.assigned_user_id =\r\n        profile_row.id\r\n\r\n    join public.schedule_periods schedule_period\r\n      on schedule_period.id =\r\n        schedule_shift.period_id\r\n\r\n    where\r\n      profile_row.is_active = true\r\n\r\n      and profile_row.role =\r\n        'dispatcher'\r\n\r\n      and (\r\n        selected_year is null\r\n        or schedule_period.year =\r\n          selected_year\r\n      )\r\n\r\n      and (\r\n        selected_month is null\r\n        or schedule_period.month =\r\n          selected_month\r\n      )\r\n\r\n      and schedule_period.status in (\r\n        'published'::public.schedule_period_status,\r\n        'archived'::public.schedule_period_status\r\n      )\r\n\r\n    group by\r\n      profile_row.id,\r\n      profile_row.display_name,\r\n      profile_row.schedule_name\r\n  ) dispatcher_row;\r\n\r\n  /*\r\n   * סטטיסטיקות כוננים לתקופה שנבחרה.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId',\r\n            driver_row.user_id,\r\n\r\n          'displayName',\r\n            driver_row.display_name,\r\n\r\n          'scheduleName',\r\n            driver_row.schedule_name,\r\n\r\n          'totalDuties',\r\n            driver_row.total_duties,\r\n\r\n          'weekdayDuties',\r\n            driver_row.weekday_duties,\r\n\r\n          'fridayDuties',\r\n            driver_row.friday_duties,\r\n\r\n          'saturdayDuties',\r\n            driver_row.saturday_duties,\r\n\r\n          'weekendDuties',\r\n            driver_row.weekend_duties,\r\n\r\n          'holidayDuties',\r\n            driver_row.holiday_duties,\r\n\r\n          'importedDuties',\r\n            driver_row.imported_duties\r\n        )\r\n        order by\r\n          driver_row.total_duties desc,\r\n          driver_row.display_name\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into driver_statistics\r\n  from (\r\n    select\r\n      profile_row.id\r\n        as user_id,\r\n\r\n      profile_row.display_name,\r\n\r\n      profile_row.schedule_name,\r\n\r\n      count(driver_day.id)::integer\r\n        as total_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number\r\n          between 0 and 4\r\n      )::integer\r\n        as weekday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number = 5\r\n      )::integer\r\n        as friday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number = 6\r\n      )::integer\r\n        as saturday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number\r\n          in (5, 6)\r\n      )::integer\r\n        as weekend_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where exists (\r\n          select 1\r\n          from public.schedule_periods schedule_period_for_day\r\n          join public.schedule_shifts holiday_shift\r\n            on holiday_shift.period_id =\r\n              schedule_period_for_day.id\r\n          where holiday_shift.shift_date =\r\n            driver_day.duty_date\r\n            and holiday_shift.schedule_type in (\r\n              'holiday_eve'::public.schedule_type,\r\n              'holiday_full'::public.schedule_type,\r\n              'holiday_end'::public.schedule_type,\r\n              'chol_hamoed'::public.schedule_type\r\n            )\r\n        )\r\n      )::integer\r\n        as holiday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.assignment_source::text =\r\n          'import'\r\n      )::integer\r\n        as imported_duties\r\n\r\n    from public.profiles profile_row\r\n\r\n    join public.driver_schedule_days driver_day\r\n      on driver_day.assigned_user_id =\r\n        profile_row.id\r\n\r\n    join public.driver_schedule_periods driver_period\r\n      on driver_period.id =\r\n        driver_day.period_id\r\n\r\n    where\r\n      profile_row.is_active = true\r\n\r\n      and profile_row.role =\r\n        'on_call'\r\n\r\n      and (\r\n        selected_year is null\r\n        or driver_period.year =\r\n          selected_year\r\n      )\r\n\r\n      and (\r\n        selected_month is null\r\n        or driver_period.month =\r\n          selected_month\r\n      )\r\n\r\n      and driver_period.status in (\r\n        'published'::public.driver_schedule_period_status,\r\n        'archived'::public.driver_schedule_period_status\r\n      )\r\n\r\n    group by\r\n      profile_row.id,\r\n      profile_row.display_name,\r\n      profile_row.schedule_name\r\n  ) driver_row;\r\n\r\n  /*\r\n   * סיכום לפי חודש.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'year',\r\n            monthly_row.year,\r\n\r\n          'month',\r\n            monthly_row.month,\r\n\r\n          'dispatcherShiftCount',\r\n            monthly_row.dispatcher_shift_count,\r\n\r\n          'driverDutyCount',\r\n            monthly_row.driver_duty_count,\r\n\r\n          'dispatcherPeriodStatus',\r\n            monthly_row.dispatcher_period_status,\r\n\r\n          'driverPeriodStatus',\r\n            monthly_row.driver_period_status\r\n        )\r\n        order by\r\n          monthly_row.year desc,\r\n          monthly_row.month desc\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into monthly_statistics\r\n  from (\r\n    select\r\n      coalesce(\r\n        schedule_period.year,\r\n        driver_period.year\r\n      ) as year,\r\n\r\n      coalesce(\r\n        schedule_period.month,\r\n        driver_period.month\r\n      ) as month,\r\n\r\n      schedule_period.status::text\r\n        as dispatcher_period_status,\r\n\r\n      driver_period.status::text\r\n        as driver_period_status,\r\n\r\n      coalesce(\r\n        schedule_count.shift_count,\r\n        0\r\n      )::integer\r\n        as dispatcher_shift_count,\r\n\r\n      coalesce(\r\n        driver_count.duty_count,\r\n        0\r\n      )::integer\r\n        as driver_duty_count\r\n\r\n    from public.schedule_periods schedule_period\r\n\r\n    full join public.driver_schedule_periods driver_period\r\n      on driver_period.year =\r\n        schedule_period.year\r\n      and driver_period.month =\r\n        schedule_period.month\r\n\r\n    left join lateral (\r\n      select\r\n        count(*)::integer\r\n          as shift_count\r\n      from public.schedule_shifts schedule_shift\r\n      where schedule_shift.period_id =\r\n        schedule_period.id\r\n    ) schedule_count\r\n      on true\r\n\r\n    left join lateral (\r\n      select\r\n        count(*)::integer\r\n          as duty_count\r\n      from public.driver_schedule_days driver_day\r\n      where driver_day.period_id =\r\n        driver_period.id\r\n    ) driver_count\r\n      on true\r\n\r\n    where\r\n      (\r\n        selected_year is null\r\n        or coalesce(\r\n          schedule_period.year,\r\n          driver_period.year\r\n        ) = selected_year\r\n      )\r\n\r\n      and (\r\n        selected_month is null\r\n        or coalesce(\r\n          schedule_period.month,\r\n          driver_period.month\r\n        ) = selected_month\r\n      )\r\n\r\n      and (\r\n        schedule_period.status in (\r\n          'published'::public.schedule_period_status,\r\n          'archived'::public.schedule_period_status\r\n        )\r\n        or\r\n        driver_period.status in (\r\n          'published'::public.driver_schedule_period_status,\r\n          'archived'::public.driver_schedule_period_status\r\n        )\r\n      )\r\n  ) monthly_row;\r\n\r\n  /*\r\n   * פירוט מוקדנים לפי חודש.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId',\r\n            dispatcher_month_row.user_id,\r\n\r\n          'displayName',\r\n            dispatcher_month_row.display_name,\r\n\r\n          'scheduleName',\r\n            dispatcher_month_row.schedule_name,\r\n\r\n          'year',\r\n            dispatcher_month_row.year,\r\n\r\n          'month',\r\n            dispatcher_month_row.month,\r\n\r\n          'totalShifts',\r\n            dispatcher_month_row.total_shifts,\r\n\r\n          'premiumShifts',\r\n            dispatcher_month_row.premium_shifts,\r\n\r\n          'regularShifts',\r\n            dispatcher_month_row.regular_shifts,\r\n\r\n          'weekdayShifts',\r\n            dispatcher_month_row.weekday_shifts,\r\n\r\n          'fridayShifts',\r\n            dispatcher_month_row.friday_shifts,\r\n\r\n          'saturdayShifts',\r\n            dispatcher_month_row.saturday_shifts,\r\n\r\n          'holidayShifts',\r\n            dispatcher_month_row.holiday_shifts,\r\n\r\n          'nightShifts',\r\n            dispatcher_month_row.night_shifts\r\n        )\r\n        order by\r\n          dispatcher_month_row.year,\r\n          dispatcher_month_row.month,\r\n          dispatcher_month_row.display_name\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into dispatcher_monthly_breakdown\r\n  from (\r\n    select\r\n      profile_row.id\r\n        as user_id,\r\n\r\n      profile_row.display_name,\r\n\r\n      profile_row.schedule_name,\r\n\r\n      schedule_period.year,\r\n\r\n      schedule_period.month,\r\n\r\n      count(schedule_shift.id)::integer\r\n        as total_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.is_premium = true\r\n      )::integer\r\n        as premium_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.is_premium = false\r\n      )::integer\r\n        as regular_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'weekday'::public.schedule_type\r\n      )::integer\r\n        as weekday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'friday'::public.schedule_type\r\n      )::integer\r\n        as friday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type =\r\n          'saturday'::public.schedule_type\r\n      )::integer\r\n        as saturday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where schedule_shift.schedule_type in (\r\n          'holiday_eve'::public.schedule_type,\r\n          'holiday_full'::public.schedule_type,\r\n          'holiday_end'::public.schedule_type,\r\n          'chol_hamoed'::public.schedule_type\r\n        )\r\n      )::integer\r\n        as holiday_shifts,\r\n\r\n      count(schedule_shift.id) filter (\r\n        where\r\n          (\r\n            schedule_shift.starts_at\r\n              at time zone 'Asia/Jerusalem'\r\n          )::time >= time '22:00'\r\n          or\r\n          (\r\n            schedule_shift.starts_at\r\n              at time zone 'Asia/Jerusalem'\r\n          )::time < time '06:00'\r\n      )::integer\r\n        as night_shifts\r\n\r\n    from public.profiles profile_row\r\n\r\n    join public.schedule_shifts schedule_shift\r\n      on schedule_shift.assigned_user_id =\r\n        profile_row.id\r\n\r\n    join public.schedule_periods schedule_period\r\n      on schedule_period.id =\r\n        schedule_shift.period_id\r\n\r\n    where\r\n      profile_row.is_active = true\r\n\r\n      and profile_row.role =\r\n        'dispatcher'\r\n\r\n      and (\r\n        selected_year is null\r\n        or schedule_period.year =\r\n          selected_year\r\n      )\r\n\r\n      and (\r\n        selected_month is null\r\n        or schedule_period.month =\r\n          selected_month\r\n      )\r\n\r\n      and schedule_period.status in (\r\n        'published'::public.schedule_period_status,\r\n        'archived'::public.schedule_period_status\r\n      )\r\n\r\n    group by\r\n      profile_row.id,\r\n      profile_row.display_name,\r\n      profile_row.schedule_name,\r\n      schedule_period.year,\r\n      schedule_period.month\r\n  ) dispatcher_month_row;\r\n\r\n  /*\r\n   * פירוט כוננים לפי חודש.\r\n   */\r\n  select\r\n    coalesce(\r\n      jsonb_agg(\r\n        jsonb_build_object(\r\n          'userId',\r\n            driver_month_row.user_id,\r\n\r\n          'displayName',\r\n            driver_month_row.display_name,\r\n\r\n          'scheduleName',\r\n            driver_month_row.schedule_name,\r\n\r\n          'year',\r\n            driver_month_row.year,\r\n\r\n          'month',\r\n            driver_month_row.month,\r\n\r\n          'totalDuties',\r\n            driver_month_row.total_duties,\r\n\r\n          'weekdayDuties',\r\n            driver_month_row.weekday_duties,\r\n\r\n          'fridayDuties',\r\n            driver_month_row.friday_duties,\r\n\r\n          'saturdayDuties',\r\n            driver_month_row.saturday_duties,\r\n\r\n          'weekendDuties',\r\n            driver_month_row.weekend_duties,\r\n\r\n          'holidayDuties',\r\n            driver_month_row.holiday_duties\r\n        )\r\n        order by\r\n          driver_month_row.year,\r\n          driver_month_row.month,\r\n          driver_month_row.display_name\r\n      ),\r\n      '[]'::jsonb\r\n    )\r\n  into driver_monthly_breakdown\r\n  from (\r\n    select\r\n      profile_row.id\r\n        as user_id,\r\n\r\n      profile_row.display_name,\r\n\r\n      profile_row.schedule_name,\r\n\r\n      driver_period.year,\r\n\r\n      driver_period.month,\r\n\r\n      count(driver_day.id)::integer\r\n        as total_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number\r\n          between 0 and 4\r\n      )::integer\r\n        as weekday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number = 5\r\n      )::integer\r\n        as friday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number = 6\r\n      )::integer\r\n        as saturday_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where driver_day.weekday_number\r\n          in (5, 6)\r\n      )::integer\r\n        as weekend_duties,\r\n\r\n      count(driver_day.id) filter (\r\n        where exists (\r\n          select 1\r\n          from public.schedule_periods schedule_period_for_day\r\n          join public.schedule_shifts holiday_shift\r\n            on holiday_shift.period_id =\r\n              schedule_period_for_day.id\r\n          where holiday_shift.shift_date =\r\n            driver_day.duty_date\r\n            and holiday_shift.schedule_type in (\r\n              'holiday_eve'::public.schedule_type,\r\n              'holiday_full'::public.schedule_type,\r\n              'holiday_end'::public.schedule_type,\r\n              'chol_hamoed'::public.schedule_type\r\n            )\r\n        )\r\n      )::integer\r\n        as holiday_duties\r\n\r\n    from public.profiles profile_row\r\n\r\n    join public.driver_schedule_days driver_day\r\n      on driver_day.assigned_user_id =\r\n        profile_row.id\r\n\r\n    join public.driver_schedule_periods driver_period\r\n      on driver_period.id =\r\n        driver_day.period_id\r\n\r\n    where\r\n      profile_row.is_active = true\r\n\r\n      and profile_row.role =\r\n        'on_call'\r\n\r\n      and (\r\n        selected_year is null\r\n        or driver_period.year =\r\n          selected_year\r\n      )\r\n\r\n      and (\r\n        selected_month is null\r\n        or driver_period.month =\r\n          selected_month\r\n      )\r\n\r\n      and driver_period.status in (\r\n        'published'::public.driver_schedule_period_status,\r\n        'archived'::public.driver_schedule_period_status\r\n      )\r\n\r\n    group by\r\n      profile_row.id,\r\n      profile_row.display_name,\r\n      profile_row.schedule_name,\r\n      driver_period.year,\r\n      driver_period.month\r\n  ) driver_month_row;\r\n\r\n  /*\r\n   * סיכום כולל לתקופה.\r\n   */\r\n  select\r\n    jsonb_build_object(\r\n      'dispatcherCount',\r\n        (\r\n          select count(distinct statistics_row->>'userId')\r\n          from jsonb_array_elements(\r\n            dispatcher_statistics\r\n          ) statistics_row\r\n        ),\r\n\r\n      'driverCount',\r\n        (\r\n          select count(distinct statistics_row->>'userId')\r\n          from jsonb_array_elements(\r\n            driver_statistics\r\n          ) statistics_row\r\n        ),\r\n\r\n      'totalDispatcherShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'totalShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'totalDriverDuties',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'totalDuties')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              driver_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'premiumShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'premiumShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'regularShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'regularShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'nightShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'nightShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'holidayShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'holidayShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'weekendShifts',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'fridayShifts')::integer +\r\n              (statistics_row->>'saturdayShifts')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              dispatcher_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'weekdayDriverDuties',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'weekdayDuties')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              driver_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'weekendDriverDuties',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'weekendDuties')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              driver_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        ),\r\n\r\n      'holidayDriverDuties',\r\n        coalesce(\r\n          (\r\n            select sum(\r\n              (statistics_row->>'holidayDuties')::integer\r\n            )\r\n            from jsonb_array_elements(\r\n              driver_statistics\r\n            ) statistics_row\r\n          ),\r\n          0\r\n        )\r\n    )\r\n  into summary_statistics;\r\n\r\n  return jsonb_build_object(\r\n    'filters',\r\n      jsonb_build_object(\r\n        'year',\r\n          selected_year,\r\n\r\n        'month',\r\n          selected_month\r\n      ),\r\n\r\n    'summary',\r\n      summary_statistics,\r\n\r\n    'dispatcherStatistics',\r\n      dispatcher_statistics,\r\n\r\n    'driverStatistics',\r\n      driver_statistics,\r\n\r\n    'monthlyStatistics',\r\n      monthly_statistics,\r\n\r\n    'dispatcherMonthlyBreakdown',\r\n      dispatcher_monthly_breakdown,\r\n\r\n    'driverMonthlyBreakdown',\r\n      driver_monthly_breakdown,\r\n\r\n    'generatedAt',\r\n      now()\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "get_user_permissions(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.get_user_permissions(target_user_id uuid)\n RETURNS text[]\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nbegin\r\n  if not public.is_current_user_admin() then\r\n    raise exception 'Only administrators can view user permissions';\r\n  end if;\r\n\r\n  return (\r\n    select coalesce(\r\n      array_agg(\r\n        up.permission_key\r\n        order by p.sort_order, up.permission_key\r\n      ),\r\n      array[]::text[]\r\n    )\r\n    from public.user_permissions up\r\n    join public.permissions p\r\n      on p.permission_key = up.permission_key\r\n    where up.user_id = target_user_id\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "handle_new_auth_user()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.handle_new_auth_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  resolved_display_name text;\r\nbegin\r\n  resolved_display_name :=\r\n    coalesce(\r\n      nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''),\r\n      nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''),\r\n      nullif(split_part(new.email, '@', 1), ''),\r\n      'משתמש חדש'\r\n    );\r\n\r\n  insert into public.profiles (\r\n    id,\r\n    email,\r\n    display_name,\r\n    schedule_name,\r\n    role,\r\n    is_active\r\n  )\r\n  values (\r\n    new.id,\r\n    coalesce(new.email, new.id::text),\r\n    resolved_display_name,\r\n    resolved_display_name,\r\n    'dispatcher',\r\n    true\r\n  )\r\n  on conflict (id) do update\r\n  set\r\n    email = excluded.email,\r\n    updated_at = now();\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "handle_profile_audit_update()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.handle_profile_audit_update()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_actor_id uuid;\r\n  current_actor_email text;\r\n  current_actor_display_name text;\r\n\r\n  audit_action text;\r\n  audit_summary text;\r\n\r\n  previous_values jsonb;\r\n  updated_values jsonb;\r\nbegin\r\n  /*\r\n   * לא יוצרים Audit אם השינוי בוצע ללא משתמש מחובר,\r\n   * למשל מתוך Edge Function עם service_role.\r\n   *\r\n   * יצירת משתמש כבר נרשמת בנפרד מתוך create-user.\r\n   */\r\n  current_actor_id := auth.uid();\r\n\r\n  if current_actor_id is null then\r\n    return new;\r\n  end if;\r\n\r\n  /*\r\n   * מתעדים רק שינויים ניהוליים משמעותיים.\r\n   * שינוי last_login_at או updated_at בלבד לא יירשם.\r\n   */\r\n  if not (\r\n    old.display_name\r\n      is distinct from new.display_name\r\n    or old.schedule_name\r\n      is distinct from new.schedule_name\r\n    or old.role\r\n      is distinct from new.role\r\n    or old.is_active\r\n      is distinct from new.is_active\r\n    or old.must_change_password\r\n      is distinct from new.must_change_password\r\n  ) then\r\n    return new;\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_actor_email,\r\n    current_actor_display_name\r\n  from public.profiles profile\r\n  where profile.id = current_actor_id;\r\n\r\n  /*\r\n   * קביעת סוג הפעולה המרכזי.\r\n   */\r\n  if old.is_active = true\r\n     and new.is_active = false then\r\n    audit_action := 'user_deactivated';\r\n\r\n    audit_summary :=\r\n      'המשתמש הושבת: ' ||\r\n      coalesce(\r\n        new.display_name,\r\n        new.email,\r\n        new.id::text\r\n      );\r\n\r\n  elsif old.is_active = false\r\n        and new.is_active = true then\r\n    audit_action := 'user_activated';\r\n\r\n    audit_summary :=\r\n      'המשתמש הופעל מחדש: ' ||\r\n      coalesce(\r\n        new.display_name,\r\n        new.email,\r\n        new.id::text\r\n      );\r\n\r\n  elsif old.must_change_password = false\r\n        and new.must_change_password = true then\r\n    audit_action :=\r\n      'user_password_change_required';\r\n\r\n    audit_summary :=\r\n      'המשתמש סומן כמי שנדרש לשנות סיסמה: ' ||\r\n      coalesce(\r\n        new.display_name,\r\n        new.email,\r\n        new.id::text\r\n      );\r\n\r\n  elsif old.must_change_password = true\r\n        and new.must_change_password = false then\r\n    audit_action :=\r\n      'user_password_change_completed';\r\n\r\n    audit_summary :=\r\n      'המשתמש השלים שינוי סיסמה: ' ||\r\n      coalesce(\r\n        new.display_name,\r\n        new.email,\r\n        new.id::text\r\n      );\r\n\r\n  else\r\n    audit_action := 'user_updated';\r\n\r\n    audit_summary :=\r\n      'עודכנו פרטי המשתמש: ' ||\r\n      coalesce(\r\n        new.display_name,\r\n        new.email,\r\n        new.id::text\r\n      );\r\n  end if;\r\n\r\n  previous_values :=\r\n    jsonb_build_object(\r\n      'display_name',\r\n      old.display_name,\r\n\r\n      'schedule_name',\r\n      old.schedule_name,\r\n\r\n      'role',\r\n      old.role,\r\n\r\n      'is_active',\r\n      old.is_active,\r\n\r\n      'must_change_password',\r\n      old.must_change_password\r\n    );\r\n\r\n  updated_values :=\r\n    jsonb_build_object(\r\n      'display_name',\r\n      new.display_name,\r\n\r\n      'schedule_name',\r\n      new.schedule_name,\r\n\r\n      'role',\r\n      new.role,\r\n\r\n      'is_active',\r\n      new.is_active,\r\n\r\n      'must_change_password',\r\n      new.must_change_password\r\n    );\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n\r\n    entity_type,\r\n    summary,\r\n\r\n    old_values,\r\n    new_values,\r\n\r\n    metadata\r\n  )\r\n  values (\r\n    audit_action,\r\n\r\n    current_actor_id,\r\n    current_actor_email,\r\n    current_actor_display_name,\r\n\r\n    new.id,\r\n    new.email,\r\n    new.display_name,\r\n\r\n    'user',\r\n    audit_summary,\r\n\r\n    previous_values,\r\n    updated_values,\r\n\r\n    jsonb_build_object(\r\n      'source',\r\n      'profiles-update-trigger'\r\n    )\r\n  );\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "handle_profile_permissions_created()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.handle_profile_permissions_created()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\nbegin\r\n  perform public.apply_default_user_permissions(\r\n    new.id\r\n  );\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "import_morning_driver_schedule_assignments(uuid,integer,integer,text,text,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.import_morning_driver_schedule_assignments(requested_import_run_id uuid, requested_year integer, requested_month integer, requested_period_type text, requested_import_strategy text, requested_morning_driver_shifts jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  imported_at timestamptz := now();\r\n\r\n  resolved_availability_period_id uuid;\r\n  resolved_schedule_period_id uuid;\r\n\r\n  detected_count integer := 0;\r\n  existing_count integer := 0;\r\n  created_count integer := 0;\r\n  updated_count integer := 0;\r\n  skipped_count integer := 0;\r\n  deleted_count integer := 0;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if requested_morning_driver_shifts is null\r\n     or jsonb_typeof(requested_morning_driver_shifts) <> 'array'\r\n  then\r\n    raise exception\r\n      'morning driver shifts must be a json array';\r\n  end if;\r\n\r\n  detected_count :=\r\n    jsonb_array_length(\r\n      requested_morning_driver_shifts\r\n    );\r\n\r\n  select period.id\r\n  into resolved_availability_period_id\r\n  from public.morning_driver_availability_periods period\r\n  where period.year = requested_year\r\n    and period.month = requested_month\r\n  for update;\r\n\r\n  if not found then\r\n    insert into public.morning_driver_availability_periods (\r\n      year,\r\n      month,\r\n      status,\r\n      title,\r\n      instructions,\r\n      submission_deadline,\r\n      closed_at,\r\n      archived_at,\r\n      created_by,\r\n      updated_by,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    values (\r\n      requested_year,\r\n      requested_month,\r\n      case\r\n        when requested_period_type = 'historical'\r\n        then 'archived'\r\n        else 'closed'\r\n      end,\r\n      format(\r\n        'כונני בוקר %s/%s',\r\n        requested_month,\r\n        requested_year\r\n      ),\r\n      'התקופה נוצרה אוטומטית מייבוא לוח שיבוצים.',\r\n      (\r\n        make_date(\r\n          requested_year,\r\n          requested_month,\r\n          1\r\n        )::timestamp\r\n        at time zone 'Asia/Jerusalem'\r\n      ),\r\n      case\r\n        when requested_period_type <> 'historical'\r\n        then imported_at\r\n        else null\r\n      end,\r\n      case\r\n        when requested_period_type = 'historical'\r\n        then imported_at\r\n        else null\r\n      end,\r\n      current_user_id,\r\n      current_user_id,\r\n      imported_at,\r\n      imported_at\r\n    )\r\n    returning id\r\n    into resolved_availability_period_id;\r\n  else\r\n    update public.morning_driver_availability_periods\r\n    set\r\n      status =\r\n        case\r\n          when requested_period_type = 'historical'\r\n          then 'archived'\r\n          else 'closed'\r\n        end,\r\n      closed_at =\r\n        case\r\n          when requested_period_type = 'historical'\r\n          then closed_at\r\n          else coalesce(closed_at, imported_at)\r\n        end,\r\n      archived_at =\r\n        case\r\n          when requested_period_type = 'historical'\r\n          then coalesce(archived_at, imported_at)\r\n          else null\r\n        end,\r\n      updated_by = current_user_id,\r\n      updated_at = imported_at\r\n    where id = resolved_availability_period_id;\r\n  end if;\r\n\r\n  select period.id\r\n  into resolved_schedule_period_id\r\n  from public.morning_driver_schedule_periods period\r\n  where period.year = requested_year\r\n    and period.month = requested_month\r\n  for update;\r\n\r\n  if not found then\r\n    insert into public.morning_driver_schedule_periods (\r\n      year,\r\n      month,\r\n      status,\r\n      availability_period_id,\r\n      title,\r\n      published_at,\r\n      created_by,\r\n      updated_by,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    values (\r\n      requested_year,\r\n      requested_month,\r\n      case\r\n        when requested_period_type = 'historical'\r\n        then 'archived'\r\n        else 'published'\r\n      end,\r\n      resolved_availability_period_id,\r\n      format(\r\n        'לוח כונני בוקר %s/%s',\r\n        requested_month,\r\n        requested_year\r\n      ),\r\n      imported_at,\r\n      current_user_id,\r\n      current_user_id,\r\n      imported_at,\r\n      imported_at\r\n    )\r\n    returning id\r\n    into resolved_schedule_period_id;\r\n  else\r\n    update public.morning_driver_schedule_periods\r\n    set\r\n      status =\r\n        case\r\n          when requested_period_type = 'historical'\r\n          then 'archived'\r\n          else 'published'\r\n        end,\r\n      availability_period_id =\r\n        resolved_availability_period_id,\r\n      published_at =\r\n        coalesce(published_at, imported_at),\r\n      updated_by =\r\n        current_user_id,\r\n      updated_at =\r\n        imported_at\r\n    where id =\r\n      resolved_schedule_period_id;\r\n  end if;\r\n\r\n  if requested_import_strategy = 'rebuild' then\r\n    select count(*)::integer\r\n    into deleted_count\r\n    from public.morning_driver_schedule_assignments assignment\r\n    where assignment.schedule_period_id =\r\n      resolved_schedule_period_id;\r\n\r\n    delete from public.morning_driver_schedule_assignments assignment\r\n    where assignment.schedule_period_id =\r\n      resolved_schedule_period_id;\r\n\r\n    delete from public.morning_driver_availability_entries entry\r\n    where entry.period_id =\r\n      resolved_availability_period_id;\r\n\r\n    delete from public.morning_driver_availability_submissions submission\r\n    where submission.period_id =\r\n      resolved_availability_period_id;\r\n\r\n    delete from public.morning_driver_availability_shifts shift_item\r\n    where shift_item.period_id =\r\n      resolved_availability_period_id;\r\n  end if;\r\n\r\n  /*\r\n   * יצירת/עדכון המשמרות שאליהן משויכים ה-Slots.\r\n   * required_workers משמש במערכת כיעד המומלץ.\r\n   */\r\n  insert into public.morning_driver_availability_shifts (\r\n    period_id,\r\n    shift_date,\r\n    weekday_number,\r\n    weekday_name,\r\n    shift_type,\r\n    start_time,\r\n    end_time,\r\n    required_workers,\r\n    sort_order,\r\n    created_at,\r\n    updated_at\r\n  )\r\n  select\r\n    resolved_availability_period_id,\r\n    payload.shift_date,\r\n    extract(\r\n      dow from payload.shift_date\r\n    )::integer,\r\n    case extract(\r\n      dow from payload.shift_date\r\n    )::integer\r\n      when 0 then 'ראשון'\r\n      when 1 then 'שני'\r\n      when 2 then 'שלישי'\r\n      when 3 then 'רביעי'\r\n      when 4 then 'חמישי'\r\n      when 5 then 'שישי'\r\n      when 6 then 'שבת'\r\n    end,\r\n    payload.shift_type,\r\n    payload.start_time,\r\n    payload.end_time,\r\n    payload.recommended_workers,\r\n    row_number() over (\r\n      order by\r\n        payload.shift_date,\r\n        payload.start_time,\r\n        payload.shift_type\r\n    )::integer,\r\n    imported_at,\r\n    imported_at\r\n  from (\r\n    select distinct\r\n      (item ->> 'date')::date as shift_date,\r\n      item ->> 'shiftType' as shift_type,\r\n      (item ->> 'startTime')::time as start_time,\r\n      (item ->> 'endTime')::time as end_time,\r\n      greatest(\r\n        least(\r\n          (item ->> 'recommendedWorkers')::integer,\r\n          2\r\n        ),\r\n        1\r\n      ) as recommended_workers\r\n    from jsonb_array_elements(\r\n      requested_morning_driver_shifts\r\n    ) item\r\n  ) payload\r\n  on conflict (\r\n    period_id,\r\n    shift_date,\r\n    shift_type\r\n  )\r\n  do update set\r\n    start_time =\r\n      excluded.start_time,\r\n    end_time =\r\n      excluded.end_time,\r\n    required_workers =\r\n      excluded.required_workers,\r\n    sort_order =\r\n      excluded.sort_order,\r\n    updated_at =\r\n      imported_at;\r\n\r\n  select count(*)::integer\r\n  into existing_count\r\n  from jsonb_array_elements(\r\n    requested_morning_driver_shifts\r\n  ) item\r\n  where exists (\r\n    select 1\r\n    from public.morning_driver_schedule_assignments assignment\r\n    join public.morning_driver_availability_shifts shift_item\r\n      on shift_item.id =\r\n        assignment.availability_shift_id\r\n    where assignment.schedule_period_id =\r\n        resolved_schedule_period_id\r\n      and shift_item.period_id =\r\n        resolved_availability_period_id\r\n      and shift_item.shift_date =\r\n        (item ->> 'date')::date\r\n      and shift_item.shift_type =\r\n        item ->> 'shiftType'\r\n      and assignment.assignment_slot =\r\n        (item ->> 'assignmentSlot')::integer\r\n  );\r\n\r\n  if requested_import_strategy = 'missing_only' then\r\n    insert into public.morning_driver_schedule_assignments (\r\n      schedule_period_id,\r\n      availability_shift_id,\r\n      assignment_slot,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_schedule_period_id,\r\n      shift_item.id,\r\n      (item ->> 'assignmentSlot')::integer,\r\n      (item ->> 'userId')::uuid,\r\n      'import',\r\n      requested_period_type = 'historical',\r\n      null,\r\n      imported_at,\r\n      imported_at\r\n    from jsonb_array_elements(\r\n      requested_morning_driver_shifts\r\n    ) item\r\n    join public.morning_driver_availability_shifts shift_item\r\n      on shift_item.period_id =\r\n        resolved_availability_period_id\r\n     and shift_item.shift_date =\r\n        (item ->> 'date')::date\r\n     and shift_item.shift_type =\r\n        item ->> 'shiftType'\r\n    on conflict (\r\n      schedule_period_id,\r\n      availability_shift_id,\r\n      assignment_slot\r\n    )\r\n    do nothing;\r\n\r\n    created_count :=\r\n      greatest(\r\n        detected_count - existing_count,\r\n        0\r\n      );\r\n    skipped_count :=\r\n      existing_count;\r\n\r\n  else\r\n    insert into public.morning_driver_schedule_assignments (\r\n      schedule_period_id,\r\n      availability_shift_id,\r\n      assignment_slot,\r\n      assigned_user_id,\r\n      assignment_source,\r\n      is_locked,\r\n      notes,\r\n      created_at,\r\n      updated_at\r\n    )\r\n    select\r\n      resolved_schedule_period_id,\r\n      shift_item.id,\r\n      (item ->> 'assignmentSlot')::integer,\r\n      (item ->> 'userId')::uuid,\r\n      'import',\r\n      requested_period_type = 'historical',\r\n      null,\r\n      imported_at,\r\n      imported_at\r\n    from jsonb_array_elements(\r\n      requested_morning_driver_shifts\r\n    ) item\r\n    join public.morning_driver_availability_shifts shift_item\r\n      on shift_item.period_id =\r\n        resolved_availability_period_id\r\n     and shift_item.shift_date =\r\n        (item ->> 'date')::date\r\n     and shift_item.shift_type =\r\n        item ->> 'shiftType'\r\n    on conflict (\r\n      schedule_period_id,\r\n      availability_shift_id,\r\n      assignment_slot\r\n    )\r\n    do update set\r\n      assigned_user_id =\r\n        excluded.assigned_user_id,\r\n      assignment_source =\r\n        excluded.assignment_source,\r\n      is_locked =\r\n        excluded.is_locked,\r\n      notes =\r\n        excluded.notes,\r\n      updated_at =\r\n        imported_at;\r\n\r\n    if requested_import_strategy = 'rebuild'\r\n       or requested_import_strategy = 'historical_archive'\r\n    then\r\n      created_count :=\r\n        detected_count;\r\n      updated_count := 0;\r\n    else\r\n      created_count :=\r\n        greatest(\r\n          detected_count - existing_count,\r\n          0\r\n        );\r\n      updated_count :=\r\n        existing_count;\r\n    end if;\r\n  end if;\r\n\r\n  update public.schedule_import_runs\r\n  set\r\n    result_summary =\r\n      coalesce(\r\n        result_summary,\r\n        '{}'::jsonb\r\n      )\r\n      ||\r\n      jsonb_build_object(\r\n        'morningDriverShifts',\r\n          jsonb_build_object(\r\n            'detected',\r\n              detected_count,\r\n            'created',\r\n              created_count,\r\n            'updated',\r\n              updated_count,\r\n            'skipped',\r\n              skipped_count,\r\n            'deleted',\r\n              deleted_count\r\n          )\r\n      ),\r\n    updated_at =\r\n      imported_at\r\n  where id =\r\n    requested_import_run_id;\r\n\r\n  return jsonb_build_object(\r\n    'availabilityPeriodId',\r\n      resolved_availability_period_id,\r\n    'schedulePeriodId',\r\n      resolved_schedule_period_id,\r\n    'detected',\r\n      detected_count,\r\n    'created',\r\n      created_count,\r\n    'updated',\r\n      updated_count,\r\n    'skipped',\r\n      skipped_count,\r\n    'deleted',\r\n      deleted_count\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "is_admin()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  select coalesce(\r\n    public.current_user_role() = 'admin',\r\n    false\r\n  );\r\n$function$\n"
  },
  {
    "function_signature": "is_current_user_admin()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.is_current_user_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\n  select exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = auth.uid()\r\n      and role::text = 'admin'\r\n      and is_active = true\r\n  );\r\n$function$\n"
  },
  {
    "function_signature": "is_manager_or_admin()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.is_manager_or_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\n  select coalesce(\r\n    public.current_user_role() in ('admin', 'manager'),\r\n    false\r\n  );\r\n$function$\n"
  },
  {
    "function_signature": "normalize_schedule_import_name(text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.normalize_schedule_import_name(requested_name text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO ''\nAS $function$\r\n  select\r\n    lower(\r\n      regexp_replace(\r\n        trim(\r\n          coalesce(\r\n            requested_name,\r\n            ''\r\n          )\r\n        ),\r\n        '\\s+',\r\n        ' ',\r\n        'g'\r\n      )\r\n    );\r\n$function$\n"
  },
  {
    "function_signature": "open_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.open_availability_period(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, period_status text, opened_at timestamp with time zone, shift_slots_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_actor_email text;\r\n  current_actor_display_name text;\r\n\r\n  target_period_title text;\r\n  target_year integer;\r\n  target_month integer;\r\n  target_status text;\r\n\r\n  target_opened_at timestamptz;\r\n  target_slots_count integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_actor_email,\r\n    current_actor_display_name\r\n  from public.profiles profile\r\n  where profile.id = current_user_id\r\n    and profile.is_active = true;\r\n\r\n  if current_actor_email is null then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability periods';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'Availability period id is required';\r\n  end if;\r\n\r\n  select\r\n    period.title,\r\n    period.year,\r\n    period.month,\r\n    period.status\r\n  into\r\n    target_period_title,\r\n    target_year,\r\n    target_month,\r\n    target_status\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if target_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  if target_status <> 'draft' then\r\n    raise exception\r\n      'Only draft availability periods can be opened';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    target_slots_count\r\n  from public.availability_shift_slots slot\r\n  where slot.period_id =\r\n    requested_period_id;\r\n\r\n  if target_slots_count = 0 then\r\n    raise exception\r\n      'Availability period does not contain shift slots';\r\n  end if;\r\n\r\n  target_opened_at := now();\r\n\r\n  update public.availability_periods period\r\n  set\r\n    status = 'open',\r\n    opened_at = target_opened_at,\r\n    closed_at = null,\r\n    updated_by = current_user_id,\r\n    updated_at = now()\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  insert into public.availability_submissions (\r\n    period_id,\r\n    user_id,\r\n    status,\r\n    submitted_at,\r\n    reopened_at,\r\n    last_saved_at,\r\n    available_count,\r\n    unavailable_count\r\n  )\r\n  select\r\n    requested_period_id,\r\n    profile.id,\r\n    'draft',\r\n    null,\r\n    null,\r\n    null,\r\n    0,\r\n    0\r\n  from public.profiles profile\r\n  where profile.role::text =\r\n    'dispatcher'\r\n    and profile.is_active = true\r\n  on conflict on constraint\r\n    availability_submissions_unique\r\n  do nothing;\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n\r\n    entity_type,\r\n    summary,\r\n\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    'availability_period_opened',\r\n\r\n    current_user_id,\r\n    current_actor_email,\r\n    current_actor_display_name,\r\n\r\n    null,\r\n    null,\r\n    null,\r\n\r\n    'availability_period',\r\n\r\n    format(\r\n      'נפתחה תקופת אילוצים להגשה: %s',\r\n      coalesce(\r\n        target_period_title,\r\n        format(\r\n          '%s/%s',\r\n          target_month,\r\n          target_year\r\n        )\r\n      )\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      'draft'\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      'open',\r\n      'opened_at',\r\n      target_opened_at,\r\n      'shift_slots_count',\r\n      target_slots_count\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'source',\r\n      'open-availability-period-rpc',\r\n\r\n      'period_id',\r\n      requested_period_id,\r\n\r\n      'year',\r\n      target_year,\r\n\r\n      'month',\r\n      target_month\r\n    )\r\n  );\r\n\r\n  return query\r\n  select\r\n    requested_period_id,\r\n    'open'::text,\r\n    target_opened_at,\r\n    target_slots_count;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "open_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.open_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  period_days_count integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status = 'open' then\r\n    select\r\n      count(*)::integer\r\n    into period_days_count\r\n    from public.driver_availability_days\r\n    where period_id =\r\n      target_period.id;\r\n\r\n    return jsonb_build_object(\r\n      'periodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'status',\r\n        target_period.status,\r\n\r\n      'openedAt',\r\n        target_period.opened_at,\r\n\r\n      'daysCount',\r\n        period_days_count,\r\n\r\n      'alreadyOpen',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status <> 'draft' then\r\n    raise exception\r\n      'only draft driver availability periods can be opened';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into period_days_count\r\n  from public.driver_availability_days\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  if period_days_count = 0 then\r\n    raise exception\r\n      'driver availability period has no days';\r\n  end if;\r\n\r\n  update public.driver_availability_periods\r\n  set\r\n    status =\r\n      'open',\r\n\r\n    opened_at =\r\n      now(),\r\n\r\n    closed_at =\r\n      null,\r\n\r\n    updated_by =\r\n      current_user_id,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_period.id\r\n\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status,\r\n\r\n    'openedAt',\r\n      target_period.opened_at,\r\n\r\n    'daysCount',\r\n      period_days_count,\r\n\r\n    'alreadyOpen',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "open_morning_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.open_morning_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  created_submissions integer := 0;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods\r\n  where id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'draft' then\r\n    raise exception\r\n      'only draft periods can be opened';\r\n  end if;\r\n\r\n  insert into public.morning_driver_availability_submissions (\r\n    period_id,\r\n    user_id,\r\n    status\r\n  )\r\n  select\r\n    target_period.id,\r\n    profile.id,\r\n    'draft'\r\n  from public.profiles profile\r\n  where profile.role =\r\n      'morning_driver'::public.user_role\r\n    and profile.is_active = true\r\n  on conflict (\r\n    period_id,\r\n    user_id\r\n  )\r\n  do nothing;\r\n\r\n  get diagnostics\r\n    created_submissions =\r\n      row_count;\r\n\r\n  update public.morning_driver_availability_periods\r\n  set\r\n    status = 'open',\r\n    opened_at = now(),\r\n    updated_by = current_user_id,\r\n    updated_at = now()\r\n  where id = target_period.id\r\n  returning *\r\n  into target_period;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'morning_driver_availability_period_opened'\r\n        ::public.audit_action_type,\r\n\r\n    requested_target_user_id :=\r\n      null,\r\n\r\n    requested_summary :=\r\n      'נפתח חודש אילוצים לכונני בוקר',\r\n\r\n    requested_old_values :=\r\n      jsonb_build_object(\r\n        'status',\r\n          'draft'\r\n      ),\r\n\r\n    requested_new_values :=\r\n      jsonb_build_object(\r\n        'status',\r\n          target_period.status,\r\n\r\n        'openedAt',\r\n          target_period.opened_at\r\n      ),\r\n\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'periodId',\r\n          target_period.id,\r\n\r\n        'year',\r\n          target_period.year,\r\n\r\n        'month',\r\n          target_period.month,\r\n\r\n        'createdSubmissions',\r\n          created_submissions\r\n      )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status,\r\n\r\n    'openedAt',\r\n      target_period.opened_at,\r\n\r\n    'createdSubmissions',\r\n      created_submissions\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "preview_schedule_excel_import(integer,integer,text,text,jsonb,jsonb,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.preview_schedule_excel_import(requested_year integer, requested_month integer, requested_period_type text, requested_import_strategy text, requested_dispatcher_shifts jsonb, requested_driver_duties jsonb, requested_morning_driver_shifts jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  base_preview jsonb;\r\n  blockers jsonb := '[]'::jsonb;\r\n  warnings jsonb := '[]'::jsonb;\r\n\r\n  target_availability_period public.morning_driver_availability_periods%rowtype;\r\n  target_schedule_period public.morning_driver_schedule_periods%rowtype;\r\n\r\n  availability_period_exists boolean := false;\r\n  schedule_period_exists boolean := false;\r\n\r\n  detected_count integer := 0;\r\n  existing_count integer := 0;\r\n  create_count integer := 0;\r\n  update_count integer := 0;\r\n  skip_count integer := 0;\r\n  delete_count integer := 0;\r\n\r\n  invalid_count integer := 0;\r\n  inactive_count integer := 0;\r\nbegin\r\n  if requested_morning_driver_shifts is null\r\n     or jsonb_typeof(requested_morning_driver_shifts) <> 'array'\r\n  then\r\n    raise exception\r\n      'morning driver shifts must be a json array';\r\n  end if;\r\n\r\n  /*\r\n   * מפעילים את הסימולציה הקיימת של מוקדנים וכוננים.\r\n   * הפונקציה בעלת ששת הפרמטרים נשארת מקור האמת\r\n   * לשני סוגי הנתונים הקיימים.\r\n   */\r\n  base_preview :=\r\n    public.preview_schedule_excel_import(\r\n      requested_year,\r\n      requested_month,\r\n      requested_period_type,\r\n      requested_import_strategy,\r\n      requested_dispatcher_shifts,\r\n      requested_driver_duties\r\n    );\r\n\r\n  blockers :=\r\n    coalesce(\r\n      base_preview -> 'blockers',\r\n      '[]'::jsonb\r\n    );\r\n\r\n  warnings :=\r\n    coalesce(\r\n      base_preview -> 'warnings',\r\n      '[]'::jsonb\r\n    );\r\n\r\n  detected_count :=\r\n    jsonb_array_length(\r\n      requested_morning_driver_shifts\r\n    );\r\n\r\n  if detected_count = 0 then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לא התקבלו שיבוצי כונני בוקר לייבוא.'\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * מבנה כל רשומת כונן בוקר:\r\n   * date, startTime, endTime, userId,\r\n   * assignmentSlot, shiftType,\r\n   * minimumWorkers, recommendedWorkers.\r\n   */\r\n  select count(*)::integer\r\n  into invalid_count\r\n  from jsonb_array_elements(\r\n    requested_morning_driver_shifts\r\n  ) item\r\n  where\r\n    jsonb_typeof(item) <> 'object'\r\n    or coalesce(item ->> 'date', '') !~\r\n      '^\\d{4}-\\d{2}-\\d{2}$'\r\n    or coalesce(item ->> 'startTime', '') !~\r\n      '^\\d{2}:\\d{2}$'\r\n    or coalesce(item ->> 'endTime', '') !~\r\n      '^\\d{2}:\\d{2}$'\r\n    or coalesce(item ->> 'userId', '') !~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n    or coalesce(item ->> 'assignmentSlot', '') !~\r\n      '^[12]$'\r\n    or coalesce(item ->> 'shiftType', '') not in (\r\n      'weekday_morning',\r\n      'weekday_evening',\r\n      'friday_morning'\r\n    )\r\n    or coalesce(item ->> 'minimumWorkers', '') !~\r\n      '^\\d+$'\r\n    or coalesce(item ->> 'recommendedWorkers', '') !~\r\n      '^\\d+$'\r\n    or (item ->> 'minimumWorkers')::integer < 1\r\n    or (item ->> 'minimumWorkers')::integer > 2\r\n    or (item ->> 'recommendedWorkers')::integer < 1\r\n    or (item ->> 'recommendedWorkers')::integer > 2\r\n    or (item ->> 'recommendedWorkers')::integer <\r\n      (item ->> 'minimumWorkers')::integer\r\n    or extract(\r\n      year from (item ->> 'date')::date\r\n    )::integer <> requested_year\r\n    or extract(\r\n      month from (item ->> 'date')::date\r\n    )::integer <> requested_month;\r\n\r\n  if invalid_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s שיבוצי כונני בוקר מכילים נתונים לא תקינים.',\r\n          invalid_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  select count(*)::integer\r\n  into inactive_count\r\n  from (\r\n    select distinct\r\n      (item ->> 'userId')::uuid as user_id\r\n    from jsonb_array_elements(\r\n      requested_morning_driver_shifts\r\n    ) item\r\n    where coalesce(item ->> 'userId', '') ~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n  ) payload_user\r\n  left join public.profiles profile_row\r\n    on profile_row.id = payload_user.user_id\r\n   and profile_row.is_active = true\r\n   and profile_row.role =\r\n     'morning_driver'::public.user_role\r\n  where profile_row.id is null;\r\n\r\n  if inactive_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s כונני בוקר אינם קיימים, אינם פעילים או אינם מוגדרים ככונני בוקר.',\r\n          inactive_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from (\r\n      select\r\n        item ->> 'date' as shift_date,\r\n        item ->> 'shiftType' as shift_type,\r\n        item ->> 'assignmentSlot' as assignment_slot,\r\n        count(*)::integer as row_count\r\n      from jsonb_array_elements(\r\n        requested_morning_driver_shifts\r\n      ) item\r\n      group by\r\n        item ->> 'date',\r\n        item ->> 'shiftType',\r\n        item ->> 'assignmentSlot'\r\n      having count(*) > 1\r\n    ) duplicate_assignment\r\n  ) then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'התקבלו מספר כונני בוקר לאותו תאריך, סוג משמרת ומיקום שיבוץ.'\r\n      );\r\n  end if;\r\n\r\n  select *\r\n  into target_availability_period\r\n  from public.morning_driver_availability_periods\r\n  where year = requested_year\r\n    and month = requested_month;\r\n\r\n  if found then\r\n    availability_period_exists := true;\r\n  end if;\r\n\r\n  select *\r\n  into target_schedule_period\r\n  from public.morning_driver_schedule_periods\r\n  where year = requested_year\r\n    and month = requested_month;\r\n\r\n  if found then\r\n    schedule_period_exists := true;\r\n  end if;\r\r\n\r\n  if schedule_period_exists then\r\n    select count(*)::integer\r\n    into existing_count\r\n    from jsonb_array_elements(\r\n      requested_morning_driver_shifts\r\n    ) item\r\n    where exists (\r\n      select 1\r\n      from public.morning_driver_schedule_assignments assignment\r\n      join public.morning_driver_availability_shifts shift_item\r\n        on shift_item.id =\r\n          assignment.availability_shift_id\r\n      where assignment.schedule_period_id =\r\n          target_schedule_period.id\r\n        and shift_item.shift_date =\r\n          (item ->> 'date')::date\r\n        and shift_item.shift_type =\r\n          item ->> 'shiftType'\r\n        and assignment.assignment_slot =\r\n          (item ->> 'assignmentSlot')::integer\r\n    );\r\n\r\n    select count(*)::integer\r\n    into delete_count\r\n    from public.morning_driver_schedule_assignments assignment\r\n    where assignment.schedule_period_id =\r\n      target_schedule_period.id;\r\n  end if;\r\n\r\n  if requested_import_strategy = 'missing_only' then\r\n    create_count :=\r\n      greatest(\r\n        detected_count - existing_count,\r\n        0\r\n      );\r\n    update_count := 0;\r\n    skip_count := existing_count;\r\n    delete_count := 0;\r\n\r\n  elsif requested_import_strategy = 'replace' then\r\n    create_count :=\r\n      greatest(\r\n        detected_count - existing_count,\r\n        0\r\n      );\r\n    update_count := existing_count;\r\n    skip_count := 0;\r\n    delete_count := 0;\r\n\r\n  elsif requested_import_strategy = 'rebuild' then\r\n    create_count := detected_count;\r\n    update_count := 0;\r\n    skip_count := 0;\r\n\r\n  elsif requested_import_strategy = 'historical_archive' then\r\n    create_count := detected_count;\r\n    update_count := 0;\r\n    skip_count := 0;\r\n    delete_count := 0;\r\n  end if;\r\n\r\n  if requested_period_type = 'current'\r\n     and schedule_period_exists\r\n     and target_schedule_period.status = 'archived'\r\n  then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'תקופת כונני הבוקר של החודש כבר נמצאת בארכיון.'\r\n      );\r\n  end if;\r\n\r\n  if requested_period_type = 'current'\r\n     and schedule_period_exists\r\n     and target_schedule_period.status = 'published'\r\n     and requested_import_strategy in (\r\n       'replace',\r\n       'rebuild'\r\n     )\r\n  then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לוח כונני הבוקר כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'\r\n      );\r\n  end if;\r\n\r\n  return\r\n    base_preview\r\n    ||\r\n    jsonb_build_object(\r\n      'canImport',\r\n        jsonb_array_length(blockers) = 0,\r\n      'blockers',\r\n        blockers,\r\n      'warnings',\r\n        warnings,\r\n      'morningDriverAvailabilityPeriod',\r\n        jsonb_build_object(\r\n          'exists',\r\n            availability_period_exists,\r\n          'id',\r\n            case\r\n              when availability_period_exists\r\n              then target_availability_period.id\r\n              else null\r\n            end,\r\n          'status',\r\n            case\r\n              when availability_period_exists\r\n              then target_availability_period.status\r\n              else null\r\n            end\r\n        ),\r\n      'morningDriverSchedulePeriod',\r\n        jsonb_build_object(\r\n          'exists',\r\n            schedule_period_exists,\r\n          'id',\r\n            case\r\n              when schedule_period_exists\r\n              then target_schedule_period.id\r\n              else null\r\n            end,\r\n          'status',\r\n            case\r\n              when schedule_period_exists\r\n              then target_schedule_period.status\r\n              else null\r\n            end\r\n        ),\r\n      'morningDriverShifts',\r\n        jsonb_build_object(\r\n          'detected',\r\n            detected_count,\r\n          'existing',\r\n            existing_count,\r\n          'toCreate',\r\n            create_count,\r\n          'toUpdate',\r\n            update_count,\r\n          'toSkip',\r\n            skip_count,\r\n          'toDelete',\r\n            delete_count\r\n        )\r\n    );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "preview_schedule_excel_import(integer,integer,text,text,jsonb,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.preview_schedule_excel_import(requested_year integer, requested_month integer, requested_period_type text, requested_import_strategy text, requested_dispatcher_shifts jsonb, requested_driver_duties jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_schedule_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  target_driver_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  dispatcher_detected_count integer := 0;\r\n  dispatcher_existing_count integer := 0;\r\n  dispatcher_create_count integer := 0;\r\n  dispatcher_update_count integer := 0;\r\n  dispatcher_skip_count integer := 0;\r\n  dispatcher_delete_count integer := 0;\r\n\r\n  driver_detected_count integer := 0;\r\n  driver_existing_count integer := 0;\r\n  driver_create_count integer := 0;\r\n  driver_update_count integer := 0;\r\n  driver_skip_count integer := 0;\r\n  driver_delete_count integer := 0;\r\n\r\n  invalid_dispatcher_count integer := 0;\r\n  invalid_driver_count integer := 0;\r\n\r\n  inactive_dispatcher_count integer := 0;\r\n  inactive_driver_count integer := 0;\r\n\r\n  blockers jsonb := '[]'::jsonb;\r\n  warnings jsonb := '[]'::jsonb;\r\n\r\n  schedule_period_exists boolean := false;\r\n  driver_period_exists boolean := false;\r\n\r\n  schedule_period_status text := null;\r\n  driver_period_status text := null;\r\n\r\n  current_period_value integer;\r\n  requested_period_value integer;\r\n  expected_period_type text;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile_row\r\n    where profile_row.id =\r\n      current_user_id\r\n      and profile_row.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n    or\r\n    'schedule.edit' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_year is null\r\n    or requested_year < 2020\r\n    or requested_year > 2100\r\n  then\r\n    raise exception\r\n      'import year is invalid';\r\n  end if;\r\n\r\n  if requested_month is null\r\n    or requested_month < 1\r\n    or requested_month > 12\r\n  then\r\n    raise exception\r\n      'import month is invalid';\r\n  end if;\r\n\r\n  if requested_period_type not in (\r\n    'historical',\r\n    'current',\r\n    'future'\r\n  ) then\r\n    raise exception\r\n      'import period type is invalid';\r\n  end if;\r\n\r\n  if requested_import_strategy not in (\r\n    'missing_only',\r\n    'replace',\r\n    'rebuild',\r\n    'historical_archive'\r\n  ) then\r\n    raise exception\r\n      'import strategy is invalid';\r\n  end if;\r\n\r\n  if requested_dispatcher_shifts is null\r\n    or jsonb_typeof(\r\n      requested_dispatcher_shifts\r\n    ) <> 'array'\r\n  then\r\n    raise exception\r\n      'dispatcher shifts must be a json array';\r\n  end if;\r\n\r\n  if requested_driver_duties is null\r\n    or jsonb_typeof(\r\n      requested_driver_duties\r\n    ) <> 'array'\r\n  then\r\n    raise exception\r\n      'driver duties must be a json array';\r\n  end if;\r\n\r\n  current_period_value :=\r\n    extract(\r\n      year from\r\n      timezone(\r\n        'Asia/Jerusalem',\r\n        now()\r\n      )\r\n    )::integer * 12\r\n    +\r\n    extract(\r\n      month from\r\n      timezone(\r\n        'Asia/Jerusalem',\r\n        now()\r\n      )\r\n    )::integer\r\n    - 1;\r\n\r\n  requested_period_value :=\r\n    requested_year * 12\r\n    + requested_month\r\n    - 1;\r\n\r\n  expected_period_type :=\r\n    case\r\n      when requested_period_value <\r\n        current_period_value\r\n      then\r\n        'historical'\r\n\r\n      when requested_period_value =\r\n        current_period_value\r\n      then\r\n        'current'\r\n\r\n      else\r\n        'future'\r\n    end;\r\n\r\n  if requested_period_type <>\r\n    expected_period_type\r\n  then\r\n    raise exception\r\n      'import period type does not match requested year and month';\r\n  end if;\r\r\n\r\n  if requested_period_type =\r\n      'current'\r\n    and requested_import_strategy =\r\n      'historical_archive'\r\n  then\r\n    raise exception\r\n      'current imports cannot use historical_archive strategy';\r\n  end if;\r\n\r\n  if requested_period_type =\r\n    'future'\r\n  then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'ייבוא חודש עתידי עדיין אינו נתמך.'\r\n      );\r\n  end if;\r\n\r\n  dispatcher_detected_count :=\r\n    jsonb_array_length(\r\n      requested_dispatcher_shifts\r\n    );\r\n\r\n  driver_detected_count :=\r\n    jsonb_array_length(\r\n      requested_driver_duties\r\n    );\r\n\r\n  if dispatcher_detected_count = 0 then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לא התקבלו משמרות מוקדנים לייבוא.'\r\n      );\r\n  end if;\r\n\r\n  if driver_detected_count = 0 then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לא התקבלו ימי כוננות לייבוא.'\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת מבנה משמרות המוקדנים.\r\n   */\r\n  select\r\n    count(*)::integer\r\n  into\r\n    invalid_dispatcher_count\r\n  from jsonb_array_elements(\r\n    requested_dispatcher_shifts\r\n  ) item\r\n  where\r\n    jsonb_typeof(item) <> 'object'\r\n\r\n    or coalesce(\r\n      item ->> 'date',\r\n      ''\r\n    ) !~\r\n      '^\\d{4}-\\d{2}-\\d{2}$'\r\n\r\n    or coalesce(\r\n      item ->> 'startTime',\r\n      ''\r\n    ) !~\r\n      '^\\d{2}:\\d{2}$'\r\n\r\n    or coalesce(\r\n      item ->> 'endTime',\r\n      ''\r\n    ) !~\r\n      '^\\d{2}:\\d{2}$'\r\n\r\n    or coalesce(\r\n      item ->> 'userId',\r\n      ''\r\n    ) !~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n\r\n    or extract(\r\n      year from\r\n      (item ->> 'date')::date\r\n    )::integer <>\r\n      requested_year\r\n\r\n    or extract(\r\n      month from\r\n      (item ->> 'date')::date\r\n    )::integer <>\r\n      requested_month;\r\n\r\n  if invalid_dispatcher_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s משמרות מוקדנים מכילות נתונים לא תקינים.',\r\n          invalid_dispatcher_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת מבנה ימי הכוננות.\r\n   */\r\n  select\r\n    count(*)::integer\r\n  into\r\n    invalid_driver_count\r\n  from jsonb_array_elements(\r\n    requested_driver_duties\r\n  ) item\r\n  where\r\n    jsonb_typeof(item) <> 'object'\r\n\r\n    or coalesce(\r\n      item ->> 'date',\r\n      ''\r\n    ) !~\r\n      '^\\d{4}-\\d{2}-\\d{2}$'\r\n\r\n    or coalesce(\r\n      item ->> 'userId',\r\n      ''\r\n    ) !~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n\r\n    or extract(\r\n      year from\r\n      (item ->> 'date')::date\r\n    )::integer <>\r\n      requested_year\r\n\r\n    or extract(\r\n      month from\r\n      (item ->> 'date')::date\r\n    )::integer <>\r\n      requested_month;\r\n\r\n  if invalid_driver_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s ימי כוננות מכילים נתונים לא תקינים.',\r\n          invalid_driver_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת משתמשי מוקדנים פעילים.\r\n   */\r\n  select\r\n    count(*)::integer\r\n  into\r\n    inactive_dispatcher_count\r\n  from (\r\n    select distinct\r\n      (\r\n        item ->> 'userId'\r\n      )::uuid as user_id\r\n    from jsonb_array_elements(\r\n      requested_dispatcher_shifts\r\n    ) item\r\n    where coalesce(\r\n      item ->> 'userId',\r\n      ''\r\n    ) ~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n  ) payload_user\r\n  left join public.profiles profile_row\r\n    on profile_row.id =\r\n      payload_user.user_id\r\n    and profile_row.is_active = true\r\n    and profile_row.role =\r\n      'dispatcher'\r\n  where profile_row.id is null;\r\n\r\n  if inactive_dispatcher_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s מוקדנים אינם קיימים, אינם פעילים או אינם מוגדרים כמוקדנים.',\r\n          inactive_dispatcher_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת משתמשי כוננים פעילים.\r\n   */\r\n  select\r\n    count(*)::integer\r\n  into\r\n    inactive_driver_count\r\n  from (\r\n    select distinct\r\n      (\r\n        item ->> 'userId'\r\n      )::uuid as user_id\r\n    from jsonb_array_elements(\r\n      requested_driver_duties\r\n    ) item\r\n    where coalesce(\r\n      item ->> 'userId',\r\n      ''\r\n    ) ~\r\n      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'\r\n  ) payload_user\r\n  left join public.profiles profile_row\r\n    on profile_row.id =\r\n      payload_user.user_id\r\n    and profile_row.is_active = true\r\n    and profile_row.role =\r\n      'on_call'\r\n  where profile_row.id is null;\r\n\r\n  if inactive_driver_count > 0 then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        format(\r\n          '%s כוננים אינם קיימים, אינם פעילים או אינם מוגדרים ככוננים.',\r\n          inactive_driver_count\r\n        )\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת כפילויות במשמרות המוקדנים.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from (\r\n      select\r\n        item ->> 'date' as shift_date,\r\n        item ->> 'startTime' as start_time,\r\n        count(*)::integer as row_count\r\n      from jsonb_array_elements(\r\n        requested_dispatcher_shifts\r\n      ) item\r\n      group by\r\n        item ->> 'date',\r\n        item ->> 'startTime'\r\n      having count(*) > 1\r\n    ) duplicate_shift\r\n  ) then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'התקבלו מספר משמרות מוקדנים לאותו תאריך ושעת התחלה.'\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת כפילויות בכוננויות.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from (\r\n      select\r\n        item ->> 'date' as duty_date,\r\n        count(*)::integer as row_count\r\n      from jsonb_array_elements(\r\n        requested_driver_duties\r\n      ) item\r\n      group by\r\n        item ->> 'date'\r\n      having count(*) > 1\r\n    ) duplicate_duty\r\n  ) then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'התקבלו מספר כוננים עבור אותו תאריך.'\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * איתור תקופות קיימות.\r\n   */\r\n  select *\r\n  into target_schedule_period\r\n  from public.schedule_periods\r\n  where year =\r\n    requested_year\r\n    and month =\r\n      requested_month;\r\n\r\n  if found then\r\n    schedule_period_exists :=\r\n      true;\r\n\r\n    schedule_period_status :=\r\n      target_schedule_period.status::text;\r\n  end if;\r\n\r\n  select *\r\n  into target_driver_period\r\n  from public.driver_schedule_periods\r\n  where year =\r\n    requested_year\r\n    and month =\r\n      requested_month;\r\n\r\n  if found then\r\n    driver_period_exists :=\r\n      true;\r\n\r\n    driver_period_status :=\r\n      target_driver_period.status::text;\r\n  end if;\r\r\n\r\n  /*\r\n   * ספירת משמרות מוקדנים קיימות.\r\n   */\r\n  if schedule_period_exists then\r\n    select\r\n      count(*)::integer\r\n    into\r\n      dispatcher_existing_count\r\n    from jsonb_array_elements(\r\n      requested_dispatcher_shifts\r\n    ) item\r\n    where exists (\r\n      select 1\r\n      from public.schedule_shifts shift_row\r\n      where shift_row.period_id =\r\n        target_schedule_period.id\r\n        and shift_row.starts_at =\r\n          (\r\n            (\r\n              (item ->> 'date')::date\r\n              +\r\n              (item ->> 'startTime')::time\r\n            )\r\n            at time zone\r\n              'Asia/Jerusalem'\r\n          )\r\n    );\r\n\r\n    select\r\n      count(*)::integer\r\n    into\r\n      dispatcher_delete_count\r\n    from public.schedule_shifts shift_row\r\n    where shift_row.period_id =\r\n      target_schedule_period.id;\r\n  end if;\r\n\r\n  /*\r\n   * ספירת ימי כוננות קיימים.\r\n   */\r\n  if driver_period_exists then\r\n    select\r\n      count(*)::integer\r\n    into\r\n      driver_existing_count\r\n    from jsonb_array_elements(\r\n      requested_driver_duties\r\n    ) item\r\n    where exists (\r\n      select 1\r\n      from public.driver_schedule_days day_row\r\n      where day_row.period_id =\r\n        target_driver_period.id\r\n        and day_row.duty_date =\r\n          (item ->> 'date')::date\r\n    );\r\n\r\n    select\r\n      count(*)::integer\r\n    into\r\n      driver_delete_count\r\n    from public.driver_schedule_days day_row\r\n    where day_row.period_id =\r\n      target_driver_period.id;\r\n  end if;\r\n\r\n  /*\r\n   * חישוב פעולות לפי אסטרטגיה.\r\n   */\r\n  if requested_import_strategy =\r\n    'missing_only'\r\n  then\r\n    dispatcher_create_count :=\r\n      greatest(\r\n        dispatcher_detected_count -\r\n        dispatcher_existing_count,\r\n        0\r\n      );\r\n\r\n    dispatcher_update_count := 0;\r\n\r\n    dispatcher_skip_count :=\r\n      dispatcher_existing_count;\r\n\r\n    dispatcher_delete_count := 0;\r\n\r\n    driver_create_count :=\r\n      greatest(\r\n        driver_detected_count -\r\n        driver_existing_count,\r\n        0\r\n      );\r\n\r\n    driver_update_count := 0;\r\n\r\n    driver_skip_count :=\r\n      driver_existing_count;\r\n\r\n    driver_delete_count := 0;\r\n\r\n  elsif requested_import_strategy =\r\n    'replace'\r\n  then\r\n    dispatcher_create_count :=\r\n      greatest(\r\n        dispatcher_detected_count -\r\n        dispatcher_existing_count,\r\n        0\r\n      );\r\n\r\n    dispatcher_update_count :=\r\n      dispatcher_existing_count;\r\n\r\n    dispatcher_skip_count := 0;\r\n\r\n    dispatcher_delete_count := 0;\r\n\r\n    driver_create_count :=\r\n      greatest(\r\n        driver_detected_count -\r\n        driver_existing_count,\r\n        0\r\n      );\r\n\r\n    driver_update_count :=\r\n      driver_existing_count;\r\n\r\n    driver_skip_count := 0;\r\n\r\n    driver_delete_count := 0;\r\n\r\n  elsif requested_import_strategy =\r\n    'rebuild'\r\n  then\r\n    dispatcher_create_count :=\r\n      dispatcher_detected_count;\r\n\r\n    dispatcher_update_count := 0;\r\n    dispatcher_skip_count := 0;\r\n\r\n    driver_create_count :=\r\n      driver_detected_count;\r\n\r\n    driver_update_count := 0;\r\n    driver_skip_count := 0;\r\n\r\n  elsif requested_import_strategy =\r\n    'historical_archive'\r\n  then\r\n    dispatcher_create_count :=\r\n      dispatcher_detected_count;\r\n\r\n    dispatcher_update_count := 0;\r\n    dispatcher_skip_count := 0;\r\n    dispatcher_delete_count := 0;\r\n\r\n    driver_create_count :=\r\n      driver_detected_count;\r\n\r\n    driver_update_count := 0;\r\n    driver_skip_count := 0;\r\n    driver_delete_count := 0;\r\n  end if;\r\n\r\n  if requested_period_type =\r\n      'current'\r\n    and schedule_period_status =\r\n      'archived'\r\n  then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'תקופת המוקדנים של החודש כבר נמצאת בארכיון.'\r\n      );\r\n  end if;\r\n\r\n  if requested_period_type =\r\n      'current'\r\n    and driver_period_status =\r\n      'archived'\r\n  then\r\n    blockers :=\r\n      blockers ||\r\n      jsonb_build_array(\r\n        'תקופת הכוננים של החודש כבר נמצאת בארכיון.'\r\n      );\r\n  end if;\r\n\r\n  if requested_period_type =\r\n      'current'\r\n    and schedule_period_status =\r\n      'published'\r\n    and requested_import_strategy in (\r\n      'replace',\r\n      'rebuild'\r\n    )\r\n  then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לוח המוקדנים כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'\r\n      );\r\n  end if;\r\n\r\n  if requested_period_type =\r\n      'current'\r\n    and driver_period_status =\r\n      'published'\r\n    and requested_import_strategy in (\r\n      'replace',\r\n      'rebuild'\r\n    )\r\n  then\r\n    warnings :=\r\n      warnings ||\r\n      jsonb_build_array(\r\n        'לוח הכוננים כבר פורסם. הייבוא צפוי לשנות לוח פעיל.'\r\n      );\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'year',\r\n      requested_year,\r\n\r\n    'month',\r\n      requested_month,\r\n\r\n    'periodType',\r\n      requested_period_type,\r\n\r\n    'importStrategy',\r\n      requested_import_strategy,\r\n\r\n    'canImport',\r\n      jsonb_array_length(\r\n        blockers\r\n      ) = 0,\r\n\r\n    'blockers',\r\n      blockers,\r\n\r\n    'warnings',\r\n      warnings,\r\n\r\n    'schedulePeriod',\r\n      jsonb_build_object(\r\n        'exists',\r\n          schedule_period_exists,\r\n\r\n        'id',\r\n          case\r\n            when schedule_period_exists\r\n            then target_schedule_period.id\r\n            else null\r\n          end,\r\n\r\n        'status',\r\n          schedule_period_status\r\n      ),\r\n\r\n    'driverSchedulePeriod',\r\n      jsonb_build_object(\r\n        'exists',\r\n          driver_period_exists,\r\n\r\n        'id',\r\n          case\r\n            when driver_period_exists\r\n            then target_driver_period.id\r\n            else null\r\n          end,\r\n\r\n        'status',\r\n          driver_period_status\r\n      ),\r\n\r\n    'dispatcherShifts',\r\n      jsonb_build_object(\r\n        'detected',\r\n          dispatcher_detected_count,\r\n\r\n        'existing',\r\n          dispatcher_existing_count,\r\n\r\n        'toCreate',\r\n          dispatcher_create_count,\r\n\r\n        'toUpdate',\r\n          dispatcher_update_count,\r\n\r\n        'toSkip',\r\n          dispatcher_skip_count,\r\n\r\n        'toDelete',\r\n          dispatcher_delete_count\r\n      ),\r\n\r\n    'driverDuties',\r\n      jsonb_build_object(\r\n        'detected',\r\n          driver_detected_count,\r\n\r\n        'existing',\r\n          driver_existing_count,\r\n\r\n        'toCreate',\r\n          driver_create_count,\r\n\r\n        'toUpdate',\r\n          driver_update_count,\r\n\r\n        'toSkip',\r\n          driver_skip_count,\r\n\r\n        'toDelete',\r\n          driver_delete_count\r\n      )\r\n  );\r\nend;\r\n$function$\n"
