    "function_signature": "publish_driver_schedule(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.publish_driver_schedule(requested_schedule_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  total_days_count integer := 0;\r\n  assigned_days_count integer := 0;\r\n  unassigned_days_count integer := 0;\r\n  consecutive_conflicts_count integer := 0;\r\n\r\n  published_at_value timestamptz :=\r\n    now();\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_period_id\r\n    is null\r\n  then\r\n    raise exception\r\n      'driver schedule period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_schedule_periods\r\n  where id =\r\n    requested_schedule_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status =\r\n    'published'\r\n  then\r\n    select\r\n      count(*)::integer,\r\n\r\n      count(*) filter (\r\n        where assigned_user_id\r\n          is not null\r\n      )::integer,\r\n\r\n      count(*) filter (\r\n        where assigned_user_id\r\n          is null\r\n      )::integer\r\n\r\n    into\r\n      total_days_count,\r\n      assigned_days_count,\r\n      unassigned_days_count\r\n\r\n    from public.driver_schedule_days\r\n    where period_id =\r\n      target_period.id;\r\n\r\n    return jsonb_build_object(\r\n      'schedulePeriodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'status',\r\n        target_period.status,\r\n\r\n      'totalDays',\r\n        total_days_count,\r\n\r\n      'assignedDays',\r\n        assigned_days_count,\r\n\r\n      'unassignedDays',\r\n        unassigned_days_count,\r\n\r\n      'publishedAt',\r\n        target_period.published_at,\r\n\r\n      'alreadyPublished',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status <>\r\n    'draft'\r\n  then\r\n    raise exception\r\n      'only draft driver schedules can be published';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer,\r\n\r\n    count(*) filter (\r\n      where assigned_user_id\r\n        is not null\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where assigned_user_id\r\n        is null\r\n    )::integer\r\n\r\n  into\r\n    total_days_count,\r\n    assigned_days_count,\r\n    unassigned_days_count\r\n\r\n  from public.driver_schedule_days\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  if total_days_count = 0 then\r\n    raise exception\r\n      'driver schedule has no days';\r\n  end if;\r\n\r\n  if unassigned_days_count > 0 then\r\n    raise exception\r\n      'all driver schedule days must be assigned before publishing';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    consecutive_conflicts_count\r\n\r\n  from public.driver_schedule_days\r\n    first_day\r\n\r\n  join public.driver_schedule_days\r\n    second_day\r\n\r\n    on second_day.period_id =\r\n      first_day.period_id\r\n\r\n    and second_day.duty_date =\r\n      first_day.duty_date + 1\r\n\r\n    and second_day.assigned_user_id =\r\n      first_day.assigned_user_id\r\n\r\n  where first_day.period_id =\r\n    target_period.id\r\n\r\n    and first_day.assigned_user_id\r\n      is not null;\r\n\r\n  if consecutive_conflicts_count > 0 then\r\n    raise exception\r\n      'driver schedule contains consecutive-day assignments';\r\n  end if;\r\n\r\n  /*\r\n   * Publishing no longer changes is_locked.\r\n   * is_locked is reserved for explicit/manual locks.\r\n   */\r\n\r\n  update public.driver_schedule_periods\r\n  set\r\n    status =\r\n      'published',\r\n\r\n    published_at =\r\n      published_at_value,\r\n\r\n    updated_by =\r\n      current_user_id,\r\n\r\n    updated_at =\r\n      published_at_value\r\n\r\n  where id =\r\n    target_period.id\r\n\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status,\r\n\r\n    'totalDays',\r\n      total_days_count,\r\n\r\n    'assignedDays',\r\n      assigned_days_count,\r\n\r\n    'unassignedDays',\r\n      unassigned_days_count,\r\n\r\n    'publishedAt',\r\n      target_period.published_at,\r\n\r\n    'alreadyPublished',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
