    "function_signature": "publish_morning_driver_schedule(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.publish_morning_driver_schedule(requested_schedule_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_schedule_periods%rowtype;\r\n\r\n  minimum_unfilled integer := 0;\r\n  recommendation_unfilled integer := 0;\r\n  published_at_value timestamptz := now();\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_schedule.edit'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_schedule_periods period\r\n  where period.id = requested_schedule_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status = 'published' then\r\n    return jsonb_build_object(\r\n      'schedulePeriodId',\r\n        target_period.id,\r\n      'status',\r\n        target_period.status,\r\n      'publishedAt',\r\n        target_period.published_at,\r\n      'recommendationWarnings',\r\n        0,\r\n      'alreadyPublished',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status <> 'draft' then\r\n    raise exception 'only draft schedules can be published';\r\n  end if;\r\n\r\n  select count(*)\r\n  into minimum_unfilled\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id = target_period.id\r\n    and assignment.assignment_slot = 1\r\n    and assignment.assigned_user_id is null;\r\n\r\n  if minimum_unfilled > 0 then\r\n    raise exception 'minimum morning driver staffing is incomplete';\r\n  end if;\r\n\r\n  select count(*)\r\n  into recommendation_unfilled\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.schedule_period_id = target_period.id\r\n    and assignment.assignment_slot > 1\r\n    and assignment.assigned_user_id is null;\r\n\r\n  update public.morning_driver_schedule_periods\r\n  set\r\n    status = 'published',\r\n    published_at = published_at_value,\r\n    updated_by = current_user_id,\r\n    updated_at = published_at_value\r\n  where id = target_period.id\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      target_period.id,\r\n    'status',\r\n      target_period.status,\r\n    'publishedAt',\r\n      target_period.published_at,\r\n    'recommendationWarnings',\r\n      recommendation_unfilled,\r\n    'alreadyPublished',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "publish_schedule_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.publish_schedule_period(requested_schedule_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_profile\r\n    public.profiles%rowtype;\r\n\r\n  target_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  user_permissions text[];\r\n\r\n  total_shift_count integer;\r\n  unassigned_shift_count integer;\r\n  invalid_shift_count integer;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  select *\r\n  into current_profile\r\n  from public.profiles\r\n  where id =\r\n    current_user_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'profile not found';\r\n  end if;\r\n\r\n  if not current_profile.is_active then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  user_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'schedule.edit' =\r\n    any(user_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_period_id\r\n    is null\r\n  then\r\n    raise exception\r\n      'schedule period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.schedule_periods\r\n  where id =\r\n    requested_schedule_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status =\r\n    'archived'::public.schedule_period_status\r\n  then\r\n    raise exception\r\n      'archived schedule cannot be published';\r\n  end if;\r\n\r\n  if target_period.status =\r\n    'published'::public.schedule_period_status\r\n  then\r\n    return jsonb_build_object(\r\n      'schedulePeriodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'status',\r\n        target_period.status::text,\r\n\r\n      'publishedAt',\r\n        target_period.published_at,\r\n\r\n      'publishedBy',\r\n        null,\r\n\r\n      'publishedShifts',\r\n        null,\r\n\r\n      'alreadyPublished',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  if target_period.status\r\n    not in (\r\n      'draft'::public.schedule_period_status,\r\n      'scheduling'::public.schedule_period_status\r\n    )\r\n  then\r\n    raise exception\r\n      'schedule is not ready for publication';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer,\r\n\r\n    count(*) filter (\r\n      where assigned_user_id\r\n        is null\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where\r\n        starts_at is null\r\n        or ends_at is null\r\n        or ends_at <= starts_at\r\n    )::integer\r\n\r\n  into\r\n    total_shift_count,\r\n    unassigned_shift_count,\r\n    invalid_shift_count\r\n\r\n  from public.schedule_shifts\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  if total_shift_count = 0 then\r\n    raise exception\r\n      'schedule has no shifts';\r\n  end if;\r\n\r\n  if unassigned_shift_count > 0 then\r\n    raise exception\r\n      'schedule contains unassigned shifts';\r\n  end if;\r\n\r\n  if invalid_shift_count > 0 then\r\n    raise exception\r\n      'schedule contains invalid shifts';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n\r\n    from public.schedule_shifts\r\n      first_shift\r\n\r\n    join public.schedule_shifts\r\n      second_shift\r\n\r\n      on second_shift.period_id =\r\n        first_shift.period_id\r\n\r\n      and second_shift.assigned_user_id =\r\n        first_shift.assigned_user_id\r\n\r\n      and second_shift.id >\r\n        first_shift.id\r\n\r\n      and second_shift.starts_at <\r\n        first_shift.ends_at\r\n\r\n      and second_shift.ends_at >\r\n        first_shift.starts_at\r\n\r\n    where first_shift.period_id =\r\n      target_period.id\r\n\r\n      and first_shift.assigned_user_id\r\n        is not null\r\n  ) then\r\n    raise exception\r\n      'schedule contains overlapping shifts';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n\r\n    from public.schedule_shifts\r\n      first_shift\r\n\r\n    join public.schedule_shifts\r\n      second_shift\r\n\r\n      on second_shift.period_id =\r\n        first_shift.period_id\r\n\r\n      and second_shift.assigned_user_id =\r\n        first_shift.assigned_user_id\r\n\r\n      and second_shift.starts_at =\r\n        first_shift.ends_at\r\n\r\n    where first_shift.period_id =\r\n      target_period.id\r\n\r\n      and first_shift.assigned_user_id\r\n        is not null\r\n  ) then\r\n    raise exception\r\n      'schedule contains consecutive shifts';\r\n  end if;\r\n\r\n  update public.schedule_periods\r\n  set\r\n    status =\r\n      'published'::public.schedule_period_status,\r\n\r\n    published_at =\r\n      now(),\r\n\r\n    approved_by =\r\n      current_user_id,\r\n\r\n    approved_at =\r\n      coalesce(\r\n        approved_at,\r\n        now()\r\n      ),\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_period.id\r\n\r\n  returning *\r\n  into target_period;\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      target_period.id,\r\n\r\n    'year',\r\n      target_period.year,\r\n\r\n    'month',\r\n      target_period.month,\r\n\r\n    'status',\r\n      target_period.status::text,\r\n\r\n    'publishedAt',\r\n      target_period.published_at,\r\n\r\n    'publishedBy',\r\n      current_user_id,\r\n\r\n    'publishedShifts',\r\n      total_shift_count,\r\n\r\n    'alreadyPublished',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "rebuild_availability_period_slots(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.rebuild_availability_period_slots(requested_period_id uuid)\n RETURNS TABLE(period_id uuid, created_slots integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  target_year integer;\r\n  target_month integer;\r\n  target_status text;\r\n  first_day_of_month date;\r\n  last_day_of_month date;\r\n  created_shift_count integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.manage'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to manage availability periods';\r\n  end if;\r\n\r\n  select\r\n    period.year,\r\n    period.month,\r\n    period.status\r\n  into\r\n    target_year,\r\n    target_month,\r\n    target_status\r\n  from public.availability_periods period\r\n  where period.id =\r\n    requested_period_id;\r\n\r\n  if target_year is null then\r\n    raise exception\r\n      'Availability period was not found';\r\n  end if;\r\n\r\n  if target_status <> 'draft' then\r\n    raise exception\r\n      'Only draft availability periods can be rebuilt';\r\n  end if;\r\n\r\n  /*\r\n   * לא בונים מחדש חודש לאחר שמוקדנים\r\n   * כבר התחילו לשמור אילוצים.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from public.dispatcher_availability availability\r\n    where availability.period_id =\r\n      requested_period_id\r\n  ) then\r\n    raise exception\r\n      'Availability period already contains dispatcher responses';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.availability_submissions submission\r\n    where submission.period_id =\r\n      requested_period_id\r\n      and (\r\n        submission.available_count > 0\r\n        or submission.unavailable_count > 0\r\n        or submission.submitted_at is not null\r\n      )\r\n  ) then\r\n    raise exception\r\n      'Availability period already contains submission data';\r\n  end if;\r\n\r\n  first_day_of_month :=\r\n    make_date(\r\n      target_year,\r\n      target_month,\r\n      1\r\n    );\r\n\r\n  last_day_of_month :=\r\n    (\r\n      first_day_of_month\r\n      + interval '1 month'\r\n      - interval '1 day'\r\n    )::date;\r\n\r\n  delete from\r\n    public.availability_shift_slots\r\n  where availability_shift_slots.period_id =\r\n    requested_period_id;\r\n\r\n  with month_dates as (\r\n    select\r\n      generated_date::date\r\n        as shift_date,\r\n\r\n      extract(\r\n        dow from generated_date\r\n      )::integer\r\n        as weekday_number\r\n\r\n    from generate_series(\r\n      first_day_of_month,\r\n      last_day_of_month,\r\n      interval '1 day'\r\n    ) generated_date\r\n  ),\r\n\r\n  classified_dates as (\r\n    select\r\n      month_date.shift_date,\r\n      month_date.weekday_number,\r\n\r\n      case\r\n        when month_date.weekday_number = 0\r\n          then 'ראשון'\r\n        when month_date.weekday_number = 1\r\n          then 'שני'\r\n        when month_date.weekday_number = 2\r\n          then 'שלישי'\r\n        when month_date.weekday_number = 3\r\n          then 'רביעי'\r\n        when month_date.weekday_number = 4\r\n          then 'חמישי'\r\n        when month_date.weekday_number = 5\r\n          then 'שישי'\r\n        when month_date.weekday_number = 6\r\n          then 'שבת'\r\n      end\r\n        as weekday_name,\r\n\r\n      coalesce(\r\n        special_day.schedule_type,\r\n\r\n        case\r\n          when month_date.weekday_number = 5\r\n            then 'friday'\r\n          when month_date.weekday_number = 6\r\n            then 'saturday'\r\n          else 'weekday'\r\n        end\r\n      )\r\n        as effective_schedule_type,\r\n\r\n      special_day.event_name\r\n        as holiday_name\r\n\r\n    from month_dates month_date\r\n\r\n    left join lateral (\r\n      select\r\n        calendar_day.schedule_type,\r\n        calendar_day.event_name\r\n\r\n      from public.calendar_special_days\r\n        calendar_day\r\n\r\n      where calendar_day.event_date =\r\n        month_date.shift_date\r\n\r\n      /*\r\n       * רשומה ידנית גוברת על Hebcal.\r\n       * סדר הסוגים משמש הגנה במקרה\r\n       * של יותר מרשומה אחת לאותו יום.\r\n       */\r\n      order by\r\n        case\r\n          when calendar_day.source_name =\r\n            'manual'\r\n            then 0\r\n          else 1\r\n        end,\r\n\r\n        case calendar_day.schedule_type\r\n          when 'holiday_full'\r\n            then 1\r\n          when 'holiday_end'\r\n            then 2\r\n          when 'holiday_eve'\r\n            then 3\r\n          when 'chol_hamoed'\r\n            then 4\r\n          else 5\r\n        end\r\n\r\n      limit 1\r\n    ) special_day\r\n      on true\r\n  ),\r\n\r\n  generated_shifts as (\r\n    -- =====================================================\r\n    -- יום חול וחול המועד\r\n    -- =====================================================\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '16:00'\r\n        as start_time,\r\n      time '23:00'\r\n        as end_time,\r\n      false\r\n        as ends_next_day,\r\n      date_row.effective_schedule_type\r\n        as schedule_type,\r\n      date_row.holiday_name,\r\n      false\r\n        as is_premium,\r\n      1\r\n        as sort_order\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type\r\n      in (\r\n        'weekday',\r\n        'chol_hamoed'\r\n      )\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '23:00',\r\n      time '06:00',\r\n      true,\r\n      date_row.effective_schedule_type,\r\n      date_row.holiday_name,\r\n      false,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type\r\n      in (\r\n        'weekday',\r\n        'chol_hamoed'\r\n      )\r\n\r\n    -- =====================================================\r\n    -- שישי רגיל\r\n    -- =====================================================\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '06:00',\r\n      time '14:00',\r\n      false,\r\n      'friday',\r\n      date_row.holiday_name,\r\n      false,\r\n      1\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'friday'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '14:00',\r\n      time '22:00',\r\n      false,\r\n      'friday',\r\n      date_row.holiday_name,\r\n      true,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'friday'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '22:00',\r\n      time '06:00',\r\n      true,\r\n      'friday',\r\n      date_row.holiday_name,\r\n      true,\r\n      3\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'friday'\r\n\r\n    -- =====================================================\r\n    -- שבת רגילה\r\n    -- =====================================================\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '06:00',\r\n      time '14:00',\r\n      false,\r\n      'saturday',\r\n      date_row.holiday_name,\r\n      true,\r\n      1\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'saturday'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '14:00',\r\n      time '22:00',\r\n      false,\r\n      'saturday',\r\n      date_row.holiday_name,\r\n      true,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'saturday'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '22:00',\r\n      time '06:00',\r\n      true,\r\n      'saturday',\r\n      date_row.holiday_name,\r\n      false,\r\n      3\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'saturday'\r\n\r\n    -- =====================================================\r\n    -- ערב חג\r\n    -- =====================================================\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '06:00',\r\n      time '14:00',\r\n      false,\r\n      'holiday_eve',\r\n      date_row.holiday_name,\r\n      false,\r\n      1\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_eve'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '14:00',\r\n      time '22:00',\r\n      false,\r\n      'holiday_eve',\r\n      date_row.holiday_name,\r\n      true,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_eve'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '22:00',\r\n      time '06:00',\r\n      true,\r\n      'holiday_eve',\r\n      date_row.holiday_name,\r\n      true,\r\n      3\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_eve'\r\n\r\n    -- =====================================================\r\n    -- חג מלא\r\n    -- =====================================================\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '06:00',\r\n      time '14:00',\r\n      false,\r\n      'holiday_full',\r\n      date_row.holiday_name,\r\n      true,\r\n      1\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_full'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '14:00',\r\n      time '22:00',\r\n      false,\r\n      'holiday_full',\r\n      date_row.holiday_name,\r\n      true,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_full'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '22:00',\r\n      time '06:00',\r\n      true,\r\n      'holiday_full',\r\n      date_row.holiday_name,\r\n      true,\r\n      3\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_full'\r\n\r\n    -- =====================================================\r\n    -- מוצאי / סיום חג\r\n    -- =====================================================\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '06:00',\r\n      time '14:00',\r\n      false,\r\n      'holiday_end',\r\n      date_row.holiday_name,\r\n      true,\r\n      1\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_end'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '14:00',\r\n      time '22:00',\r\n      false,\r\n      'holiday_end',\r\n      date_row.holiday_name,\r\n      true,\r\n      2\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_end'\r\n\r\n    union all\r\n\r\n    select\r\n      date_row.shift_date,\r\n      date_row.weekday_number,\r\n      date_row.weekday_name,\r\n      time '22:00',\r\n      time '06:00',\r\n      true,\r\n      'holiday_end',\r\n      date_row.holiday_name,\r\n      false,\r\n      3\r\n\r\n    from classified_dates date_row\r\n    where date_row.effective_schedule_type =\r\n      'holiday_end'\r\n  )\r\n\r\n  insert into\r\n    public.availability_shift_slots (\r\n      period_id,\r\n      shift_date,\r\n      weekday_number,\r\n      weekday_name,\r\n      start_time,\r\n      end_time,\r\n      ends_next_day,\r\n      schedule_type,\r\n      holiday_name,\r\n      is_premium,\r\n      sort_order\r\n    )\r\n  select\r\n    requested_period_id,\r\n    generated_shift.shift_date,\r\n    generated_shift.weekday_number,\r\n    generated_shift.weekday_name,\r\n    generated_shift.start_time,\r\n    generated_shift.end_time,\r\n    generated_shift.ends_next_day,\r\n    generated_shift.schedule_type,\r\n    generated_shift.holiday_name,\r\n    generated_shift.is_premium,\r\n    generated_shift.sort_order\r\n\r\n  from generated_shifts\r\n    generated_shift\r\n\r\n  order by\r\n    generated_shift.shift_date,\r\n    generated_shift.sort_order;\r\n\r\n  get diagnostics\r\n    created_shift_count =\r\n      row_count;\r\n\r\n  update public.availability_periods\r\n  set\r\n    updated_by =\r\n      current_user_id,\r\n    updated_at =\r\n      now()\r\n  where id =\r\n    requested_period_id;\r\n\r\n  return query\r\n  select\r\n    requested_period_id,\r\n    created_shift_count;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "record_driver_schedule_assignment_change()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.record_driver_schedule_assignment_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  resolved_change_type\r\n    public.driver_assignment_change_type;\r\nbegin\r\n  if old.assigned_user_id\r\n    is not distinct from\r\n    new.assigned_user_id\r\n  then\r\n    return new;\r\n  end if;\r\n\r\n  resolved_change_type :=\r\n    case\r\n      when new.assigned_user_id is null then\r\n        'clear_assignment'\r\n          ::public.driver_assignment_change_type\r\n\r\n      when new.assignment_source = 'automatic' then\r\n        'automatic_assignment'\r\n          ::public.driver_assignment_change_type\r\n\r\n      when new.assignment_source = 'swap' then\r\n        'swap'\r\n          ::public.driver_assignment_change_type\r\n\r\n      when new.assignment_source = 'import' then\r\n        'import'\r\n          ::public.driver_assignment_change_type\r\n\r\n      when old.assigned_user_id is null then\r\n        'initial_assignment'\r\n          ::public.driver_assignment_change_type\r\n\r\n      else\r\n        'manual_edit'\r\n          ::public.driver_assignment_change_type\r\n    end;\r\n\r\n  insert into\r\n    public.driver_schedule_assignment_history (\r\n      schedule_day_id,\r\n      previous_user_id,\r\n      new_user_id,\r\n      change_type,\r\n      changed_by\r\n    )\r\n  values (\r\n    new.id,\r\n    old.assigned_user_id,\r\n    new.assigned_user_id,\r\n    resolved_change_type,\r\n    auth.uid()\r\n  );\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "record_schedule_assignment_change()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.record_schedule_assignment_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  resolved_change_type public.assignment_change_type;\r\nbegin\r\n  if old.assigned_user_id is not distinct from new.assigned_user_id then\r\n    return new;\r\n  end if;\r\n\r\n  resolved_change_type :=\r\n    case\r\n      when new.assigned_user_id is null then\r\n        'clear_assignment'::public.assignment_change_type\r\n\r\n      when old.assigned_user_id is null\r\n        and new.assignment_source = 'automatic' then\r\n        'automatic_assignment'::public.assignment_change_type\r\n\r\n      when old.assigned_user_id is null\r\n        and new.assignment_source = 'import' then\r\n        'import'::public.assignment_change_type\r\n\r\n      when old.assigned_user_id is null\r\n        and new.assignment_source = 'shift_swap' then\r\n        'shift_swap'::public.assignment_change_type\r\n\r\n      when old.assigned_user_id is null then\r\n        'initial_assignment'::public.assignment_change_type\r\n\r\n      when new.assignment_source = 'automatic' then\r\n        'automatic_assignment'::public.assignment_change_type\r\n\r\n      when new.assignment_source = 'import' then\r\n        'import'::public.assignment_change_type\r\n\r\n      when new.assignment_source = 'shift_swap' then\r\n        'shift_swap'::public.assignment_change_type\r\n\r\n      else\r\n        'manual_edit'::public.assignment_change_type\r\n    end;\r\n\r\n  insert into public.schedule_assignment_history (\r\n    shift_id,\r\n    previous_user_id,\r\n    new_user_id,\r\n    change_type,\r\n    changed_by\r\n  )\r\n  values (\r\n    new.id,\r\n    old.assigned_user_id,\r\n    new.assigned_user_id,\r\n    resolved_change_type,\r\n    (select auth.uid())\r\n  );\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "record_user_login()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.record_user_login()\n RETURNS timestamp with time zone\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  login_time timestamptz := now();\r\n  affected_rows integer;\r\nbegin\r\n  if auth.uid() is null then\r\n    raise exception 'User is not authenticated';\r\n  end if;\r\n\r\n  update public.profiles\r\n  set\r\n    last_login_at = login_time,\r\n    updated_at = login_time\r\n  where id = auth.uid();\r\n\r\n  get diagnostics affected_rows = row_count;\r\n\r\n  if affected_rows = 0 then\r\n    raise exception 'User profile was not found';\r\n  end if;\r\n\r\n  return login_time;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "register_push_subscription(text,text,text,text,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.register_push_subscription(requested_endpoint text, requested_p256dh_key text, requested_auth_key text, requested_user_agent text DEFAULT NULL::text, requested_device_name text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  subscription_id uuid;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  if nullif(\r\n    trim(\r\n      coalesce(\r\n        requested_endpoint,\r\n        ''\r\n      )\r\n    ),\r\n    ''\r\n  ) is null then\r\n    raise exception\r\n      'push endpoint is required';\r\n  end if;\r\n\r\n  if nullif(\r\n    trim(\r\n      coalesce(\r\n        requested_p256dh_key,\r\n        ''\r\n      )\r\n    ),\r\n    ''\r\n  ) is null then\r\n    raise exception\r\n      'p256dh key is required';\r\n  end if;\r\n\r\n  if nullif(\r\n    trim(\r\n      coalesce(\r\n        requested_auth_key,\r\n        ''\r\n      )\r\n    ),\r\n    ''\r\n  ) is null then\r\n    raise exception\r\n      'auth key is required';\r\n  end if;\r\n\r\n  insert into public.push_subscriptions (\r\n    user_id,\r\n    endpoint,\r\n    p256dh_key,\r\n    auth_key,\r\n    user_agent,\r\n    device_name,\r\n    is_active,\r\n    last_used_at\r\n  )\r\n  values (\r\n    current_user_id,\r\n    requested_endpoint,\r\n    requested_p256dh_key,\r\n    requested_auth_key,\r\n    requested_user_agent,\r\n    requested_device_name,\r\n    true,\r\n    now()\r\n  )\r\n\r\n  on conflict (endpoint)\r\n  do update\r\n  set\r\n    user_id =\r\n      current_user_id,\r\n\r\n    p256dh_key =\r\n      excluded.p256dh_key,\r\n\r\n    auth_key =\r\n      excluded.auth_key,\r\n\r\n    user_agent =\r\n      excluded.user_agent,\r\n\r\n    device_name =\r\n      excluded.device_name,\r\n\r\n    is_active =\r\n      true,\r\n\r\n    last_used_at =\r\n      now()\r\n\r\n  returning id\r\n  into subscription_id;\r\n\r\n  return subscription_id;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "reopen_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.reopen_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  actor_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_period public.availability_periods%rowtype;\r\n  reopened_at timestamptz := now();\r\nbegin\r\n  if actor_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = actor_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception 'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.availability_periods\r\n  where id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'closed' then\r\n    raise exception 'only closed availability periods can be reopened';\r\n  end if;\r\n\r\n  update public.availability_periods\r\n  set\r\n    status = 'open',\r\n    opened_at = reopened_at,\r\n    closed_at = null,\r\n    updated_by = actor_user_id,\r\n    updated_at = reopened_at\r\n  where id = target_period.id;\r\n\r\n  update public.availability_submissions\r\n  set\r\n    status = 'reopened',\r\n    updated_at = reopened_at\r\n  where period_id = target_period.id\r\n    and status = 'submitted';\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n    metadata\r\n  )\r\n  values (\r\n    actor_user_id,\r\n    'availability.period.reopened',\r\n    'availability_period',\r\n    target_period.id,\r\n    'תקופת אילוצי מוקדנים נפתחה מחדש',\r\n    jsonb_build_object(\r\n      'year', target_period.year,\r\n      'month', target_period.month\r\n    )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'periodId', target_period.id,\r\n    'periodStatus', 'open',\r\n    'openedAt', reopened_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "reopen_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.reopen_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  reopened_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  updated_submissions integer := 0;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into reopened_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if reopened_period.status::text <>\r\n      'closed'\r\n  then\r\n    raise exception\r\n      'only closed driver availability periods can be reopened';\r\n  end if;\r\n\r\n  /*\r\n   * Once a schedule already exists for this availability period,\r\n   * reopening constraints would make the schedule inconsistent.\r\n   * Delete/rebuild the schedule first if the period must be reopened.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_periods\r\n      schedule_period\r\n    where schedule_period.availability_period_id =\r\n      requested_period_id\r\n  ) then\r\n    raise exception\r\n      'driver availability period already has a schedule';\r\n  end if;\r\n\r\n  update public.driver_availability_periods\r\n  set\r\n    status =\r\n      'open',\r\n\r\n    closed_at =\r\n      null,\r\n\r\n    opened_at =\r\n      coalesce(\r\n        opened_at,\r\n        now()\r\n      ),\r\n\r\n    updated_by =\r\n      current_user_id,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    requested_period_id\r\n\r\n  returning *\r\n  into reopened_period;\r\n\r\n  update public.driver_availability_submissions\r\n  set\r\n    status =\r\n      'reopened',\r\n\r\n    submitted_at =\r\n      null,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where period_id =\r\n      requested_period_id\r\n    and status::text =\r\n      'submitted';\r\n\r\n  get diagnostics\r\n    updated_submissions =\r\n      row_count;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'driver_availability_period_reopened'\r\n        ::public.audit_action_type,\r\n\r\n    requested_target_user_id :=\r\n      null,\r\n\r\n    requested_summary :=\r\n      'Driver availability period reopened',\r\n\r\n    requested_old_values :=\r\n      jsonb_build_object(\r\n        'status',\r\n        'closed'\r\n      ),\r\n\r\n    requested_new_values :=\r\n      jsonb_build_object(\r\n        'status',\r\n        'open'\r\n      ),\r\n\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'periodId',\r\n          reopened_period.id,\r\n\r\n        'year',\r\n          reopened_period.year,\r\n\r\n        'month',\r\n          reopened_period.month,\r\n\r\n        'reopenedSubmissions',\r\n          updated_submissions\r\n      )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      reopened_period.id,\r\n\r\n    'year',\r\n      reopened_period.year,\r\n\r\n    'month',\r\n      reopened_period.month,\r\n\r\n    'status',\r\n      reopened_period.status,\r\n\r\n    'openedAt',\r\n      reopened_period.opened_at,\r\n\r\n    'reopenedSubmissions',\r\n      updated_submissions\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "reopen_morning_driver_availability_period(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.reopen_morning_driver_availability_period(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  actor_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_period public.morning_driver_availability_periods%rowtype;\r\n  reopened_at timestamptz := now();\r\nbegin\r\n  if actor_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = actor_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception 'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods\r\n  where id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'closed' then\r\n    raise exception 'only closed morning driver availability periods can be reopened';\r\n  end if;\r\n\r\n  update public.morning_driver_availability_periods\r\n  set\r\n    status = 'open',\r\n    opened_at = reopened_at,\r\n    closed_at = null,\r\n    updated_by = actor_user_id,\r\n    updated_at = reopened_at\r\n  where id = target_period.id;\r\n\r\n  update public.morning_driver_availability_submissions\r\n  set\r\n    status = 'reopened',\r\n    updated_at = reopened_at\r\n  where period_id = target_period.id\r\n    and status = 'submitted';\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n    metadata\r\n  )\r\n  values (\r\n    actor_user_id,\r\n    'morning_driver_availability.period.reopened',\r\n    'morning_driver_availability_period',\r\n    target_period.id,\r\n    'תקופת אילוצי כונני בוקר נפתחה מחדש',\r\n    jsonb_build_object(\r\n      'year', target_period.year,\r\n      'month', target_period.month\r\n    )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'periodId', target_period.id,\r\n    'year', target_period.year,\r\n    'month', target_period.month,\r\n    'status', 'open',\r\n    'openedAt', reopened_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "reopen_morning_driver_availability_submission(uuid,uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.reopen_morning_driver_availability_submission(requested_period_id uuid, requested_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.morning_driver_availability_periods%rowtype;\r\n\r\n  target_submission\r\n    public.morning_driver_availability_submissions%rowtype;\r\n\r\n  reopened_at_value timestamptz := now();\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.manage'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception 'period id is required';\r\n  end if;\r\n\r\n  if requested_user_id is null then\r\n    raise exception 'user id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception 'only open periods support reopening submissions';\r\n  end if;\r\n\r\n  select *\r\n  into target_submission\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.user_id = requested_user_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability submission not found';\r\n  end if;\r\n\r\n  if target_submission.status <> 'submitted' then\r\n    raise exception 'only submitted availability can be reopened';\r\n  end if;\r\n\r\n  update public.morning_driver_availability_submissions\r\n  set\r\n    status = 'reopened',\r\n    submitted_at = null,\r\n    updated_at = reopened_at_value\r\n  where id = target_submission.id\r\n  returning *\r\n  into target_submission;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'userId',\r\n      requested_user_id,\r\n\r\n    'submissionId',\r\n      target_submission.id,\r\n\r\n    'status',\r\n      target_submission.status,\r\n\r\n    'reopenedAt',\r\n      reopened_at_value\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "respond_to_shift_swap_request(uuid,boolean,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.respond_to_shift_swap_request(requested_request_id uuid, requested_approve boolean, requested_rejection_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  request_row public.shift_swap_requests%rowtype;\r\n  validation_result jsonb;\r\n  next_status text;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'לא נמצאה התחברות פעילה.';\r\n  end if;\r\n\r\n  if not public.current_user_has_permission('shift_swaps.view') then\r\n    raise exception 'אין לך הרשאה לטפל בבקשות להחלפת משמרות.';\r\n  end if;\r\n\r\n  select *\r\n  into request_row\r\n  from public.shift_swap_requests\r\n  where id = requested_request_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'בקשת ההחלפה לא נמצאה.';\r\n  end if;\r\n\r\n  if request_row.counterparty_user_id <> current_user_id then\r\n    raise exception 'רק המוקדן שהתבקש להחליף יכול להגיב לבקשה.';\r\n  end if;\r\n\r\n  if request_row.status <> 'pending_counterparty' then\r\n    raise exception 'הבקשה אינה ממתינה עוד לאישור המוקדן.';\r\n  end if;\r\n\r\n  if requested_approve then\r\n    validation_result := public.validate_shift_swap_final_state(\r\n      request_row.swap_type,\r\n      request_row.requester_user_id,\r\n      request_row.counterparty_user_id,\r\n      request_row.requester_shift_id,\r\n      request_row.counterparty_shift_id\r\n    );\r\n\r\n    if not coalesce((validation_result ->> 'valid')::boolean, false) then\r\n      raise exception '%', validation_result ->> 'message';\r\n    end if;\r\n\r\n    next_status := 'pending_manager';\r\n  else\r\n    next_status := 'rejected_by_counterparty';\r\n  end if;\r\n\r\n  update public.shift_swap_requests\r\n  set\r\n    status = next_status,\r\n    counterparty_responded_at = now(),\r\n    rejection_reason = case\r\n      when requested_approve then null\r\n      else nullif(trim(coalesce(requested_rejection_reason, '')), '')\r\n    end\r\n  where id = request_row.id\r\n  returning * into request_row;\r\n\r\n  return jsonb_build_object(\r\n    'id', request_row.id,\r\n    'status', request_row.status,\r\n    'requesterUserId', request_row.requester_user_id,\r\n    'counterpartyUserId', request_row.counterparty_user_id,\r\n    'counterpartyRespondedAt', request_row.counterparty_responded_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "review_shift_swap_request(uuid,boolean,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.review_shift_swap_request(requested_request_id uuid, requested_approve boolean, requested_rejection_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  request_row public.shift_swap_requests%rowtype;\r\n  requester_shift public.schedule_shifts%rowtype;\r\n  counterparty_shift public.schedule_shifts%rowtype;\r\n  validation_result jsonb;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'לא נמצאה התחברות פעילה.';\r\n  end if;\r\n\r\n  if not public.current_user_has_permission('shift_swaps.approve') then\r\n    raise exception 'אין לך הרשאה לאשר או לדחות בקשות החלפה.';\r\n  end if;\r\n\r\n  select *\r\n  into request_row\r\n  from public.shift_swap_requests\r\n  where id = requested_request_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'בקשת ההחלפה לא נמצאה.';\r\n  end if;\r\n\r\n  if request_row.status <> 'pending_manager' then\r\n    raise exception 'הבקשה אינה ממתינה לאישור מנהל.';\r\n  end if;\r\n\r\n  if not requested_approve then\r\n    update public.shift_swap_requests\r\n    set\r\n      status = 'rejected_by_manager',\r\n      manager_user_id = current_user_id,\r\n      manager_reviewed_at = now(),\r\n      rejection_reason = nullif(trim(coalesce(requested_rejection_reason, '')), '')\r\n    where id = request_row.id\r\n    returning * into request_row;\r\n\r\n    return jsonb_build_object(\r\n      'id', request_row.id,\r\n      'status', request_row.status,\r\n      'requesterUserId', request_row.requester_user_id,\r\n      'counterpartyUserId', request_row.counterparty_user_id,\r\n      'managerUserId', request_row.manager_user_id,\r\n      'managerReviewedAt', request_row.manager_reviewed_at\r\n    );\r\n  end if;\r\n\r\n  select *\r\n  into requester_shift\r\n  from public.schedule_shifts\r\n  where id = request_row.requester_shift_id\r\n  for update;\r\n\r\n  if not found\r\n    or requester_shift.assigned_user_id is distinct from request_row.requester_user_id then\r\n    raise exception 'השיבוץ המקורי השתנה מאז יצירת הבקשה. יש ליצור בקשה חדשה.';\r\n  end if;\r\n\r\n  if requester_shift.starts_at <= now() then\r\n    raise exception 'לא ניתן לאשר החלפה לאחר שהמשמרת התחילה.';\r\n  end if;\r\n\r\n  if request_row.swap_type = 'two_way' then\r\n    select *\r\n    into counterparty_shift\r\n    from public.schedule_shifts\r\n    where id = request_row.counterparty_shift_id\r\n    for update;\r\n\r\n    if not found\r\n      or counterparty_shift.assigned_user_id is distinct from request_row.counterparty_user_id then\r\n      raise exception 'השיבוץ של המוקדן השני השתנה מאז יצירת הבקשה. יש ליצור בקשה חדשה.';\r\n    end if;\r\n\r\n    if counterparty_shift.starts_at <= now() then\r\n      raise exception 'לא ניתן לאשר החלפה לאחר שאחת המשמרות התחילה.';\r\n    end if;\r\n  end if;\r\n\r\n  validation_result := public.validate_shift_swap_final_state(\r\n    request_row.swap_type,\r\n    request_row.requester_user_id,\r\n    request_row.counterparty_user_id,\r\n    request_row.requester_shift_id,\r\n    request_row.counterparty_shift_id\r\n  );\r\n\r\n  if not coalesce((validation_result ->> 'valid')::boolean, false) then\r\n    raise exception '%', validation_result ->> 'message';\r\n  end if;\r\n\r\n  update public.schedule_shifts\r\n  set\r\n    assigned_user_id = request_row.counterparty_user_id,\r\n    assignment_source = 'shift_swap'\r\n  where id = request_row.requester_shift_id;\r\n\r\n  if request_row.swap_type = 'two_way' then\r\n    update public.schedule_shifts\r\n    set\r\n      assigned_user_id = request_row.requester_user_id,\r\n      assignment_source = 'shift_swap'\r\n    where id = request_row.counterparty_shift_id;\r\n  end if;\r\n\r\n  update public.shift_swap_requests\r\n  set\r\n    status = 'approved',\r\n    manager_user_id = current_user_id,\r\n    manager_reviewed_at = now(),\r\n    rejection_reason = null\r\n  where id = request_row.id\r\n  returning * into request_row;\r\n\r\n  return jsonb_build_object(\r\n    'id', request_row.id,\r\n    'status', request_row.status,\r\n    'swapType', request_row.swap_type,\r\n    'requesterUserId', request_row.requester_user_id,\r\n    'counterpartyUserId', request_row.counterparty_user_id,\r\n    'requesterShiftId', request_row.requester_shift_id,\r\n    'counterpartyShiftId', request_row.counterparty_shift_id,\r\n    'managerUserId', request_row.manager_user_id,\r\n    'managerReviewedAt', request_row.manager_reviewed_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "save_my_driver_availability(uuid,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.save_my_driver_availability(requested_period_id uuid, requested_entries jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  saved_entries_count integer := 0;\r\n\r\n  v_available_count integer := 0;\r\n  v_unavailable_count integer := 0;\r\n\r\n  total_period_days integer := 0;\r\n\r\n  invalid_entries_count integer := 0;\r\n\r\n  saved_at timestamptz :=\r\n    now();\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  if requested_entries is null then\r\n    raise exception\r\n      'driver availability entries are required';\r\n  end if;\r\n\r\n  if jsonb_typeof(\r\n    requested_entries\r\n  ) <> 'array' then\r\n    raise exception\r\n      'driver availability entries must be an array';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_availability_periods\r\n  where id =\r\n    requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception\r\n      'driver availability period is not open';\r\n  end if;\r\n\r\n  if (\r\n    target_period.submission_deadline\r\n      is not null\r\n    and now() >\r\n      target_period.submission_deadline\r\n  ) then\r\n    raise exception\r\n      'driver availability submission deadline has passed';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_availability_submissions\r\n    where period_id =\r\n      target_period.id\r\n      and user_id =\r\n        current_user_id\r\n      and status =\r\n        'submitted'\r\n  ) then\r\n    raise exception\r\n      'driver availability was already submitted';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into total_period_days\r\n  from public.driver_availability_days\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  if total_period_days = 0 then\r\n    raise exception\r\n      'driver availability period has no days';\r\n  end if;\r\n\r\n  with supplied_entries as (\r\n    select\r\n      nullif(\r\n        trim(\r\n          entry_row.value\r\n            ->> 'dayId'\r\n        ),\r\n        ''\r\n      )::uuid\r\n        as day_id,\r\n\r\n      nullif(\r\n        trim(\r\n          entry_row.value\r\n            ->> 'availabilityStatus'\r\n        ),\r\n        ''\r\n      )\r\n        as availability_status,\r\n\r\n      nullif(\r\n        trim(\r\n          coalesce(\r\n            entry_row.value\r\n              ->> 'note',\r\n            ''\r\n          )\r\n        ),\r\n        ''\r\n      )\r\n        as note\r\n\r\n    from jsonb_array_elements(\r\n      requested_entries\r\n    ) as entry_row(value)\r\n  )\r\n\r\n  select\r\n    count(*)::integer\r\n\r\n  into invalid_entries_count\r\n\r\n  from supplied_entries\r\n  left join public.driver_availability_days\r\n    day_row\r\n    on day_row.id =\r\n      supplied_entries.day_id\r\n    and day_row.period_id =\r\n      target_period.id\r\n\r\n  where\r\n    supplied_entries.day_id is null\r\n\r\n    or day_row.id is null\r\n\r\n    or supplied_entries\r\n      .availability_status\r\n      not in (\r\n        'available',\r\n        'unavailable'\r\n      );\r\n\r\n  if invalid_entries_count > 0 then\r\n    raise exception\r\n      'one or more driver availability entries are invalid';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n\r\n    from (\r\n      select\r\n        nullif(\r\n          trim(\r\n            entry_row.value\r\n              ->> 'dayId'\r\n          ),\r\n          ''\r\n        )::uuid\r\n          as day_id,\r\n\r\n        count(*)::integer\r\n          as entry_count\r\n\r\n      from jsonb_array_elements(\r\n        requested_entries\r\n      ) as entry_row(value)\r\n\r\n      group by\r\n        nullif(\r\n          trim(\r\n            entry_row.value\r\n              ->> 'dayId'\r\n          ),\r\n          ''\r\n        )::uuid\r\n\r\n      having count(*) > 1\r\n    ) duplicate_entries\r\n  ) then\r\n    raise exception\r\n      'duplicate driver availability entries';\r\n  end if;\r\n\r\n  insert into public.driver_availability_submissions (\r\n    period_id,\r\n    user_id,\r\n    status,\r\n    last_saved_at,\r\n    available_count,\r\n    unavailable_count\r\n  )\r\n  values (\r\n    target_period.id,\r\n    current_user_id,\r\n    'draft',\r\n    saved_at,\r\n    0,\r\n    0\r\n  )\r\n  on conflict (\r\n    period_id,\r\n    user_id\r\n  )\r\n  do update set\r\n    status =\r\n      case\r\n        when public.driver_availability_submissions.status =\r\n          'reopened'\r\n        then\r\n          'reopened'\r\n        else\r\n          'draft'\r\n      end,\r\n\r\n    last_saved_at =\r\n      excluded.last_saved_at,\r\n\r\n    updated_at =\r\n      saved_at;\r\n\r\n  with supplied_entries as (\r\n    select\r\n      nullif(\r\n        trim(\r\n          entry_row.value\r\n            ->> 'dayId'\r\n        ),\r\n        ''\r\n      )::uuid\r\n        as day_id,\r\n\r\n      nullif(\r\n        trim(\r\n          entry_row.value\r\n            ->> 'availabilityStatus'\r\n        ),\r\n        ''\r\n      )\r\n        as availability_status,\r\n\r\n      nullif(\r\n        trim(\r\n          coalesce(\r\n            entry_row.value\r\n              ->> 'note',\r\n            ''\r\n          )\r\n        ),\r\n        ''\r\n      )\r\n        as note\r\n\r\n    from jsonb_array_elements(\r\n      requested_entries\r\n    ) as entry_row(value)\r\n  )\r\n\r\n  insert into public.driver_availability_entries (\r\n    period_id,\r\n    day_id,\r\n    user_id,\r\n    availability_status,\r\n    note\r\n  )\r\n  select\r\n    target_period.id,\r\n\r\n    supplied_entry.day_id,\r\n\r\n    current_user_id,\r\n\r\n    supplied_entry\r\n      .availability_status,\r\n\r\n    supplied_entry.note\r\n\r\n  from supplied_entries\r\n    supplied_entry\r\n\r\n  on conflict (\r\n    day_id,\r\n    user_id\r\n  )\r\n  do update set\r\n    availability_status =\r\n      excluded.availability_status,\r\n\r\n    note =\r\n      excluded.note,\r\n\r\n    updated_at =\r\n      saved_at;\r\n\r\n  get diagnostics\r\n    saved_entries_count =\r\n      row_count;\r\n\r\n  select\r\n    count(*) filter (\r\n      where availability_status =\r\n        'available'\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where availability_status =\r\n        'unavailable'\r\n    )::integer\r\n\r\n  into\r\n    v_available_count,\r\n    v_unavailable_count\r\n\r\n  from public.driver_availability_entries\r\n  where period_id =\r\n    target_period.id\r\n    and user_id =\r\n      current_user_id;\r\n\r\n  update public.driver_availability_submissions\r\n  set\r\n    available_count =\r\n      v_available_count,\r\n\r\n    unavailable_count =\r\n      v_unavailable_count,\r\n\r\n    last_saved_at =\r\n      saved_at,\r\n\r\n    updated_at =\r\n      saved_at\r\n\r\n  where period_id =\r\n    target_period.id\r\n    and user_id =\r\n      current_user_id;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'userId',\r\n      current_user_id,\r\n\r\n    'availableCount',\r\n      v_available_count,\r\n\r\n    'unavailableCount',\r\n      v_unavailable_count,\r\n\r\n    'unmarkedCount',\r\n      greatest(\r\n        total_period_days -\r\n        v_available_count -\r\n        v_unavailable_count,\r\n        0\r\n      ),\r\n\r\n    'savedEntries',\r\n      saved_entries_count,\r\n\r\n    'savedAt',\r\n      saved_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "save_my_morning_driver_availability(uuid,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.save_my_morning_driver_availability(requested_period_id uuid, requested_entries jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_period public.morning_driver_availability_periods%rowtype;\r\n  target_submission public.morning_driver_availability_submissions%rowtype;\r\n  requested_entry jsonb;\r\n  requested_shift_id uuid;\r\n  requested_status text;\r\n  requested_note text;\r\n  saved_entries integer := 0;\r\n  available_count integer := 0;\r\n  unavailable_count integer := 0;\r\n  unmarked_count integer := 0;\r\n  saved_at_value timestamptz := now();\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.view'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception 'period id is required';\r\n  end if;\r\n\r\n  if requested_entries is null\r\n     or jsonb_typeof(requested_entries) <> 'array'\r\n  then\r\n    raise exception 'entries must be a JSON array';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception 'morning driver availability period is not open';\r\n  end if;\r\n\r\n  select *\r\n  into target_submission\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.user_id = current_user_id\r\n  for update;\r\n\r\n  if not found then\r\n    insert into public.morning_driver_availability_submissions (\r\n      period_id,\r\n      user_id,\r\n      status\r\n    )\r\n    values (\r\n      target_period.id,\r\n      current_user_id,\r\n      'draft'\r\n    )\r\n    returning *\r\n    into target_submission;\r\n  end if;\r\n\r\n  if target_submission.status = 'submitted' then\r\n    raise exception 'morning driver availability already submitted';\r\n  end if;\r\n\r\n  for requested_entry\r\n  in\r\n    select value\r\n    from jsonb_array_elements(requested_entries)\r\n  loop\r\n    requested_shift_id :=\r\n      nullif(\r\n        trim(\r\n          coalesce(\r\n            requested_entry ->> 'shiftId',\r\n            ''\r\n          )\r\n        ),\r\n        ''\r\n      )::uuid;\r\n\r\n    requested_status :=\r\n      nullif(\r\n        trim(\r\n          coalesce(\r\n            requested_entry ->> 'availabilityStatus',\r\n            ''\r\n          )\r\n        ),\r\n        ''\r\n      );\r\n\r\n    requested_note :=\r\n      nullif(\r\n        trim(\r\n          coalesce(\r\n            requested_entry ->> 'note',\r\n            ''\r\n          )\r\n        ),\r\n        ''\r\n      );\r\n\r\n    if requested_shift_id is null then\r\n      raise exception 'shift id is required';\r\n    end if;\r\n\r\n    if requested_status not in (\r\n      'available',\r\n      'unavailable'\r\n    ) then\r\n      raise exception 'invalid availability status';\r\n    end if;\r\n\r\n    if not exists (\r\n      select 1\r\n      from public.morning_driver_availability_shifts shift_item\r\n      where shift_item.id = requested_shift_id\r\n        and shift_item.period_id = target_period.id\r\n    ) then\r\n      raise exception 'shift does not belong to the requested period';\r\n    end if;\r\n\r\n    insert into public.morning_driver_availability_entries (\r\n      period_id,\r\n      shift_id,\r\n      user_id,\r\n      availability_status,\r\n      note,\r\n      updated_at\r\n    )\r\n    values (\r\n      target_period.id,\r\n      requested_shift_id,\r\n      current_user_id,\r\n      requested_status,\r\n      requested_note,\r\n      saved_at_value\r\n    )\r\n    on conflict (\r\n      shift_id,\r\n      user_id\r\n    )\r\n    do update\r\n    set\r\n      availability_status =\r\n        excluded.availability_status,\r\n      note =\r\n        excluded.note,\r\n      updated_at =\r\n        excluded.updated_at;\r\n\r\n    saved_entries :=\r\n      saved_entries + 1;\r\n  end loop;\r\n\r\n  update public.morning_driver_availability_submissions\r\n  set\r\n    status =\r\n      case\r\n        when status = 'reopened'\r\n          then 'reopened'\r\n        else 'draft'\r\n      end,\r\n    last_saved_at =\r\n      saved_at_value,\r\n    updated_at =\r\n      saved_at_value\r\n  where id = target_submission.id;\r\n\r\n  select\r\n    count(*) filter (\r\n      where entry.availability_status = 'available'\r\n    ),\r\n    count(*) filter (\r\n      where entry.availability_status = 'unavailable'\r\n    ),\r\n    count(*) filter (\r\n      where entry.id is null\r\n    )\r\n  into\r\n    available_count,\r\n    unavailable_count,\r\n    unmarked_count\r\n  from public.morning_driver_availability_shifts shift_item\r\n  left join public.morning_driver_availability_entries entry\r\n    on entry.shift_id = shift_item.id\r\n   and entry.user_id = current_user_id\r\n  where shift_item.period_id = target_period.id;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n    'userId',\r\n      current_user_id,\r\n    'availableCount',\r\n      available_count,\r\n    'unavailableCount',\r\n      unavailable_count,\r\n    'unmarkedCount',\r\n      unmarked_count,\r\n    'savedEntries',\r\n      saved_entries,\r\n    'savedAt',\r\n      saved_at_value\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "save_my_shift_availability(uuid,text,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.save_my_shift_availability(requested_shift_slot_id uuid, requested_availability_status text, requested_note text DEFAULT NULL::text)\n RETURNS TABLE(shift_slot_id uuid, availability_status text, availability_note text, availability_updated_at timestamp with time zone, available_count integer, unavailable_count integer, answered_count integer, total_shift_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  target_period_id uuid;\r\n  target_period_status text;\r\n  target_submission_deadline timestamptz;\r\n\r\n  target_submission_status text;\r\n\r\n  normalized_note text;\r\n  saved_at timestamptz;\r\n\r\n  calculated_available_count integer;\r\n  calculated_unavailable_count integer;\r\n  calculated_total_shift_count integer;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id = current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.view'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to submit availability';\r\n  end if;\r\n\r\n  if requested_shift_slot_id is null then\r\n    raise exception\r\n      'Shift slot id is required';\r\n  end if;\r\n\r\n  if requested_availability_status not in (\r\n    'available',\r\n    'unavailable'\r\n  ) then\r\n    raise exception\r\n      'Invalid availability status';\r\n  end if;\r\n\r\n  normalized_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  if (\r\n    normalized_note is not null\r\n    and length(normalized_note) > 1000\r\n  ) then\r\n    raise exception\r\n      'Availability note is too long';\r\n  end if;\r\n\r\n  select\r\n    period.id,\r\n    period.status,\r\n    period.submission_deadline\r\n  into\r\n    target_period_id,\r\n    target_period_status,\r\n    target_submission_deadline\r\n  from public.availability_shift_slots slot\r\n  join public.availability_periods period\r\n    on period.id = slot.period_id\r\n  where slot.id =\r\n    requested_shift_slot_id;\r\n\r\n  if target_period_id is null then\r\n    raise exception\r\n      'Shift slot was not found';\r\n  end if;\r\n\r\n  if target_period_status <> 'open' then\r\n    raise exception\r\n      'Availability period is not open';\r\n  end if;\r\n\r\n  if (\r\n    target_submission_deadline is not null\r\n    and target_submission_deadline <= now()\r\n  ) then\r\n    raise exception\r\n      'Availability submission deadline has passed';\r\n  end if;\r\n\r\n  select\r\n    submission.status\r\n  into\r\n    target_submission_status\r\n  from public.availability_submissions submission\r\n  where submission.period_id =\r\n    target_period_id\r\n    and submission.user_id =\r\n      current_user_id\r\n  for update;\r\n\r\n  if target_submission_status is null then\r\n    insert into\r\n      public.availability_submissions (\r\n        period_id,\r\n        user_id,\r\n        status,\r\n        available_count,\r\n        unavailable_count\r\n      )\r\n    values (\r\n      target_period_id,\r\n      current_user_id,\r\n      'draft',\r\n      0,\r\n      0\r\n    );\r\n\r\n    target_submission_status :=\r\n      'draft';\r\n  end if;\r\n\r\n  if target_submission_status =\r\n    'submitted' then\r\n    raise exception\r\n      'Availability submission is already submitted';\r\n  end if;\r\n\r\n  saved_at := now();\r\n\r\n  insert into\r\n    public.dispatcher_availability (\r\n      period_id,\r\n      shift_slot_id,\r\n      user_id,\r\n      availability_status,\r\n      note,\r\n      created_at,\r\n      updated_at\r\n    )\r\n  values (\r\n    target_period_id,\r\n    requested_shift_slot_id,\r\n    current_user_id,\r\n    requested_availability_status,\r\n    normalized_note,\r\n    saved_at,\r\n    saved_at\r\n  )\r\n  on conflict on constraint\r\n    dispatcher_availability_unique\r\n  do update set\r\n    availability_status =\r\n      excluded.availability_status,\r\n\r\n    note =\r\n      excluded.note,\r\n\r\n    updated_at =\r\n      excluded.updated_at;\r\n\r\n  select\r\n    count(*) filter (\r\n      where availability.availability_status =\r\n        'available'\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where availability.availability_status =\r\n        'unavailable'\r\n    )::integer\r\n  into\r\n    calculated_available_count,\r\n    calculated_unavailable_count\r\n  from public.dispatcher_availability\r\n    availability\r\n  where availability.period_id =\r\n    target_period_id\r\n    and availability.user_id =\r\n      current_user_id;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_total_shift_count\r\n  from public.availability_shift_slots slot\r\n  where slot.period_id =\r\n    target_period_id;\r\n\r\n  update public.availability_submissions\r\n  set\r\n    available_count =\r\n      calculated_available_count,\r\n\r\n    unavailable_count =\r\n      calculated_unavailable_count,\r\n\r\n    last_saved_at =\r\n      saved_at,\r\n\r\n    updated_at =\r\n      saved_at\r\n  where period_id =\r\n    target_period_id\r\n    and user_id =\r\n      current_user_id;\r\n\r\n  return query\r\n  select\r\n    requested_shift_slot_id,\r\n\r\n    requested_availability_status,\r\n\r\n    normalized_note,\r\n\r\n    saved_at,\r\n\r\n    calculated_available_count,\r\n\r\n    calculated_unavailable_count,\r\n\r\n    calculated_available_count\r\n      + calculated_unavailable_count,\r\n\r\n    calculated_total_shift_count;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "save_schedule_draft(uuid,jsonb,boolean)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.save_schedule_draft(requested_availability_period_id uuid, requested_assignments jsonb, requested_confirm_warnings boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  source_period\r\n    public.availability_periods%rowtype;\r\n\r\n  existing_schedule_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  resolved_schedule_period_id uuid;\r\n\r\n  source_shift_count integer;\r\n  payload_count integer;\r\n  distinct_payload_count integer;\r\n\r\n  inactive_user_count integer;\r\n  unavailable_assignment_count integer := 0;\r\n\r\n  overlap_count integer;\r\n  consecutive_count integer;\r\n\r\n  saved_shift_count integer;\r\n  automatic_assignment_count integer;\r\n  manual_assignment_count integer;\r\nbegin\r\n  current_user_id :=\r\n    (select auth.uid());\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id =\r\n      current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  if not (\r\n    'schedule.edit' = any(\r\n      public.get_my_permissions()\r\n    )\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_availability_period_id\r\n    is null\r\n  then\r\n    raise exception\r\n      'availability period id is required';\r\n  end if;\r\n\r\n  if requested_assignments is null\r\n    or jsonb_typeof(\r\n      requested_assignments\r\n    ) <> 'array'\r\n  then\r\n    raise exception\r\n      'assignments must be a json array';\r\n  end if;\r\n\r\n  select *\r\n  into source_period\r\n  from public.availability_periods\r\n  where id =\r\n    requested_availability_period_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'availability period not found';\r\n  end if;\r\n\r\n  if source_period.status <> 'closed' then\r\n    raise exception\r\n      'availability period must be closed';\r\n  end if;\r\n\r\n  select count(*)\r\n  into source_shift_count\r\n  from public.availability_shift_slots\r\n  where period_id =\r\n    requested_availability_period_id;\r\n\r\n  if source_shift_count = 0 then\r\n    raise exception\r\n      'availability period has no shift slots';\r\n  end if;\r\n\r\n  payload_count :=\r\n    jsonb_array_length(\r\n      requested_assignments\r\n    );\r\n\r\n  if payload_count = 0 then\r\n    raise exception\r\n      'assignments array is empty';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 4. בדיקת מבנה האובייקטים\r\n  -- =======================================================\r\n\r\n  if exists (\r\n    select 1\r\n    from jsonb_array_elements(\r\n      requested_assignments\r\n    ) item\r\n    where\r\n      jsonb_typeof(item) <> 'object'\r\n\r\n      or nullif(\r\n        btrim(\r\n          item ->> 'shiftId'\r\n        ),\r\n        ''\r\n      ) is null\r\n\r\n      or nullif(\r\n        btrim(\r\n          item ->> 'userId'\r\n        ),\r\n        ''\r\n      ) is null\r\n\r\n      or nullif(\r\n        btrim(\r\n          item ->> 'source'\r\n        ),\r\n        ''\r\n      ) is null\r\n  ) then\r\n    raise exception\r\n      'one or more assignment objects are invalid';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from jsonb_array_elements(\r\n      requested_assignments\r\n    ) item\r\n    where item ->> 'source'\r\n      not in (\r\n        'automatic_single_candidate',\r\n        'automatic_scoring',\r\n        'manual',\r\n        'automatic',\r\n        'shift_swap',\r\n        'import'\r\n      )\r\n  ) then\r\n    raise exception\r\n      'unsupported assignment source';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 5. מניעת UUID לא תקין\r\n  -- =======================================================\r\n\r\n  if exists (\r\n    select 1\r\n    from jsonb_array_elements(\r\n      requested_assignments\r\n    ) item\r\n    where\r\n      not (\r\n        item ->> 'shiftId'\r\n        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'\r\n      )\r\n\r\n      or not (\r\n        item ->> 'userId'\r\n        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'\r\n      )\r\n  ) then\r\n    raise exception\r\n      'one or more assignment identifiers are invalid';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 6. בדיקת כפילויות ושלמות\r\n  -- =======================================================\r\n\r\n  select count(\r\n    distinct (\r\n      item ->> 'shiftId'\r\n    )\r\n  )\r\n  into distinct_payload_count\r\n  from jsonb_array_elements(\r\n    requested_assignments\r\n  ) item;\r\n\r\n  if distinct_payload_count\r\n    <> payload_count\r\n  then\r\n    raise exception\r\n      'duplicate shift assignments were received';\r\n  end if;\r\n\r\n  if payload_count\r\n    <> source_shift_count\r\n  then\r\n    raise exception\r\n      'every availability shift must have exactly one assignment';\r\n  end if;\r\n\r\n  if exists (\r\n    with payload as (\r\n      select\r\n        (\r\n          item ->> 'shiftId'\r\n        )::uuid as shift_id\r\n      from jsonb_array_elements(\r\n        requested_assignments\r\n      ) item\r\n    )\r\n    select 1\r\n    from payload\r\n    left join\r\n      public.availability_shift_slots slot\r\n      on slot.id =\r\n        payload.shift_id\r\n      and slot.period_id =\r\n        requested_availability_period_id\r\n    where slot.id is null\r\n  ) then\r\n    raise exception\r\n      'one or more shifts do not belong to the requested availability period';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.availability_shift_slots slot\r\n    where slot.period_id =\r\n      requested_availability_period_id\r\n      and not exists (\r\n        select 1\r\n        from jsonb_array_elements(\r\n          requested_assignments\r\n        ) item\r\n        where (\r\n          item ->> 'shiftId'\r\n        )::uuid = slot.id\r\n      )\r\n  ) then\r\n    raise exception\r\n      'one or more availability shifts are missing from the draft';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 7. בדיקת מוקדנים\r\n  -- =======================================================\r\n\r\n  with payload as (\r\n    select distinct\r\n      (\r\n        item ->> 'userId'\r\n      )::uuid as user_id\r\n    from jsonb_array_elements(\r\n      requested_assignments\r\n    ) item\r\n  )\r\n  select count(*)\r\n  into inactive_user_count\r\n  from payload\r\n  left join public.profiles profile\r\n    on profile.id =\r\n      payload.user_id\r\n  where\r\n    profile.id is null\r\n    or profile.is_active = false;\r\n\r\n  if inactive_user_count > 0 then\r\n    raise exception\r\n      'one or more assigned dispatchers are missing or inactive';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 8. אזהרת זמינות\r\n  --\r\n  -- נעשה שימוש ב-Dynamic SQL כדי שה-Migration לא ייכשל\r\n  -- אם שם עמודת סטטוס הזמינות שונה בפרויקט.\r\n  -- =======================================================\r\n\r\n  if exists (\r\n    select 1\r\n    from information_schema.columns\r\n    where table_schema = 'public'\r\n      and table_name =\r\n        'dispatcher_availability'\r\n      and column_name =\r\n        'availability_status'\r\n  ) then\r\n    execute $warning_query$\r\n      with payload as (\r\n        select\r\n          (\r\n            item ->> 'shiftId'\r\n          )::uuid as shift_id,\r\n\r\n          (\r\n            item ->> 'userId'\r\n          )::uuid as user_id\r\n        from jsonb_array_elements(\r\n          $1\r\n        ) item\r\n      )\r\n      select count(*)\r\n      from payload\r\n      left join\r\n        public.dispatcher_availability availability\r\n        on availability.period_id = $2\r\n        and availability.shift_slot_id =\r\n          payload.shift_id\r\n        and availability.user_id =\r\n          payload.user_id\r\n      where\r\n        availability.user_id is null\r\n        or availability.availability_status::text\r\n          <> 'available'\r\n    $warning_query$\r\n    into unavailable_assignment_count\r\n    using\r\n      requested_assignments,\r\n      requested_availability_period_id;\r\n  end if;\r\n\r\n  if unavailable_assignment_count > 0\r\n    and not requested_confirm_warnings\r\n  then\r\n    raise exception\r\n      'availability warnings require confirmation';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 9. בדיקת חפיפות ומשמרות רצופות\r\n  -- =======================================================\r\n\r\n  with payload as (\r\n    select\r\n      (\r\n        item ->> 'shiftId'\r\n      )::uuid as shift_id,\r\n\r\n      (\r\n        item ->> 'userId'\r\n      )::uuid as user_id\r\n    from jsonb_array_elements(\r\n      requested_assignments\r\n    ) item\r\n  ),\r\n\r\n  intervals as (\r\n    select\r\n      payload.shift_id,\r\n      payload.user_id,\r\n\r\n      (\r\n        slot.shift_date +\r\n        slot.start_time\r\n      ) at time zone\r\n        'Asia/Jerusalem'\r\n        as starts_at,\r\n\r\n      (\r\n        slot.shift_date +\r\n        slot.end_time +\r\n        case\r\n          when slot.ends_next_day\r\n            or slot.end_time <=\r\n              slot.start_time\r\n          then interval '1 day'\r\n          else interval '0 day'\r\n        end\r\n      ) at time zone\r\n        'Asia/Jerusalem'\r\n        as ends_at\r\n\r\n    from payload\r\n    join public.availability_shift_slots slot\r\n      on slot.id =\r\n        payload.shift_id\r\n      and slot.period_id =\r\n        requested_availability_period_id\r\n  ),\r\n\r\n  ordered as (\r\n    select\r\n      intervals.*,\r\n\r\n      lag(shift_id) over (\r\n        partition by user_id\r\n        order by starts_at\r\n      ) as previous_shift_id,\r\n\r\n      lag(ends_at) over (\r\n        partition by user_id\r\n        order by starts_at\r\n      ) as previous_ends_at\r\n\r\n    from intervals\r\n  )\r\n\r\n  select\r\n    count(*) filter (\r\n      where previous_ends_at\r\n        is not null\r\n        and starts_at <\r\n          previous_ends_at\r\n    ),\r\n\r\n    count(*) filter (\r\n      where previous_ends_at\r\n        is not null\r\n        and starts_at =\r\n          previous_ends_at\r\n    )\r\n\r\n  into\r\n    overlap_count,\r\n    consecutive_count\r\n\r\n  from ordered;\r\n\r\n  if overlap_count > 0 then\r\n    raise exception\r\n      'the schedule contains overlapping shifts';\r\n  end if;\r\n\r\n  if consecutive_count > 0 then\r\n    raise exception\r\n      'the schedule contains consecutive shifts';\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 10. איתור או יצירת תקופת השיבוץ\r\n  -- =======================================================\r\n\r\n  select *\r\n  into existing_schedule_period\r\n  from public.schedule_periods\r\n  where year =\r\n    source_period.year\r\n    and month =\r\n      source_period.month\r\n  for update;\r\n\r\n  if found then\r\n    if existing_schedule_period.status\r\n      in (\r\n        'published',\r\n        'archived'\r\n      )\r\n    then\r\n      raise exception\r\n        'published or archived schedules cannot be overwritten';\r\n    end if;\r\n\r\n    resolved_schedule_period_id :=\r\n      existing_schedule_period.id;\r\n\r\n    update public.schedule_periods\r\n    set\r\n      availability_period_id =\r\n        source_period.id,\r\n\r\n      title =\r\n        coalesce(\r\n          source_period.title,\r\n          concat(\r\n            'שיבוץ ',\r\n            source_period.month,\r\n            '/',\r\n            source_period.year\r\n          )\r\n        ),\r\n\r\n      status =\r\n        'scheduling'::public.schedule_period_status,\r\n\r\n      availability_deadline =\r\n        source_period.submission_deadline,\r\n\r\n      approved_by =\r\n        current_user_id,\r\n\r\n      approved_at =\r\n        now(),\r\n\r\n      updated_at =\r\n        now()\r\n\r\n    where id =\r\n      resolved_schedule_period_id;\r\n  else\r\n    insert into public.schedule_periods (\r\n      year,\r\n      month,\r\n      status,\r\n      availability_deadline,\r\n      availability_period_id,\r\n      title,\r\n      created_by,\r\n      approved_by,\r\n      approved_at\r\n    )\r\n    values (\r\n      source_period.year,\r\n      source_period.month,\r\n      'scheduling'::public.schedule_period_status,\r\n      source_period.submission_deadline,\r\n      source_period.id,\r\n      coalesce(\r\n        source_period.title,\r\n        concat(\r\n          'שיבוץ ',\r\n          source_period.month,\r\n          '/',\r\n          source_period.year\r\n        )\r\n      ),\r\n      current_user_id,\r\n      current_user_id,\r\n      now()\r\n    )\r\n    returning id\r\n    into resolved_schedule_period_id;\r\n  end if;\r\n\r\n\r\n  -- =======================================================\r\n  -- 11. שמירת המשמרות\r\n  -- =======================================================\r\n\r\n  insert into public.schedule_shifts (\r\n    period_id,\r\n    availability_shift_slot_id,\r\n    shift_date,\r\n    starts_at,\r\n    ends_at,\r\n    shift_code,\r\n    schedule_type,\r\n    is_premium,\r\n    holiday_name,\r\n    assigned_user_id,\r\n    assignment_source,\r\n    assignment_score,\r\n    assignment_reasons,\r\n    is_locked,\r\n    notes\r\n  )\r\n  select\r\n    resolved_schedule_period_id,\r\n\r\n    slot.id,\r\n\r\n    slot.shift_date,\r\n\r\n    (\r\n      slot.shift_date +\r\n      slot.start_time\r\n    ) at time zone\r\n      'Asia/Jerusalem',\r\n\r\n    (\r\n      slot.shift_date +\r\n      slot.end_time +\r\n      case\r\n        when slot.ends_next_day\r\n          or slot.end_time <=\r\n            slot.start_time\r\n        then interval '1 day'\r\n        else interval '0 day'\r\n      end\r\n    ) at time zone\r\n      'Asia/Jerusalem',\r\n\r\n    concat(\r\n      to_char(\r\n        slot.shift_date,\r\n        'YYYYMMDD'\r\n      ),\r\n      '-',\r\n      to_char(\r\n        slot.start_time,\r\n        'HH24MI'\r\n      )\r\n    ),\r\n\r\n    slot.schedule_type::public.schedule_type,\r\n\r\n    slot.is_premium,\r\n\r\n    slot.holiday_name,\r\n\r\n    (\r\n      item ->> 'userId'\r\n    )::uuid,\r\n\r\n    case\r\n      when item ->> 'source'\r\n        in (\r\n          'automatic_single_candidate',\r\n          'automatic_scoring',\r\n          'automatic'\r\n        )\r\n      then\r\n        'automatic'::public.assignment_source\r\n\r\n      when item ->> 'source' =\r\n        'shift_swap'\r\n      then\r\n        'shift_swap'::public.assignment_source\r\n\r\n      when item ->> 'source' =\r\n        'import'\r\n      then\r\n        'import'::public.assignment_source\r\n\r\n      else\r\n        'manual'::public.assignment_source\r\n    end,\r\n\r\n    case\r\n      when nullif(\r\n        item ->> 'score',\r\n        ''\r\n      ) is null\r\n      then null\r\n\r\n      else (\r\n        item ->> 'score'\r\n      )::numeric\r\n    end,\r\n\r\n    case\r\n      when jsonb_typeof(\r\n        item -> 'reasons'\r\n      ) = 'array'\r\n      then item -> 'reasons'\r\n\r\n      else '[]'::jsonb\r\n    end,\r\n\r\n    false,\r\n\r\n    case\r\n      when jsonb_typeof(\r\n        item -> 'reasons'\r\n      ) = 'array'\r\n      then (\r\n        select string_agg(\r\n          reason_value,\r\n          E'\\n'\r\n        )\r\n        from jsonb_array_elements_text(\r\n          item -> 'reasons'\r\n        ) reason_value\r\n      )\r\n\r\n      else null\r\n    end\r\n\r\n  from jsonb_array_elements(\r\n    requested_assignments\r\n  ) item\r\n\r\n  join public.availability_shift_slots slot\r\n    on slot.id =\r\n      (\r\n        item ->> 'shiftId'\r\n      )::uuid\r\n\r\n    and slot.period_id =\r\n      requested_availability_period_id\r\n\r\n  on conflict (\r\n    period_id,\r\n    starts_at\r\n  )\r\n  do update set\r\n    availability_shift_slot_id =\r\n      excluded.availability_shift_slot_id,\r\n\r\n    shift_date =\r\n      excluded.shift_date,\r\n\r\n    ends_at =\r\n      excluded.ends_at,\r\n\r\n    shift_code =\r\n      excluded.shift_code,\r\n\r\n    schedule_type =\r\n      excluded.schedule_type,\r\n\r\n    is_premium =\r\n      excluded.is_premium,\r\n\r\n    holiday_name =\r\n      excluded.holiday_name,\r\n\r\n    assigned_user_id =\r\n      excluded.assigned_user_id,\r\n\r\n    assignment_source =\r\n      excluded.assignment_source,\r\n\r\n    assignment_score =\r\n      excluded.assignment_score,\r\n\r\n    assignment_reasons =\r\n      excluded.assignment_reasons,\r\n\r\n    is_locked =\r\n      false,\r\n\r\n    notes =\r\n      excluded.notes,\r\n\r\n    updated_at =\r\n      now();\r\n\r\n\r\n  -- =======================================================\r\n  -- 12. בדיקת תוצאת השמירה\r\n  -- =======================================================\r\n\r\n  select count(*)\r\n  into saved_shift_count\r\n  from public.schedule_shifts shift\r\n  where shift.period_id =\r\n    resolved_schedule_period_id\r\n    and shift.availability_shift_slot_id\r\n      in (\r\n        select slot.id\r\n        from public.availability_shift_slots slot\r\n        where slot.period_id =\r\n          requested_availability_period_id\r\n      );\r\n\r\n  if saved_shift_count\r\n    <> source_shift_count\r\n  then\r\n    raise exception\r\n      'saved shift count does not match source shift count';\r\n  end if;\r\n\r\n  select\r\n    count(*) filter (\r\n      where shift.assignment_source =\r\n        'automatic'\r\n    ),\r\n\r\n    count(*) filter (\r\n      where shift.assignment_source =\r\n        'manual'\r\n    )\r\n\r\n  into\r\n    automatic_assignment_count,\r\n    manual_assignment_count\r\n\r\n  from public.schedule_shifts shift\r\n  where shift.period_id =\r\n    resolved_schedule_period_id;\r\n\r\n\r\n  -- =======================================================\r\n  -- 13. תשובה ללקוח\r\n  -- =======================================================\r\n\r\n  return jsonb_build_object(\r\n    'schedulePeriodId',\r\n      resolved_schedule_period_id,\r\n\r\n    'availabilityPeriodId',\r\n      requested_availability_period_id,\r\n\r\n    'year',\r\n      source_period.year,\r\n\r\n    'month',\r\n      source_period.month,\r\n\r\n    'status',\r\n      'scheduling',\r\n\r\n    'savedShifts',\r\n      saved_shift_count,\r\n\r\n    'automaticAssignments',\r\n      automatic_assignment_count,\r\n\r\n    'manualAssignments',\r\n      manual_assignment_count,\r\n\r\n    'warningCount',\r\n      unavailable_assignment_count,\r\n\r\n    'approvedBy',\r\n      current_user_id,\r\n\r\n    'approvedAt',\r\n      now()\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "save_schedule_import_name_alias(text,uuid,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.save_schedule_import_name_alias(requested_source_name text, requested_user_id uuid, requested_user_type text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_permissions text[];\r\n\r\n  normalized_name text;\r\n\r\n  target_profile\r\n    public.profiles%rowtype;\r\n\r\n  saved_alias\r\n    public.schedule_import_name_aliases%rowtype;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.manage' =\r\n      any(current_permissions)\r\n    or\r\n    'users.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  normalized_name :=\r\n    public.normalize_schedule_import_name(\r\n      requested_source_name\r\n    );\r\n\r\n  if normalized_name = '' then\r\n    raise exception\r\n      'source name is required';\r\n  end if;\r\n\r\n  if requested_user_id is null then\r\n    raise exception\r\n      'user id is required';\r\n  end if;\r\n\r\n  if requested_user_type not in (\r\n    'dispatcher',\r\n    'on_call'\r\n  ) then\r\n    raise exception\r\n      'user type is invalid';\r\n  end if;\r\n\r\n  select *\r\n  into target_profile\r\n  from public.profiles\r\n  where id =\r\n    requested_user_id\r\n    and is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'user not found or inactive';\r\n  end if;\r\n\r\n  if target_profile.role <>\r\n    requested_user_type\r\n  then\r\n    raise exception\r\n      'user role does not match import type';\r\n  end if;\r\n\r\n  insert into\r\n    public.schedule_import_name_aliases (\r\n      source_name,\r\n      normalized_source_name,\r\n      user_id,\r\n      user_type,\r\n      created_by,\r\n      updated_by,\r\n      created_at,\r\n      updated_at\r\n    )\r\n  values (\r\n    trim(\r\n      requested_source_name\r\n    ),\r\n    normalized_name,\r\n    requested_user_id,\r\n    requested_user_type,\r\n    current_user_id,\r\n    current_user_id,\r\n    now(),\r\n    now()\r\n  )\r\n  on conflict (\r\n    normalized_source_name,\r\n    user_type\r\n  )\r\n  do update set\r\n    source_name =\r\n      excluded.source_name,\r\n\r\n    user_id =\r\n      excluded.user_id,\r\n\r\n    updated_by =\r\n      current_user_id,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  returning *\r\n  into saved_alias;\r\n\r\n  return jsonb_build_object(\r\n    'id',\r\n      saved_alias.id,\r\n\r\n    'sourceName',\r\n      saved_alias.source_name,\r\n\r\n    'normalizedSourceName',\r\n      saved_alias.normalized_source_name,\r\n\r\n    'userId',\r\n      saved_alias.user_id,\r\n\r\n    'userType',\r\n      saved_alias.user_type,\r\n\r\n    'updatedAt',\r\n      saved_alias.updated_at\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "set_push_updated_at()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.set_push_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\r\nbegin\r\n  new.updated_at := now();\r\n\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "set_updated_at()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\r\nbegin\r\n  new.updated_at = now();\r\n  return new;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "set_user_permissions(uuid,text[])",
    "function_definition": "CREATE OR REPLACE FUNCTION public.set_user_permissions(target_user_id uuid, requested_permissions text[])\n RETURNS text[]\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  normalized_permissions text[];\r\n  invalid_permissions text[];\r\n  target_exists boolean;\r\nbegin\r\n  if not public.is_current_user_admin() then\r\n    raise exception 'Only administrators can update user permissions';\r\n  end if;\r\n\r\n  select exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = target_user_id\r\n  )\r\n  into target_exists;\r\n\r\n  if not target_exists then\r\n    raise exception 'Target user was not found';\r\n  end if;\r\n\r\n  select coalesce(\r\n    array_agg(distinct permission_key),\r\n    array[]::text[]\r\n  )\r\n  into normalized_permissions\r\n  from unnest(\r\n    coalesce(\r\n      requested_permissions,\r\n      array[]::text[]\r\n    )\r\n  ) as permission_key;\r\n\r\n  select coalesce(\r\n    array_agg(requested.permission_key),\r\n    array[]::text[]\r\n  )\r\n  into invalid_permissions\r\n  from unnest(normalized_permissions)\r\n    as requested(permission_key)\r\n  left join public.permissions existing\r\n    on existing.permission_key =\r\n      requested.permission_key\r\n  where existing.permission_key is null;\r\n\r\n  if cardinality(invalid_permissions) > 0 then\r\n    raise exception\r\n      'Invalid permissions: %',\r\n      array_to_string(\r\n        invalid_permissions,\r\n        ', '\r\n      );\r\n  end if;\r\n\r\n  -- מניעת מצב שבו מנהל מסיר מעצמו את האפשרות לנהל משתמשים.\r\n  if target_user_id = auth.uid() then\r\n    if not (\r\n      'users.manage' =\r\n      any(normalized_permissions)\r\n    ) then\r\n      raise exception\r\n        'An administrator cannot remove users.manage from their own account';\r\n    end if;\r\n\r\n    if not (\r\n      'users.view' =\r\n      any(normalized_permissions)\r\n    ) then\r\n      raise exception\r\n        'An administrator cannot remove users.view from their own account';\r\n    end if;\r\n  end if;\r\n\r\n  delete from public.user_permissions\r\n  where user_id = target_user_id;\r\n\r\n  insert into public.user_permissions (\r\n    user_id,\r\n    permission_key,\r\n    granted_by\r\n  )\r\n  select\r\n    target_user_id,\r\n    permission_key,\r\n    auth.uid()\r\n  from unnest(normalized_permissions)\r\n    as permission_key;\r\n\r\n  return (\r\n    select coalesce(\r\n      array_agg(\r\n        up.permission_key\r\n        order by p.sort_order, up.permission_key\r\n      ),\r\n      array[]::text[]\r\n    )\r\n    from public.user_permissions up\r\n    join public.permissions p\r\n      on p.permission_key = up.permission_key\r\n    where up.user_id = target_user_id\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "submit_my_availability()",
    "function_definition": "CREATE OR REPLACE FUNCTION public.submit_my_availability()\n RETURNS TABLE(period_id uuid, submission_status text, submitted_at timestamp with time zone, available_count integer, unavailable_count integer, answered_count integer, total_shift_count integer)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n\r\n  current_user_email text;\r\n  current_user_display_name text;\r\n\r\n  target_period_id uuid;\r\n  target_period_title text;\r\n  target_period_year integer;\r\n  target_period_month integer;\r\n  target_period_status text;\r\n  target_submission_deadline timestamptz;\r\n\r\n  current_submission_status text;\r\n\r\n  calculated_available_count integer;\r\n  calculated_unavailable_count integer;\r\n  calculated_answered_count integer;\r\n  calculated_total_shift_count integer;\r\n\r\n  submitted_timestamp timestamptz;\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_user_email,\r\n    current_user_display_name\r\n  from public.profiles profile\r\n  where profile.id = current_user_id\r\n    and profile.is_active = true;\r\n\r\n  if current_user_email is null then\r\n    raise exception\r\n      'Authenticated user is not active';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.user_permissions permission\r\n    where permission.user_id =\r\n      current_user_id\r\n      and permission.permission_key =\r\n        'availability.view'\r\n  ) then\r\n    raise exception\r\n      'User is not allowed to submit availability';\r\n  end if;\r\n\r\n  select\r\n    period.id,\r\n    period.title,\r\n    period.year,\r\n    period.month,\r\n    period.status,\r\n    period.submission_deadline\r\n  into\r\n    target_period_id,\r\n    target_period_title,\r\n    target_period_year,\r\n    target_period_month,\r\n    target_period_status,\r\n    target_submission_deadline\r\n  from public.availability_periods period\r\n  where period.status = 'open'\r\n  order by\r\n    period.year desc,\r\n    period.month desc,\r\n    period.opened_at desc nulls last\r\n  limit 1;\r\n\r\n  if target_period_id is null then\r\n    raise exception\r\n      'Open availability period was not found';\r\n  end if;\r\n\r\n  if target_period_status <> 'open' then\r\n    raise exception\r\n      'Availability period is not open';\r\n  end if;\r\n\r\n  if (\r\n    target_submission_deadline is not null\r\n    and target_submission_deadline <= now()\r\n  ) then\r\n    raise exception\r\n      'Availability submission deadline has passed';\r\n  end if;\r\n\r\n  select\r\n    submission.status\r\n  into\r\n    current_submission_status\r\n  from public.availability_submissions submission\r\n  where submission.period_id =\r\n    target_period_id\r\n    and submission.user_id =\r\n      current_user_id\r\n  for update;\r\n\r\n  if current_submission_status is null then\r\n    raise exception\r\n      'Availability submission record was not found';\r\n  end if;\r\n\r\n  if current_submission_status = 'submitted' then\r\n    raise exception\r\n      'Availability submission is already submitted';\r\n  end if;\r\n\r\n  select\r\n    count(*) filter (\r\n      where availability.availability_status =\r\n        'available'\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where availability.availability_status =\r\n        'unavailable'\r\n    )::integer\r\n  into\r\n    calculated_available_count,\r\n    calculated_unavailable_count\r\n  from public.dispatcher_availability availability\r\n  where availability.period_id =\r\n    target_period_id\r\n    and availability.user_id =\r\n      current_user_id;\r\n\r\n  calculated_answered_count :=\r\n    calculated_available_count\r\n    + calculated_unavailable_count;\r\n\r\n  select\r\n    count(*)::integer\r\n  into\r\n    calculated_total_shift_count\r\n  from public.availability_shift_slots slot\r\n  where slot.period_id =\r\n    target_period_id;\r\n\r\n  if calculated_total_shift_count = 0 then\r\n    raise exception\r\n      'Availability period does not contain shift slots';\r\n  end if;\r\n\r\n  if (\r\n    calculated_answered_count <>\r\n    calculated_total_shift_count\r\n  ) then\r\n    raise exception\r\n      'All shift slots must be answered before submission';\r\n  end if;\r\n\r\n  submitted_timestamp := now();\r\n\r\n  update public.availability_submissions submission\r\n  set\r\n    status = 'submitted',\r\n\r\n    submitted_at =\r\n      submitted_timestamp,\r\n\r\n    last_saved_at =\r\n      coalesce(\r\n        submission.last_saved_at,\r\n        submitted_timestamp\r\n      ),\r\n\r\n    available_count =\r\n      calculated_available_count,\r\n\r\n    unavailable_count =\r\n      calculated_unavailable_count,\r\n\r\n    updated_at =\r\n      submitted_timestamp\r\n\r\n  where submission.period_id =\r\n    target_period_id\r\n    and submission.user_id =\r\n      current_user_id;\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    'availability_submitted',\r\n\r\n    current_user_id,\r\n    current_user_email,\r\n    current_user_display_name,\r\n\r\n    current_user_id,\r\n    current_user_email,\r\n    current_user_display_name,\r\n\r\n    'availability_submission',\r\n    target_period_id,\r\n\r\n    format(\r\n      'הוגשו אילוצים לחודש %s/%s על ידי %s',\r\n      target_period_month,\r\n      target_period_year,\r\n      current_user_display_name\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      current_submission_status\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'status',\r\n      'submitted',\r\n\r\n      'submitted_at',\r\n      submitted_timestamp,\r\n\r\n      'available_count',\r\n      calculated_available_count,\r\n\r\n      'unavailable_count',\r\n      calculated_unavailable_count,\r\n\r\n      'answered_count',\r\n      calculated_answered_count,\r\n\r\n      'total_shift_count',\r\n      calculated_total_shift_count\r\n    ),\r\n\r\n    jsonb_build_object(\r\n      'source',\r\n      'submit-my-availability-rpc',\r\n\r\n      'period_id',\r\n      target_period_id,\r\n\r\n      'period_title',\r\n      target_period_title,\r\n\r\n      'year',\r\n      target_period_year,\r\n\r\n      'month',\r\n      target_period_month\r\n    )\r\n  );\r\n\r\n  return query\r\n  select\r\n    target_period_id,\r\n    'submitted'::text,\r\n    submitted_timestamp,\r\n    calculated_available_count,\r\n    calculated_unavailable_count,\r\n    calculated_answered_count,\r\n    calculated_total_shift_count;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "submit_my_driver_availability(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.submit_my_driver_availability(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_period\r\n    public.driver_availability_periods%rowtype;\r\n\r\n  target_submission\r\n    public.driver_availability_submissions%rowtype;\r\n\r\n  total_days_count integer := 0;\r\n  available_days_count integer := 0;\r\n  unavailable_days_count integer := 0;\r\n  marked_days_count integer := 0;\r\n  submitted_at_value timestamptz := now();\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id = current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_availability.view' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception\r\n      'driver availability period id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_availability_periods\r\n  where id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception\r\n      'driver availability period is not open';\r\n  end if;\r\n\r\n  if (\r\n    target_period.submission_deadline is not null\r\n    and now() >\r\n      target_period.submission_deadline\r\n  ) then\r\n    raise exception\r\n      'driver availability submission deadline has passed';\r\n  end if;\r\n\r\n  select\r\n    count(*)::integer\r\n  into total_days_count\r\n  from public.driver_availability_days\r\n  where period_id =\r\n    target_period.id;\r\n\r\n  if total_days_count = 0 then\r\n    raise exception\r\n      'driver availability period has no days';\r\n  end if;\r\n\r\n  select\r\n    count(*) filter (\r\n      where availability_status =\r\n        'available'\r\n    )::integer,\r\n\r\n    count(*) filter (\r\n      where availability_status =\r\n        'unavailable'\r\n    )::integer,\r\n\r\n    count(*)::integer\r\n\r\n  into\r\n    available_days_count,\r\n    unavailable_days_count,\r\n    marked_days_count\r\n\r\n  from public.driver_availability_entries\r\n  where period_id =\r\n    target_period.id\r\n    and user_id =\r\n      current_user_id;\r\n\r\n  if marked_days_count < total_days_count then\r\n    raise exception\r\n      'all driver availability days must be marked before submission';\r\n  end if;\r\n\r\n  select *\r\n  into target_submission\r\n  from public.driver_availability_submissions\r\n  where period_id =\r\n    target_period.id\r\n    and user_id =\r\n      current_user_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver availability draft was not found';\r\n  end if;\r\n\r\n  if target_submission.status =\r\n    'submitted'\r\n  then\r\n    return jsonb_build_object(\r\n      'periodId',\r\n        target_period.id,\r\n\r\n      'userId',\r\n        current_user_id,\r\n\r\n      'status',\r\n        target_submission.status,\r\n\r\n      'availableCount',\r\n        target_submission.available_count,\r\n\r\n      'unavailableCount',\r\n        target_submission.unavailable_count,\r\n\r\n      'submittedAt',\r\n        target_submission.submitted_at,\r\n\r\n      'alreadySubmitted',\r\n        true\r\n    );\r\n  end if;\r\n\r\n  update public.driver_availability_submissions\r\n  set\r\n    status =\r\n      'submitted',\r\n\r\n    submitted_at =\r\n      submitted_at_value,\r\n\r\n    available_count =\r\n      available_days_count,\r\n\r\n    unavailable_count =\r\n      unavailable_days_count,\r\n\r\n    last_saved_at =\r\n      coalesce(\r\n        last_saved_at,\r\n        submitted_at_value\r\n      ),\r\n\r\n    updated_at =\r\n      submitted_at_value\r\n\r\n  where id =\r\n    target_submission.id\r\n\r\n  returning *\r\n  into target_submission;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n\r\n    'userId',\r\n      current_user_id,\r\n\r\n    'status',\r\n      target_submission.status,\r\n\r\n    'availableCount',\r\n      target_submission.available_count,\r\n\r\n    'unavailableCount',\r\n      target_submission.unavailable_count,\r\n\r\n    'submittedAt',\r\n      target_submission.submitted_at,\r\n\r\n    'alreadySubmitted',\r\n      false\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "submit_my_morning_driver_availability(uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.submit_my_morning_driver_availability(requested_period_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_period public.morning_driver_availability_periods%rowtype;\r\n  target_submission public.morning_driver_availability_submissions%rowtype;\r\n  total_shifts integer;\r\n  available_count integer;\r\n  unavailable_count integer;\r\n  answered_count integer;\r\n  submitted_at_value timestamptz := now();\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_availability.view'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_availability_periods period\r\n  where period.id = requested_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'open' then\r\n    raise exception 'morning driver availability period is not open';\r\n  end if;\r\n\r\n  select *\r\n  into target_submission\r\n  from public.morning_driver_availability_submissions submission\r\n  where submission.period_id = target_period.id\r\n    and submission.user_id = current_user_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'morning driver availability submission not found';\r\n  end if;\r\n\r\n  select count(*)\r\n  into total_shifts\r\n  from public.morning_driver_availability_shifts shift_item\r\n  where shift_item.period_id = target_period.id;\r\n\r\n  select\r\n    count(*) filter (\r\n      where entry.availability_status = 'available'\r\n    ),\r\n    count(*) filter (\r\n      where entry.availability_status = 'unavailable'\r\n    ),\r\n    count(entry.id)\r\n  into\r\n    available_count,\r\n    unavailable_count,\r\n    answered_count\r\n  from public.morning_driver_availability_shifts shift_item\r\n  left join public.morning_driver_availability_entries entry\r\n    on entry.shift_id = shift_item.id\r\n   and entry.user_id = current_user_id\r\n  where shift_item.period_id = target_period.id;\r\n\r\n  if answered_count <> total_shifts then\r\n    raise exception\r\n      'all morning driver shifts must be answered before submission';\r\n  end if;\r\n\r\n  update public.morning_driver_availability_submissions\r\n  set\r\n    status = 'submitted',\r\n    submitted_at =\r\n      submitted_at_value,\r\n    last_saved_at =\r\n      coalesce(\r\n        last_saved_at,\r\n        submitted_at_value\r\n      ),\r\n    updated_at =\r\n      submitted_at_value\r\n  where id = target_submission.id;\r\n\r\n  return jsonb_build_object(\r\n    'periodId',\r\n      target_period.id,\r\n    'userId',\r\n      current_user_id,\r\n    'status',\r\n      'submitted',\r\n    'availableCount',\r\n      available_count,\r\n    'unavailableCount',\r\n      unavailable_count,\r\n    'submittedAt',\r\n      submitted_at_value,\r\n    'alreadySubmitted',\r\n      target_submission.status = 'submitted'\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "transfer_my_driver_duty(uuid,uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.transfer_my_driver_duty(requested_schedule_day_id uuid, requested_new_driver_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  target_day public.driver_schedule_days%rowtype;\r\n  target_period public.driver_schedule_periods%rowtype;\r\n  current_driver public.profiles%rowtype;\r\n  selected_driver public.profiles%rowtype;\r\n  current_year integer;\r\n  current_month integer;\r\n  current_period_value integer;\r\n  target_period_value integer;\r\n  current_date_in_israel date;\r\n  previous_assignment_date date;\r\n  next_assignment_date date;\r\n  previous_gap_days integer;\r\n  next_gap_days integer;\r\n  warning_messages text[] := array[]::text[];\r\nbegin\r\n  current_user_id := auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  select *\r\n  into current_driver\r\n  from public.profiles\r\n  where id = current_user_id\r\n    and role = 'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  if not found then\r\n    raise exception 'active on-call driver profile not found';\r\n  end if;\r\n\r\n  if requested_schedule_day_id is null then\r\n    raise exception 'driver schedule day id is required';\r\n  end if;\r\n\r\n  if requested_new_driver_id is null then\r\n    raise exception 'new on-call driver id is required';\r\n  end if;\r\n\r\n  if requested_new_driver_id = current_user_id then\r\n    raise exception 'new on-call driver must be different';\r\n  end if;\r\n\r\n  current_date_in_israel :=\r\n    (now() at time zone 'Asia/Jerusalem')::date;\r\n\r\n  current_year :=\r\n    extract(year from current_date_in_israel)::integer;\r\n\r\n  current_month :=\r\n    extract(month from current_date_in_israel)::integer;\r\n\r\n  current_period_value :=\r\n    current_year * 12 + current_month - 1;\r\n\r\n  select *\r\n  into target_day\r\n  from public.driver_schedule_days\r\n  where id = requested_schedule_day_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'driver schedule day not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_schedule_periods\r\n  where id = target_day.period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status <>\r\n    'published'::public.driver_schedule_period_status\r\n  then\r\n    raise exception\r\n      'only published driver schedules can be changed by drivers';\r\n  end if;\r\n\r\n  target_period_value :=\r\n    target_period.year * 12 +\r\n    target_period.month - 1;\r\n\r\n  if target_period_value not in (\r\n    current_period_value,\r\n    current_period_value + 1\r\n  ) then\r\n    raise exception\r\n      'drivers can change duties only in the current or next month';\r\n  end if;\r\n\r\n  if target_day.duty_date < current_date_in_israel then\r\n    raise exception\r\n      'past driver duties cannot be changed';\r\n  end if;\r\n\r\n  if target_day.assigned_user_id <> current_user_id then\r\n    raise exception\r\n      'driver can transfer only their own duty';\r\n  end if;\r\n\r\n  if target_day.is_locked then\r\n    raise exception\r\n      'locked driver duty cannot be changed';\r\n  end if;\r\n\r\n  select *\r\n  into selected_driver\r\n  from public.profiles\r\n  where id = requested_new_driver_id\r\n    and role = 'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'selected on-call driver was not found or is inactive';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_days adjacent_day\r\n    where adjacent_day.id <> target_day.id\r\n      and adjacent_day.assigned_user_id = requested_new_driver_id\r\n      and adjacent_day.duty_date in (\r\n        target_day.duty_date - 1,\r\n        target_day.duty_date + 1\r\n      )\r\n  ) then\r\n    raise exception\r\n      'driver cannot be assigned on consecutive days';\r\n  end if;\r\n\r\n  select max(schedule_day.duty_date)\r\n  into previous_assignment_date\r\n  from public.driver_schedule_days schedule_day\r\n  where schedule_day.id <> target_day.id\r\n    and schedule_day.assigned_user_id = requested_new_driver_id\r\n    and schedule_day.duty_date < target_day.duty_date;\r\n\r\n  select min(schedule_day.duty_date)\r\n  into next_assignment_date\r\n  from public.driver_schedule_days schedule_day\r\n  where schedule_day.id <> target_day.id\r\n    and schedule_day.assigned_user_id = requested_new_driver_id\r\n    and schedule_day.duty_date > target_day.duty_date;\r\n\r\n  if previous_assignment_date is not null then\r\n    previous_gap_days :=\r\n      target_day.duty_date - previous_assignment_date;\r\n\r\n    if previous_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד מהכוננות הקודמת',\r\n            previous_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  if next_assignment_date is not null then\r\n    next_gap_days :=\r\n      next_assignment_date - target_day.duty_date;\r\n\r\n    if next_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד עד הכוננות הבאה',\r\n            next_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  update public.driver_schedule_days\r\n  set\r\n    assigned_user_id = requested_new_driver_id,\r\n    assignment_source = 'swap'::public.driver_assignment_source,\r\n    updated_at = now()\r\n  where id = target_day.id\r\n  returning *\r\n  into target_day;\r\n\r\n  perform public.write_audit_log(\r\n    requested_action :=\r\n      'driver_schedule_duty_transferred'::public.audit_action_type,\r\n    requested_target_user_id :=\r\n      requested_new_driver_id,\r\n    requested_summary :=\r\n      'Driver duty transferred',\r\n    requested_old_values :=\r\n      jsonb_build_object(\r\n        'scheduleDayId', target_day.id,\r\n        'dutyDate', target_day.duty_date,\r\n        'assignedUserId', current_user_id,\r\n        'assignedUserName',\r\n          coalesce(\r\n            current_driver.schedule_name,\r\n            current_driver.display_name\r\n          )\r\n      ),\r\n    requested_new_values :=\r\n      jsonb_build_object(\r\n        'scheduleDayId', target_day.id,\r\n        'dutyDate', target_day.duty_date,\r\n        'assignedUserId', requested_new_driver_id,\r\n        'assignedUserName',\r\n          coalesce(\r\n            selected_driver.schedule_name,\r\n            selected_driver.display_name\r\n          ),\r\n        'assignmentSource', 'swap'\r\n      ),\r\n    requested_metadata :=\r\n      jsonb_build_object(\r\n        'periodId', target_period.id,\r\n        'year', target_period.year,\r\n        'month', target_period.month,\r\n        'warnings', to_jsonb(warning_messages)\r\n      )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'scheduleDayId', target_day.id,\r\n    'periodId', target_day.period_id,\r\n    'dutyDate', target_day.duty_date,\r\n    'previousDriverId', current_user_id,\r\n    'previousDriverName',\r\n      coalesce(\r\n        current_driver.schedule_name,\r\n        current_driver.display_name\r\n      ),\r\n    'assignedUserId', target_day.assigned_user_id,\r\n    'assignedUserName',\r\n      coalesce(\r\n        selected_driver.schedule_name,\r\n        selected_driver.display_name\r\n      ),\r\n    'assignmentSource', target_day.assignment_source,\r\n    'hasWarnings',\r\n      cardinality(warning_messages) > 0,\r\n    'warnings', to_jsonb(warning_messages)\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "transfer_my_morning_driver_assignment(uuid,uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.transfer_my_morning_driver_assignment(requested_assignment_id uuid, requested_new_driver_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n\r\n  current_permissions text[];\r\n\r\n  target_assignment\r\n    public.morning_driver_schedule_assignments%rowtype;\r\n\r\n  target_period\r\n    public.morning_driver_schedule_periods%rowtype;\r\n\r\n  target_shift\r\n    public.morning_driver_availability_shifts%rowtype;\r\n\r\n  current_driver\r\n    public.profiles%rowtype;\r\n\r\n  selected_driver\r\n    public.profiles%rowtype;\r\n\r\n  current_date_in_israel date;\r\n\r\n  warning_messages text[] :=\r\n    array[]::text[];\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if requested_assignment_id is null then\r\n    raise exception\r\n      'morning driver assignment id is required';\r\n  end if;\r\n\r\n  if requested_new_driver_id is null then\r\n    raise exception\r\n      'new morning driver id is required';\r\n  end if;\r\n\r\n  if requested_new_driver_id =\r\n    current_user_id\r\n  then\r\n    raise exception\r\n      'new morning driver must be different';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_schedule.view'\r\n      = any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  select *\r\n  into current_driver\r\n  from public.profiles profile\r\n  where profile.id =\r\n      current_user_id\r\n    and profile.role =\r\n      'morning_driver'\r\n        ::public.user_role\r\n    and profile.is_active =\r\n      true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'active morning driver profile not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_assignment\r\n  from public.morning_driver_schedule_assignments assignment\r\n  where assignment.id =\r\n    requested_assignment_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver schedule assignment not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_schedule_periods period\r\n  where period.id =\r\n    target_assignment.schedule_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status <>\r\n    'published'\r\n  then\r\n    raise exception\r\n      'only published morning driver schedules can be changed by drivers';\r\n  end if;\r\n\r\n  current_date_in_israel :=\r\n    (\r\n      now()\r\n      at time zone\r\n        'Asia/Jerusalem'\r\n    )::date;\r\n\r\n  if target_period.year <>\r\n      extract(\r\n        year\r\n        from current_date_in_israel\r\n      )::integer\r\n     or target_period.month <>\r\n      extract(\r\n        month\r\n        from current_date_in_israel\r\n      )::integer\r\n  then\r\n    raise exception\r\n      'morning drivers can change assignments only in the current month';\r\n  end if;\r\n\r\n  select *\r\n  into target_shift\r\n  from public.morning_driver_availability_shifts shift_item\r\n  where shift_item.id =\r\n    target_assignment.availability_shift_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver availability shift not found';\r\n  end if;\r\n\r\n  if target_shift.shift_date <\r\n    current_date_in_israel\r\n  then\r\n    raise exception\r\n      'past morning driver assignments cannot be changed';\r\n  end if;\r\n\r\n  if target_assignment.assigned_user_id <>\r\n    current_user_id\r\n  then\r\n    raise exception\r\n      'morning driver can transfer only their own assignment';\r\n  end if;\r\n\r\n  if target_assignment.is_locked then\r\n    raise exception\r\n      'locked morning driver assignment cannot be changed';\r\n  end if;\r\n\r\n  select *\r\n  into selected_driver\r\n  from public.profiles profile\r\n  where profile.id =\r\n      requested_new_driver_id\r\n    and profile.role =\r\n      'morning_driver'\r\n        ::public.user_role\r\n    and profile.is_active =\r\n      true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'selected morning driver was not found or is inactive';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.morning_driver_schedule_assignments duplicate_assignment\r\n    where duplicate_assignment.schedule_period_id =\r\n        target_assignment.schedule_period_id\r\n      and duplicate_assignment.availability_shift_id =\r\n        target_assignment.availability_shift_id\r\n      and duplicate_assignment.id <>\r\n        target_assignment.id\r\n      and duplicate_assignment.assigned_user_id =\r\n        requested_new_driver_id\r\n  ) then\r\n    raise exception\r\n      'selected morning driver is already assigned to this shift';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.morning_driver_schedule_assignments same_day_assignment\r\n    join public.morning_driver_availability_shifts other_shift\r\n      on other_shift.id =\r\n        same_day_assignment.availability_shift_id\r\n    where same_day_assignment.schedule_period_id =\r\n        target_assignment.schedule_period_id\r\n      and same_day_assignment.id <>\r\n        target_assignment.id\r\n      and same_day_assignment.assigned_user_id =\r\n        requested_new_driver_id\r\n      and other_shift.shift_date =\r\n        target_shift.shift_date\r\n  ) then\r\n    warning_messages :=\r\n      array_append(\r\n        warning_messages,\r\n        'הכונן החלופי כבר משובץ במשמרת אחרת באותו יום'\r\n      );\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.morning_driver_availability_entries entry\r\n    where entry.period_id =\r\n        target_period.availability_period_id\r\n      and entry.shift_id =\r\n        target_shift.id\r\n      and entry.user_id =\r\n        requested_new_driver_id\r\n      and entry.availability_status =\r\n        'available'\r\n  ) then\r\n    warning_messages :=\r\n      array_append(\r\n        warning_messages,\r\n        'הכונן החלופי לא סימן זמינות למשמרת זו'\r\n      );\r\n  end if;\r\n\r\n  update public.morning_driver_schedule_assignments\r\n  set\r\n    assigned_user_id =\r\n      requested_new_driver_id,\r\n\r\n    assignment_source =\r\n      'swap',\r\n\r\n    notes =\r\n      nullif(\r\n        concat_ws(\r\n          E'\\n',\r\n          target_assignment.notes,\r\n          case\r\n            when cardinality(\r\n              warning_messages\r\n            ) > 0\r\n            then\r\n              'אזהרות העברה: '\r\n              ||\r\n              array_to_string(\r\n                warning_messages,\r\n                '; '\r\n              )\r\n            else null\r\n          end\r\n        ),\r\n        ''\r\n      ),\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_assignment.id\r\n\r\n  returning *\r\n  into target_assignment;\r\n\r\n  return jsonb_build_object(\r\n    'assignmentId',\r\n      target_assignment.id,\r\n\r\n    'schedulePeriodId',\r\n      target_assignment.schedule_period_id,\r\n\r\n    'shiftDate',\r\n      target_shift.shift_date,\r\n\r\n    'startTime',\r\n      target_shift.start_time,\r\n\r\n    'endTime',\r\n      target_shift.end_time,\r\n\r\n    'previousDriverId',\r\n      current_user_id,\r\n\r\n    'previousDriverName',\r\n      coalesce(\r\n        current_driver.schedule_name,\r\n        current_driver.display_name\r\n      ),\r\n\r\n    'assignedUserId',\r\n      target_assignment.assigned_user_id,\r\n\r\n    'assignedUserName',\r\n      coalesce(\r\n        selected_driver.schedule_name,\r\n        selected_driver.display_name\r\n      ),\r\n\r\n    'assignmentSource',\r\n      target_assignment.assignment_source,\r\n\r\n    'hasWarnings',\r\n      cardinality(\r\n        warning_messages\r\n      ) > 0,\r\n\r\n    'warnings',\r\n      to_jsonb(\r\n        warning_messages\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_availability_submission_deadline(text,uuid,timestamp with time zone)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_availability_submission_deadline(requested_category text, requested_period_id uuid, requested_deadline timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  required_permission text;\r\n  resolved_status text;\r\n  updated_at_value timestamptz := now();\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  if requested_period_id is null then\r\n    raise exception 'period id is required';\r\n  end if;\r\n\r\n  if requested_deadline is null then\r\n    raise exception 'submission deadline is required';\r\n  end if;\r\n\r\n  required_permission :=\r\n    case requested_category\r\n      when 'dispatcher'\r\n        then 'availability.manage'\r\n      when 'driver'\r\n        then 'driver_availability.manage'\r\n      when 'morning_driver'\r\n        then 'morning_driver_availability.manage'\r\n      else null\r\n    end;\r\n\r\n  if required_permission is null then\r\n    raise exception 'invalid availability category';\r\n  end if;\r\n\r\n  if not (\r\n    required_permission =\r\n      any(\r\n        coalesce(\r\n          public.get_my_permissions(),\r\n          array[]::text[]\r\n        )\r\n      )\r\n  ) then\r\n    raise exception 'not allowed';\r\n  end if;\r\n\r\n  if requested_category =\r\n    'dispatcher'\r\n  then\r\n    select period.status::text\r\n    into resolved_status\r\n    from public.availability_periods period\r\n    where period.id =\r\n      requested_period_id\r\n    for update;\r\n\r\n    if not found then\r\n      raise exception 'availability period not found';\r\n    end if;\r\n\r\n    if resolved_status not in (\r\n      'draft',\r\n      'open'\r\n    ) then\r\n      raise exception\r\n        'deadline can only be changed while the period is draft or open';\r\n    end if;\r\n\r\n    update public.availability_periods\r\n    set\r\n      submission_deadline =\r\n        requested_deadline,\r\n      updated_by =\r\n        current_user_id,\r\n      updated_at =\r\n        updated_at_value\r\n    where id =\r\n      requested_period_id;\r\n\r\n  elsif requested_category =\r\n    'driver'\r\n  then\r\n    select period.status::text\r\n    into resolved_status\r\n    from public.driver_availability_periods period\r\n    where period.id =\r\n      requested_period_id\r\n    for update;\r\n\r\n    if not found then\r\n      raise exception 'driver availability period not found';\r\n    end if;\r\n\r\n    if resolved_status not in (\r\n      'draft',\r\n      'open'\r\n    ) then\r\n      raise exception\r\n        'deadline can only be changed while the period is draft or open';\r\n    end if;\r\n\r\n    update public.driver_availability_periods\r\n    set\r\n      submission_deadline =\r\n        requested_deadline,\r\n      updated_by =\r\n        current_user_id,\r\n      updated_at =\r\n        updated_at_value\r\n    where id =\r\n      requested_period_id;\r\n\r\n  else\r\n    select period.status::text\r\n    into resolved_status\r\n    from public.morning_driver_availability_periods period\r\n    where period.id =\r\n      requested_period_id\r\n    for update;\r\n\r\n    if not found then\r\n      raise exception 'morning driver availability period not found';\r\n    end if;\r\n\r\n    if resolved_status not in (\r\n      'draft',\r\n      'open'\r\n    ) then\r\n      raise exception\r\n        'deadline can only be changed while the period is draft or open';\r\n    end if;\r\n\r\n    update public.morning_driver_availability_periods\r\n    set\r\n      submission_deadline =\r\n        requested_deadline,\r\n      updated_by =\r\n        current_user_id,\r\n      updated_at =\r\n        updated_at_value\r\n    where id =\r\n      requested_period_id;\r\n  end if;\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n    actor_user_id,\r\n    metadata\r\n  )\r\n  values (\r\n    current_user_id,\r\n    'availability.deadline.updated',\r\n    requested_category ||\r\n      '_availability_period',\r\n    requested_period_id,\r\n    'עודכן מועד אחרון להגשת אילוצים',\r\n    current_user_id,\r\n    jsonb_build_object(\r\n      'category',\r\n        requested_category,\r\n      'submissionDeadline',\r\n        requested_deadline\r\n    )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'category',\r\n      requested_category,\r\n    'periodId',\r\n      requested_period_id,\r\n    'submissionDeadline',\r\n      requested_deadline,\r\n    'updatedAt',\r\n      updated_at_value\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_current_driver_schedule_day(uuid,uuid,boolean,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_current_driver_schedule_day(requested_schedule_day_id uuid, requested_assigned_user_id uuid DEFAULT NULL::uuid, requested_is_locked boolean DEFAULT false, requested_note text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_day\r\n    public.driver_schedule_days%rowtype;\r\n\r\n  target_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  selected_driver\r\n    public.profiles%rowtype;\r\n\r\n  linked_availability_day_id uuid;\r\n\r\n  selected_availability_status text;\r\n\r\n  previous_assignment_date date;\r\n  next_assignment_date date;\r\n\r\n  previous_gap_days integer;\r\n  next_gap_days integer;\r\n\r\n  current_date_in_israel date;\r\n  current_year integer;\r\n  current_month integer;\r\n\r\n  normalized_note text;\r\n\r\n  warning_messages text[] :=\r\n    array[]::text[];\r\n\r\n  final_note text;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_day_id is null then\r\n    raise exception\r\n      'driver schedule day id is required';\r\n  end if;\r\n\r\n  current_date_in_israel :=\r\n    (\r\n      now()\r\n      at time zone\r\n        'Asia/Jerusalem'\r\n    )::date;\r\n\r\n  current_year :=\r\n    extract(\r\n      year\r\n      from current_date_in_israel\r\n    )::integer;\r\n\r\n  current_month :=\r\n    extract(\r\n      month\r\n      from current_date_in_israel\r\n    )::integer;\r\n\r\n  select *\r\n  into target_day\r\n  from public.driver_schedule_days\r\n  where id =\r\n    requested_schedule_day_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver schedule day not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_schedule_periods\r\n  where id =\r\n    target_day.period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status <>\r\n    'published'\r\n      ::public.driver_schedule_period_status\r\n  then\r\n    raise exception\r\n      'only published current driver schedules can be edited';\r\n  end if;\r\n\r\n  if (\r\n    target_period.year <>\r\n      current_year\r\n    or\r\n    target_period.month <>\r\n      current_month\r\n  ) then\r\n    raise exception\r\n      'only current month driver schedule can be edited';\r\n  end if;\r\n\r\n  normalized_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  /*\r\n   * הסרת שיבוץ מהיום.\r\n   */\r\n  if requested_assigned_user_id is null then\r\n    update public.driver_schedule_days\r\n    set\r\n      assigned_user_id =\r\n        null,\r\n\r\n      assignment_source =\r\n        null,\r\n\r\n      is_locked =\r\n        coalesce(\r\n          requested_is_locked,\r\n          false\r\n        ),\r\n\r\n      notes =\r\n        normalized_note,\r\n\r\n      updated_at =\r\n        now()\r\n\r\n    where id =\r\n      target_day.id\r\n\r\n    returning *\r\n    into target_day;\r\n\r\n    return jsonb_build_object(\r\n      'scheduleDayId',\r\n        target_day.id,\r\n\r\n      'periodId',\r\n        target_day.period_id,\r\n\r\n      'dutyDate',\r\n        target_day.duty_date,\r\n\r\n      'assignedUserId',\r\n        null,\r\n\r\n      'assignedUserName',\r\n        null,\r\n\r\n      'assignmentSource',\r\n        null,\r\n\r\n      'isLocked',\r\n        target_day.is_locked,\r\n\r\n      'notes',\r\n        target_day.notes,\r\n\r\n      'hasWarnings',\r\n        false,\r\n\r\n      'warnings',\r\n        '[]'::jsonb\r\n    );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת הכונן שנבחר.\r\n   */\r\n  select *\r\n  into selected_driver\r\n  from public.profiles\r\n  where id =\r\n    requested_assigned_user_id\r\n    and role =\r\n      'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'selected on-call driver was not found or is inactive';\r\n  end if;\r\n\r\n  /*\r\n   * בעריכת חודש שכבר פורסם מותר לשבץ\r\n   * כונן גם ביום רצוף.\r\n   *\r\n   * במקום לחסום את הפעולה,\r\n   * נשמור אזהרה בלבד.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_days\r\n      adjacent_day\r\n    where adjacent_day.id <>\r\n      target_day.id\r\n      and adjacent_day.assigned_user_id =\r\n        requested_assigned_user_id\r\n      and adjacent_day.duty_date in (\r\n        target_day.duty_date - 1,\r\n        target_day.duty_date + 1\r\n      )\r\n  ) then\r\n    warning_messages :=\r\n      array_append(\r\n        warning_messages,\r\n        'לכונן קיימת כוננות ביום סמוך'\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * איתור הכוננות הקודמת.\r\n   */\r\n  select\r\n    max(schedule_day.duty_date)\r\n  into previous_assignment_date\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n  where schedule_day.id <>\r\n    target_day.id\r\n    and schedule_day.assigned_user_id =\r\n      requested_assigned_user_id\r\n    and schedule_day.duty_date <\r\n      target_day.duty_date;\r\n\r\n  /*\r\n   * איתור הכוננות הבאה.\r\n   */\r\n  select\r\n    min(schedule_day.duty_date)\r\n  into next_assignment_date\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n  where schedule_day.id <>\r\n    target_day.id\r\n    and schedule_day.assigned_user_id =\r\n      requested_assigned_user_id\r\n    and schedule_day.duty_date >\r\n      target_day.duty_date;\r\n\r\n  if previous_assignment_date is not null then\r\n    previous_gap_days :=\r\n      target_day.duty_date -\r\n      previous_assignment_date;\r\n\r\n    if previous_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד מהכוננות הקודמת',\r\n            previous_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  if next_assignment_date is not null then\r\n    next_gap_days :=\r\n      next_assignment_date -\r\n      target_day.duty_date;\r\n\r\n    if next_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד עד הכוננות הבאה',\r\n            next_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת אילוץ הכונן.\r\n   *\r\n   * גם אם הכונן סימן שאינו זמין,\r\n   * עריכה ידנית עדיין מותרת.\r\n   * נשמרת אזהרה בלבד.\r\n   */\r\n  if target_period.availability_period_id\r\n    is not null\r\n  then\r\n    select\r\n      availability_day.id\r\n    into linked_availability_day_id\r\n    from public.driver_availability_days\r\n      availability_day\r\n    where availability_day.period_id =\r\n      target_period.availability_period_id\r\n      and availability_day.availability_date =\r\n        target_day.duty_date\r\n    limit 1;\r\n\r\n    if linked_availability_day_id\r\n      is not null\r\n    then\r\n      select\r\n        availability_entry.availability_status\r\n      into selected_availability_status\r\n      from public.driver_availability_entries\r\n        availability_entry\r\n      where availability_entry.period_id =\r\n        target_period.availability_period_id\r\n        and availability_entry.day_id =\r\n          linked_availability_day_id\r\n        and availability_entry.user_id =\r\n          requested_assigned_user_id\r\n      limit 1;\r\n\r\n      if selected_availability_status =\r\n        'unavailable'\r\n      then\r\n        warning_messages :=\r\n          array_append(\r\n            warning_messages,\r\n            'הכונן סימן שאינו זמין בתאריך זה'\r\n          );\r\n\r\n      elsif selected_availability_status\r\n        is null\r\n      then\r\n        warning_messages :=\r\n          array_append(\r\n            warning_messages,\r\n            'לא נמצא סימון זמינות של הכונן לתאריך זה'\r\n          );\r\n      end if;\r\n    end if;\r\n  end if;\r\n\r\n  final_note :=\r\n    concat_ws(\r\n      E'\\n',\r\n      normalized_note,\r\n      case\r\n        when cardinality(\r\n          warning_messages\r\n        ) > 0\r\n        then\r\n          'אזהרות: '\r\n          ||\r\n          array_to_string(\r\n            warning_messages,\r\n            '; '\r\n          )\r\n        else\r\n          null\r\n      end\r\n    );\r\n\r\n  final_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          final_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  update public.driver_schedule_days\r\n  set\r\n    assigned_user_id =\r\n      requested_assigned_user_id,\r\n\r\n    assignment_source =\r\n      'manual'\r\n        ::public.driver_assignment_source,\r\n\r\n    is_locked =\r\n      coalesce(\r\n        requested_is_locked,\r\n        false\r\n      ),\r\n\r\n    notes =\r\n      final_note,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_day.id\r\n\r\n  returning *\r\n  into target_day;\r\n\r\n  return jsonb_build_object(\r\n    'scheduleDayId',\r\n      target_day.id,\r\n\r\n    'periodId',\r\n      target_day.period_id,\r\n\r\n    'dutyDate',\r\n      target_day.duty_date,\r\n\r\n    'assignedUserId',\r\n      target_day.assigned_user_id,\r\n\r\n    'assignedUserName',\r\n      coalesce(\r\n        selected_driver.schedule_name,\r\n        selected_driver.display_name\r\n      ),\r\n\r\n    'assignmentSource',\r\n      target_day.assignment_source,\r\n\r\n    'isLocked',\r\n      target_day.is_locked,\r\n\r\n    'notes',\r\n      target_day.notes,\r\n\r\n    'hasWarnings',\r\n      cardinality(\r\n        warning_messages\r\n      ) > 0,\r\n\r\n    'warnings',\r\n      to_jsonb(\r\n        warning_messages\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_current_schedule_shift(uuid,uuid,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_current_schedule_shift(requested_shift_id uuid, requested_new_user_id uuid, requested_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  actor_user_id uuid :=\r\n    (select auth.uid());\r\n\r\n  actor_display_name text;\r\n\r\n  has_schedule_edit boolean :=\r\n    false;\r\n\r\n  target_shift\r\n    public.schedule_shifts%rowtype;\r\n\r\n  target_period\r\n    public.schedule_periods%rowtype;\r\n\r\n  previous_user_id uuid;\r\n  previous_user_name text;\r\n  new_user_name text;\r\n\r\n  normalized_reason text :=\r\n    nullif(\r\n      trim(requested_reason),\r\n      ''\r\n    );\r\n\r\n  old_notification_id uuid;\r\n  new_notification_id uuid;\r\n\r\n  notification_ids uuid[] :=\r\n    array[]::uuid[];\r\n\r\n  shift_label text;\r\n\r\n  current_year integer;\r\n  current_month integer;\r\n\r\n  audit_summary text;\r\nbegin\r\n  if actor_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  select\r\n    profile.display_name\r\n  into\r\n    actor_display_name\r\n  from public.profiles\r\n    profile\r\n  where profile.id =\r\n      actor_user_id\r\n    and profile.is_active =\r\n      true;\r\n\r\n  if actor_display_name is null then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  select exists (\r\n    select 1\r\n    from public.user_permissions\r\n      permission\r\n    where permission.user_id =\r\n        actor_user_id\r\n      and permission.permission_key =\r\n        'schedule.edit'\r\n  )\r\n  into\r\n    has_schedule_edit;\r\n\r\n  if not has_schedule_edit then\r\n    raise exception\r\n      'schedule edit permission required';\r\n  end if;\r\n\r\n  select\r\n    shift.*\r\n  into\r\n    target_shift\r\n  from public.schedule_shifts\r\n    shift\r\n  where shift.id =\r\n      requested_shift_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'schedule shift not found';\r\n  end if;\r\n\r\n  select\r\n    period.*\r\n  into\r\n    target_period\r\n  from public.schedule_periods\r\n    period\r\n  where period.id =\r\n      target_shift.period_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'schedule period not found';\r\n  end if;\r\n\r\n  current_year :=\r\n    to_char(\r\n      timezone(\r\n        'Asia/Jerusalem',\r\n        now()\r\n      ),\r\n      'YYYY'\r\n    )::integer;\r\n\r\n  current_month :=\r\n    to_char(\r\n      timezone(\r\n        'Asia/Jerusalem',\r\n        now()\r\n      ),\r\n      'MM'\r\n    )::integer;\r\n\r\n  if (\r\n    target_period.year <>\r\n      current_year\r\n    or\r\n    target_period.month <>\r\n      current_month\r\n  ) then\r\n    raise exception\r\n      'only current month schedule can be edited';\r\n  end if;\r\n\r\n  if target_period.status <>\r\n      'published'\r\n  then\r\n    raise exception\r\n      'only published current schedule can be edited';\r\n  end if;\r\n\r\n  select\r\n    coalesce(\r\n      profile.schedule_name,\r\n      profile.display_name\r\n    )\r\n  into\r\n    new_user_name\r\n  from public.profiles\r\n    profile\r\n  where profile.id =\r\n      requested_new_user_id\r\n    and profile.is_active =\r\n      true\r\n    and profile.role =\r\n      'dispatcher';\r\n\r\n  if new_user_name is null then\r\n    raise exception\r\n      'target dispatcher is not active';\r\n  end if;\r\n\r\n  previous_user_id :=\r\n    target_shift.assigned_user_id;\r\n\r\n  if previous_user_id is not null then\r\n    select\r\n      coalesce(\r\n        profile.schedule_name,\r\n        profile.display_name\r\n      )\r\n    into\r\n      previous_user_name\r\n    from public.profiles\r\n      profile\r\n    where profile.id =\r\n        previous_user_id;\r\n  end if;\r\n\r\n  if previous_user_id =\r\n      requested_new_user_id\r\n  then\r\n    raise exception\r\n      'dispatcher is already assigned to this shift';\r\n  end if;\r\n\r\n  if exists (\r\n    select 1\r\n    from public.schedule_shifts\r\n      other_shift\r\n    where other_shift.period_id =\r\n        target_shift.period_id\r\n\r\n      and other_shift.id <>\r\n        target_shift.id\r\n\r\n      and other_shift.assigned_user_id =\r\n        requested_new_user_id\r\n\r\n      and (\r\n        (\r\n          other_shift.starts_at <\r\n            target_shift.ends_at\r\n\r\n          and other_shift.ends_at >\r\n            target_shift.starts_at\r\n        )\r\n\r\n        or\r\n\r\n        other_shift.ends_at =\r\n          target_shift.starts_at\r\n\r\n        or\r\n\r\n        other_shift.starts_at =\r\n          target_shift.ends_at\r\n      )\r\n  ) then\r\n    raise exception\r\n      'target dispatcher has overlapping or consecutive shift';\r\n  end if;\r\n\r\n  update public.schedule_shifts\r\n  set\r\n    assigned_user_id =\r\n      requested_new_user_id,\r\n\r\n    assignment_source =\r\n      'manual',\r\n\r\n    updated_at =\r\n      now()\r\n  where id =\r\n      target_shift.id;\r\n\r\n  /*\r\n   * ה-trigger של schedule_shifts יוצר את רשומת\r\n   * schedule_assignment_history.\r\n   * אם נמסרה סיבה, אנחנו מוסיפים אותה לרשומה\r\n   * שנוצרה עכשיו.\r\n   */\r\n  if normalized_reason is not null then\r\n    update public.schedule_assignment_history\r\n      history\r\n    set\r\n      reason =\r\n        normalized_reason\r\n    where history.id = (\r\n      select\r\n        recent_history.id\r\n      from public.schedule_assignment_history\r\n        recent_history\r\n      where recent_history.shift_id =\r\n          target_shift.id\r\n\r\n        and recent_history.changed_by =\r\n          actor_user_id\r\n\r\n        and recent_history.previous_user_id\r\n          is not distinct from\r\n            previous_user_id\r\n\r\n        and recent_history.new_user_id =\r\n          requested_new_user_id\r\n\r\n      order by\r\n        recent_history.created_at\r\n          desc\r\n\r\n      limit 1\r\n    );\r\n  end if;\r\n\r\n  shift_label :=\r\n    to_char(\r\n      target_shift.shift_date,\r\n      'DD/MM/YYYY'\r\n    )\r\n    ||\r\n    ' '\r\n    ||\r\n    to_char(\r\n      target_shift.starts_at\r\n        at time zone\r\n          'Asia/Jerusalem',\r\n      'HH24:MI'\r\n    )\r\n    ||\r\n    '–'\r\n    ||\r\n    to_char(\r\n      target_shift.ends_at\r\n        at time zone\r\n          'Asia/Jerusalem',\r\n      'HH24:MI'\r\n    );\r\n\r\n  /*\r\n   * התראה למוקדן שהוסר מהמשמרת.\r\n   */\r\n  if previous_user_id is not null then\r\n    insert into public.notifications (\r\n      type,\r\n      priority,\r\n      source,\r\n      title,\r\n      body,\r\n      url,\r\n      data,\r\n      created_by,\r\n      expires_at\r\n    )\r\n    values (\r\n      'system',\r\n      'important',\r\n      'schedule_edit',\r\n      'שינוי בשיבוץ המשמרות',\r\n      'הוסרת מהמשמרת '\r\n        || shift_label\r\n        || '. המוקדן החדש: '\r\n        || new_user_name\r\n        || '.',\r\n      '/schedule',\r\n      jsonb_build_object(\r\n        'workflow',\r\n          'schedule_edit',\r\n\r\n        'event',\r\n          'assignment_changed',\r\n\r\n        'actorUserId',\r\n          actor_user_id,\r\n\r\n        'shiftId',\r\n          target_shift.id,\r\n\r\n        'previousUserId',\r\n          previous_user_id,\r\n\r\n        'newUserId',\r\n          requested_new_user_id\r\n      ),\r\n      actor_user_id,\r\n      now() +\r\n        interval '90 days'\r\n    )\r\n    returning id\r\n    into old_notification_id;\r\n\r\n    insert into public.notification_recipients (\r\n      notification_id,\r\n      user_id\r\n    )\r\n    values (\r\n      old_notification_id,\r\n      previous_user_id\r\n    );\r\n\r\n    notification_ids :=\r\n      array_append(\r\n        notification_ids,\r\n        old_notification_id\r\n      );\r\n  end if;\r\n\r\n  /*\r\n   * התראה למוקדן החדש.\r\n   */\r\n  insert into public.notifications (\r\n    type,\r\n    priority,\r\n    source,\r\n    title,\r\n    body,\r\n    url,\r\n    data,\r\n    created_by,\r\n    expires_at\r\n  )\r\n  values (\r\n    'system',\r\n    'important',\r\n    'schedule_edit',\r\n    'שובצת למשמרת',\r\n    'שובצת למשמרת '\r\n      || shift_label\r\n      || ' בעקבות שינוי בלוח.',\r\n    '/schedule',\r\n    jsonb_build_object(\r\n      'workflow',\r\n        'schedule_edit',\r\n\r\n      'event',\r\n        'assignment_changed',\r\n\r\n      'actorUserId',\r\n        actor_user_id,\r\n\r\n      'shiftId',\r\n        target_shift.id,\r\n\r\n      'previousUserId',\r\n        previous_user_id,\r\n\r\n      'newUserId',\r\n        requested_new_user_id\r\n    ),\r\n    actor_user_id,\r\n    now() +\r\n      interval '90 days'\r\n  )\r\n  returning id\r\n  into new_notification_id;\r\n\r\n  insert into public.notification_recipients (\r\n    notification_id,\r\n    user_id\r\n  )\r\n  values (\r\n    new_notification_id,\r\n    requested_new_user_id\r\n  );\r\n\r\n  notification_ids :=\r\n    array_append(\r\n      notification_ids,\r\n      new_notification_id\r\n    );\r\n\r\n  /*\r\n   * תיאור אנושי ליומן המערכת.\r\n   * audit_logs.summary הוא NOT NULL.\r\n   */\r\n  audit_summary :=\r\n    concat(\r\n      'שינוי שיבוץ מוקדן: ',\r\n      coalesce(\r\n        previous_user_name,\r\n        'ללא שיבוץ'\r\n      ),\r\n      ' → ',\r\n      new_user_name,\r\n      ' | ',\r\n      shift_label,\r\n      case\r\n        when normalized_reason\r\n          is not null\r\n        then\r\n          ' | סיבה: '\r\n          || normalized_reason\r\n        else\r\n          ''\r\n      end\r\n    );\r\n\r\n  insert into public.audit_logs (\r\n    user_id,\r\n    action,\r\n    entity_type,\r\n    entity_id,\r\n    summary,\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    actor_user_id,\r\n    'schedule.assignment.updated',\r\n    'schedule_shift',\r\n    target_shift.id,\r\n    audit_summary,\r\n    jsonb_build_object(\r\n      'assignedUserId',\r\n        previous_user_id,\r\n\r\n      'assignedUserName',\r\n        previous_user_name\r\n    ),\r\n    jsonb_build_object(\r\n      'assignedUserId',\r\n        requested_new_user_id,\r\n\r\n      'assignedUserName',\r\n        new_user_name\r\n    ),\r\n    jsonb_build_object(\r\n      'reason',\r\n        normalized_reason,\r\n\r\n      'periodId',\r\n        target_period.id,\r\n\r\n      'year',\r\n        target_period.year,\r\n\r\n      'month',\r\n        target_period.month,\r\n\r\n      'actorDisplayName',\r\n        actor_display_name\r\n    )\r\n  );\r\n\r\n  return jsonb_build_object(\r\n    'shiftId',\r\n      target_shift.id,\r\n\r\n    'previousUserId',\r\n      previous_user_id,\r\n\r\n    'previousUserName',\r\n      previous_user_name,\r\n\r\n    'newUserId',\r\n      requested_new_user_id,\r\n\r\n    'newUserName',\r\n      new_user_name,\r\n\r\n    'shiftDate',\r\n      target_shift.shift_date,\r\n\r\n    'startsAt',\r\n      target_shift.starts_at,\r\n\r\n    'endsAt',\r\n      target_shift.ends_at,\r\n\r\n    'notificationIds',\r\n      to_jsonb(\r\n        notification_ids\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_driver_schedule_day(uuid,uuid,boolean,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_driver_schedule_day(requested_schedule_day_id uuid, requested_assigned_user_id uuid DEFAULT NULL::uuid, requested_is_locked boolean DEFAULT false, requested_note text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_day\r\n    public.driver_schedule_days%rowtype;\r\n\r\n  target_period\r\n    public.driver_schedule_periods%rowtype;\r\n\r\n  selected_driver\r\n    public.profiles%rowtype;\r\n\r\n  linked_availability_day_id uuid;\r\n\r\n  selected_availability_status text;\r\n\r\n  previous_assignment_date date;\r\n  next_assignment_date date;\r\n\r\n  previous_gap_days integer;\r\n  next_gap_days integer;\r\n\r\n  normalized_note text;\r\n  warning_messages text[] :=\r\n    array[]::text[];\r\n\r\n  final_note text;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles\r\n    where id =\r\n      current_user_id\r\n      and is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_schedule_day_id is null then\r\n    raise exception\r\n      'driver schedule day id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_day\r\n  from public.driver_schedule_days\r\n  where id =\r\n    requested_schedule_day_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver schedule day not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.driver_schedule_periods\r\n  where id =\r\n    target_day.period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'driver schedule period not found';\r\n  end if;\r\n\r\n  if target_period.status <> 'draft' then\r\n    raise exception\r\n      'only draft driver schedules can be edited';\r\n  end if;\r\n\r\n  normalized_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  /*\r\n   * הסרת שיבוץ מהיום.\r\n   */\r\n  if requested_assigned_user_id is null then\r\n    update public.driver_schedule_days\r\n    set\r\n      assigned_user_id =\r\n        null,\r\n\r\n      assignment_source =\r\n        null,\r\n\r\n      is_locked =\r\n        coalesce(\r\n          requested_is_locked,\r\n          false\r\n        ),\r\n\r\n      notes =\r\n        normalized_note,\r\n\r\n      updated_at =\r\n        now()\r\n\r\n    where id =\r\n      target_day.id\r\n\r\n    returning *\r\n    into target_day;\r\n\r\n    return jsonb_build_object(\r\n      'scheduleDayId',\r\n        target_day.id,\r\n\r\n      'periodId',\r\n        target_day.period_id,\r\n\r\n      'dutyDate',\r\n        target_day.duty_date,\r\n\r\n      'assignedUserId',\r\n        null,\r\n\r\n      'assignedUserName',\r\n        null,\r\n\r\n      'assignmentSource',\r\n        null,\r\n\r\n      'isLocked',\r\n        target_day.is_locked,\r\n\r\n      'notes',\r\n        target_day.notes,\r\n\r\n      'hasWarnings',\r\n        false,\r\n\r\n      'warnings',\r\n        '[]'::jsonb\r\n    );\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת הכונן שנבחר.\r\n   */\r\n  select *\r\n  into selected_driver\r\n  from public.profiles\r\n  where id =\r\n    requested_assigned_user_id\r\n    and role =\r\n      'on_call'::public.user_role\r\n    and is_active = true;\r\n\r\n  if not found then\r\n    raise exception\r\n      'selected on-call driver was not found or is inactive';\r\n  end if;\r\n\r\n  /*\r\n   * איסור קשיח על כוננות ביום רצוף.\r\n   * הבדיקה נעשית לפי מי שמשובץ בפועל.\r\n   */\r\n  if exists (\r\n    select 1\r\n    from public.driver_schedule_days\r\n      adjacent_day\r\n    where adjacent_day.id <>\r\n      target_day.id\r\n      and adjacent_day.assigned_user_id =\r\n        requested_assigned_user_id\r\n      and adjacent_day.duty_date in (\r\n        target_day.duty_date -\r\n          1,\r\n        target_day.duty_date +\r\n          1\r\n      )\r\n  ) then\r\n    raise exception\r\n      'driver cannot be assigned on consecutive days';\r\n  end if;\r\n\r\n  /*\r\n   * איתור הכוננות הקודמת והבאה של אותו כונן.\r\n   */\r\n  select\r\n    max(schedule_day.duty_date)\r\n  into previous_assignment_date\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n  where schedule_day.id <>\r\n    target_day.id\r\n    and schedule_day.assigned_user_id =\r\n      requested_assigned_user_id\r\n    and schedule_day.duty_date <\r\n      target_day.duty_date;\r\n\r\n  select\r\n    min(schedule_day.duty_date)\r\n  into next_assignment_date\r\n  from public.driver_schedule_days\r\n    schedule_day\r\n  where schedule_day.id <>\r\n    target_day.id\r\n    and schedule_day.assigned_user_id =\r\n      requested_assigned_user_id\r\n    and schedule_day.duty_date >\r\n      target_day.duty_date;\r\n\r\n  if previous_assignment_date is not null then\r\n    previous_gap_days :=\r\n      target_day.duty_date -\r\n      previous_assignment_date;\r\n\r\n    if previous_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד מהכוננות הקודמת',\r\n            previous_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  if next_assignment_date is not null then\r\n    next_gap_days :=\r\n      next_assignment_date -\r\n      target_day.duty_date;\r\n\r\n    if next_gap_days between 2 and 4 then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          format(\r\n            'מרווח של %s ימים בלבד עד הכוננות הבאה',\r\n            next_gap_days\r\n          )\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  /*\r\n   * בדיקת האילוץ שהכונן הגיש עבור היום.\r\n   * עריכה ידנית עדיין מותרת, אך תוצג אזהרה.\r\n   */\r\n  if target_period.availability_period_id\r\n    is not null\r\n  then\r\n    select\r\n      availability_day.id\r\n    into linked_availability_day_id\r\n    from public.driver_availability_days\r\n      availability_day\r\n    where availability_day.period_id =\r\n      target_period.availability_period_id\r\n      and availability_day.availability_date =\r\n        target_day.duty_date\r\n    limit 1;\r\n\r\n    if linked_availability_day_id is not null then\r\n      select\r\n        availability_entry.availability_status\r\n      into selected_availability_status\r\n      from public.driver_availability_entries\r\n        availability_entry\r\n      where availability_entry.period_id =\r\n        target_period.availability_period_id\r\n        and availability_entry.day_id =\r\n          linked_availability_day_id\r\n        and availability_entry.user_id =\r\n          requested_assigned_user_id\r\n      limit 1;\r\n\r\n      if selected_availability_status =\r\n        'unavailable'\r\n      then\r\n        warning_messages :=\r\n          array_append(\r\n            warning_messages,\r\n            'הכונן סימן שאינו זמין בתאריך זה'\r\n          );\r\n      elsif selected_availability_status is null then\r\n        warning_messages :=\r\n          array_append(\r\n            warning_messages,\r\n            'לא נמצא סימון זמינות של הכונן לתאריך זה'\r\n          );\r\n      end if;\r\n    end if;\r\n  end if;\r\n\r\n  final_note :=\r\n    concat_ws(\r\n      E'\\n',\r\n      normalized_note,\r\n      case\r\n        when cardinality(\r\n          warning_messages\r\n        ) > 0\r\n        then\r\n          'אזהרות: '\r\n          ||\r\n          array_to_string(\r\n            warning_messages,\r\n            '; '\r\n          )\r\n        else\r\n          null\r\n      end\r\n    );\r\n\r\n  final_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          final_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  update public.driver_schedule_days\r\n  set\r\n    assigned_user_id =\r\n      requested_assigned_user_id,\r\n\r\n    assignment_source =\r\n      'manual'\r\n        ::public.driver_assignment_source,\r\n\r\n    is_locked =\r\n      coalesce(\r\n        requested_is_locked,\r\n        false\r\n      ),\r\n\r\n    notes =\r\n      final_note,\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_day.id\r\n\r\n  returning *\r\n  into target_day;\r\n\r\n  return jsonb_build_object(\r\n    'scheduleDayId',\r\n      target_day.id,\r\n\r\n    'periodId',\r\n      target_day.period_id,\r\n\r\n    'dutyDate',\r\n      target_day.duty_date,\r\n\r\n    'assignedUserId',\r\n      target_day.assigned_user_id,\r\n\r\n    'assignedUserName',\r\n      coalesce(\r\n        selected_driver.schedule_name,\r\n        selected_driver.display_name\r\n      ),\r\n\r\n    'assignmentSource',\r\n      target_day.assignment_source,\r\n\r\n    'isLocked',\r\n      target_day.is_locked,\r\n\r\n    'notes',\r\n      target_day.notes,\r\n\r\n    'hasWarnings',\r\n      cardinality(\r\n        warning_messages\r\n      ) > 0,\r\n\r\n    'warnings',\r\n      to_jsonb(\r\n        warning_messages\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_morning_driver_schedule_assignment(uuid,uuid,boolean,text)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_morning_driver_schedule_assignment(requested_assignment_id uuid, requested_assigned_user_id uuid DEFAULT NULL::uuid, requested_is_locked boolean DEFAULT false, requested_note text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid;\r\n  current_permissions text[];\r\n\r\n  target_assignment\r\n    public.morning_driver_schedule_assignments%rowtype;\r\n\r\n  target_period\r\n    public.morning_driver_schedule_periods%rowtype;\r\n\r\n  target_shift\r\n    public.morning_driver_availability_shifts%rowtype;\r\n\r\n  selected_driver\r\n    public.profiles%rowtype;\r\n\r\n  warning_messages text[] :=\r\n    array[]::text[];\r\n\r\n  normalized_note text;\r\nbegin\r\n  current_user_id :=\r\n    auth.uid();\r\n\r\n  if current_user_id is null then\r\n    raise exception\r\n      'not authenticated';\r\n  end if;\r\n\r\n  if not exists (\r\n    select 1\r\n    from public.profiles profile\r\n    where profile.id =\r\n      current_user_id\r\n      and profile.is_active = true\r\n  ) then\r\n    raise exception\r\n      'user not active';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'morning_driver_schedule.edit' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception\r\n      'not allowed';\r\n  end if;\r\n\r\n  if requested_assignment_id is null then\r\n    raise exception\r\n      'morning driver schedule assignment id is required';\r\n  end if;\r\n\r\n  select *\r\n  into target_assignment\r\n  from public.morning_driver_schedule_assignments\r\n    assignment\r\n  where assignment.id =\r\n    requested_assignment_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver schedule assignment not found';\r\n  end if;\r\n\r\n  select *\r\n  into target_period\r\n  from public.morning_driver_schedule_periods\r\n    period\r\n  where period.id =\r\n    target_assignment.schedule_period_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver schedule period not found';\r\n  end if;\r\n\r\n  /*\r\n   * Managers with the edit permission may correct both\r\n   * draft and already-published schedules.\r\n   *\r\n   * Archived historical schedules stay read-only.\r\n   */\r\n  if target_period.status not in (\r\n    'draft',\r\n    'published'\r\n  ) then\r\n    raise exception\r\n      'only draft or published schedules can be edited';\r\n  end if;\r\n\r\n  select *\r\n  into target_shift\r\n  from public.morning_driver_availability_shifts\r\n    shift_item\r\n  where shift_item.id =\r\n    target_assignment.availability_shift_id;\r\n\r\n  if not found then\r\n    raise exception\r\n      'morning driver availability shift not found';\r\n  end if;\r\n\r\n  normalized_note :=\r\n    nullif(\r\n      trim(\r\n        coalesce(\r\n          requested_note,\r\n          ''\r\n        )\r\n      ),\r\n      ''\r\n    );\r\n\r\n  if requested_assigned_user_id is not null then\r\n    select *\r\n    into selected_driver\r\n    from public.profiles profile\r\n    where profile.id =\r\n        requested_assigned_user_id\r\n      and profile.role =\r\n        'morning_driver'\r\n          ::public.user_role\r\n      and profile.is_active =\r\n        true;\r\n\r\n    if not found then\r\n      raise exception\r\n        'selected morning driver not found or inactive';\r\n    end if;\r\n\r\n    /*\r\n     * Do not assign the same morning driver twice\r\n     * to different slots of the same shift.\r\n     */\r\n    if exists (\r\n      select 1\r\n      from public.morning_driver_schedule_assignments\r\n        duplicate_assignment\r\n      where duplicate_assignment.schedule_period_id =\r\n          target_assignment.schedule_period_id\r\n        and duplicate_assignment.availability_shift_id =\r\n          target_assignment.availability_shift_id\r\n        and duplicate_assignment.id <>\r\n          target_assignment.id\r\n        and duplicate_assignment.assigned_user_id =\r\n          requested_assigned_user_id\r\n    ) then\r\n      raise exception\r\n        'driver is already assigned to this shift';\r\n    end if;\r\n\r\n    /*\r\n     * Same-day assignment is kept as a warning,\r\n     * matching the existing behavior.\r\n     */\r\n    if exists (\r\n      select 1\r\n      from public.morning_driver_schedule_assignments\r\n        same_day_assignment\r\n      join public.morning_driver_availability_shifts\r\n        other_shift\r\n        on other_shift.id =\r\n          same_day_assignment.availability_shift_id\r\n      where same_day_assignment.schedule_period_id =\r\n          target_assignment.schedule_period_id\r\n        and same_day_assignment.id <>\r\n          target_assignment.id\r\n        and same_day_assignment.assigned_user_id =\r\n          requested_assigned_user_id\r\n        and other_shift.shift_date =\r\n          target_shift.shift_date\r\n    ) then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          'הכונן כבר משובץ במשמרת אחרת באותו יום'\r\n        );\r\n    end if;\r\n\r\n    /*\r\n     * Availability remains a warning for manual manager edits,\r\n     * rather than a hard blocker.\r\n     */\r\n    if not exists (\r\n      select 1\r\n      from public.morning_driver_availability_entries\r\n        entry\r\n      where entry.period_id =\r\n          target_period.availability_period_id\r\n        and entry.shift_id =\r\n          target_shift.id\r\n        and entry.user_id =\r\n          requested_assigned_user_id\r\n        and entry.availability_status =\r\n          'available'\r\n    ) then\r\n      warning_messages :=\r\n        array_append(\r\n          warning_messages,\r\n          'הכונן לא סימן זמינות למשמרת זו'\r\n        );\r\n    end if;\r\n  end if;\r\n\r\n  update public.morning_driver_schedule_assignments\r\n  set\r\n    assigned_user_id =\r\n      requested_assigned_user_id,\r\n\r\n    assignment_source =\r\n      case\r\n        when requested_assigned_user_id\r\n          is null\r\n        then null\r\n\r\n        else 'manual'\r\n      end,\r\n\r\n    is_locked =\r\n      coalesce(\r\n        requested_is_locked,\r\n        false\r\n      ),\r\n\r\n    notes =\r\n      nullif(\r\n        concat_ws(\r\n          E'\\n',\r\n          normalized_note,\r\n          case\r\n            when cardinality(\r\n              warning_messages\r\n            ) > 0\r\n            then\r\n              'אזהרות: '\r\n              ||\r\n              array_to_string(\r\n                warning_messages,\r\n                '; '\r\n              )\r\n\r\n            else null\r\n          end\r\n        ),\r\n        ''\r\n      ),\r\n\r\n    updated_at =\r\n      now()\r\n\r\n  where id =\r\n    target_assignment.id\r\n\r\n  returning *\r\n  into target_assignment;\r\n\r\n  return jsonb_build_object(\r\n    'assignmentId',\r\n      target_assignment.id,\r\n\r\n    'schedulePeriodId',\r\n      target_assignment.schedule_period_id,\r\n\r\n    'scheduleStatus',\r\n      target_period.status,\r\n\r\n    'shiftDate',\r\n      target_shift.shift_date,\r\n\r\n    'assignedUserId',\r\n      target_assignment.assigned_user_id,\r\n\r\n    'assignedUserName',\r\n      case\r\n        when target_assignment.assigned_user_id\r\n          is null\r\n        then null\r\n\r\n        else coalesce(\r\n          selected_driver.schedule_name,\r\n          selected_driver.display_name\r\n        )\r\n      end,\r\n\r\n    'assignmentSource',\r\n      target_assignment.assignment_source,\r\n\r\n    'isLocked',\r\n      target_assignment.is_locked,\r\n\r\n    'notes',\r\n      target_assignment.notes,\r\n\r\n    'hasWarnings',\r\n      cardinality(\r\n        warning_messages\r\n      ) > 0,\r\n\r\n    'warnings',\r\n      to_jsonb(\r\n        warning_messages\r\n      )\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "update_user_compensation(uuid,numeric,numeric)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.update_user_compensation(target_user_id uuid, requested_hourly_rate numeric DEFAULT NULL::numeric, requested_daily_duty_rate numeric DEFAULT NULL::numeric)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_user_id uuid := auth.uid();\r\n  current_permissions text[];\r\n  target_role public.user_role;\r\nbegin\r\n  if current_user_id is null then\r\n    raise exception 'not authenticated';\r\n  end if;\r\n\r\n  current_permissions :=\r\n    coalesce(\r\n      public.get_my_permissions(),\r\n      array[]::text[]\r\n    );\r\n\r\n  if not (\r\n    'payroll.manage' =\r\n      any(current_permissions)\r\n  ) then\r\n    raise exception 'payroll manage permission required';\r\n  end if;\r\n\r\n  if requested_hourly_rate is not null\r\n    and requested_hourly_rate < 0\r\n  then\r\n    raise exception 'hourly rate cannot be negative';\r\n  end if;\r\n\r\n  if requested_daily_duty_rate is not null\r\n    and requested_daily_duty_rate < 0\r\n  then\r\n    raise exception 'daily duty rate cannot be negative';\r\n  end if;\r\n\r\n  select role\r\n  into target_role\r\n  from public.profiles\r\n  where id = target_user_id\r\n  for update;\r\n\r\n  if not found then\r\n    raise exception 'target user was not found';\r\n  end if;\r\n\r\n  if target_role =\r\n    'dispatcher'::public.user_role\r\n  then\r\n    update public.profiles\r\n    set\r\n      hourly_rate = requested_hourly_rate,\r\n      daily_duty_rate = null,\r\n      updated_at = now()\r\n    where id = target_user_id;\r\n\r\n  elsif target_role =\r\n    'on_call'::public.user_role\r\n  then\r\n    update public.profiles\r\n    set\r\n      hourly_rate = null,\r\n      daily_duty_rate = requested_daily_duty_rate,\r\n      updated_at = now()\r\n    where id = target_user_id;\r\n\r\n  else\r\n    raise exception\r\n      'compensation can currently be configured only for dispatchers and on-call drivers';\r\n  end if;\r\n\r\n  return true;\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "validate_shift_swap_final_state(text,uuid,uuid,uuid,uuid)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.validate_shift_swap_final_state(requested_swap_type text, requested_requester_user_id uuid, requested_counterparty_user_id uuid, requested_requester_shift_id uuid, requested_counterparty_shift_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  conflict_record record;\r\nbegin\r\n  if requested_swap_type not in ('one_way', 'two_way') then\r\n    return jsonb_build_object(\r\n      'valid', false,\r\n      'code', 'invalid_swap_type',\r\n      'message', 'סוג ההחלפה אינו תקין.'\r\n    );\r\n  end if;\r\n\r\n  if requested_requester_user_id is null\r\n    or requested_counterparty_user_id is null\r\n    or requested_requester_user_id = requested_counterparty_user_id then\r\n    return jsonb_build_object(\r\n      'valid', false,\r\n      'code', 'invalid_users',\r\n      'message', 'יש לבחור שני מוקדנים שונים.'\r\n    );\r\n  end if;\r\n\r\n  if requested_swap_type = 'two_way'\r\n    and requested_counterparty_shift_id is null then\r\n    return jsonb_build_object(\r\n      'valid', false,\r\n      'code', 'missing_counterparty_shift',\r\n      'message', 'בהחלפה דו-כיוונית יש לבחור משמרת של המוקדן השני.'\r\n    );\r\n  end if;\r\n\r\n  with simulated_assignments as (\r\n    select\r\n      s.id,\r\n      s.starts_at,\r\n      s.ends_at,\r\n      case\r\n        when s.id = requested_requester_shift_id\r\n          then requested_counterparty_user_id\r\n        when requested_swap_type = 'two_way'\r\n          and s.id = requested_counterparty_shift_id\r\n          then requested_requester_user_id\r\n        else s.assigned_user_id\r\n      end as simulated_user_id\r\n    from public.schedule_shifts s\r\n    where s.assigned_user_id in (\r\n      requested_requester_user_id,\r\n      requested_counterparty_user_id\r\n    )\r\n      or s.id = requested_requester_shift_id\r\n      or s.id = requested_counterparty_shift_id\r\n  ),\r\n  relevant as (\r\n    select *\r\n    from simulated_assignments\r\n    where simulated_user_id in (\r\n      requested_requester_user_id,\r\n      requested_counterparty_user_id\r\n    )\r\n  ),\r\n  conflicts as (\r\n    select\r\n      first_shift.simulated_user_id as user_id,\r\n      first_shift.id as first_shift_id,\r\n      second_shift.id as second_shift_id,\r\n      case\r\n        when second_shift.starts_at < first_shift.ends_at\r\n          then 'overlapping_shifts'\r\n        else 'consecutive_shifts'\r\n      end as conflict_type\r\n    from relevant first_shift\r\n    join relevant second_shift\r\n      on second_shift.simulated_user_id = first_shift.simulated_user_id\r\n     and second_shift.id <> first_shift.id\r\n     and second_shift.starts_at >= first_shift.starts_at\r\n     and (\r\n       second_shift.starts_at < first_shift.ends_at\r\n       or second_shift.starts_at = first_shift.ends_at\r\n     )\r\n    order by first_shift.starts_at, second_shift.starts_at\r\n    limit 1\r\n  )\r\n  select *\r\n  into conflict_record\r\n  from conflicts;\r\n\r\n  if found then\r\n    return jsonb_build_object(\r\n      'valid', false,\r\n      'code', conflict_record.conflict_type,\r\n      'message',\r\n        case\r\n          when conflict_record.conflict_type = 'overlapping_shifts'\r\n            then 'ההחלפה יוצרת חפיפה בין משמרות של אחד המוקדנים.'\r\n          else 'ההחלפה יוצרת משמרות רצופות לאותו מוקדן.'\r\n        end,\r\n      'userId', conflict_record.user_id,\r\n      'firstShiftId', conflict_record.first_shift_id,\r\n      'secondShiftId', conflict_record.second_shift_id\r\n    );\r\n  end if;\r\n\r\n  return jsonb_build_object(\r\n    'valid', true,\r\n    'code', null,\r\n    'message', null\r\n  );\r\nend;\r\n$function$\n"
  },
  {
    "function_signature": "write_audit_log(audit_action_type,uuid,text,jsonb,jsonb,jsonb)",
    "function_definition": "CREATE OR REPLACE FUNCTION public.write_audit_log(requested_action audit_action_type, requested_target_user_id uuid, requested_summary text, requested_old_values jsonb DEFAULT NULL::jsonb, requested_new_values jsonb DEFAULT NULL::jsonb, requested_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\r\ndeclare\r\n  current_actor_id uuid;\r\n  current_actor_email text;\r\n  current_actor_display_name text;\r\n\r\n  current_target_email text;\r\n  current_target_display_name text;\r\n\r\n  created_log_id uuid;\r\nbegin\r\n  current_actor_id :=\r\n    auth.uid();\r\n\r\n  if current_actor_id is null then\r\n    raise exception\r\n      'User is not authenticated';\r\n  end if;\r\n\r\n  if requested_summary is null\r\n     or length(\r\n       trim(\r\n         requested_summary\r\n       )\r\n     ) = 0\r\n  then\r\n    raise exception\r\n      'Audit summary is required';\r\n  end if;\r\n\r\n  if requested_old_values is not null\r\n     and jsonb_typeof(\r\n       requested_old_values\r\n     ) <> 'object'\r\n  then\r\n    raise exception\r\n      'old_values must be a JSON object';\r\n  end if;\r\n\r\n  if requested_new_values is not null\r\n     and jsonb_typeof(\r\n       requested_new_values\r\n     ) <> 'object'\r\n  then\r\n    raise exception\r\n      'new_values must be a JSON object';\r\n  end if;\r\n\r\n  if requested_metadata is null\r\n     or jsonb_typeof(\r\n       requested_metadata\r\n     ) <> 'object'\r\n  then\r\n    raise exception\r\n      'metadata must be a JSON object';\r\n  end if;\r\n\r\n  select\r\n    profile.email,\r\n    profile.display_name\r\n  into\r\n    current_actor_email,\r\n    current_actor_display_name\r\n  from public.profiles profile\r\n  where profile.id =\r\n    current_actor_id;\r\n\r\n  if current_actor_email is null then\r\n    raise exception\r\n      'Authenticated user profile was not found';\r\n  end if;\r\n\r\n  if requested_target_user_id\r\n     is not null\r\n  then\r\n    select\r\n      profile.email,\r\n      profile.display_name\r\n    into\r\n      current_target_email,\r\n      current_target_display_name\r\n    from public.profiles profile\r\n    where profile.id =\r\n      requested_target_user_id;\r\n  end if;\r\n\r\n  insert into public.audit_logs (\r\n    action,\r\n    actor_user_id,\r\n    actor_email,\r\n    actor_display_name,\r\n    target_user_id,\r\n    target_email,\r\n    target_display_name,\r\n    entity_type,\r\n    summary,\r\n    old_values,\r\n    new_values,\r\n    metadata\r\n  )\r\n  values (\r\n    requested_action::text,\r\n    current_actor_id,\r\n    current_actor_email,\r\n    current_actor_display_name,\r\n    requested_target_user_id,\r\n    current_target_email,\r\n    current_target_display_name,\r\n    'user',\r\n    trim(\r\n      requested_summary\r\n    ),\r\n    requested_old_values,\r\n    requested_new_values,\r\n    requested_metadata\r\n  )\r\n  returning id\r\n  into created_log_id;\r\n\r\n  return created_log_id;\r\nend;\r\n$function$\n"
  }
]